def init_db():
    """
    Create all required tables if they don't already exist.
    This runs on every app startup to ensure the schema is ready.
    Existing data is never touched (IF NOT EXISTS / ON CONFLICT).

    FROZEN as of Tier 10 (April 2026). New schema changes go through
    Alembic — see `_run_alembic_upgrade()` below and `migrations/`.
    """
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("""
                -- Site-wide settings (singleton row with id=1)
                CREATE TABLE IF NOT EXISTS site_settings (
                    id            SERIAL PRIMARY KEY,
                    site_name     TEXT NOT NULL DEFAULT 'My Site',
                    site_subtitle TEXT NOT NULL DEFAULT 'Your Tagline Here',
                    hero_tagline  TEXT NOT NULL DEFAULT 'Welcome to Our Website',
                    hero_title    TEXT NOT NULL DEFAULT 'My Site',
                    hero_description TEXT NOT NULL DEFAULT '',
                    hero_image    TEXT NOT NULL DEFAULT '',
                    logo_initials TEXT NOT NULL DEFAULT 'CS',
                    created_at    TIMESTAMP DEFAULT NOW(),
                    updated_at    TIMESTAMP DEFAULT NOW()
                );

                -- Gallery slides / explore cards
                CREATE TABLE IF NOT EXISTS gallery_cards (
                    id          SERIAL PRIMARY KEY,
                    slug        VARCHAR(100) UNIQUE NOT NULL,
                    title       TEXT NOT NULL,
                    subtitle    TEXT NOT NULL,
                    image_url   TEXT NOT NULL,
                    category    VARCHAR(50) NOT NULL,
                    description TEXT NOT NULL DEFAULT '',
                    details     JSONB DEFAULT '[]'::jsonb,
                    price       TEXT,
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP DEFAULT NOW(),
                    updated_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_gallery_cards_sort ON gallery_cards (sort_order);

                -- Curated experiences
                CREATE TABLE IF NOT EXISTS experiences (
                    id          SERIAL PRIMARY KEY,
                    name        TEXT NOT NULL,
                    description TEXT NOT NULL DEFAULT '',
                    icon        VARCHAR(50) NOT NULL DEFAULT 'star',
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP DEFAULT NOW(),
                    updated_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_experiences_sort ON experiences (sort_order);

                -- Seasonal pricing tiers
                CREATE TABLE IF NOT EXISTS pricing_seasons (
                    id          SERIAL PRIMARY KEY,
                    label       VARCHAR(50) NOT NULL,
                    date_range  TEXT NOT NULL,
                    price_range TEXT NOT NULL,
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP DEFAULT NOW(),
                    updated_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_pricing_sort ON pricing_seasons (sort_order);

                -- =============================================================
                -- CHATBOT SETTINGS (singleton row with id=1)
                -- =============================================================
                -- Controls whether the AI chatbot is shown on the public site,
                -- and how it connects to an AI agent.
                --
                -- enabled: Master on/off toggle. When false, no chatbot appears.
                -- mode: 'builtin' uses the template's built-in chat UI.
                --        'embed' loads an external chatbot widget via embed_code.
                -- agent_name: Display name shown in the chat bar.
                -- agent_role: Role label (e.g., "Concierge", "Assistant").
                -- agent_avatar: Text initials or image URL for the avatar.
                -- greeting: First message the bot sends when chat opens.
                -- quick_prompts: JSON array of suggested prompt strings.
                -- api_endpoint: URL to POST messages to (for builtin mode).
                -- embed_code: External HTML/script snippet (for embed mode).
                -- =============================================================
                CREATE TABLE IF NOT EXISTS chatbot_settings (
                    id            SERIAL PRIMARY KEY,
                    enabled       BOOLEAN NOT NULL DEFAULT false,
                    mode          TEXT NOT NULL DEFAULT 'builtin',
                    agent_name    TEXT NOT NULL DEFAULT 'AI Assistant',
                    agent_role    TEXT NOT NULL DEFAULT 'Assistant',
                    agent_avatar  TEXT NOT NULL DEFAULT 'A',
                    greeting      TEXT NOT NULL DEFAULT 'Welcome! I''m your AI assistant. How can I help you today?',
                    quick_prompts JSONB DEFAULT '["Browse our offerings", "Tell me more", "What do you offer?", "Show me pricing"]'::jsonb,
                    api_endpoint  TEXT NOT NULL DEFAULT '/api/chat',
                    embed_code    TEXT NOT NULL DEFAULT '',
                    system_prompt TEXT NOT NULL DEFAULT '',
                    brand_voice   TEXT NOT NULL DEFAULT '',
                    created_at    TIMESTAMP DEFAULT NOW(),
                    updated_at    TIMESTAMP DEFAULT NOW()
                );

                -- Chat conversations (one per page load / session).
                -- session_id: unique per page load (new conversation each refresh).
                -- visitor_id: persistent across reloads (tracks returning visitors via localStorage).
                CREATE TABLE IF NOT EXISTS chat_conversations (
                    id          SERIAL PRIMARY KEY,
                    session_id  VARCHAR(100) NOT NULL,
                    visitor_id  VARCHAR(100) DEFAULT '',
                    visitor_ip  VARCHAR(45) DEFAULT '',
                    device_type VARCHAR(20) DEFAULT 'desktop',
                    user_agent  TEXT DEFAULT '',
                    started_at  TIMESTAMP DEFAULT NOW(),
                    updated_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_chat_conv_session ON chat_conversations (session_id);

                -- Chat messages (linked to conversations)
                CREATE TABLE IF NOT EXISTS chat_messages (
                    id              SERIAL PRIMARY KEY,
                    conversation_id INTEGER REFERENCES chat_conversations(id) ON DELETE CASCADE,
                    role            VARCHAR(20) NOT NULL DEFAULT 'user',
                    content         TEXT NOT NULL DEFAULT '',
                    command_json    JSONB,
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_chat_msg_conv ON chat_messages (conversation_id);

                -- Conversation takeover / AI-pause state (task 095, gap §2.4). One row
                -- per conversation a human took over; NO row = normal AI mode. Kept off
                -- chat_conversations (the hot per-turn write path). Also in migration 0035.
                CREATE TABLE IF NOT EXISTS conversation_takeover (
                    conversation_id INTEGER PRIMARY KEY REFERENCES chat_conversations(id) ON DELETE CASCADE,
                    tenant_id       INTEGER NOT NULL DEFAULT 1,
                    ai_paused       BOOLEAN NOT NULL DEFAULT FALSE,
                    taken_over_by   TEXT NOT NULL DEFAULT '',
                    taken_over_at   TIMESTAMP,
                    released_at     TIMESTAMP,
                    updated_at      TIMESTAMP NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS conversation_takeover_active_idx ON conversation_takeover (tenant_id, ai_paused);

                -- Uploaded images
                CREATE TABLE IF NOT EXISTS uploaded_images (
                    id            SERIAL PRIMARY KEY,
                    filename      TEXT NOT NULL,
                    original_name TEXT NOT NULL DEFAULT '',
                    file_size     INTEGER DEFAULT 0,
                    uploaded_at   TIMESTAMP DEFAULT NOW()
                );

                -- Dynamic forms (form builder)
                CREATE TABLE IF NOT EXISTS custom_forms (
                    id                SERIAL PRIMARY KEY,
                    name              TEXT NOT NULL DEFAULT '',
                    slug              VARCHAR(100) NOT NULL UNIQUE,
                    description       TEXT NOT NULL DEFAULT '',
                    status            VARCHAR(20) NOT NULL DEFAULT 'active',
                    submit_button_text TEXT NOT NULL DEFAULT 'Submit',
                    success_message   TEXT NOT NULL DEFAULT 'Thank you! Your submission has been received.',
                    created_at        TIMESTAMP DEFAULT NOW(),
                    updated_at        TIMESTAMP DEFAULT NOW(),
                    sort_order        INTEGER DEFAULT 0
                );

                -- Dynamic form fields
                CREATE TABLE IF NOT EXISTS form_fields (
                    id              SERIAL PRIMARY KEY,
                    form_id         INTEGER NOT NULL REFERENCES custom_forms(id) ON DELETE CASCADE,
                    field_type      VARCHAR(30) NOT NULL DEFAULT 'text',
                    label           TEXT NOT NULL DEFAULT '',
                    name            VARCHAR(100) NOT NULL DEFAULT '',
                    placeholder     TEXT NOT NULL DEFAULT '',
                    required        BOOLEAN NOT NULL DEFAULT false,
                    options         JSONB,
                    default_value   TEXT NOT NULL DEFAULT '',
                    sort_order      INTEGER DEFAULT 0,
                    width           VARCHAR(10) NOT NULL DEFAULT 'full',
                    validation_regex TEXT NOT NULL DEFAULT '',
                    help_text       TEXT NOT NULL DEFAULT ''
                );
                CREATE INDEX IF NOT EXISTS idx_form_fields_form ON form_fields (form_id);

                -- Dynamic form submissions (JSONB for flexible field storage)
                CREATE TABLE IF NOT EXISTS form_submissions (
                    id                SERIAL PRIMARY KEY,
                    form_id           INTEGER NOT NULL REFERENCES custom_forms(id) ON DELETE CASCADE,
                    submission_data   JSONB NOT NULL DEFAULT '{}'::jsonb,
                    status            VARCHAR(20) NOT NULL DEFAULT 'new',
                    device_type       VARCHAR(20) DEFAULT 'desktop',
                    user_agent        TEXT DEFAULT '',
                    referrer_url      TEXT DEFAULT '',
                    utm_source        TEXT DEFAULT '',
                    utm_medium        TEXT DEFAULT '',
                    utm_campaign      TEXT DEFAULT '',
                    utm_term          TEXT DEFAULT '',
                    utm_content       TEXT DEFAULT '',
                    page_url          TEXT DEFAULT '',
                    ip_address        VARCHAR(45) DEFAULT '',
                    browser           TEXT DEFAULT '',
                    os                TEXT DEFAULT '',
                    screen_resolution TEXT DEFAULT '',
                    language          TEXT DEFAULT '',
                    session_id        TEXT DEFAULT '',
                    submitted_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_form_sub_form ON form_submissions (form_id);
                CREATE INDEX IF NOT EXISTS idx_form_sub_status ON form_submissions (status);

                -- AI-generated HTML pages (saved from the chatbot)
                CREATE TABLE IF NOT EXISTS generated_pages (
                    id          SERIAL PRIMARY KEY,
                    title       TEXT NOT NULL DEFAULT 'Untitled Page',
                    html        TEXT NOT NULL DEFAULT '',
                    prompt      TEXT NOT NULL DEFAULT '',
                    slug        VARCHAR(200) UNIQUE,
                    status      VARCHAR(20) NOT NULL DEFAULT 'draft',
                    created_at  TIMESTAMP DEFAULT NOW(),
                    updated_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_generated_pages_status ON generated_pages (status);

                -- =============================================================
                -- TESTIMONIALS / REVIEWS
                -- =============================================================
                -- Client reviews displayed on the public site.
                -- Each has a star rating (1-5), reviewer info, and optional photo.
                -- Enabled/disabled via section_testimonials toggle in site_settings.
                CREATE TABLE IF NOT EXISTS testimonials (
                    id            SERIAL PRIMARY KEY,
                    reviewer_name TEXT NOT NULL DEFAULT '',
                    reviewer_role TEXT NOT NULL DEFAULT '',
                    content       TEXT NOT NULL DEFAULT '',
                    rating        INTEGER NOT NULL DEFAULT 5,
                    image_url     TEXT NOT NULL DEFAULT '',
                    sort_order    INTEGER NOT NULL DEFAULT 0,
                    created_at    TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_testimonials_sort ON testimonials (sort_order);

                -- =============================================================
                -- TEAM MEMBERS
                -- =============================================================
                -- Staff/team member cards displayed on the public site.
                -- Enabled/disabled via section_team toggle in site_settings.
                CREATE TABLE IF NOT EXISTS team_members (
                    id          SERIAL PRIMARY KEY,
                    name        TEXT NOT NULL DEFAULT '',
                    title       TEXT NOT NULL DEFAULT '',
                    bio         TEXT NOT NULL DEFAULT '',
                    image_url   TEXT NOT NULL DEFAULT '',
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_team_sort ON team_members (sort_order);

                -- =============================================================
                -- FREQUENTLY ASKED QUESTIONS
                -- =============================================================
                -- FAQ pairs shown in an accordion on the public site.
                -- Enabled/disabled via section_faq toggle in site_settings.
                CREATE TABLE IF NOT EXISTS faqs (
                    id          SERIAL PRIMARY KEY,
                    question    TEXT NOT NULL DEFAULT '',
                    answer      TEXT NOT NULL DEFAULT '',
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_faqs_sort ON faqs (sort_order);

                -- =============================================================
                -- PAGE SECTIONS REGISTRY
                -- =============================================================
                -- Master list of ALL page sections (built-in + custom).
                -- Controls the order sections appear on the public site,
                -- which ones are enabled/disabled, and what template to use.
                -- Built-in sections (hero, highlights, etc.) are seeded on first run.
                -- Custom sections are created by the admin and use templates.
                CREATE TABLE IF NOT EXISTS page_sections (
                    id            SERIAL PRIMARY KEY,
                    slug          TEXT UNIQUE NOT NULL,
                    title         TEXT NOT NULL DEFAULT '',
                    subtitle      TEXT NOT NULL DEFAULT '',
                    section_type  TEXT NOT NULL DEFAULT 'built_in',
                    template      TEXT NOT NULL DEFAULT '',
                    sort_order    INTEGER NOT NULL DEFAULT 0,
                    enabled       BOOLEAN DEFAULT true,
                    settings      JSONB DEFAULT '{}'::jsonb,
                    bg_image      TEXT NOT NULL DEFAULT '',
                    bg_overlay_alpha NUMERIC NOT NULL DEFAULT 0.45,
                    created_at    TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_page_sections_sort ON page_sections (sort_order);

                -- Optional small free-text pointer used by some custom-section
                -- templates as a single-field "settings" hint. The rsvp_form
                -- template stashes the event slug here so the admin doesn't
                -- need a whole settings panel just to pick which event to show.
                ALTER TABLE page_sections
                  ADD COLUMN IF NOT EXISTS subtitle TEXT NOT NULL DEFAULT '';

                -- =============================================================
                -- STANDALONE PAGES (Task #71) — admin-authored extra pages
                -- =============================================================
                -- The site has always been a single-page app at "/". This
                -- table backs admin-authored extra pages reachable at
                -- /p/<slug>, each composed of one or more existing
                -- page_sections (many-to-many via page_section_assignments).
                -- The same section can live on the homepage AND on a
                -- standalone page — content is reused, not duplicated.
                CREATE TABLE IF NOT EXISTS pages (
                    id               SERIAL PRIMARY KEY,
                    slug             TEXT UNIQUE NOT NULL,
                    title            TEXT NOT NULL DEFAULT '',
                    meta_description TEXT NOT NULL DEFAULT '',
                    sort_order       INTEGER NOT NULL DEFAULT 0,
                    enabled          BOOLEAN NOT NULL DEFAULT TRUE,
                    created_at       TIMESTAMP DEFAULT NOW(),
                    updated_at       TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_pages_sort ON pages (sort_order);

                -- Section <-> page assignment join table. sort_order is
                -- per-page (not global) so the same section can appear at
                -- different positions on different pages.
                CREATE TABLE IF NOT EXISTS page_section_assignments (
                    id          SERIAL PRIMARY KEY,
                    page_id     INTEGER NOT NULL REFERENCES pages(id) ON DELETE CASCADE,
                    section_id  INTEGER NOT NULL REFERENCES page_sections(id) ON DELETE CASCADE,
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    UNIQUE (page_id, section_id)
                );
                CREATE INDEX IF NOT EXISTS idx_psa_page_sort
                    ON page_section_assignments (page_id, sort_order);

                -- =============================================================
                -- CUSTOM SECTION ITEMS
                -- =============================================================
                -- Content items for custom sections. Each item belongs to a
                -- page_section via section_id. The fields used depend on the
                -- section's template (cards_grid uses title/image/content,
                -- stats_counter uses title/subtitle for number/label, etc.)
                CREATE TABLE IF NOT EXISTS custom_section_items (
                    id          SERIAL PRIMARY KEY,
                    section_id  INTEGER NOT NULL REFERENCES page_sections(id) ON DELETE CASCADE,
                    title       TEXT NOT NULL DEFAULT '',
                    subtitle    TEXT NOT NULL DEFAULT '',
                    content     TEXT NOT NULL DEFAULT '',
                    image_url   TEXT NOT NULL DEFAULT '',
                    link_url    TEXT NOT NULL DEFAULT '',
                    link_text   TEXT NOT NULL DEFAULT '',
                    icon        TEXT NOT NULL DEFAULT '',
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    extra_data  JSONB DEFAULT '{}'::jsonb,
                    created_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_custom_items_section ON custom_section_items (section_id, sort_order);

                -- =============================================================
                -- BLOG POSTS
                -- =============================================================
                -- Database-driven blog with gallery-style preview cards on the
                -- landing page. Each post has SEO fields, cover image, and
                -- supports draft/published workflow.
                CREATE TABLE IF NOT EXISTS blog_posts (
                    id              SERIAL PRIMARY KEY,
                    slug            TEXT UNIQUE NOT NULL,
                    title           TEXT NOT NULL,
                    subtitle        TEXT DEFAULT '',
                    excerpt         TEXT DEFAULT '',
                    content         TEXT DEFAULT '',
                    cover_image     TEXT DEFAULT '',
                    author          TEXT DEFAULT '',
                    category        TEXT DEFAULT '',
                    tags            TEXT DEFAULT '',
                    status          TEXT DEFAULT 'draft',
                    seo_title       TEXT DEFAULT '',
                    seo_description TEXT DEFAULT '',
                    published_at    TIMESTAMP,
                    created_at      TIMESTAMP DEFAULT NOW(),
                    updated_at      TIMESTAMP DEFAULT NOW(),
                    sort_order      INTEGER DEFAULT 0
                );
                CREATE INDEX IF NOT EXISTS idx_blog_posts_status ON blog_posts (status);
                CREATE INDEX IF NOT EXISTS idx_blog_posts_slug ON blog_posts (slug);
                CREATE INDEX IF NOT EXISTS idx_blog_posts_sort ON blog_posts (sort_order);

                -- =============================================================
                -- EVENTS
                -- =============================================================
                -- Industry-agnostic event listings (workshops, webinars, retreats,
                -- store openings, concerts, etc.). Each event has a public detail
                -- page at /event/<slug> with an optional RSVP form.
                --
                -- status: 'draft' (admin-only), 'published' (visible to public),
                --         or 'cancelled' (visible but RSVPs blocked).
                -- capacity: NULL means unlimited; otherwise the RSVP endpoint
                --           rejects new sign-ups once SUM(guests) >= capacity.
                -- price: free-form text so admins can write "Free", "$25", or
                --        "From $99 — pay at the door" without numeric coercion.
                CREATE TABLE IF NOT EXISTS events (
                    id          SERIAL PRIMARY KEY,
                    title       TEXT NOT NULL,
                    slug        VARCHAR(120) UNIQUE NOT NULL,
                    description TEXT NOT NULL DEFAULT '',
                    image_url   TEXT NOT NULL DEFAULT '',
                    start_at    TIMESTAMP WITH TIME ZONE NOT NULL,
                    end_at      TIMESTAMP WITH TIME ZONE,
                    location    TEXT NOT NULL DEFAULT '',
                    capacity    INTEGER,
                    price       TEXT NOT NULL DEFAULT 'Free',
                    status      VARCHAR(20) NOT NULL DEFAULT 'published',
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP DEFAULT NOW(),
                    updated_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_events_status ON events (status);
                CREATE INDEX IF NOT EXISTS idx_events_slug   ON events (slug);
                CREATE INDEX IF NOT EXISTS idx_events_start  ON events (start_at);

                -- RSVPs are optional per event. Capacity is enforced at write
                -- time in the API layer, not via a DB trigger, to keep the
                -- public flow simple and to allow admins to manually exceed it.
                CREATE TABLE IF NOT EXISTS event_rsvps (
                    id         SERIAL PRIMARY KEY,
                    event_id   INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
                    name       TEXT NOT NULL,
                    email      TEXT NOT NULL,
                    phone      TEXT NOT NULL DEFAULT '',
                    guests     INTEGER NOT NULL DEFAULT 1,
                    notes      TEXT NOT NULL DEFAULT '',
                    created_at TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_event_rsvps_event ON event_rsvps (event_id);

                -- Optional payment columns (added after launch). Keep nullable
                -- so existing free events keep working unchanged.
                --   price_mode: 'free' | 'paid' | 'donation'
                --   price_amount: cents charged when price_mode='paid'
                --   min_donation: cents minimum when price_mode='donation' (NULL = any)
                --   currency: ISO-4217 lower-case (e.g. 'usd', 'eur')
                ALTER TABLE events
                  ADD COLUMN IF NOT EXISTS price_mode    VARCHAR(20) NOT NULL DEFAULT 'free',
                  ADD COLUMN IF NOT EXISTS price_amount  INTEGER,
                  ADD COLUMN IF NOT EXISTS min_donation  INTEGER,
                  ADD COLUMN IF NOT EXISTS currency      VARCHAR(3) NOT NULL DEFAULT 'usd';

                -- Track Stripe Checkout state on each RSVP. payment_status:
                --   'none'    — free event, no payment expected
                --   'pending' — Checkout session created, awaiting webhook
                --   'paid'    — checkout.session.completed received
                ALTER TABLE event_rsvps
                  ADD COLUMN IF NOT EXISTS payment_status    VARCHAR(20) NOT NULL DEFAULT 'none',
                  ADD COLUMN IF NOT EXISTS payment_amount    INTEGER,
                  ADD COLUMN IF NOT EXISTS stripe_session_id VARCHAR(255);
                CREATE INDEX IF NOT EXISTS idx_event_rsvps_session ON event_rsvps (stripe_session_id);

                -- =============================================================
                -- VIDEO GALLERY ITEMS
                -- =============================================================
                -- A library of videos shown in a gallery section. Each item
                -- has its own thumbnail and a video URL (typically pointing to
                -- a /uploads/... mp4 from the Media Library).
                CREATE TABLE IF NOT EXISTS video_gallery_items (
                    id            SERIAL PRIMARY KEY,
                    title         TEXT NOT NULL DEFAULT '',
                    description   TEXT NOT NULL DEFAULT '',
                    video_url     TEXT NOT NULL DEFAULT '',
                    thumbnail_url TEXT NOT NULL DEFAULT '',
                    sort_order    INTEGER NOT NULL DEFAULT 0,
                    created_at    TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_video_gallery_sort ON video_gallery_items (sort_order);

                -- =============================================================
                -- PODCAST EPISODES
                -- =============================================================
                -- An audio podcast / talks library. Each episode has a cover
                -- image, an audio URL (mp3 from the Media Library), and an
                -- optional episode number.
                CREATE TABLE IF NOT EXISTS podcast_episodes (
                    id             SERIAL PRIMARY KEY,
                    title          TEXT NOT NULL DEFAULT '',
                    description    TEXT NOT NULL DEFAULT '',
                    audio_url      TEXT NOT NULL DEFAULT '',
                    cover_image    TEXT NOT NULL DEFAULT '',
                    episode_number INTEGER,
                    published_at   TIMESTAMP,
                    sort_order     INTEGER NOT NULL DEFAULT 0,
                    created_at     TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_podcast_sort ON podcast_episodes (sort_order);

                -- =============================================================
                -- COMMERCE — Products, Customers, Orders, Order Items
                -- =============================================================
                CREATE TABLE IF NOT EXISTS products (
                    id              SERIAL PRIMARY KEY,
                    slug            VARCHAR(150) UNIQUE NOT NULL,
                    name            TEXT NOT NULL DEFAULT '',
                    description     TEXT NOT NULL DEFAULT '',
                    price_cents     INTEGER NOT NULL DEFAULT 0,
                    currency        VARCHAR(3) NOT NULL DEFAULT 'USD',
                    image_url       TEXT NOT NULL DEFAULT '',
                    gallery_images  JSONB NOT NULL DEFAULT '[]'::jsonb,
                    stock           INTEGER NOT NULL DEFAULT 0,
                    track_inventory BOOLEAN NOT NULL DEFAULT true,
                    active          BOOLEAN NOT NULL DEFAULT true,
                    sort_order      INTEGER NOT NULL DEFAULT 0,
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_products_active ON products (active);
                CREATE INDEX IF NOT EXISTS idx_products_sort ON products (sort_order);

                CREATE TABLE IF NOT EXISTS customers (
                    id                 SERIAL PRIMARY KEY,
                    email              VARCHAR(255) UNIQUE NOT NULL,
                    name               TEXT NOT NULL DEFAULT '',
                    stripe_customer_id VARCHAR(100) DEFAULT '',
                    created_at         TIMESTAMP DEFAULT NOW()
                );

                CREATE TABLE IF NOT EXISTS orders (
                    id                       SERIAL PRIMARY KEY,
                    order_number             VARCHAR(40) UNIQUE NOT NULL,
                    customer_id              INTEGER REFERENCES customers(id) ON DELETE SET NULL,
                    customer_email           VARCHAR(255) NOT NULL DEFAULT '',
                    customer_name            TEXT NOT NULL DEFAULT '',
                    status                   VARCHAR(20) NOT NULL DEFAULT 'pending',
                    subtotal_cents           INTEGER NOT NULL DEFAULT 0,
                    total_cents              INTEGER NOT NULL DEFAULT 0,
                    currency                 VARCHAR(3) NOT NULL DEFAULT 'USD',
                    stripe_payment_intent_id VARCHAR(100) DEFAULT '',
                    stripe_charge_id         VARCHAR(100) DEFAULT '',
                    shipping_address         JSONB NOT NULL DEFAULT '{}'::jsonb,
                    notes                    TEXT NOT NULL DEFAULT '',
                    created_at               TIMESTAMP DEFAULT NOW(),
                    paid_at                  TIMESTAMP
                );
                CREATE INDEX IF NOT EXISTS idx_orders_status ON orders (status);
                CREATE INDEX IF NOT EXISTS idx_orders_created ON orders (created_at);
                CREATE INDEX IF NOT EXISTS idx_orders_pi ON orders (stripe_payment_intent_id);

                CREATE TABLE IF NOT EXISTS order_items (
                    id               SERIAL PRIMARY KEY,
                    order_id         INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
                    product_id       INTEGER REFERENCES products(id) ON DELETE SET NULL,
                    product_name     TEXT NOT NULL DEFAULT '',
                    unit_price_cents INTEGER NOT NULL DEFAULT 0,
                    quantity         INTEGER NOT NULL DEFAULT 1
                );
                CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items (order_id);

                -- =============================================================
                -- PAGE VIEWS — Visitor Analytics
                -- =============================================================
                -- Tracks individual page views for the visitor analytics
                -- dashboard. Captures session, referrer, UTM params, device
                -- info, and session duration for aggregated reporting.
                CREATE TABLE IF NOT EXISTS page_views (
                    id                SERIAL PRIMARY KEY,
                    session_id        VARCHAR(100) NOT NULL,
                    visitor_id        VARCHAR(100) DEFAULT '',
                    page_url          TEXT NOT NULL,
                    referrer_url      TEXT DEFAULT '',
                    utm_source        TEXT DEFAULT '',
                    utm_medium        TEXT DEFAULT '',
                    utm_campaign      TEXT DEFAULT '',
                    utm_term          TEXT DEFAULT '',
                    utm_content       TEXT DEFAULT '',
                    ip_address        VARCHAR(45) DEFAULT '',
                    browser           TEXT DEFAULT '',
                    os                TEXT DEFAULT '',
                    device_type       TEXT DEFAULT 'desktop',
                    screen_resolution TEXT DEFAULT '',
                    language          TEXT DEFAULT '',
                    country           TEXT DEFAULT '',
                    duration_seconds  INTEGER DEFAULT 0,
                    created_at        TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_page_views_session ON page_views (session_id);
                CREATE INDEX IF NOT EXISTS idx_page_views_created ON page_views (created_at);
                CREATE INDEX IF NOT EXISTS idx_page_views_page ON page_views (page_url);
            """)

            cur.execute("""
                CREATE TABLE IF NOT EXISTS sphere_settings (
                    id              INTEGER PRIMARY KEY DEFAULT 1,
                    enabled         BOOLEAN DEFAULT false,
                    heading_text    TEXT NOT NULL DEFAULT '',
                    view_mode       TEXT NOT NULL DEFAULT 'sections',
                    particle_count  INTEGER NOT NULL DEFAULT 1500,
                    rotation_speed  REAL NOT NULL DEFAULT 0.0005,
                    sphere_radius   REAL NOT NULL DEFAULT 9,
                    image_size      REAL NOT NULL DEFAULT 1.5,
                    image_source    TEXT NOT NULL DEFAULT 'gallery',
                    position_randomness REAL NOT NULL DEFAULT 4,
                    particle_opacity REAL NOT NULL DEFAULT 1,
                    zoom_min        REAL NOT NULL DEFAULT 5,
                    zoom_max        REAL NOT NULL DEFAULT 30,
                    card_scale      REAL NOT NULL DEFAULT 1.0,
                    card_gap        REAL NOT NULL DEFAULT 2.5,
                    updated_at      TIMESTAMP DEFAULT NOW()
                );

                INSERT INTO sphere_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

                CREATE TABLE IF NOT EXISTS sphere_images (
                    id          SERIAL PRIMARY KEY,
                    image_url   TEXT NOT NULL DEFAULT '',
                    caption     TEXT NOT NULL DEFAULT '',
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_sphere_images_sort ON sphere_images (sort_order);
            """)

            # =================================================================
            # VOICE AGENT TABLES
            # =================================================================
            # The voice agent is a proactive AI feature: it can play a
            # personalized voice intro when a visitor lands on the site
            # (matched against UTM source/medium/campaign), and optionally
            # support full back-and-forth voice conversations.
            #
            # Three tables power the system:
            #   1. voice_settings  — singleton row for global toggles
            #   2. voice_intros    — predefined intro messages (pre-generated audio)
            #   3. voice_usage_log — usage tracking (for billing and analytics)
            # =================================================================

            cur.execute("""
                -- Singleton settings row (id=1) for global voice configuration.
                -- Three independent toggles let the site owner enable/disable
                -- each voice feature without affecting the others.
                CREATE TABLE IF NOT EXISTS voice_settings (
                    id                       INTEGER PRIMARY KEY DEFAULT 1,
                    enabled_intros           BOOLEAN NOT NULL DEFAULT false,
                    enabled_visitor_voice    BOOLEAN NOT NULL DEFAULT false,
                    enabled_ai_voice         BOOLEAN NOT NULL DEFAULT false,
                    default_voice            TEXT NOT NULL DEFAULT 'alloy',
                    tts_model                TEXT NOT NULL DEFAULT 'tts-1',
                    autoplay_strategy        TEXT NOT NULL DEFAULT 'gesture',
                    -- Multi-provider support (added in v2 of voice agent):
                    -- tts_provider: 'openai' (default) or 'elevenlabs' (premium)
                    -- stt_provider: 'webspeech' (default, free) or 'whisper' (premium)
                    -- premium_enabled: master kill-switch for paid providers; when
                    --   false, ElevenLabs/Whisper are unavailable even if keys exist
                    -- elevenlabs_voice_id / elevenlabs_model: ElevenLabs config
                    tts_provider             TEXT NOT NULL DEFAULT 'openai',
                    stt_provider             TEXT NOT NULL DEFAULT 'webspeech',
                    premium_enabled          BOOLEAN NOT NULL DEFAULT false,
                    elevenlabs_voice_id      TEXT NOT NULL DEFAULT '',
                    elevenlabs_model         TEXT NOT NULL DEFAULT 'eleven_turbo_v2_5',
                    updated_at               TIMESTAMP DEFAULT NOW()
                );

                -- Idempotent column adds for upgrades from v1 schema. Each
                -- ADD COLUMN IF NOT EXISTS is safe to re-run on existing DBs.
                ALTER TABLE voice_settings ADD COLUMN IF NOT EXISTS tts_provider TEXT NOT NULL DEFAULT 'openai';
                ALTER TABLE voice_settings ADD COLUMN IF NOT EXISTS stt_provider TEXT NOT NULL DEFAULT 'webspeech';
                ALTER TABLE voice_settings ADD COLUMN IF NOT EXISTS premium_enabled BOOLEAN NOT NULL DEFAULT false;
                ALTER TABLE voice_settings ADD COLUMN IF NOT EXISTS elevenlabs_voice_id TEXT NOT NULL DEFAULT '';
                ALTER TABLE voice_settings ADD COLUMN IF NOT EXISTS elevenlabs_model TEXT NOT NULL DEFAULT 'eleven_turbo_v2_5';

                -- Predefined intro voice notes. Each intro has a message text
                -- and a pre-generated audio file (cached to avoid re-paying
                -- TTS cost on every visit). Intros can be filtered by UTM
                -- params or referrer so different traffic sources hear
                -- different welcomes (e.g. Google Ads visitors hear "Welcome
                -- from Google!", Instagram visitors hear something else).
                CREATE TABLE IF NOT EXISTS voice_intros (
                    id              SERIAL PRIMARY KEY,
                    name            TEXT NOT NULL DEFAULT '',
                    message_text    TEXT NOT NULL DEFAULT '',
                    audio_url       TEXT NOT NULL DEFAULT '',
                    voice_id        TEXT NOT NULL DEFAULT 'alloy',
                    utm_source      TEXT NOT NULL DEFAULT '',
                    utm_medium      TEXT NOT NULL DEFAULT '',
                    utm_campaign    TEXT NOT NULL DEFAULT '',
                    referrer_match  TEXT NOT NULL DEFAULT '',
                    priority        INTEGER NOT NULL DEFAULT 0,
                    enabled         BOOLEAN NOT NULL DEFAULT true,
                    play_count      INTEGER NOT NULL DEFAULT 0,
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_voice_intros_priority ON voice_intros (priority DESC, id);
                CREATE INDEX IF NOT EXISTS idx_voice_intros_enabled ON voice_intros (enabled);

                -- Usage log — tracks every TTS generation, intro play, and
                -- speech-to-text request. Used for billing customers based
                -- on their voice feature consumption.
                -- feature_type is one of: 'intro_play', 'tts_generate',
                -- 'tts_cached', 'stt_request'.
                CREATE TABLE IF NOT EXISTS voice_usage_log (
                    id            SERIAL PRIMARY KEY,
                    session_id    VARCHAR(100) DEFAULT '',
                    feature_type  VARCHAR(40) NOT NULL DEFAULT '',
                    char_count    INTEGER NOT NULL DEFAULT 0,
                    voice_id      TEXT NOT NULL DEFAULT '',
                    intro_id      INTEGER,
                    created_at    TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_voice_usage_created ON voice_usage_log (created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_voice_usage_feature ON voice_usage_log (feature_type);

                -- =============================================================
                -- AGENTIC SKILLS + PRESENTATIONS (Phase A)
                -- =============================================================
                -- Presentations: an admin-managed (or AI-generated) deck of
                -- ordered slides. Each slide carries its own title/body/image
                -- and an optional narration_text the voice agent reads aloud
                -- before auto-advancing. Auto_play=false means the AI offers
                -- the deck first ("want me to walk you through it?") before
                -- launching the overlay; auto_play=true means the AI launches
                -- it immediately when relevant.
                CREATE TABLE IF NOT EXISTS presentations (
                    id              SERIAL PRIMARY KEY,
                    slug            VARCHAR(120) UNIQUE NOT NULL,
                    title           TEXT NOT NULL DEFAULT '',
                    description     TEXT NOT NULL DEFAULT '',
                    cover_image_url TEXT NOT NULL DEFAULT '',
                    source          VARCHAR(20) NOT NULL DEFAULT 'admin',
                    auto_play       BOOLEAN NOT NULL DEFAULT false,
                    enabled         BOOLEAN NOT NULL DEFAULT true,
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_presentations_slug ON presentations (slug);

                CREATE TABLE IF NOT EXISTS presentation_slides (
                    id              SERIAL PRIMARY KEY,
                    presentation_id INTEGER NOT NULL REFERENCES presentations(id) ON DELETE CASCADE,
                    order_index     INTEGER NOT NULL DEFAULT 0,
                    title           TEXT NOT NULL DEFAULT '',
                    body            TEXT NOT NULL DEFAULT '',
                    image_url       TEXT NOT NULL DEFAULT '',
                    narration_text  TEXT NOT NULL DEFAULT ''
                );
                CREATE INDEX IF NOT EXISTS idx_presentation_slides_presentation ON presentation_slides (presentation_id, order_index);

                -- Skills registry: every tool the AI can call lives here as a
                -- row. Built-in skills (the lookup_* family + presentation
                -- skills) are auto-synced on startup. The `enabled` flag is
                -- the on/off switch the admin flips in the Skills tab — when
                -- false, the skill is filtered out of the tool schema sent to
                -- the model, so the AI literally cannot call it that turn.
                -- config_json holds per-skill JSON config (e.g. default
                -- from-email, max scrape depth) — populated as needed by
                -- future action skills.
                CREATE TABLE IF NOT EXISTS agent_skills (
                    id              SERIAL PRIMARY KEY,
                    name            VARCHAR(100) UNIQUE NOT NULL,
                    display_name    TEXT NOT NULL DEFAULT '',
                    description     TEXT NOT NULL DEFAULT '',
                    category        VARCHAR(40) NOT NULL DEFAULT 'lookup',
                    builtin         BOOLEAN NOT NULL DEFAULT true,
                    enabled         BOOLEAN NOT NULL DEFAULT true,
                    config_json     JSONB DEFAULT '{}'::jsonb,
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_agent_skills_enabled ON agent_skills (enabled);
                CREATE INDEX IF NOT EXISTS idx_agent_skills_category ON agent_skills (category);

                -- Per-invocation log row for every skill call (in addition to
                -- the per-turn tool_calls_json on chat_messages). Powers the
                -- Skills tab "recent usage" view and lets us spot skills
                -- erroring out or being heavily used.
                CREATE TABLE IF NOT EXISTS skill_usage_log (
                    id           SERIAL PRIMARY KEY,
                    session_id   VARCHAR(100) DEFAULT '',
                    skill_name   VARCHAR(100) NOT NULL DEFAULT '',
                    args_json    JSONB,
                    row_count    INTEGER NOT NULL DEFAULT 0,
                    duration_ms  INTEGER NOT NULL DEFAULT 0,
                    error        TEXT NOT NULL DEFAULT '',
                    created_at   TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_skill_usage_skill ON skill_usage_log (skill_name, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_skill_usage_created ON skill_usage_log (created_at DESC);

                -- Singleton (id=1 only) holding the active LLM provider +
                -- model choices. Admin can flip provider OpenAI <-> Claude
                -- and pick the model per provider. Read on every chat turn.
                CREATE TABLE IF NOT EXISTS agent_provider_settings (
                    id            INTEGER PRIMARY KEY DEFAULT 1,
                    provider      VARCHAR(20) NOT NULL DEFAULT 'openai',
                    openai_model  TEXT NOT NULL DEFAULT 'gpt-4o-mini',
                    claude_model  TEXT NOT NULL DEFAULT 'claude-sonnet-4-5',
                    updated_at    TIMESTAMP DEFAULT NOW()
                );

                -- Persistent transcript for the new admin-side chat surface.
                -- Two separate "modes" share the table:
                --   mode='visitor' rows are the admin previewing the visitor
                --   agent (so they don't pollute real visitor analytics).
                --   mode='admin'   rows are the admin agent with elevated
                --   tools (run SQL, manage skills, edit content, analytics).
                -- session_id is generated client-side and persisted in
                -- localStorage so the admin can keep one ongoing thread
                -- per mode across reloads. tool_calls_json (assistant rows)
                -- captures the same per-step trace used in the visitor
                -- chat history view, including admin-tool calls.
                CREATE TABLE IF NOT EXISTS admin_chat_messages (
                    id              SERIAL PRIMARY KEY,
                    session_id      VARCHAR(100) NOT NULL DEFAULT '',
                    mode            VARCHAR(20)  NOT NULL DEFAULT 'admin',
                    role            VARCHAR(20)  NOT NULL DEFAULT 'user',
                    content         TEXT         NOT NULL DEFAULT '',
                    tool_calls_json JSONB,
                    tool_call_id    TEXT,
                    tool_name       TEXT,
                    created_at      TIMESTAMP    DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_admin_chat_session
                    ON admin_chat_messages (session_id, mode, created_at);
                -- Per-message metadata so the chat UI can rehydrate the
                -- token/cost badge under each assistant turn AND the
                -- rows/ms badge inside each tool card after a refresh.
                -- usage_json on assistant rows: {provider,model,
                -- prompt_tokens,completion_tokens,total_tokens,cost_usd}.
                -- tool_meta_json on tool rows: {rows,ms,error}.
                ALTER TABLE admin_chat_messages
                    ADD COLUMN IF NOT EXISTS usage_json JSONB;
                ALTER TABLE admin_chat_messages
                    ADD COLUMN IF NOT EXISTS tool_meta_json JSONB;

                -- One row per admin-chat conversation. The session_id used
                -- to be only a localStorage value with no server-side
                -- record beyond the message rows it produced; this table
                -- now holds per-session metadata (title, pinned) AND per-
                -- session config overrides (model, system prompt,
                -- disabled tools) that the stream loop reads on each
                -- turn. Created lazily by _admin_chat_get_or_create_session
                -- so any pre-existing session_id in admin_chat_messages
                -- self-heals on its next message; a startup backfill (see
                -- _backfill_admin_chat_sessions below) also seeds rows
                -- for historical sessions so the sidebar shows them.
                CREATE TABLE IF NOT EXISTS admin_chat_sessions (
                    id                     SERIAL PRIMARY KEY,
                    session_id             VARCHAR(100) NOT NULL UNIQUE,
                    mode                   VARCHAR(20)  NOT NULL DEFAULT 'admin',
                    title                  TEXT         NOT NULL DEFAULT '',
                    pinned                 BOOLEAN      NOT NULL DEFAULT false,
                    model                  TEXT         NOT NULL DEFAULT '',
                    system_prompt_override TEXT         NOT NULL DEFAULT '',
                    disabled_tools_json    JSONB        NOT NULL DEFAULT '[]'::jsonb,
                    created_at             TIMESTAMP    DEFAULT NOW(),
                    updated_at             TIMESTAMP    DEFAULT NOW(),
                    last_message_at        TIMESTAMP    DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_admin_chat_sessions_recent
                    ON admin_chat_sessions (mode, pinned DESC, last_message_at DESC);

                -- Admin assistant: every WRITE the assistant wants to make
                -- is parked here as a pending action with a preview, and
                -- only runs after the owner clicks Approve in the chat UI.
                CREATE TABLE IF NOT EXISTS admin_pending_actions (
                    id              SERIAL PRIMARY KEY,
                    session_id      VARCHAR(100) NOT NULL DEFAULT '',
                    action_type     VARCHAR(20)  NOT NULL,
                    target_table    VARCHAR(100),
                    target_id       INTEGER,
                    payload_json    JSONB,
                    preview         TEXT         NOT NULL DEFAULT '',
                    status          VARCHAR(20)  NOT NULL DEFAULT 'pending',
                    result_json     JSONB,
                    error_text      TEXT,
                    created_at      TIMESTAMP    DEFAULT NOW(),
                    decided_at      TIMESTAMP
                );
                CREATE INDEX IF NOT EXISTS idx_admin_pending_session
                    ON admin_pending_actions (session_id, created_at);
                CREATE INDEX IF NOT EXISTS idx_admin_pending_status
                    ON admin_pending_actions (status, created_at);

                -- Snapshot of any "settings" row before the admin chat
                -- assistant overwrites or deletes it. Powers the Recent
                -- Changes panel and the one-click Revert button. Each row
                -- is a self-contained "undo this change" record.
                CREATE TABLE IF NOT EXISTS admin_setting_snapshots (
                    id              SERIAL PRIMARY KEY,
                    table_name      VARCHAR(100) NOT NULL,
                    row_id          INTEGER,
                    snapshot_json   JSONB        NOT NULL,
                    action_id       INTEGER,
                    reason          TEXT         NOT NULL DEFAULT '',
                    reverted_at     TIMESTAMP,
                    created_at      TIMESTAMP    DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_admin_snap_recent
                    ON admin_setting_snapshots (created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_admin_snap_table
                    ON admin_setting_snapshots (table_name, row_id, created_at DESC);

                -- Knowledge entries powering the lookup_knowledge skill.
                -- Each row is a small chunk of admin-authored prose (FAQ,
                -- policy text, product detail) that the consumer agent
                -- can search by keyword.
                CREATE TABLE IF NOT EXISTS custom_knowledge_entries (
                    id          SERIAL PRIMARY KEY,
                    topic       VARCHAR(200) NOT NULL DEFAULT '',
                    content     TEXT         NOT NULL DEFAULT '',
                    enabled     BOOLEAN      NOT NULL DEFAULT true,
                    created_at  TIMESTAMP    DEFAULT NOW(),
                    updated_at  TIMESTAMP    DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_custom_knowledge_enabled
                    ON custom_knowledge_entries (enabled);

                -- Webhook skills — each row is one tool the consumer
                -- agent can call. Calling the tool POSTs (or GETs) to
                -- url with the tool args as the JSON body / query
                -- string. URL is validated at call time (no
                -- private/loopback/link-local) to prevent SSRF.
                CREATE TABLE IF NOT EXISTS custom_webhook_skills (
                    id                  SERIAL PRIMARY KEY,
                    name                VARCHAR(100) NOT NULL UNIQUE,
                    description         TEXT         NOT NULL DEFAULT '',
                    url                 TEXT         NOT NULL DEFAULT '',
                    method              VARCHAR(10)  NOT NULL DEFAULT 'POST',
                    headers_json        JSONB        DEFAULT '{}'::jsonb,
                    args_schema_json    JSONB        DEFAULT '{"type":"object","properties":{},"required":[]}'::jsonb,
                    timeout_seconds     INTEGER      NOT NULL DEFAULT 10,
                    enabled             BOOLEAN      NOT NULL DEFAULT false,
                    created_at          TIMESTAMP    DEFAULT NOW(),
                    updated_at          TIMESTAMP    DEFAULT NOW()
                );

                -- SQL skills — each row is one read-only SELECT-style
                -- tool the consumer agent can call. sql_template uses
                -- psycopg2 named-parameter style (%(name)s) and is
                -- bound at call time. Subject to SELECT-only / 100-row
                -- / 5-second guardrails identical to the admin
                -- read-only SQL tool.
                CREATE TABLE IF NOT EXISTS custom_sql_skills (
                    id                  SERIAL PRIMARY KEY,
                    name                VARCHAR(100) NOT NULL UNIQUE,
                    description         TEXT         NOT NULL DEFAULT '',
                    sql_template        TEXT         NOT NULL DEFAULT '',
                    args_schema_json    JSONB        DEFAULT '{"type":"object","properties":{},"required":[]}'::jsonb,
                    -- Datahub (task 056): which data source this query runs
                    -- against. 0 = the app's own DB; other ids reference
                    -- external_data_connections. Default 0 = prior behavior.
                    connection_id       INTEGER      NOT NULL DEFAULT 0,
                    enabled             BOOLEAN      NOT NULL DEFAULT false,
                    created_at          TIMESTAMP    DEFAULT NOW(),
                    updated_at          TIMESTAMP    DEFAULT NOW()
                );

                -- MCP (Model Context Protocol) connector registry. Each
                -- row is one external MCP server the admin has wired
                -- in. We discover the server's tools and cache them in
                -- mcp_tools_cache. Enabled tools are then mirrored into
                -- agent_skills so the existing dispatcher can route to
                -- them. allowed_for_velo defaults FALSE on purpose so
                -- a freshly added server never leaks tools to the
                -- consumer agent without an explicit toggle.
                --   transport: 'http' (Streamable HTTP, JSON-RPC 2.0
                --              POST) or 'sse' (legacy SSE-only).
                --   auth_type: 'none' | 'bearer' | 'header'. v2 will
                --              add 'oauth' driven by MCP_CONNECTOR_BLUEPRINTS.
                --   connector_type: 'custom' for a free-form URL the
                --              admin pasted in. v2 OAuth blueprints
                --              (e.g. 'linear', 'github') will stamp
                --              their own slug here.
                CREATE TABLE IF NOT EXISTS mcp_servers (
                    id                  SERIAL PRIMARY KEY,
                    name                VARCHAR(100) NOT NULL UNIQUE,
                    description         TEXT         NOT NULL DEFAULT '',
                    transport           VARCHAR(20)  NOT NULL DEFAULT 'http',
                    url                 TEXT         NOT NULL DEFAULT '',
                    auth_type           VARCHAR(20)  NOT NULL DEFAULT 'none',
                    auth_header_name    VARCHAR(100) NOT NULL DEFAULT '',
                    auth_credential     TEXT         NOT NULL DEFAULT '',
                    enabled             BOOLEAN      NOT NULL DEFAULT true,
                    allowed_for_admin   BOOLEAN      NOT NULL DEFAULT true,
                    allowed_for_velo    BOOLEAN      NOT NULL DEFAULT false,
                    connector_type      VARCHAR(50)  NOT NULL DEFAULT 'custom',
                    oauth_state         JSONB        DEFAULT '{}'::jsonb,
                    last_test_at        TIMESTAMP,
                    last_test_ok        BOOLEAN,
                    last_test_error     TEXT         NOT NULL DEFAULT '',
                    created_at          TIMESTAMP    DEFAULT NOW(),
                    updated_at          TIMESTAMP    DEFAULT NOW()
                );

                -- Per-server tool catalog. Refreshed on demand (Test /
                -- Refresh Tools buttons) — we don't query the upstream
                -- server on every chat turn. ON DELETE CASCADE keeps
                -- the cache aligned when a server is removed.
                CREATE TABLE IF NOT EXISTS mcp_tools_cache (
                    id                  SERIAL PRIMARY KEY,
                    server_id           INTEGER      NOT NULL
                                        REFERENCES mcp_servers(id)
                                        ON DELETE CASCADE,
                    tool_name           VARCHAR(200) NOT NULL,
                    description         TEXT         NOT NULL DEFAULT '',
                    input_schema_json   JSONB        DEFAULT '{"type":"object","properties":{},"required":[]}'::jsonb,
                    enabled             BOOLEAN      NOT NULL DEFAULT true,
                    last_synced_at      TIMESTAMP    DEFAULT NOW(),
                    UNIQUE(server_id, tool_name)
                );
                CREATE INDEX IF NOT EXISTS idx_mcp_tools_server
                    ON mcp_tools_cache (server_id);

                -- =============================================================
                -- TENANCY + PLANS + FEATURE FLAGS  (Phase 1 multi-tenant prep)
                -- =============================================================
                -- For now there is exactly ONE tenant (id=1) and the whole
                -- codebase calls current_tenant_id() which returns 1. Every
                -- capability check goes through tenant_has_feature(name) so
                -- we can later flip features per-tenant from a super-admin
                -- screen without touching call-sites.
                --
                --   plans          — tier definitions (solo / growth / enterprise).
                --   tenants        — one row per customer site (today: 1).
                --   tenant_features— enabled/disabled state per (tenant, feature).
                --   feature_addons — one-off feature unlocks layered on top of plan.
                --
                -- Default seed: tenant_id=1 on plan=growth, every feature
                -- registered in _FEATURE_REGISTRY enabled=true so the existing
                -- behaviour is preserved.
                CREATE TABLE IF NOT EXISTS plans (
                    id          SERIAL PRIMARY KEY,
                    slug        VARCHAR(40) NOT NULL UNIQUE,
                    name        TEXT        NOT NULL,
                    description TEXT        NOT NULL DEFAULT '',
                    sort_order  INTEGER     NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP   DEFAULT NOW()
                );

                CREATE TABLE IF NOT EXISTS tenants (
                    id          SERIAL PRIMARY KEY,
                    name        TEXT        NOT NULL DEFAULT 'Default Tenant',
                    plan_id     INTEGER     REFERENCES plans(id) ON DELETE SET NULL,
                    status      VARCHAR(20) NOT NULL DEFAULT 'active',
                    timezone    VARCHAR(64) NOT NULL DEFAULT 'UTC',
                    created_at  TIMESTAMP   DEFAULT NOW(),
                    updated_at  TIMESTAMP   DEFAULT NOW()
                );
                -- Older deployments created `tenants` before the
                -- timezone column existed. This idempotent ALTER lets
                -- the weekly digest fire on the tenant's local Monday
                -- 09:00 instead of UTC. Defaults to 'UTC' so existing
                -- behaviour is preserved unless the admin sets it.
                ALTER TABLE tenants
                    ADD COLUMN IF NOT EXISTS timezone VARCHAR(64) NOT NULL DEFAULT 'UTC';

                CREATE TABLE IF NOT EXISTS tenant_features (
                    id           SERIAL PRIMARY KEY,
                    tenant_id    INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                    feature_name VARCHAR(80) NOT NULL,
                    enabled      BOOLEAN     NOT NULL DEFAULT true,
                    note         TEXT        NOT NULL DEFAULT '',
                    created_at   TIMESTAMP   DEFAULT NOW(),
                    updated_at   TIMESTAMP   DEFAULT NOW(),
                    UNIQUE(tenant_id, feature_name)
                );
                CREATE INDEX IF NOT EXISTS idx_tenant_features_tenant
                    ON tenant_features (tenant_id);

                CREATE TABLE IF NOT EXISTS feature_addons (
                    id           SERIAL PRIMARY KEY,
                    tenant_id    INTEGER     NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
                    feature_name VARCHAR(80) NOT NULL,
                    granted_at   TIMESTAMP   DEFAULT NOW(),
                    note         TEXT        NOT NULL DEFAULT '',
                    UNIQUE(tenant_id, feature_name)
                );

                -- Publishable per-client embed keys for the cross-origin widget.
                -- origin_allowlist is a JSONB array of allowed page origins; the
                -- embed before_request validates the request Origin against it.
                CREATE TABLE IF NOT EXISTS tenant_embed_keys (
                    id               SERIAL PRIMARY KEY,
                    tenant_id        INTEGER NOT NULL DEFAULT 1 REFERENCES tenants(id) ON DELETE CASCADE,
                    embed_key        VARCHAR(64) UNIQUE NOT NULL,
                    label            TEXT NOT NULL DEFAULT '',
                    origin_allowlist JSONB NOT NULL DEFAULT '[]'::jsonb,
                    enabled          BOOLEAN NOT NULL DEFAULT TRUE,
                    created_at       TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_tenant_embed_keys_key
                    ON tenant_embed_keys (embed_key);

                -- Single-use SSO token jti ledger (WordPress-embedded admin).
                -- A token's jti is recorded on first use so it can't be replayed.
                CREATE TABLE IF NOT EXISTS sso_used_jtis (
                    jti         VARCHAR(64) PRIMARY KEY,
                    expires_at  TIMESTAMP NOT NULL
                );
            """)

            # Seed the voice_settings singleton row (idempotent)
            cur.execute("""
                INSERT INTO voice_settings (id) VALUES (1)
                ON CONFLICT (id) DO NOTHING
            """)

            # Seed chatbot_settings singleton if it doesn't exist
            cur.execute("""
                INSERT INTO chatbot_settings (id, enabled, mode, agent_name, agent_role, agent_avatar,
                    greeting, quick_prompts, api_endpoint, embed_code)
                VALUES (1, false, 'builtin', 'AI Assistant', 'Assistant', 'A',
                    'Welcome! I''m your AI assistant. How can I help you today?',
                    '["Browse our offerings", "Tell me more", "What do you offer?", "Show me pricing"]'::jsonb,
                    '/api/chat', '')
                ON CONFLICT (id) DO NOTHING
            """)

            # Seed agent_provider_settings singleton (default OpenAI)
            cur.execute("""
                INSERT INTO agent_provider_settings (id, provider, openai_model, claude_model)
                VALUES (1, 'openai', 'gpt-4o-mini', 'claude-sonnet-4-5')
                ON CONFLICT (id) DO NOTHING
            """)

            # =========================================================
            # PHASE 1 SEED — plans + the single default tenant.
            # tenant_features rows are lazy-seeded the first time
            # tenant_has_feature() is asked about a feature, defaulting
            # to enabled=true so existing behaviour is preserved.
            # =========================================================
            cur.execute("""
                INSERT INTO plans (id, slug, name, description, sort_order) VALUES
                    (1, 'solo',       'Solo',       'Single-site, core features only.',                     10),
                    (2, 'growth',     'Growth',     'Everything in Solo + AI capabilities + integrations.', 20),
                    (3, 'enterprise', 'Enterprise', 'Everything in Growth + multi-site + white-glove SLA.', 30)
                ON CONFLICT (slug) DO NOTHING
            """)
            cur.execute("""
                INSERT INTO tenants (id, name, plan_id, status)
                VALUES (1, 'Default Tenant',
                        (SELECT id FROM plans WHERE slug='growth'),
                        'active')
                ON CONFLICT (id) DO NOTHING
            """)
            # Keep the plans / tenants sequences past the manually-
            # inserted ids so future INSERTs don't collide.
            cur.execute("SELECT setval('plans_id_seq',   (SELECT GREATEST(MAX(id), 1) FROM plans))")
            cur.execute("SELECT setval('tenants_id_seq', (SELECT GREATEST(MAX(id), 1) FROM tenants))")

            # Bulk-seed tenant_features for tenant id=1: every name registered
            # in _FEATURE_REGISTRY gets enabled=its_default (most default True,
            # but the sensitive owner tabs — secrets/developer/performance/
            # snapshot/fleet/llm_provider/stripe — default False so a client
            # doesn't see them until the super admin opts in). ON CONFLICT DO
            # NOTHING preserves any state an admin has already toggled — we only
            # fill in missing rows. This makes /admin/api/tenant/features return
            # a complete grid on first load instead of relying solely on the
            # lazy-touch path.
            for _fname, _label, _tier, _default, _grp in _FEATURE_REGISTRY:
                cur.execute(
                    "INSERT INTO tenant_features (tenant_id, feature_name, enabled, note) "
                    "VALUES (1, %s, %s, 'auto-seeded by init_db') "
                    "ON CONFLICT (tenant_id, feature_name) DO NOTHING",
                    (_fname, bool(_default)),
                )

            # Add new columns to existing tables (safe — does nothing if already present)
            for col_sql in [
                "ALTER TABLE chatbot_settings ADD COLUMN IF NOT EXISTS system_prompt TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_bg TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_section1 TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_section2 TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_accent TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_text TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_glass_border TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_glass_bg TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_font_serif TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_font_sans TEXT NOT NULL DEFAULT ''",
                # First-run wizard marker (Tier 3). NULL means "not yet
                # bootstrapped" → /setup is reachable. Set to NOW() at the
                # end of a successful bootstrap; reset to NULL if bootstrap
                # fails so the operator can retry without manual SQL. Used
                # instead of a sentinel string on site_name so an operator
                # who legitimately names their business "My Site" doesn't
                # leave the wizard publicly reachable.
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS installation_bootstrapped_at TIMESTAMPTZ NULL",
                # Universal master visual tokens — exposed in admin Themes
                # editor so the loading screen, glass surfaces, corner radii
                # and motion timing all flex with the active theme.
                # NUMERIC keeps half-step values (0.85 alpha, 1.25rem radius).
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_loading_bg_alpha NUMERIC NOT NULL DEFAULT 0.85",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_glass_blur_px INTEGER NOT NULL DEFAULT 24",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_radius_rem NUMERIC NOT NULL DEFAULT 1.0",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_transition_sec NUMERIC NOT NULL DEFAULT 0.6",
                "ALTER TABLE form_submissions ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT NOW()",
                "ALTER TABLE form_submissions ADD COLUMN IF NOT EXISTS confirmation_number VARCHAR(20) DEFAULT ''",
                "ALTER TABLE form_fields ADD COLUMN IF NOT EXISTS step INTEGER NOT NULL DEFAULT 1",
                # --- Service-booking forms: lets each service appear in the
                #     Forms tab so admins can see submissions + abandoned
                #     carts using the same UI/analytics as regular forms.
                #     form_type='service_booking' marks an auto-managed form
                #     (admin can't edit/delete fields). linked_service_id
                #     links the form back to its service row.
                "ALTER TABLE custom_forms ADD COLUMN IF NOT EXISTS form_type VARCHAR(40) NOT NULL DEFAULT 'standard'",
                "ALTER TABLE custom_forms ADD COLUMN IF NOT EXISTS linked_service_id INTEGER",
                "ALTER TABLE chat_conversations ADD COLUMN IF NOT EXISTS visitor_id VARCHAR(100) DEFAULT ''",
                # --- AI lookup-tool observability: each assistant turn can
                #     record which lookup_* tools the model called (with args
                #     and row counts) so the admin can see in chat history
                #     which slices of the site the AI actually pulled into
                #     context to answer that turn.
                "ALTER TABLE chat_messages ADD COLUMN IF NOT EXISTS tool_calls_json JSONB",
                # --- Section visibility toggles (admin can show/hide entire sections) ---
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS section_testimonials BOOLEAN DEFAULT false",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS section_team BOOLEAN DEFAULT false",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS section_faq BOOLEAN DEFAULT false",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS section_footer BOOLEAN DEFAULT true",
                # --- Landing page scroll behavior toggle ---
                #   'snap'   — default, each section snaps fully into view (page-by-page swipe feel)
                #   'smooth' — natural continuous scrolling, no snap points (free-scroll feel)
                # Frontend reads this from /api/site-settings and reflects it as
                # data-scroll-mode on <html>; styles.css turns the snap rules off
                # under [data-scroll-mode="smooth"]. See public/styles.css §5.
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS scroll_mode TEXT NOT NULL DEFAULT 'snap'",
                # --- Business contact information ---
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS business_phone TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS business_email TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS business_address TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS business_hours JSONB DEFAULT '[]'::jsonb",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS business_map_embed TEXT NOT NULL DEFAULT ''",
                # --- Social media profile links (JSON object) ---
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS social_links JSONB DEFAULT '{}'::jsonb",
                # --- SEO settings columns (admin-managed meta tags for the public site) ---
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS seo_meta_title TEXT DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS seo_meta_description TEXT DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS seo_keywords TEXT DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS seo_og_image TEXT DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS seo_twitter_handle TEXT DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS seo_canonical_url TEXT DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS seo_robots TEXT DEFAULT 'index, follow'",
                # --- Media Library: extend uploaded_images to support video & audio ---
                "ALTER TABLE uploaded_images ADD COLUMN IF NOT EXISTS media_type VARCHAR(10) NOT NULL DEFAULT 'image'",
                "ALTER TABLE uploaded_images ADD COLUMN IF NOT EXISTS mime_type TEXT NOT NULL DEFAULT ''",
                # --- Hero video background (alternative to hero_image) ---
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS hero_video_url TEXT NOT NULL DEFAULT ''",
                # --- Gallery card video (alternative to image) ---
                "ALTER TABLE gallery_cards ADD COLUMN IF NOT EXISTS video_url TEXT NOT NULL DEFAULT ''",
                # --- Per-section background images (Task #60 / item 1).
                #     bg_image is a path returned by /admin/api/upload-image
                #     (typically '/uploads/<hex>.jpg'). Empty string means
                #     "use the default theme color" (--bg-section-N) — the
                #     existing inline `style="background: var(--bg-section-X)"`
                #     in index.html keeps providing the fallback paint.
                #     bg_overlay_alpha (0.0-1.0) controls a dark gradient
                #     applied above the photo so titles stay legible — 0.45
                #     is the default; admin can dial it per section.
                "ALTER TABLE page_sections ADD COLUMN IF NOT EXISTS bg_image TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE page_sections ADD COLUMN IF NOT EXISTS bg_overlay_alpha NUMERIC NOT NULL DEFAULT 0.45",
                # --- Section Menu link override (Task #71 / standalone pages).
                #     Empty string (default) means the in-hero Section Menu
                #     link for this section behaves as before: a same-page
                #     anchor that smooth-scrolls to #section-<slug>. A non-
                #     empty value (typically "/p/<slug>") makes the menu
                #     entry a normal cross-page link — used to surface a
                #     standalone page from the menu without auto-listing
                #     every page there.
                "ALTER TABLE page_sections ADD COLUMN IF NOT EXISTS nav_link_target TEXT NOT NULL DEFAULT ''",
                # --- Per-section SEO overrides (Task #69).
                #     Each pretty per-section URL (/podcast, /events, etc.,
                #     served by serve_section) inherits the homepage's SEO
                #     <title>, meta description, and og:image by default,
                #     which means every section URL produces an identical
                #     social-share preview card. These three nullable-by-
                #     default columns let the admin override that on a
                #     per-section basis. Empty string = fall back to the
                #     site-wide cascade in _build_seo_meta_html (preserves
                #     existing behaviour for unconfigured sections).
                "ALTER TABLE page_sections ADD COLUMN IF NOT EXISTS seo_title TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE page_sections ADD COLUMN IF NOT EXISTS seo_description TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE page_sections ADD COLUMN IF NOT EXISTS seo_image TEXT NOT NULL DEFAULT ''",
                # --- Brand identity (Task #61 / items 2,4,17,18).
                #     theme_accent_secondary is the second stop of the
                #     accent gradient (only used when theme_accent_gradient
                #     is true). Empty string = solid accent only.
                #     theme_logo_mode is one of: 'monogram' (default
                #     letters-in-circle), 'image' (uploaded logo only),
                #     'wordmark' (site name as wordmark, no badge),
                #     'lockup' (uploaded image + site name side-by-side).
                #     theme_logo_image is a path returned by
                #     /admin/api/upload-image (typically /uploads/<hex>.png).
                #     The "font pair" picker writes through to the existing
                #     theme_font_serif + theme_font_sans columns — no new
                #     column needed.
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_accent_secondary TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_accent_gradient BOOLEAN NOT NULL DEFAULT FALSE",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_logo_mode TEXT NOT NULL DEFAULT 'monogram'",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_logo_image TEXT NOT NULL DEFAULT ''",
                # --- Surface treatment presets (Task #62 / items 3, 5, 12, 13) ---
                #     theme_card_style picks the visual treatment applied to
                #     every card-shaped surface on the public site:
                #       'editorial' (default — large radius, soft shadow),
                #       'glass'     (heavier glass blur + subtle border),
                #       'brutal'    (square corners, hard shadow, thick border),
                #       'minimal'   (no shadow, hairline border).
                #     theme_easing picks the named cubic-bezier the public
                #     site uses for transitions:
                #       'snappy'    (quick out-cubic, default replacement),
                #       'gentle'    (the existing smooth-out, current default),
                #       'bouncy'    (an elastic-ish overshoot),
                #       'editorial' (slow in-out for an unhurried feel).
                #     theme_photo_filter applies a global filter to image
                #     surfaces (hero bg, card images): 'none' (default),
                #     'warm', 'cool', 'bw', 'grain'.
                #     theme_loading_mode controls what shows on the boot
                #     overlay: 'logo_name' (default — current behavior),
                #     'logo_only', 'spinner_only', 'fade_only'.
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_card_style TEXT NOT NULL DEFAULT 'editorial'",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_easing TEXT NOT NULL DEFAULT 'gentle'",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_photo_filter TEXT NOT NULL DEFAULT 'none'",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_loading_mode TEXT NOT NULL DEFAULT 'logo_name'",
                # Layout & rhythm controls (Task #63 / items 6, 7, 9, 16):
                # density (compact/comfortable/spacious), frame inset (0..32px),
                # header alignment (centered/left/numbered/split), hero mode
                # (full_bleed/split/text_mesh/carousel/video).
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_density TEXT NOT NULL DEFAULT 'comfortable'",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_section_frame_inset INTEGER NOT NULL DEFAULT 0",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_header_align TEXT NOT NULL DEFAULT 'centered'",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS hero_layout_mode TEXT NOT NULL DEFAULT 'full_bleed'",
                # Personality controls (Task #64 / items 10, 11, 14, 15):
                # cursor mode (native/dot/magnetic), scroll-progress bar
                # (on/off + accent color), nav style (floating_glass/sticky/
                # hamburger/hidden_on_scroll/side_rail), chatbot placement
                # (bottom_center/bottom_right/side_panel/cmd_k/hidden_until_button).
                # All five are additive, IF NOT EXISTS, with documented defaults
                # so older installs land on the legacy behavior without a
                # migration step.
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_cursor_mode TEXT NOT NULL DEFAULT 'native'",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_scroll_progress BOOLEAN NOT NULL DEFAULT FALSE",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_scroll_progress_color TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_nav_style TEXT NOT NULL DEFAULT 'floating_glass'",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS theme_chatbot_placement TEXT NOT NULL DEFAULT 'bottom_center'",
                "ALTER TABLE sphere_settings ADD COLUMN IF NOT EXISTS view_mode TEXT NOT NULL DEFAULT 'sections'",
                "ALTER TABLE sphere_settings ADD COLUMN IF NOT EXISTS card_scale REAL NOT NULL DEFAULT 1.0",
                "ALTER TABLE sphere_settings ADD COLUMN IF NOT EXISTS card_gap REAL NOT NULL DEFAULT 2.5",
                # --- Presentation rendering + narration toggles ---
                # display_mode controls what the visitor sees per slide:
                #   'rich'     — render parsed title + body styled on top of the slide image (default)
                #   'original' — show the imported slide image full-bleed only, no text overlay
                # ai_narrate_mode controls how per-slide voice scripts are populated:
                #   'manual'   — admin types narration_text per slide (default)
                #   'auto'     — owner clicked "Auto-narrate with AI"; the
                #                generator endpoint fills empty narration_text
                #                rows from title+body using gpt-4o-mini
                "ALTER TABLE presentations ADD COLUMN IF NOT EXISTS display_mode TEXT NOT NULL DEFAULT 'rich'",
                "ALTER TABLE presentations ADD COLUMN IF NOT EXISTS ai_narrate_mode TEXT NOT NULL DEFAULT 'manual'",
                # --- Generated-page curation + reuse instrumentation ---
                # Admin AI uses these to score, summarize, and publish
                # auto-generated pages; the visitor agent uses the FTS
                # index over title+prompt+summary+search_text to find
                # an already-published page BEFORE falling back to a
                # fresh (slow, costly) generatePage. archive_reason
                # captures why the admin pulled a page from rotation.
                "ALTER TABLE generated_pages ADD COLUMN IF NOT EXISTS summary TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE generated_pages ADD COLUMN IF NOT EXISTS search_text TEXT NOT NULL DEFAULT ''",
                "ALTER TABLE generated_pages ADD COLUMN IF NOT EXISTS ai_score INTEGER NOT NULL DEFAULT 0",
                "ALTER TABLE generated_pages ADD COLUMN IF NOT EXISTS reuse_count INTEGER NOT NULL DEFAULT 0",
                "ALTER TABLE generated_pages ADD COLUMN IF NOT EXISTS last_served_at TIMESTAMP",
                "ALTER TABLE generated_pages ADD COLUMN IF NOT EXISTS source_visitor_id VARCHAR(100) NOT NULL DEFAULT ''",
                "ALTER TABLE generated_pages ADD COLUMN IF NOT EXISTS source_session_id VARCHAR(100) NOT NULL DEFAULT ''",
                "ALTER TABLE generated_pages ADD COLUMN IF NOT EXISTS archive_reason TEXT NOT NULL DEFAULT ''",
                # --- Multiple themes + multiple homepage designs ---
                # Pointer columns to the currently-active row in
                # site_themes / site_designs (created in the CREATE
                # TABLE block below). NULL means "no override —
                # fall back to the legacy theme_* columns or to
                # public/index.html". Atomic theme/design switching
                # is just an UPDATE on these two ints.
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS active_theme_id INTEGER",
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS active_design_id INTEGER",
                # --- Agent scope tightness (Phase 1) ---
                # Controls how proactive / expansive the public-facing AI
                # is when answering visitor questions:
                #   'strict'   — minimal scope, only answers exactly what
                #                was asked, never volunteers tools.
                #   'balanced' — default; one obvious next-step suggested
                #                when relevant.
                #   'generous' — proactive, surfaces decks / pages /
                #                store items / nav even on narrow Qs.
                # The slider in the Chatbot tab is hidden when
                # tenant_has_feature('agent_scope_slider') is false.
                "ALTER TABLE chatbot_settings ADD COLUMN IF NOT EXISTS agent_scope_tightness TEXT NOT NULL DEFAULT 'balanced'",
                # Client-editable Brand Voice layer — APPENDED on top of the
                # default/system prompt (never replaces it). Editable by every
                # admin (unlike system_prompt, which is super-admin only).
                "ALTER TABLE chatbot_settings ADD COLUMN IF NOT EXISTS brand_voice TEXT NOT NULL DEFAULT ''",
            ]:
                cur.execute(col_sql)

            # --- Generated-page FTS + reuse indexes + insights cache ---
            # The expression in idx_generated_pages_fts is identical to
            # the lookup_generated_page query so PG uses this index.
            # marketing_insights_log caches insight runs so repeat
            # questions in the same window can be deduped.
            cur.execute("""
                CREATE INDEX IF NOT EXISTS idx_generated_pages_fts
                    ON generated_pages USING gin (
                        to_tsvector('english',
                            coalesce(title,'') || ' ' ||
                            coalesce(prompt,'') || ' ' ||
                            coalesce(summary,'') || ' ' ||
                            coalesce(search_text,''))
                    );
                CREATE INDEX IF NOT EXISTS idx_generated_pages_reuse
                    ON generated_pages (reuse_count DESC, last_served_at DESC);
                CREATE TABLE IF NOT EXISTS marketing_insights_log (
                    id              SERIAL PRIMARY KEY,
                    insight_type    VARCHAR(50) NOT NULL,
                    window_start    TIMESTAMP,
                    window_end      TIMESTAMP,
                    summary_json    JSONB,
                    notes           TEXT NOT NULL DEFAULT '',
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_marketing_insights_recent
                    ON marketing_insights_log (insight_type, created_at DESC);
            """)

            # =============================================================
            # SITE THEMES + WEBSITE DESIGNS — admin (and the AI web-
            # designer agent in a follow-up turn) can stash multiple
            # named themes and full-page designs here, preview them in
            # an iframe, and atomically swap which one is "active" by
            # updating site_settings.active_theme_id / active_design_id.
            # serve_index reads the active design's HTML on every page
            # load (with the same SEO injection); /api/theme reads the
            # active theme's palette + fonts JSON.
            # =============================================================
            cur.execute("""
                CREATE TABLE IF NOT EXISTS site_themes (
                    id              SERIAL PRIMARY KEY,
                    name            TEXT NOT NULL,
                    palette_json    JSONB NOT NULL DEFAULT '{}'::jsonb,
                    fonts_json      JSONB NOT NULL DEFAULT '{}'::jsonb,
                    source          TEXT NOT NULL DEFAULT 'manual',
                    notes           TEXT NOT NULL DEFAULT '',
                    status          TEXT NOT NULL DEFAULT 'draft',
                    created_at      TIMESTAMP NOT NULL DEFAULT NOW()
                );
                CREATE TABLE IF NOT EXISTS site_designs (
                    id              SERIAL PRIMARY KEY,
                    name            TEXT NOT NULL,
                    html            TEXT NOT NULL DEFAULT '',
                    notes           TEXT NOT NULL DEFAULT '',
                    source          TEXT NOT NULL DEFAULT 'manual',
                    model_used      TEXT NOT NULL DEFAULT '',
                    status          TEXT NOT NULL DEFAULT 'draft',
                    created_at      TIMESTAMP NOT NULL DEFAULT NOW(),
                    updated_at      TIMESTAMP NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_site_themes_status
                    ON site_themes (status, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_site_designs_status
                    ON site_designs (status, created_at DESC);
            """)

            # Seed the first "Default" theme from the existing 9 theme
            # columns on site_settings — only if site_themes is empty.
            # This way today's colors are always one click away even
            # after admin starts trying AI-drafted themes. We use the
            # plain (tuple-returning) cursor that init_db opened, so
            # fetchone() returns a tuple — index by position, not key.
            cur.execute("SELECT COUNT(*) FROM site_themes")
            if (cur.fetchone() or [0])[0] == 0:
                cur.execute("""
                    INSERT INTO site_themes (
                        name, palette_json, fonts_json,
                        source, notes, status
                    )
                    SELECT 'Default',
                           jsonb_build_object(
                               'bg',           coalesce(theme_bg, ''),
                               'section1',     coalesce(theme_section1, ''),
                               'section2',     coalesce(theme_section2, ''),
                               'accent',       coalesce(theme_accent, ''),
                               'text',         coalesce(theme_text, ''),
                               'glass_border', coalesce(theme_glass_border, ''),
                               'glass_bg',     coalesce(theme_glass_bg, '')
                           ),
                           jsonb_build_object(
                               'serif', coalesce(theme_font_serif, ''),
                               'sans',  coalesce(theme_font_sans,  '')
                           ),
                           'manual',
                           'Snapshot of the colors the site shipped with.',
                           'published'
                    FROM site_settings WHERE id = 1
                    RETURNING id
                """)
                _seed_theme_row = cur.fetchone()
                if _seed_theme_row:
                    cur.execute(
                        "UPDATE site_settings "
                        "SET active_theme_id = %s "
                        "WHERE id = 1 AND active_theme_id IS NULL",
                        (_seed_theme_row[0],),
                    )

            # Seed curated brand-identity palettes (Task #61 / item 4).
            # Each one is an opinionated full-stack visual: 7 colors plus
            # a font pairing the admin can apply with one click from the
            # Brand Identity panel. Idempotent — only inserts a name we
            # don't already have, so an admin who renames or edits a
            # seeded palette won't get it re-created on every restart.
            for _p in CURATED_PALETTES:
                cur.execute(
                    "SELECT 1 FROM site_themes WHERE name = %s LIMIT 1",
                    (_p["name"],),
                )
                if cur.fetchone():
                    continue
                cur.execute(
                    "INSERT INTO site_themes ("
                    "  name, palette_json, fonts_json, "
                    "  source, notes, status"
                    ") VALUES (%s, %s::jsonb, %s::jsonb, %s, %s, %s)",
                    (
                        _p["name"],
                        json.dumps(_p["palette"]),
                        json.dumps(_p["fonts"]),
                        "curated",
                        _p.get("notes", ""),
                        "draft",
                    ),
                )

            # Seed the first "Default" design from public/index.html —
            # only if site_designs is empty. This makes the active
            # design always safely fall back to whatever shipped with
            # the project; the / route reads from this row going
            # forward (with the same SEO injection wrapper).
            cur.execute("SELECT COUNT(*) FROM site_designs")
            if (cur.fetchone() or [0])[0] == 0:
                _idx_html = ""
                try:
                    _idx_path = os.path.join(
                        app.static_folder or "public", "index.html"
                    )
                    with open(_idx_path, "r", encoding="utf-8") as _f:
                        _idx_html = _f.read()
                except Exception as _e:
                    print(f"[site_designs seed] could not read index.html: {_e}")
                cur.execute(
                    "INSERT INTO site_designs ("
                    "  name, html, notes, source, model_used, status"
                    ") VALUES (%s, %s, %s, %s, %s, %s) RETURNING id",
                    (
                        "Default",
                        _idx_html,
                        "Snapshot of public/index.html — safe fallback design.",
                        "manual",
                        "",
                        "published",
                    ),
                )
                _seed_design_row = cur.fetchone()
                if _seed_design_row:
                    cur.execute(
                        "UPDATE site_settings "
                        "SET active_design_id = %s "
                        "WHERE id = 1 AND active_design_id IS NULL",
                        (_seed_design_row[0],),
                    )

            # =============================================================
            # CUSTOM DASHBOARDS — admin-built KPI/chart boards
            # =============================================================
            # Three tables power the custom dashboard builder:
            #
            #   external_data_connections
            #     Reusable named connections to outside data sources
            #     (Postgres URL, REST API endpoint). Credentials are
            #     stored encrypted at rest via encrypt_secret().
            #
            #   dashboards
            #     A named board the admin builds. Holds zero or more
            #     widgets and renders them in a simple stacked grid.
            #
            #   dashboard_widgets
            #     One card on a dashboard. Each widget has a type
            #     (kpi / table / line / bar) and a data source config
            #     (built-in metric or external connection + query).
            cur.execute("""
                CREATE TABLE IF NOT EXISTS external_data_connections (
                    id              SERIAL PRIMARY KEY,
                    name            VARCHAR(120) NOT NULL,
                    kind            VARCHAR(40)  NOT NULL DEFAULT 'postgres',
                    -- For 'postgres': encrypted full connection URL.
                    -- For 'rest':     encrypted JSON {"url":"...", "headers":{...}}
                    encrypted_config TEXT NOT NULL DEFAULT '',
                    created_at      TIMESTAMP DEFAULT NOW()
                );

                CREATE TABLE IF NOT EXISTS dashboards (
                    id          SERIAL PRIMARY KEY,
                    name        VARCHAR(160) NOT NULL,
                    description TEXT NOT NULL DEFAULT '',
                    sort_order  INTEGER NOT NULL DEFAULT 0,
                    created_at  TIMESTAMP DEFAULT NOW()
                );

                CREATE TABLE IF NOT EXISTS dashboard_widgets (
                    id              SERIAL PRIMARY KEY,
                    dashboard_id    INTEGER NOT NULL
                        REFERENCES dashboards(id) ON DELETE CASCADE,
                    name            VARCHAR(160) NOT NULL,
                    -- 'kpi' | 'table' | 'line' | 'bar'
                    widget_type     VARCHAR(20)  NOT NULL DEFAULT 'kpi',
                    -- 'builtin' | 'external_postgres' | 'external_rest'
                    source_type     VARCHAR(30)  NOT NULL DEFAULT 'builtin',
                    -- Free-form JSON config: depends on source_type.
                    -- builtin            -> {"metric":"visitors","range":"7d"}
                    -- external_postgres  -> {"connection_id":3,"query":"SELECT ..."}
                    -- external_rest      -> {"connection_id":4,"path":"/users",
                    --                       "value_path":"data.count"}
                    source_config   JSONB        NOT NULL DEFAULT '{}'::jsonb,
                    sort_order      INTEGER      NOT NULL DEFAULT 0,
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_widgets_dashboard
                    ON dashboard_widgets (dashboard_id);

                -- =========================================================
                -- DATAHUB — semantic layer (Phase 7 / task 053)
                -- =========================================================
                -- Human/AI descriptions of a data source's schema so the
                -- Business Assistant writes correct SQL. connection_id 0 means
                -- THE APP'S OWN database; any other id references an
                -- external_data_connections row. ai_generated/reviewed drive the
                -- "AI-suggested · review" UX: the assistant drafts rows
                -- (ai_generated=true, reviewed=false) and a super-admin edits
                -- what's wrong (manual save → reviewed=true). Also migration 0024.
                CREATE TABLE IF NOT EXISTS db_table_annotations (
                    id            BIGSERIAL PRIMARY KEY,
                    connection_id INTEGER NOT NULL DEFAULT 0,
                    table_name    TEXT NOT NULL,
                    description   TEXT NOT NULL DEFAULT '',
                    is_sensitive  BOOLEAN NOT NULL DEFAULT FALSE,
                    ai_generated  BOOLEAN NOT NULL DEFAULT FALSE,
                    reviewed      BOOLEAN NOT NULL DEFAULT FALSE,
                    updated_by    TEXT NOT NULL DEFAULT '',
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (connection_id, table_name)
                );

                CREATE TABLE IF NOT EXISTS db_column_annotations (
                    id            BIGSERIAL PRIMARY KEY,
                    connection_id INTEGER NOT NULL DEFAULT 0,
                    table_name    TEXT NOT NULL,
                    column_name   TEXT NOT NULL,
                    description   TEXT NOT NULL DEFAULT '',
                    semantic_type TEXT NOT NULL DEFAULT '',
                    is_sensitive  BOOLEAN NOT NULL DEFAULT FALSE,
                    sample_values JSONB NOT NULL DEFAULT '[]'::jsonb,
                    ai_generated  BOOLEAN NOT NULL DEFAULT FALSE,
                    reviewed      BOOLEAN NOT NULL DEFAULT FALSE,
                    updated_by    TEXT NOT NULL DEFAULT '',
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (connection_id, table_name, column_name)
                );
                CREATE INDEX IF NOT EXISTS idx_dh_cols
                    ON db_column_annotations (connection_id, table_name);

                CREATE TABLE IF NOT EXISTS db_relationships (
                    id            BIGSERIAL PRIMARY KEY,
                    connection_id INTEGER NOT NULL DEFAULT 0,
                    from_table    TEXT NOT NULL,
                    from_column   TEXT NOT NULL,
                    to_table      TEXT NOT NULL,
                    to_column     TEXT NOT NULL,
                    description   TEXT NOT NULL DEFAULT '',
                    ai_generated  BOOLEAN NOT NULL DEFAULT FALSE,
                    reviewed      BOOLEAN NOT NULL DEFAULT FALSE,
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (connection_id, from_table, from_column, to_table, to_column)
                );

                CREATE TABLE IF NOT EXISTS db_query_examples (
                    id            BIGSERIAL PRIMARY KEY,
                    connection_id INTEGER NOT NULL DEFAULT 0,
                    question      TEXT NOT NULL DEFAULT '',
                    sql           TEXT NOT NULL DEFAULT '',
                    notes         TEXT NOT NULL DEFAULT '',
                    ai_generated  BOOLEAN NOT NULL DEFAULT FALSE,
                    reviewed      BOOLEAN NOT NULL DEFAULT FALSE,
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_dh_examples
                    ON db_query_examples (connection_id);
            """)

            # =============================================================
            # MESSAGING — subscribers, templates, campaigns, log
            # =============================================================
            # Foundation for the email + SMS layer (Resend / Twilio).
            #
            #   subscribers            People we may message. opt_in defaults
            #                          to TRUE; the unsubscribe flow flips it
            #                          to FALSE and the dispatcher honors it.
            #
            #   messaging_templates    Reusable bodies — channel is 'email'
            #                          or 'sms'. Email rows carry a subject;
            #                          SMS rows ignore it. Body supports
            #                          {{merge_tag}} placeholders.
            #
            #   messaging_campaigns    A scheduled or immediate send. status
            #                          flows draft → queued → sending → sent
            #                          (or failed). recipient_filter is JSON
            #                          describing who the campaign targets.
            #
            #   messaging_log          One row per (campaign, subscriber).
            #                          status flows queued → sent → delivered
            #                          (or failed/bounced). opens/clicks
            #                          updated by Resend webhook.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS subscribers (
                    id              SERIAL PRIMARY KEY,
                    email           TEXT NOT NULL DEFAULT '',
                    phone           TEXT NOT NULL DEFAULT '',
                    full_name       TEXT NOT NULL DEFAULT '',
                    list_name       TEXT NOT NULL DEFAULT 'default',
                    source          TEXT NOT NULL DEFAULT 'manual',
                    opt_in          BOOLEAN NOT NULL DEFAULT TRUE,
                    opt_in_email    BOOLEAN NOT NULL DEFAULT TRUE,
                    opt_in_sms      BOOLEAN NOT NULL DEFAULT TRUE,
                    custom_fields   JSONB NOT NULL DEFAULT '{}'::jsonb,
                    unsubscribed_at TIMESTAMP,
                    created_at      TIMESTAMP DEFAULT NOW(),
                    updated_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_subscribers_email ON subscribers (email);
                CREATE INDEX IF NOT EXISTS idx_subscribers_phone ON subscribers (phone);
                CREATE INDEX IF NOT EXISTS idx_subscribers_list  ON subscribers (list_name);

                CREATE TABLE IF NOT EXISTS messaging_templates (
                    id           SERIAL PRIMARY KEY,
                    name         TEXT NOT NULL DEFAULT 'Untitled template',
                    channel      VARCHAR(10) NOT NULL DEFAULT 'email',
                    subject      TEXT NOT NULL DEFAULT '',
                    body         TEXT NOT NULL DEFAULT '',
                    from_name    TEXT NOT NULL DEFAULT '',
                    reply_to     TEXT NOT NULL DEFAULT '',
                    notes        TEXT NOT NULL DEFAULT '',
                    created_at   TIMESTAMP DEFAULT NOW(),
                    updated_at   TIMESTAMP DEFAULT NOW()
                );

                CREATE TABLE IF NOT EXISTS messaging_campaigns (
                    id                 SERIAL PRIMARY KEY,
                    name               TEXT NOT NULL DEFAULT '',
                    template_id        INTEGER REFERENCES messaging_templates(id) ON DELETE SET NULL,
                    channel            VARCHAR(10) NOT NULL DEFAULT 'email',
                    -- Snapshot of the rendered template at send time. We
                    -- snapshot rather than re-read the template so editing
                    -- a template later cannot retroactively change a sent
                    -- campaign's body.
                    subject_snapshot   TEXT NOT NULL DEFAULT '',
                    body_snapshot      TEXT NOT NULL DEFAULT '',
                    -- 'all' | 'list' | 'ids' (recipient_filter has the params)
                    recipient_kind     VARCHAR(20) NOT NULL DEFAULT 'all',
                    recipient_filter   JSONB NOT NULL DEFAULT '{}'::jsonb,
                    -- 'draft' | 'queued' | 'sending' | 'sent' | 'failed' | 'cancelled'
                    status             VARCHAR(20) NOT NULL DEFAULT 'draft',
                    send_at            TIMESTAMP,
                    started_at         TIMESTAMP,
                    finished_at        TIMESTAMP,
                    total_recipients   INTEGER NOT NULL DEFAULT 0,
                    sent_count         INTEGER NOT NULL DEFAULT 0,
                    failed_count       INTEGER NOT NULL DEFAULT 0,
                    error_text         TEXT NOT NULL DEFAULT '',
                    created_at         TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_campaigns_status   ON messaging_campaigns (status);
                CREATE INDEX IF NOT EXISTS idx_campaigns_send_at  ON messaging_campaigns (send_at);

                CREATE TABLE IF NOT EXISTS messaging_log (
                    id                 SERIAL PRIMARY KEY,
                    campaign_id        INTEGER REFERENCES messaging_campaigns(id) ON DELETE SET NULL,
                    subscriber_id      INTEGER REFERENCES subscribers(id) ON DELETE SET NULL,
                    channel            VARCHAR(10) NOT NULL DEFAULT 'email',
                    -- Recipient address resolved at send time (kept even if
                    -- the subscriber row is later deleted).
                    to_address         TEXT NOT NULL DEFAULT '',
                    subject_snapshot   TEXT NOT NULL DEFAULT '',
                    body_snapshot      TEXT NOT NULL DEFAULT '',
                    -- 'queued' | 'sent' | 'delivered' | 'opened' | 'clicked'
                    -- | 'bounced' | 'complained' | 'failed' | 'unsubscribed'
                    status             VARCHAR(20) NOT NULL DEFAULT 'queued',
                    provider           VARCHAR(20) NOT NULL DEFAULT '',
                    provider_message_id TEXT NOT NULL DEFAULT '',
                    error_text         TEXT NOT NULL DEFAULT '',
                    sent_at            TIMESTAMP,
                    delivered_at       TIMESTAMP,
                    opened_at          TIMESTAMP,
                    clicked_at         TIMESTAMP,
                    open_count         INTEGER NOT NULL DEFAULT 0,
                    click_count        INTEGER NOT NULL DEFAULT 0,
                    is_test            BOOLEAN NOT NULL DEFAULT FALSE,
                    created_at         TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_msg_log_campaign ON messaging_log (campaign_id);
                CREATE INDEX IF NOT EXISTS idx_msg_log_provider ON messaging_log (provider_message_id);
                CREATE INDEX IF NOT EXISTS idx_msg_log_to       ON messaging_log (to_address);

                -- =============================================================
                -- AI REVIEW COLLECTOR
                -- =============================================================
                -- Three tables drive the post-purchase review-ask flow.
                --
                --   review_destinations  Where each ask should send the visitor
                --                        (Google place, Yelp page, TripAdvisor
                --                        page, or an internal review form).
                --                        Each row carries optional auto-send
                --                        settings so a destination can fire N
                --                        days after a booking is paid.
                --
                --   review_requests      One row per personalized ask. The
                --                        short_token powers /r/<token>. We
                --                        record sent / clicked / converted
                --                        timestamps so the Insights tab can
                --                        compute funnel rates.
                --
                --   external_reviews     Cached aggregate snapshot (count and
                --                        average rating) per destination, kept
                --                        fresh by a once-per-day scheduler tick
                --                        for destinations whose provider
                --                        exposes a public API.
                --
                --   review_settings      Singleton (id=1) holding the email
                --                        and SMS templates that wrap each ask
                --                        plus default auto-send days.
                CREATE TABLE IF NOT EXISTS review_destinations (
                    id              SERIAL PRIMARY KEY,
                    name            TEXT NOT NULL DEFAULT '',
                    -- 'google' | 'yelp' | 'tripadvisor' | 'internal'
                    kind            VARCHAR(20) NOT NULL DEFAULT 'google',
                    url             TEXT NOT NULL DEFAULT '',
                    -- Provider id used to fetch the aggregate snapshot:
                    --   google      → Place ID (e.g. ChIJN1t_tDeuEmsRUsoyG83frY4)
                    --   yelp        → Yelp business id / alias
                    --   tripadvisor → TripAdvisor location id
                    --   internal    → optional internal form slug
                    external_id     TEXT NOT NULL DEFAULT '',
                    auto_send       BOOLEAN NOT NULL DEFAULT FALSE,
                    auto_send_days  INTEGER NOT NULL DEFAULT 3,
                    is_default      BOOLEAN NOT NULL DEFAULT FALSE,
                    public_visible  BOOLEAN NOT NULL DEFAULT FALSE,
                    sort_order      INTEGER NOT NULL DEFAULT 0,
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_review_dest_sort ON review_destinations (sort_order);

                CREATE TABLE IF NOT EXISTS review_requests (
                    id                SERIAL PRIMARY KEY,
                    destination_id    INTEGER REFERENCES review_destinations(id) ON DELETE SET NULL,
                    -- 'email' | 'sms'
                    channel           VARCHAR(10) NOT NULL DEFAULT 'email',
                    recipient_name    TEXT NOT NULL DEFAULT '',
                    recipient_email   TEXT NOT NULL DEFAULT '',
                    recipient_phone   TEXT NOT NULL DEFAULT '',
                    -- Free-text describing the thing the customer bought or
                    -- booked, used by the AI prompt for personalization.
                    purchased_item    TEXT NOT NULL DEFAULT '',
                    -- 'order' | 'form_submission' | 'rsvp' | 'manual'
                    source_kind       VARCHAR(20) NOT NULL DEFAULT 'manual',
                    source_id         INTEGER,
                    -- 'queued' | 'sending' | 'sent' | 'failed' | 'cancelled'
                    --   sending: claimed by the dispatcher, in flight
                    --   sent:    successfully handed off to email/SMS provider
                    status            VARCHAR(20) NOT NULL DEFAULT 'queued',
                    short_token       VARCHAR(40) UNIQUE NOT NULL,
                    subject_snapshot  TEXT NOT NULL DEFAULT '',
                    body_snapshot     TEXT NOT NULL DEFAULT '',
                    error_text        TEXT NOT NULL DEFAULT '',
                    send_at           TIMESTAMP DEFAULT NOW(),
                    sent_at           TIMESTAMP,
                    clicked_at        TIMESTAMP,
                    converted_at      TIMESTAMP,
                    click_count       INTEGER NOT NULL DEFAULT 0,
                    created_at        TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_review_req_status  ON review_requests (status);
                CREATE INDEX IF NOT EXISTS idx_review_req_send_at ON review_requests (send_at);
                CREATE INDEX IF NOT EXISTS idx_review_req_dest    ON review_requests (destination_id);
                CREATE INDEX IF NOT EXISTS idx_review_req_source  ON review_requests (source_kind, source_id);

                CREATE TABLE IF NOT EXISTS external_reviews (
                    id              SERIAL PRIMARY KEY,
                    destination_id  INTEGER UNIQUE REFERENCES review_destinations(id) ON DELETE CASCADE,
                    total_count     INTEGER NOT NULL DEFAULT 0,
                    avg_rating      REAL NOT NULL DEFAULT 0,
                    snapshot_at     TIMESTAMP DEFAULT NOW(),
                    raw_json        JSONB NOT NULL DEFAULT '{}'::jsonb,
                    error_text      TEXT NOT NULL DEFAULT ''
                );

                CREATE TABLE IF NOT EXISTS review_settings (
                    id                  INTEGER PRIMARY KEY DEFAULT 1,
                    email_template_id   INTEGER REFERENCES messaging_templates(id) ON DELETE SET NULL,
                    sms_template_id     INTEGER REFERENCES messaging_templates(id) ON DELETE SET NULL,
                    -- Default lead-time used when a destination row does not
                    -- override auto_send_days. 0 means "send immediately when
                    -- the booking is marked complete".
                    auto_send_days      INTEGER NOT NULL DEFAULT 3,
                    -- Master switch for the public-facing snapshot widget.
                    -- Per-destination opt-in still controls which cards show.
                    public_show         BOOLEAN NOT NULL DEFAULT FALSE,
                    last_snapshot_at    TIMESTAMP,
                    updated_at          TIMESTAMP DEFAULT NOW()
                );
                INSERT INTO review_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;
            """)

            # =============================================================
            # AUTOMATIONS — no-code "if X then Y" workflow builder
            # =============================================================
            #
            #   automations         A single workflow definition. One trigger
            #                       (form_submitted / new_chat / schedule /
            #                       webhook / manual) plus an ordered list of
            #                       action steps stored as JSON. webhook_token
            #                       is the random URL slug for incoming
            #                       /automations/hook/<token> calls.
            #
            #   automation_runs     One row per execution. status flows
            #                       queued → running → succeeded|failed|
            #                       timeout|cancelled. step_results captures
            #                       per-step output for the run-log drilldown.
            #
            #   automation_settings Singleton (id=1) holding admin-tunable
            #                       overrides for the run-history retention
            #                       knobs. NULL columns mean "use the
            #                       AUTOMATIONS_RETENTION_* env-var default".
            cur.execute("""
                CREATE TABLE IF NOT EXISTS automations (
                    id                  SERIAL PRIMARY KEY,
                    name                TEXT NOT NULL DEFAULT 'Untitled automation',
                    description         TEXT NOT NULL DEFAULT '',
                    enabled             BOOLEAN NOT NULL DEFAULT FALSE,
                    trigger_type        VARCHAR(30) NOT NULL DEFAULT 'manual',
                    trigger_config      JSONB NOT NULL DEFAULT '{}'::jsonb,
                    action_steps        JSONB NOT NULL DEFAULT '[]'::jsonb,
                    webhook_token       TEXT NOT NULL DEFAULT '',
                    last_run_at         TIMESTAMP,
                    last_run_status     VARCHAR(20) NOT NULL DEFAULT '',
                    next_scheduled_at   TIMESTAMP,
                    created_at          TIMESTAMP DEFAULT NOW(),
                    updated_at          TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_automations_enabled ON automations (enabled);
                CREATE INDEX IF NOT EXISTS idx_automations_trigger ON automations (trigger_type);
                CREATE UNIQUE INDEX IF NOT EXISTS idx_automations_webhook
                    ON automations (webhook_token) WHERE webhook_token <> '';

                CREATE TABLE IF NOT EXISTS automation_runs (
                    id                  SERIAL PRIMARY KEY,
                    automation_id       INTEGER REFERENCES automations(id) ON DELETE CASCADE,
                    status              VARCHAR(20) NOT NULL DEFAULT 'queued',
                    triggered_by        VARCHAR(20) NOT NULL DEFAULT 'event',
                    trigger_data        JSONB NOT NULL DEFAULT '{}'::jsonb,
                    step_results        JSONB NOT NULL DEFAULT '[]'::jsonb,
                    error_text          TEXT NOT NULL DEFAULT '',
                    is_dry_run          BOOLEAN NOT NULL DEFAULT FALSE,
                    queued_at           TIMESTAMP DEFAULT NOW(),
                    started_at          TIMESTAMP,
                    finished_at         TIMESTAMP
                );
                CREATE INDEX IF NOT EXISTS idx_runs_automation ON automation_runs (automation_id);
                CREATE INDEX IF NOT EXISTS idx_runs_status ON automation_runs (status);
                CREATE INDEX IF NOT EXISTS idx_runs_queued ON automation_runs (status, queued_at);
                -- Backs both the editor's "recent runs" panel
                -- (`ORDER BY id DESC LIMIT 100` per automation) and the
                -- retention cleanup's window-function scan, so neither has
                -- to seq-scan the whole table once it gets large.
                CREATE INDEX IF NOT EXISTS idx_runs_automation_queued
                    ON automation_runs (automation_id, queued_at DESC);

                -- Saved snapshots of an automation's editable content (name,
                -- description, trigger, action steps). One row is appended on
                -- every meaningful save so the admin can browse the history
                -- and restore an earlier version if a change was a mistake.
                CREATE TABLE IF NOT EXISTS automation_versions (
                    id              SERIAL PRIMARY KEY,
                    automation_id   INTEGER NOT NULL REFERENCES automations(id) ON DELETE CASCADE,
                    version_no      INTEGER NOT NULL,
                    snapshot        JSONB NOT NULL,
                    note            TEXT NOT NULL DEFAULT '',
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_versions_automation
                    ON automation_versions (automation_id, version_no DESC);
                CREATE UNIQUE INDEX IF NOT EXISTS idx_versions_unique
                    ON automation_versions (automation_id, version_no);

                -- Singleton (id=1) holding the admin-tunable retention knobs
                -- the cleanup tick reads on each pass. NULL columns mean
                -- "fall back to the AUTOMATIONS_RETENTION_* env-var defaults"
                -- so existing installations behave exactly as before until
                -- an admin saves an override from the UI.
                CREATE TABLE IF NOT EXISTS automation_settings (
                    id                          INTEGER PRIMARY KEY DEFAULT 1,
                    retention_days              INTEGER,
                    keep_recent_per_automation  INTEGER,
                    updated_at                  TIMESTAMP DEFAULT NOW()
                );
                INSERT INTO automation_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

                -- Per-automation log of webhook posts that failed signature
                -- verification BEFORE a run row was queued. Without this an
                -- admin who turned on signing has no visible record when a
                -- third party (or attacker) sends bad signatures, so they
                -- can't tell a misconfigured secret from active abuse.
                -- `header_excerpt` is a small truncated dump of relevant
                -- request headers (signature header, content-type, UA) to
                -- help diagnose sender misconfiguration; we never store the
                -- raw body to avoid retaining attacker-controlled blobs.
                CREATE TABLE IF NOT EXISTS automation_webhook_rejections (
                    id              SERIAL PRIMARY KEY,
                    automation_id   INTEGER NOT NULL REFERENCES automations(id) ON DELETE CASCADE,
                    reason          TEXT NOT NULL DEFAULT '',
                    source_ip       VARCHAR(64) NOT NULL DEFAULT '',
                    header_excerpt  TEXT NOT NULL DEFAULT '',
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_webhook_rejections_automation
                    ON automation_webhook_rejections (automation_id, created_at DESC);
            """)

            # Seed a default "Contact / Inquiry" form if no forms exist yet
            # This is sample data — customize it from the admin panel for your industry
            cur.execute("SELECT COUNT(*) FROM custom_forms")
            row = cur.fetchone()
            form_count = row[0] if row else 0
            if form_count == 0:
                cur.execute("""
                    INSERT INTO custom_forms (name, slug, description, status, submit_button_text, success_message, sort_order)
                    VALUES ('Contact Request', 'contact-request',
                            'Get in touch with us',
                            'active', 'Submit Request',
                            'Thank you! Your request has been received. We will get back to you within 24 hours.',
                            0)
                    RETURNING id
                """)
                form_row = cur.fetchone()
                if form_row:
                    fid = form_row[0]
                    fields = [
                        (fid, 'text',   'Full Name',    'name',      'Enter your full name', True,  None, '', 0, 'full', '', '', 1),
                        (fid, 'email',  'Email',        'email',     'your@email.com',       True,  None, '', 1, 'full', '', '', 1),
                        (fid, 'select', 'Service',      'service',   '',                     True,  '[]', '', 2, 'full', '', 'Select your preferred option', 1),
                        (fid, 'date',   'Start Date',   'start_date','',                     True,  None, '', 3, 'half', '', '', 2),
                        (fid, 'date',   'End Date',     'end_date',  '',                     True,  None, '', 4, 'half', '', '', 2),
                        (fid, 'number', 'Quantity',     'quantity',  '',                     False, None, '1', 5, 'half', '', 'How many?', 2),
                        (fid, 'tel',    'Phone',        'phone',     '+1 (555) 000-0000',    False, None, '', 6, 'half', '', '', 2),
                        (fid, 'textarea','Additional Details','details','Any special requirements or preferences...', False, None, '', 7, 'full', '', '', 3),
                    ]
                    for f in fields:
                        cur.execute("""
                            INSERT INTO form_fields (form_id, field_type, label, name, placeholder, required, options, default_value, sort_order, width, validation_regex, help_text, step)
                            VALUES (%s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s, %s, %s, %s, %s)
                        """, f)

            # Seed built-in page sections if the table is empty
            # These represent the hardcoded sections that exist in index.html.
            # The admin can reorder them but not delete them.
            cur.execute("SELECT COUNT(*) FROM page_sections")
            row = cur.fetchone()
            section_count = row[0] if row else 0
            if section_count == 0:
                built_in_sections = [
                    ('hero',         'Hero',            'built_in', 'hero',         0, True),
                    ('highlights',   'Highlights',      'built_in', 'highlights', 1, True),
                    ('experiences',  'Offerings & Pricing', 'built_in', 'experiences', 2, True),
                    ('testimonials', 'Testimonials',    'built_in', 'testimonials', 3, False),
                    ('team',         'Our Team',        'built_in', 'team',         4, False),
                    ('faq',          'FAQ',             'built_in', 'faq',          5, False),
                    ('blog',         'Latest Stories',  'built_in', 'blog',         6, False),
                    ('footer',       'Footer',          'built_in', 'footer',       7, True),
                ]
                for slug, title, stype, tmpl, order, enabled in built_in_sections:
                    cur.execute("""
                        INSERT INTO page_sections (slug, title, section_type, template, sort_order, enabled)
                        VALUES (%s, %s, %s, %s, %s, %s)
                        ON CONFLICT (slug) DO NOTHING
                    """, (slug, title, stype, tmpl, order, enabled))

            # =============================================================
            # SEED: Insert the 'blog' page section if it doesn't exist yet
            # (for databases that were initialized before blog support)
            # =============================================================
            cur.execute("""
                INSERT INTO page_sections (slug, title, section_type, template, sort_order, enabled)
                VALUES ('blog', 'Latest Stories', 'built_in', 'blog', 6, false)
                ON CONFLICT (slug) DO NOTHING
            """)

            cur.execute("""
                INSERT INTO page_sections (slug, title, section_type, template, sort_order, enabled)
                VALUES ('video-gallery', 'Video Gallery', 'built_in', 'video-gallery', 8, false)
                ON CONFLICT (slug) DO NOTHING
            """)

            cur.execute("""
                INSERT INTO page_sections (slug, title, section_type, template, sort_order, enabled)
                VALUES ('podcast', 'Podcast', 'built_in', 'podcast', 9, false)
                ON CONFLICT (slug) DO NOTHING
            """)

            cur.execute("""
                INSERT INTO page_sections (slug, title, section_type, template, sort_order, enabled)
                VALUES ('store', 'Store', 'built_in', 'store', 10, false)
                ON CONFLICT (slug) DO NOTHING
            """)

            cur.execute("""
                INSERT INTO page_sections (slug, title, section_type, template, sort_order, enabled)
                VALUES ('business-info', 'Contact Us', 'built_in', 'business-info', 7, true)
                ON CONFLICT (slug) DO NOTHING
            """)

            cur.execute("""
                INSERT INTO page_sections (slug, title, section_type, template, sort_order, enabled)
                VALUES ('events', 'Upcoming Events', 'built_in', 'events', 11, false)
                ON CONFLICT (slug) DO NOTHING
            """)

            # Services / Bookings section — disabled by default; admin
            # turns it on once at least one service is set up. The DOM id
            # in public/index.html is "section-services" (mirrored in
            # BUILTIN_SECTION_MAP in public/script.js).
            cur.execute("""
                INSERT INTO page_sections (slug, title, section_type, template, sort_order, enabled)
                VALUES ('services', 'Services', 'built_in', 'services', 12, false)
                ON CONFLICT (slug) DO NOTHING
            """)

            cur.execute("SELECT COUNT(*) FROM custom_forms WHERE slug = 'contact-us'")
            contact_form_exists = cur.fetchone()[0]
            if contact_form_exists == 0:
                cur.execute("""
                    INSERT INTO custom_forms (name, slug, description, status, submit_button_text, success_message, sort_order)
                    VALUES ('Contact Us', 'contact-us', 'General contact and inquiry form',
                            'active', 'Send Message',
                            'Thank you for reaching out! We will get back to you soon.',
                            COALESCE((SELECT MAX(sort_order)+1 FROM custom_forms), 0))
                    RETURNING id
                """)
                contact_form_id = cur.fetchone()[0]
                contact_fields = [
                    ('full_name', 'Full Name', 'text', True, 'Your name', 1, 'half'),
                    ('email', 'Email Address', 'email', True, 'you@example.com', 2, 'half'),
                    ('subject', 'Subject', 'text', False, 'What is this about?', 3, 'full'),
                    ('message', 'Message', 'textarea', True, 'Tell us more...', 4, 'full'),
                ]
                for fname, flabel, ftype, freq, fplaceholder, fsort, fwidth in contact_fields:
                    cur.execute("""
                        INSERT INTO form_fields (form_id, field_type, label, name, placeholder, required, sort_order, width, step)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 1)
                    """, (contact_form_id, ftype, flabel, fname, fplaceholder, freq, fsort, fwidth))

            # =============================================================
            # SEED: Sample blog post (industry-agnostic)
            # =============================================================
            # Insert one well-written sample blog post so the blog section
            # has content to display immediately. Only inserted if no blog
            # posts exist yet — admins can edit or delete from the dashboard.
            cur.execute("SELECT COUNT(*) FROM blog_posts")
            row = cur.fetchone()
            blog_count = row[0] if row else 0
            if blog_count == 0:
                cur.execute("""
                    INSERT INTO blog_posts (
                        slug, title, subtitle, excerpt, content, cover_image,
                        author, category, tags, status, seo_title, seo_description,
                        published_at, sort_order
                    ) VALUES (
                        'the-art-of-first-impressions',
                        'The Art of First Impressions: Why Every Detail Matters',
                        'How thoughtful design transforms ordinary moments into lasting memories',
                        'First impressions are formed in milliseconds, yet their impact endures for years. Discover how attention to detail — from the warmth of a greeting to the subtlety of ambient lighting — shapes the way people experience your space and your brand.',
                        '<p>First impressions are formed in milliseconds, yet their impact endures for years. Whether you are greeting a customer in person, meeting a client at your office, or launching a new product online, the initial moment of contact sets the tone for everything that follows.</p>

<h2>The Science Behind First Impressions</h2>
<p>Research in cognitive psychology shows that people make judgments about trustworthiness, competence, and likability within the first seven seconds of an encounter. These snap judgments are remarkably persistent — once formed, they color every subsequent interaction.</p>
<p>This is not limited to face-to-face meetings. Digital experiences follow the same pattern. A website visitor decides whether to stay or leave in roughly 50 milliseconds, based on visual appeal alone. The implications for businesses are profound: every pixel, every word, and every interaction point is an opportunity to build — or erode — trust.</p>

<h2>Details That Make the Difference</h2>
<p>The most memorable experiences share a common thread: intentionality. Nothing feels accidental. Consider these elements that elevate an ordinary moment into something remarkable:</p>
<ul>
<li><strong>Consistency</strong> — Every touchpoint reflects the same values and aesthetic, from signage to staff demeanor to digital presence.</li>
<li><strong>Sensory awareness</strong> — Lighting, temperature, scent, and sound are calibrated to create comfort without being obtrusive.</li>
<li><strong>Personalization</strong> — Small gestures that acknowledge the individual — a remembered name, a tailored recommendation — signal genuine care.</li>
<li><strong>Anticipation</strong> — Great hosts solve problems before they arise. The umbrella by the door on a cloudy day. The FAQ that answers the question before it is asked.</li>
</ul>

<h2>Translating This to Your Brand</h2>
<p>Whether you run a physical space or a digital platform, the principle is the same: design every interaction as if it were the first and only chance to earn someone''s trust. Audit your customer journey from the outside in. What does a newcomer see, feel, and understand in those critical opening seconds?</p>
<p>The brands that thrive are those that treat first impressions not as a marketing problem, but as a design philosophy — one that permeates every layer of the experience.</p>

<h2>Start With One Thing</h2>
<p>You do not need to overhaul everything at once. Pick the single most common entry point for your audience — your homepage, your front door, your opening email — and refine it until it feels effortless. Then move to the next. Excellence is built one detail at a time.</p>',
                        '',
                        'Editorial Team',
                        'Insights',
                        'branding, design, customer experience, first impressions',
                        'published',
                        'The Art of First Impressions: Why Every Detail Matters',
                        'Discover how attention to detail shapes lasting impressions — from the warmth of a greeting to the subtlety of ambient design.',
                        NOW(),
                        0
                    ) ON CONFLICT (slug) DO NOTHING
                """)

            # =============================================================
            # AI WEB SCRAPER
            # =============================================================
            # One row per scrape job. The admin pastes a URL OR an objective,
            # picks a target shape, and we run the job in the background.
            #
            #   input_mode      'url' or 'objective'
            #   url             Source URL when input_mode='url' (else '').
            #   objective       Free-text ask when input_mode='objective'.
            #   target_shape    'free_form' | 'gallery_card' | 'pricing_tier'
            #                   | 'blog_post' | 'contact_details' | 'custom'
            #   custom_schema   Admin-supplied JSON schema (custom shape only).
            #   status          'queued' | 'running' | 'done' | 'failed'
            #   result_json     Extracted record (shape-specific) once done.
            #   error           Short user-facing failure message, if any.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS scrape_jobs (
                    id              SERIAL PRIMARY KEY,
                    input_mode      VARCHAR(20) NOT NULL DEFAULT 'url',
                    url             TEXT NOT NULL DEFAULT '',
                    objective       TEXT NOT NULL DEFAULT '',
                    target_shape    VARCHAR(40) NOT NULL DEFAULT 'free_form',
                    custom_schema   JSONB,
                    status          VARCHAR(20) NOT NULL DEFAULT 'queued',
                    result_json     JSONB,
                    error           TEXT NOT NULL DEFAULT '',
                    requested_at    TIMESTAMP DEFAULT NOW(),
                    completed_at    TIMESTAMP
                );
                CREATE INDEX IF NOT EXISTS idx_scrape_jobs_status
                    ON scrape_jobs (status);
                CREATE INDEX IF NOT EXISTS idx_scrape_jobs_requested
                    ON scrape_jobs (requested_at DESC);
            """)
            # Admin-editable disallowed-domain list lives on site_settings as
            # a comma/newline-separated string — keeps it editable from one
            # form panel without an extra table.
            cur.execute(
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS "
                "scraper_disallowed_domains TEXT NOT NULL DEFAULT ''"
            )
            # Toggle for the headless-browser fallback path used on JS-only
            # pages. Off by default so plain GETs (free, fast) stay the
            # default and the rendered path is opt-in for SPA scraping.
            cur.execute(
                "ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS "
                "scraper_render_enabled BOOLEAN NOT NULL DEFAULT false"
            )

            # ---------- Recurring scrape schedules ------------------------
            # A "schedule" is a saved scrape template (mode/url/objective/
            # target_shape/custom_schema) plus a cadence. The scheduler tick
            # spawns a new row in scrape_jobs every time the cadence fires;
            # we link them via scrape_jobs.schedule_id so the result detail
            # view can show what changed since the previous run.
            #
            #   schedule_mode   'hourly' | 'daily' | 'weekly' | 'interval'
            #   interval_minutes  used when schedule_mode='interval'
            #   daily_time      'HH:MM' (24h, UTC) for daily/weekly
            #   weekly_dow      0=Sun..6=Sat for weekly
            #   notify_email/phone  optional contact for change alerts
            #   notify_only_on_change  when False, every completion notifies
            #   last_run_at / last_job_id  most recent fire (cursor)
            #   next_run_at     scheduler cursor — next time we should fire
            cur.execute("""
                CREATE TABLE IF NOT EXISTS scrape_schedules (
                    id              SERIAL PRIMARY KEY,
                    name            VARCHAR(200) NOT NULL DEFAULT '',
                    input_mode      VARCHAR(20) NOT NULL DEFAULT 'url',
                    url             TEXT NOT NULL DEFAULT '',
                    objective       TEXT NOT NULL DEFAULT '',
                    target_shape    VARCHAR(40) NOT NULL DEFAULT 'free_form',
                    custom_schema   JSONB,
                    schedule_mode   VARCHAR(20) NOT NULL DEFAULT 'daily',
                    interval_minutes INTEGER NOT NULL DEFAULT 60,
                    daily_time      VARCHAR(5) NOT NULL DEFAULT '09:00',
                    weekly_dow      INTEGER NOT NULL DEFAULT 1,
                    enabled         BOOLEAN NOT NULL DEFAULT TRUE,
                    notify_email    TEXT NOT NULL DEFAULT '',
                    notify_phone    TEXT NOT NULL DEFAULT '',
                    notify_only_on_change BOOLEAN NOT NULL DEFAULT TRUE,
                    last_run_at     TIMESTAMP,
                    last_job_id     INTEGER,
                    next_run_at     TIMESTAMP,
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_scrape_schedules_enabled
                    ON scrape_schedules (enabled, next_run_at);
            """)
            # Tie each spawned job back to its schedule (NULL = one-shot job)
            # and remember a stable signature of the extracted record so we
            # can quickly say "did the result change since last run?"
            cur.execute(
                "ALTER TABLE scrape_jobs ADD COLUMN IF NOT EXISTS "
                "schedule_id INTEGER"
            )
            cur.execute(
                "ALTER TABLE scrape_jobs ADD COLUMN IF NOT EXISTS "
                "result_signature TEXT NOT NULL DEFAULT ''"
            )
            cur.execute(
                "ALTER TABLE scrape_jobs ADD COLUMN IF NOT EXISTS "
                "changed_from_previous BOOLEAN NOT NULL DEFAULT FALSE"
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_scrape_jobs_schedule "
                "ON scrape_jobs (schedule_id, requested_at DESC)"
            )
            # Live progress timeline. Each entry is
            #   {"ts": iso8601, "level": "info|warn|error", "message": str,
            #    "meta": {...optional structured detail...}}
            # The runner appends entries as it moves through fetch / clean /
            # render-fallback / AI extraction so the admin sees what the
            # scraper is actually doing instead of a bare 'running' status.
            cur.execute(
                "ALTER TABLE scrape_jobs ADD COLUMN IF NOT EXISTS "
                "progress_steps JSONB NOT NULL DEFAULT '[]'::jsonb"
            )
            # Cooperative-cancellation flag. The /stop admin endpoint sets
            # this to TRUE; the worker checks it between major steps and
            # exits gracefully (status='stopped') without losing the
            # progress timeline or any partially-fetched content.
            cur.execute(
                "ALTER TABLE scrape_jobs ADD COLUMN IF NOT EXISTS "
                "stop_requested BOOLEAN NOT NULL DEFAULT FALSE"
            )
            # Mid-run snapshot used for resume. After each expensive step
            # (URL fetch, HTML clean, render fallback, objective research)
            # the worker writes the bits needed to skip ahead on a future
            # /resume — e.g. {"cleaned": "...", "source": {...}} so a
            # resumed job can jump straight to AI extraction without
            # re-paying for the fetch + clean.
            cur.execute(
                "ALTER TABLE scrape_jobs ADD COLUMN IF NOT EXISTS "
                "partial_state JSONB"
            )
            # Auto-pause guardrail: when a schedule fails N times in a row
            # (e.g. dead site, missing API key, page shape changed) we stop
            # firing it instead of burning API budget and spamming alerts.
            # The admin can resume it from the dashboard once the underlying
            # issue is fixed.
            cur.execute(
                "ALTER TABLE scrape_schedules ADD COLUMN IF NOT EXISTS "
                "consecutive_failures INTEGER NOT NULL DEFAULT 0"
            )
            cur.execute(
                "ALTER TABLE scrape_schedules ADD COLUMN IF NOT EXISTS "
                "failure_threshold INTEGER NOT NULL DEFAULT 5"
            )
            cur.execute(
                "ALTER TABLE scrape_schedules ADD COLUMN IF NOT EXISTS "
                "auto_paused BOOLEAN NOT NULL DEFAULT FALSE"
            )
            cur.execute(
                "ALTER TABLE scrape_schedules ADD COLUMN IF NOT EXISTS "
                "auto_paused_at TIMESTAMP"
            )
            cur.execute(
                "ALTER TABLE scrape_schedules ADD COLUMN IF NOT EXISTS "
                "last_failure_error TEXT NOT NULL DEFAULT ''"
            )

            # =================================================================
            # SERVICE BOOKINGS — services + addons + availability + bookings
            # =================================================================
            # A service is anything a client can book on the public site.
            # Each service picks ONE pricing model:
            #   * rsvp      — free reservation, no payment
            #   * deposit   — Stripe Checkout for a partial up-front amount
            #   * full      — Stripe Checkout for the full price
            #   * contract  — admin uploads a contract template, client
            #                 downloads, signs offline, uploads signed copy
            #
            # Calendar-backed services (requires_calendar = TRUE) use
            # recurring weekly rules + per-date overrides. A confirmed
            # deposit/full booking instantly removes its slot from the
            # public availability response (subject to capacity_per_slot).
            cur.execute("""
                CREATE TABLE IF NOT EXISTS services (
                    id                     SERIAL PRIMARY KEY,
                    slug                   VARCHAR(100) UNIQUE NOT NULL,
                    name                   VARCHAR(200) NOT NULL,
                    short_description      VARCHAR(500) NOT NULL DEFAULT '',
                    long_description       TEXT NOT NULL DEFAULT '',
                    image_url              TEXT NOT NULL DEFAULT '',
                    duration_minutes       INTEGER NOT NULL DEFAULT 60,
                    pricing_model          VARCHAR(20) NOT NULL DEFAULT 'rsvp',
                    base_price_cents       INTEGER NOT NULL DEFAULT 0,
                    deposit_cents          INTEGER NOT NULL DEFAULT 0,
                    currency               VARCHAR(8) NOT NULL DEFAULT 'usd',
                    contract_template_url  TEXT NOT NULL DEFAULT '',
                    contract_template_name VARCHAR(200) NOT NULL DEFAULT '',
                    requires_calendar      BOOLEAN NOT NULL DEFAULT TRUE,
                    capacity_per_slot      INTEGER NOT NULL DEFAULT 1,
                    sort_order             INTEGER NOT NULL DEFAULT 0,
                    is_active              BOOLEAN NOT NULL DEFAULT TRUE,
                    created_at             TIMESTAMP DEFAULT NOW(),
                    updated_at             TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_services_active_sort
                    ON services (is_active, sort_order);

                CREATE TABLE IF NOT EXISTS service_addons (
                    id           SERIAL PRIMARY KEY,
                    service_id   INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
                    name         VARCHAR(200) NOT NULL,
                    description  TEXT NOT NULL DEFAULT '',
                    price_cents  INTEGER NOT NULL DEFAULT 0,
                    sort_order   INTEGER NOT NULL DEFAULT 0,
                    is_active    BOOLEAN NOT NULL DEFAULT TRUE
                );
                CREATE INDEX IF NOT EXISTS idx_service_addons_svc
                    ON service_addons (service_id, sort_order);

                -- Recurring weekly availability templates.
                CREATE TABLE IF NOT EXISTS service_availability_rules (
                    id            SERIAL PRIMARY KEY,
                    service_id    INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
                    day_of_week   INTEGER NOT NULL,        -- 0=Sun .. 6=Sat
                    start_time    TIME NOT NULL,
                    end_time      TIME NOT NULL,
                    slot_minutes  INTEGER NOT NULL DEFAULT 60,
                    is_active     BOOLEAN NOT NULL DEFAULT TRUE
                );
                CREATE INDEX IF NOT EXISTS idx_avail_rules_svc
                    ON service_availability_rules (service_id, day_of_week);

                -- Per-date overrides — block out a holiday, or open a
                -- one-off date that the recurring rules wouldn't cover.
                CREATE TABLE IF NOT EXISTS service_availability_overrides (
                    id             SERIAL PRIMARY KEY,
                    service_id     INTEGER NOT NULL REFERENCES services(id) ON DELETE CASCADE,
                    override_date  DATE NOT NULL,
                    start_time     TIME,                   -- NULL = whole day
                    end_time       TIME,
                    override_kind  VARCHAR(10) NOT NULL,   -- 'block' or 'open'
                    slot_minutes   INTEGER NOT NULL DEFAULT 60,
                    note           TEXT NOT NULL DEFAULT ''
                );
                CREATE INDEX IF NOT EXISTS idx_avail_ovr_svc
                    ON service_availability_overrides (service_id, override_date);

                CREATE TABLE IF NOT EXISTS service_bookings (
                    id                    SERIAL PRIMARY KEY,
                    service_id            INTEGER REFERENCES services(id) ON DELETE SET NULL,
                    booking_token         VARCHAR(64) NOT NULL UNIQUE,
                    client_name           VARCHAR(200) NOT NULL,
                    client_email          VARCHAR(200) NOT NULL,
                    client_phone          VARCHAR(50) NOT NULL DEFAULT '',
                    notes                 TEXT NOT NULL DEFAULT '',
                    scheduled_date        DATE,
                    scheduled_start       TIME,
                    scheduled_end         TIME,
                    selected_addon_ids    INTEGER[] NOT NULL DEFAULT '{}',
                    addon_snapshot        JSONB NOT NULL DEFAULT '[]'::jsonb,
                    pricing_model         VARCHAR(20) NOT NULL DEFAULT 'rsvp',
                    base_price_cents      INTEGER NOT NULL DEFAULT 0,
                    addons_total_cents    INTEGER NOT NULL DEFAULT 0,
                    total_cents           INTEGER NOT NULL DEFAULT 0,
                    amount_paid_cents     INTEGER NOT NULL DEFAULT 0,
                    currency              VARCHAR(8) NOT NULL DEFAULT 'usd',
                    payment_status        VARCHAR(20) NOT NULL DEFAULT 'none',
                    stripe_session_id     VARCHAR(200) NOT NULL DEFAULT '',
                    signed_contract_url   TEXT NOT NULL DEFAULT '',
                    status                VARCHAR(20) NOT NULL DEFAULT 'pending',
                    utm_source            VARCHAR(200) NOT NULL DEFAULT '',
                    utm_medium            VARCHAR(200) NOT NULL DEFAULT '',
                    utm_campaign          VARCHAR(200) NOT NULL DEFAULT '',
                    created_at            TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_bookings_slot
                    ON service_bookings (service_id, scheduled_date, scheduled_start)
                    WHERE status IN ('pending', 'confirmed')
                      AND payment_status NOT IN ('expired', 'refunded');
                CREATE INDEX IF NOT EXISTS idx_bookings_recent
                    ON service_bookings (created_at DESC);

                -- =============================================================
                -- COST TRANSPARENCY (Phase 2)
                -- =============================================================
                -- model_prices: admin-editable per-unit prices for every
                -- third-party API the app meters. We use *unit* names
                -- specific to each provider so the math is transparent:
                --   * OpenAI / Claude chat: input_price_per_million_tokens
                --     and output_price_per_million_tokens (cost = tokens
                --     * price / 1_000_000).
                --   * TTS (OpenAI / ElevenLabs): tts_price_per_million_chars.
                --   * STT (Whisper): stt_price_per_minute.
                --   * SMS (Twilio): sms_price_per_segment.
                -- A single row holds whichever fields apply for that
                -- model; unused fields are NULL (NOT zero — zero would
                -- silently price something at $0). The `active` flag
                -- lets the admin retire an old model row without losing
                -- the historical reference.
                CREATE TABLE IF NOT EXISTS model_prices (
                    id                                SERIAL PRIMARY KEY,
                    provider                          VARCHAR(40)  NOT NULL,
                    model                             VARCHAR(120) NOT NULL,
                    surface                           VARCHAR(40)  NOT NULL DEFAULT 'chat',
                    input_price_per_million_tokens    NUMERIC(12,6),
                    output_price_per_million_tokens   NUMERIC(12,6),
                    tts_price_per_million_chars       NUMERIC(12,6),
                    stt_price_per_minute              NUMERIC(12,6),
                    sms_price_per_segment             NUMERIC(12,6),
                    notes                             TEXT NOT NULL DEFAULT '',
                    active                            BOOLEAN NOT NULL DEFAULT TRUE,
                    updated_at                        TIMESTAMP DEFAULT NOW()
                );
                CREATE UNIQUE INDEX IF NOT EXISTS idx_model_prices_lookup
                    ON model_prices (provider, model, surface);

                -- api_cost_events: one row per LLM round (visitor chat,
                -- admin chat, page generation, deck narration, etc).
                -- The unit_*_price_usd columns stamp the price *at the
                -- time of the call* so a later price edit never shifts
                -- historical totals. cost_usd = NULL means the call
                -- happened but we couldn't price it (no matching
                -- model_prices row, or provider didn't return usage).
                CREATE TABLE IF NOT EXISTS api_cost_events (
                    id                       SERIAL PRIMARY KEY,
                    tenant_id                INTEGER NOT NULL DEFAULT 1,
                    session_id               VARCHAR(100) NOT NULL DEFAULT '',
                    visitor_id               VARCHAR(100) NOT NULL DEFAULT '',
                    surface                  VARCHAR(40)  NOT NULL DEFAULT 'visitor_chat',
                    provider                 VARCHAR(40)  NOT NULL DEFAULT '',
                    model                    VARCHAR(120) NOT NULL DEFAULT '',
                    prompt_tokens            INTEGER NOT NULL DEFAULT 0,
                    completion_tokens        INTEGER NOT NULL DEFAULT 0,
                    total_tokens             INTEGER NOT NULL DEFAULT 0,
                    unit_input_price_usd     NUMERIC(14,8),
                    unit_output_price_usd    NUMERIC(14,8),
                    cost_usd                 NUMERIC(14,8),
                    created_at               TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_api_cost_tenant_created
                    ON api_cost_events (tenant_id, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_api_cost_tenant_surface
                    ON api_cost_events (tenant_id, surface, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_api_cost_tenant_model
                    ON api_cost_events (tenant_id, provider, model, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_api_cost_tenant_session
                    ON api_cost_events (tenant_id, session_id, created_at DESC);

                -- voice_cost_events: one row per TTS render OR STT
                -- transcription. feature_type mirrors voice_usage_log
                -- ('tts_generate_openai', 'tts_generate_elevenlabs',
                -- 'tts_cached', 'stt_whisper', 'sample_audition').
                -- char_count is set for TTS, audio_seconds for STT.
                CREATE TABLE IF NOT EXISTS voice_cost_events (
                    id                       SERIAL PRIMARY KEY,
                    tenant_id                INTEGER NOT NULL DEFAULT 1,
                    session_id               VARCHAR(100) NOT NULL DEFAULT '',
                    surface                  VARCHAR(40)  NOT NULL DEFAULT 'voice_tts',
                    provider                 VARCHAR(40)  NOT NULL DEFAULT '',
                    model                    VARCHAR(120) NOT NULL DEFAULT '',
                    feature_type             VARCHAR(40)  NOT NULL DEFAULT '',
                    voice_id                 TEXT NOT NULL DEFAULT '',
                    char_count               INTEGER NOT NULL DEFAULT 0,
                    audio_seconds            NUMERIC(10,3) NOT NULL DEFAULT 0,
                    unit_tts_price_usd       NUMERIC(14,8),
                    unit_stt_price_usd       NUMERIC(14,8),
                    cost_usd                 NUMERIC(14,8),
                    created_at               TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_voice_cost_tenant_created
                    ON voice_cost_events (tenant_id, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_voice_cost_tenant_provider
                    ON voice_cost_events (tenant_id, provider, created_at DESC);

                -- sms_cost_events: one row per outbound SMS send
                -- attempt. Twilio's response includes 'num_segments'
                -- which we use to compute cost. The status callback
                -- webhook can correct the segment count if Twilio
                -- later revises it (rare but possible for long /
                -- non-GSM7 messages); we update by message_sid.
                CREATE TABLE IF NOT EXISTS sms_cost_events (
                    id                       SERIAL PRIMARY KEY,
                    tenant_id                INTEGER NOT NULL DEFAULT 1,
                    surface                  VARCHAR(40)  NOT NULL DEFAULT 'sms_outbound',
                    provider                 VARCHAR(40)  NOT NULL DEFAULT 'twilio',
                    to_number                VARCHAR(40)  NOT NULL DEFAULT '',
                    message_sid              VARCHAR(80)  NOT NULL DEFAULT '',
                    segments                 INTEGER,
                    unit_sms_price_usd       NUMERIC(14,8),
                    cost_usd                 NUMERIC(14,8),
                    created_at               TIMESTAMP DEFAULT NOW()
                );
                -- Earlier dev iterations had `segments INTEGER NOT NULL
                -- DEFAULT 1`. The "no fabricated numbers" rule means we
                -- now write segments=NULL when Twilio's POST response
                -- doesn't include num_segments and let the status
                -- webhook fill it in. Drop the NOT NULL post-hoc.
                ALTER TABLE sms_cost_events
                    ALTER COLUMN segments DROP NOT NULL;
                ALTER TABLE sms_cost_events
                    ALTER COLUMN segments DROP DEFAULT;
                CREATE INDEX IF NOT EXISTS idx_sms_cost_tenant_created
                    ON sms_cost_events (tenant_id, created_at DESC);
                -- UNIQUE so retries / webhook updates can never create
                -- duplicate ledger rows for the same Twilio SID. The
                -- empty-string filter lets older rows (or any future
                -- non-Twilio path) continue to insert without conflict.
                -- DROP first because earlier dev iterations created the
                -- index as non-unique under the same name; IF NOT EXISTS
                -- alone would silently skip the upgrade.
                DROP INDEX IF EXISTS idx_sms_cost_msgsid;
                CREATE UNIQUE INDEX IF NOT EXISTS idx_sms_cost_msgsid
                    ON sms_cost_events (tenant_id, message_sid)
                    WHERE message_sid <> '';

                -- tenant_cost_caps: one row per tenant configuring the
                -- monthly USD cap, the warn-at-percent trigger, and the
                -- behaviour to apply when the cap is reached. Default
                -- on first seed is 'alert_only' so existing tenants get
                -- visibility without any service interruption.
                CREATE TABLE IF NOT EXISTS tenant_cost_caps (
                    id                       SERIAL PRIMARY KEY,
                    tenant_id                INTEGER NOT NULL UNIQUE,
                    monthly_cap_usd          NUMERIC(12,2),
                    warn_at_percent          INTEGER NOT NULL DEFAULT 80,
                    cap_behavior             VARCHAR(20) NOT NULL DEFAULT 'alert_only',
                    alert_email              TEXT NOT NULL DEFAULT '',
                    digest_email             TEXT NOT NULL DEFAULT '',
                    digest_send_hour_utc     INTEGER NOT NULL DEFAULT 9,
                    last_warned_period       VARCHAR(10) NOT NULL DEFAULT '',
                    last_capped_period       VARCHAR(10) NOT NULL DEFAULT '',
                    updated_at               TIMESTAMP DEFAULT NOW()
                );

                -- The original table shipped with DEFAULT 14 (UTC-only
                -- assumption); the spec actually wants Monday 09:00 in
                -- the tenant's local timezone. Re-aim the default for
                -- new tenants AND fix any existing rows still on the
                -- old default so they don't keep emailing at 14:00 local.
                ALTER TABLE tenant_cost_caps
                  ALTER COLUMN digest_send_hour_utc SET DEFAULT 9;
                UPDATE tenant_cost_caps
                   SET digest_send_hour_utc = 9
                 WHERE digest_send_hour_utc = 14;

                -- cost_alerts: idempotency log for warn-line and cap
                -- alert emails. (tenant_id, period, kind) is unique
                -- so the async warn-check can never double-fire even
                -- under concurrent requests.
                CREATE TABLE IF NOT EXISTS cost_alerts (
                    id              SERIAL PRIMARY KEY,
                    tenant_id       INTEGER NOT NULL,
                    period          VARCHAR(10) NOT NULL,
                    kind            VARCHAR(20) NOT NULL,
                    spent_usd       NUMERIC(12,4) NOT NULL DEFAULT 0,
                    cap_usd         NUMERIC(12,4) NOT NULL DEFAULT 0,
                    sent_at         TIMESTAMP DEFAULT NOW()
                );
                CREATE UNIQUE INDEX IF NOT EXISTS idx_cost_alerts_unique
                    ON cost_alerts (tenant_id, period, kind);

                -- weekly_digest_sends: idempotency log for the Monday
                -- "What your AI did this week" email. (tenant_id,
                -- week_start) is unique so a scheduler restart on a
                -- Monday morning can never double-send.
                CREATE TABLE IF NOT EXISTS weekly_digest_sends (
                    id              SERIAL PRIMARY KEY,
                    tenant_id       INTEGER NOT NULL,
                    week_start      DATE NOT NULL,
                    sent_at         TIMESTAMP DEFAULT NOW(),
                    payload_json    JSONB
                );
                CREATE UNIQUE INDEX IF NOT EXISTS idx_weekly_digest_unique
                    ON weekly_digest_sends (tenant_id, week_start);

                -- Task #80: admin chat multimodal input.
                -- One row per uploaded attachment. Attachments are
                -- created via /admin/api/chat/attachments/upload BEFORE
                -- the user message is sent, then their ids are passed
                -- into /admin/api/chat/stream which assembles them into
                -- the next assistant turn (image_url parts for vision,
                -- transient extracted-text system block for documents).
                -- session_id is the admin chat session; message_id is
                -- populated after persistence so attachments can be
                -- replayed on /history.
                CREATE TABLE IF NOT EXISTS admin_chat_attachments (
                    id              SERIAL PRIMARY KEY,
                    tenant_id       INTEGER      NOT NULL DEFAULT 1,
                    session_id      VARCHAR(100) NOT NULL DEFAULT '',
                    message_id      INTEGER,
                    kind            VARCHAR(20)  NOT NULL DEFAULT 'file',
                    filename        TEXT         NOT NULL DEFAULT '',
                    mime            VARCHAR(120) NOT NULL DEFAULT '',
                    size_bytes      INTEGER      NOT NULL DEFAULT 0,
                    storage_key     TEXT         NOT NULL DEFAULT '',
                    thumbnail_key   TEXT,
                    extracted_text  TEXT,
                    created_at      TIMESTAMP    DEFAULT NOW()
                );
                -- Defensive ALTER for any install that created the
                -- table BEFORE the tenant_id / thumbnail_key columns
                -- were added.
                ALTER TABLE admin_chat_attachments
                  ADD COLUMN IF NOT EXISTS tenant_id INTEGER NOT NULL DEFAULT 1;
                ALTER TABLE admin_chat_attachments
                  ADD COLUMN IF NOT EXISTS thumbnail_key TEXT;
                CREATE INDEX IF NOT EXISTS idx_admin_chat_attachments_tenant
                    ON admin_chat_attachments (tenant_id, session_id, created_at);
                CREATE INDEX IF NOT EXISTS idx_admin_chat_attachments_session
                    ON admin_chat_attachments (session_id, created_at);

                -- Task #80: parallel subagent run log. One row per
                -- `spawn_agents` worker — captures the sub-task, the
                -- persona/tool subset it was constrained to, token and
                -- cost totals (also written to api_cost_events under
                -- surface='admin_chat'), and wall-clock duration so the
                -- admin can see which subtasks ran in parallel and how
                -- much they cost.
                CREATE TABLE IF NOT EXISTS admin_subagent_runs (
                    id                 SERIAL PRIMARY KEY,
                    tenant_id          INTEGER      NOT NULL DEFAULT 1,
                    parent_session_id  VARCHAR(100) NOT NULL DEFAULT '',
                    sub_task           TEXT         NOT NULL DEFAULT '',
                    persona            VARCHAR(40)  NOT NULL DEFAULT 'general',
                    model              TEXT         NOT NULL DEFAULT '',
                    prompt_tokens      INTEGER      NOT NULL DEFAULT 0,
                    completion_tokens  INTEGER      NOT NULL DEFAULT 0,
                    cost_usd           NUMERIC(12,6),
                    duration_ms        INTEGER      NOT NULL DEFAULT 0,
                    status             VARCHAR(20)  NOT NULL DEFAULT 'completed',
                    result_preview     TEXT,
                    error_text         TEXT,
                    created_at         TIMESTAMP    DEFAULT NOW()
                );
                ALTER TABLE admin_subagent_runs
                  ADD COLUMN IF NOT EXISTS tenant_id INTEGER NOT NULL DEFAULT 1;
                CREATE INDEX IF NOT EXISTS idx_admin_subagent_runs_tenant
                    ON admin_subagent_runs (tenant_id, created_at);
                CREATE INDEX IF NOT EXISTS idx_admin_subagent_runs_session
                    ON admin_subagent_runs (parent_session_id, created_at);

                -- Task #80: atomic per-tenant daily subagent counter.
                -- A separate counters table lets the quota check be a
                -- SINGLE conditional UPSERT (INSERT ... ON CONFLICT DO
                -- UPDATE WHERE count+req <= cap RETURNING) instead of
                -- a racy SELECT-then-INSERT. The WHERE on DO UPDATE
                -- is the atomic gate: when it fails, RETURNING is
                -- empty and the caller knows quota would be exceeded.
                CREATE TABLE IF NOT EXISTS admin_subagent_daily_counters (
                    tenant_id  INTEGER NOT NULL,
                    day        DATE    NOT NULL,
                    count      INTEGER NOT NULL DEFAULT 0,
                    updated_at TIMESTAMP DEFAULT NOW(),
                    PRIMARY KEY (tenant_id, day)
                );

                -- Task #80: per-tenant parallel subagent quotas. Reuses
                -- tenant_cost_caps so admins can tune chat-quality
                -- knobs (parallelism, daily-run cap) in the same place
                -- they tune $$ caps. Both DEFAULT to safe values so
                -- existing tenants pick them up on next restart.
                ALTER TABLE tenant_cost_caps
                  ADD COLUMN IF NOT EXISTS max_parallel_subagents INTEGER NOT NULL DEFAULT 5;
                ALTER TABLE tenant_cost_caps
                  ADD COLUMN IF NOT EXISTS daily_subagent_runs_cap INTEGER NOT NULL DEFAULT 50;

                -- Task #80: per-message attachment ids snapshot, so a
                -- history reload can show "📎 file.pdf" chips on the
                -- right user bubble.
                ALTER TABLE admin_chat_messages
                  ADD COLUMN IF NOT EXISTS attachment_ids_json JSONB;
            """)

            # Seed model_prices with current public list prices for the
            # models actually wired into this app. ON CONFLICT DO NOTHING
            # so an admin who edits a price in the UI never gets it
            # reverted on the next restart. (provider, model, surface)
            # is the conflict target via idx_model_prices_lookup.
            cur.execute(
                """
                INSERT INTO model_prices
                  (provider, model, surface,
                   input_price_per_million_tokens,
                   output_price_per_million_tokens,
                   tts_price_per_million_chars,
                   stt_price_per_minute,
                   sms_price_per_segment, notes)
                VALUES
                  ('openai',     'gpt-4o-mini',           'chat', 0.150, 0.600, NULL, NULL, NULL,
                   'OpenAI gpt-4o-mini list price (2025)'),
                  ('openai',     'gpt-4o',                'chat', 2.500, 10.000, NULL, NULL, NULL,
                   'OpenAI gpt-4o list price (2025)'),
                  ('anthropic',  'claude-sonnet-4-5',     'chat', 3.000, 15.000, NULL, NULL, NULL,
                   'Anthropic Claude Sonnet 4.5 list price (2025)'),
                  ('anthropic',  'claude-opus-4',         'chat', 15.000, 75.000, NULL, NULL, NULL,
                   'Anthropic Claude Opus 4 list price (2025)'),
                  ('openai',     'tts-1',                 'tts',  NULL, NULL, 15.000, NULL, NULL,
                   'OpenAI tts-1 list price (2025): $15 per 1M chars'),
                  ('openai',     'tts-1-hd',              'tts',  NULL, NULL, 30.000, NULL, NULL,
                   'OpenAI tts-1-hd list price (2025): $30 per 1M chars'),
                  ('elevenlabs', 'eleven_turbo_v2_5',     'tts',  NULL, NULL, 50.000, NULL, NULL,
                   'ElevenLabs Turbo v2.5 approx price (2025)'),
                  ('elevenlabs', 'eleven_multilingual_v2','tts',  NULL, NULL, 90.000, NULL, NULL,
                   'ElevenLabs Multilingual v2 approx price (2025)'),
                  ('openai',     'whisper-1',             'stt',  NULL, NULL, NULL, 0.006, NULL,
                   'OpenAI Whisper list price (2025): $0.006 per minute'),
                  ('twilio',     'sms-us',                'sms',  NULL, NULL, NULL, NULL, 0.0079,
                   'Twilio US outbound SMS approx price (2025): $0.0079 per segment')
                ON CONFLICT (provider, model, surface) DO NOTHING
                """
            )

            # Seed the default tenant cost cap row. cap_behavior =
            # 'alert_only' so no existing tenant suddenly starts being
            # blocked / throttled the moment this ships — they get
            # observability + an email when they cross 80% of any cap
            # they later set, but no behaviour change unless they
            # opt in.
            cur.execute(
                """
                INSERT INTO tenant_cost_caps
                  (tenant_id, monthly_cap_usd, warn_at_percent,
                   cap_behavior)
                VALUES (1, NULL, 80, 'alert_only')
                ON CONFLICT (tenant_id) DO NOTHING
                """
            )

            # =================================================================
            # VELO AUDIT LOG
            # =================================================================
            # Every command VELO Master sends to /api/velo/command is logged
            # here, including the params, status, a truncated result summary,
            # and any error message. Used for traceability when VELO has
            # made changes to this install (feature flips, FAQ edits, etc.).
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS velo_audit_log (
                    id              SERIAL PRIMARY KEY,
                    command         VARCHAR(100) NOT NULL,
                    params          JSONB DEFAULT '{}'::jsonb,
                    status          VARCHAR(20) NOT NULL DEFAULT 'ok',
                    result_summary  TEXT NOT NULL DEFAULT '',
                    error_msg       TEXT NOT NULL DEFAULT '',
                    actor           VARCHAR(50) NOT NULL DEFAULT 'velo',
                    created_at      TIMESTAMP DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS idx_velo_audit_created
                    ON velo_audit_log (created_at);
                CREATE INDEX IF NOT EXISTS idx_velo_audit_command
                    ON velo_audit_log (command);
                """
            )

            # =============================================================
            # STRIPE ADMIN — mode toggle + product mirror map
            # =============================================================
            # `stripe_settings` is a single-row config (id=1) that lets the
            # admin pick "test" vs "live" mode at runtime without touching
            # env vars (the keys themselves still live in env / Replit
            # connectors — we never store secrets in the DB). The row is
            # seeded lazily by stripe_settings.get_settings() if missing.
            #
            # `stripe_product_sync` maps each local products.id to the
            # Stripe Product ID + Price ID it was last mirrored to, keyed
            # by mode so test and live each have independent mappings
            # (a flip between modes does NOT re-create products in the
            # other mode's catalog — they stay where they are).
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS stripe_settings (
                    id                    INTEGER PRIMARY KEY,
                    mode                  VARCHAR(10) NOT NULL DEFAULT 'test',
                    autosync_products     BOOLEAN NOT NULL DEFAULT FALSE,
                    last_health_check_at  TIMESTAMP,
                    last_health_ok        BOOLEAN,
                    last_health_error     TEXT NOT NULL DEFAULT '',
                    last_backfill_at      TIMESTAMP,
                    last_backfill_summary JSONB DEFAULT '{}'::jsonb,
                    updated_at            TIMESTAMP DEFAULT NOW()
                );

                CREATE TABLE IF NOT EXISTS stripe_product_sync (
                    id                  SERIAL PRIMARY KEY,
                    local_product_id    INTEGER NOT NULL
                        REFERENCES products(id) ON DELETE CASCADE,
                    mode                VARCHAR(10) NOT NULL,
                    stripe_product_id   VARCHAR(100) NOT NULL DEFAULT '',
                    stripe_price_id     VARCHAR(100) NOT NULL DEFAULT '',
                    synced_price_cents  INTEGER,
                    synced_currency     VARCHAR(8) NOT NULL DEFAULT '',
                    last_synced_at      TIMESTAMP,
                    last_attempt_at     TIMESTAMP DEFAULT NOW(),
                    last_error          TEXT NOT NULL DEFAULT '',
                    UNIQUE (local_product_id, mode)
                );
                CREATE INDEX IF NOT EXISTS idx_stripe_sync_product
                    ON stripe_product_sync (local_product_id);
                CREATE INDEX IF NOT EXISTS idx_stripe_sync_mode
                    ON stripe_product_sync (mode);
                """
            )

            # AI EDITABLE PROMPTS — one row per editable system prompt. Seeded
            # with current defaults by sync_ai_prompts() at boot; super-admin
            # edits land here and are served from an in-memory cache.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS ai_prompts (
                    id          SERIAL PRIMARY KEY,
                    prompt_key  TEXT UNIQUE NOT NULL,
                    content     TEXT NOT NULL DEFAULT '',
                    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_by  TEXT
                );
                """
            )

            # AI CONTROL SETTINGS (Phase 5) — super-admin-tunable knobs for the
            # Admin AI (reliability/context/safety/activity). One row per knob;
            # absent = fall back to env var, then to the registry default. Also
            # declared in migration 0009 for existing DBs. Mirrors ai_prompts.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS ai_control_settings (
                    key         TEXT PRIMARY KEY,
                    value       TEXT NOT NULL DEFAULT '',
                    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_by  TEXT NOT NULL DEFAULT ''
                );
                """
            )

            # AI ACTIVITY LOG (Phase 5) — one row per admin-AI turn, written by
            # the pylego.obs DB sink. Metadata + (redacted) question/answer so the
            # super admin can review what the AI did. Also in migration 0009.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS ai_activity_log (
                    id            BIGSERIAL PRIMARY KEY,
                    tenant_id     INTEGER NOT NULL DEFAULT 1,
                    surface       TEXT NOT NULL DEFAULT 'admin',
                    session_id    TEXT,
                    model         TEXT,
                    provider      TEXT,
                    rounds        INTEGER NOT NULL DEFAULT 0,
                    tool_calls    INTEGER NOT NULL DEFAULT 0,
                    tokens_in     INTEGER NOT NULL DEFAULT 0,
                    tokens_out    INTEGER NOT NULL DEFAULT 0,
                    cost_usd      DOUBLE PRECISION NOT NULL DEFAULT 0,
                    duration_ms   INTEGER NOT NULL DEFAULT 0,
                    status        TEXT,
                    error_text    TEXT,
                    user_message  TEXT,
                    final_answer  TEXT,
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS ai_activity_log_recent_idx "
                "ON ai_activity_log (created_at DESC);"
            )

            # VISITOR PROFILES (Phase 6 / Epic D, task 042) — one row per stable
            # visitor_id, accumulating the soft signals the concierge picks up
            # over time: interests/needs (jsonb tag arrays), a 0-100 lead_score,
            # a marketing-consent flag, and a short rolling summary. Written by a
            # gated, fail-open background updater after each visitor turn (the
            # 'Visitor CRM' AI Control knob); empty/no-op when the knob is off, so
            # a fresh fork behaves exactly as before. Also in migration 0012.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS visitor_profiles (
                    id           BIGSERIAL PRIMARY KEY,
                    tenant_id    INTEGER NOT NULL DEFAULT 1,
                    visitor_id   VARCHAR(100) NOT NULL,
                    interests    JSONB NOT NULL DEFAULT '[]'::jsonb,
                    needs        JSONB NOT NULL DEFAULT '[]'::jsonb,
                    lead_score   INTEGER NOT NULL DEFAULT 0,
                    consent      BOOLEAN NOT NULL DEFAULT FALSE,
                    summary      TEXT NOT NULL DEFAULT '',
                    turns        INTEGER NOT NULL DEFAULT 0,
                    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (tenant_id, visitor_id)
                );
                """
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS visitor_profiles_lead_idx "
                "ON visitor_profiles (tenant_id, lead_score DESC, updated_at DESC);"
            )

            # OFFERS / DEALS (Phase 6 / Epic D, task 044) — super-admin-defined
            # promotions the visitor concierge can surface CONTEXTUALLY via the
            # gated `lookup_offers` tool. trigger_tags (jsonb array) lets an offer
            # target visitors who showed matching interests; an empty array means
            # "always eligible". active + the optional starts_at/ends_at window
            # bound when an offer is live. Nothing is surfaced unless the 'Offers'
            # knob is on AND the skill is enabled, so a fresh fork is unaffected.
            # Also in migration 0013.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS offers (
                    id            BIGSERIAL PRIMARY KEY,
                    tenant_id     INTEGER NOT NULL DEFAULT 1,
                    title         TEXT NOT NULL DEFAULT '',
                    description   TEXT NOT NULL DEFAULT '',
                    code          TEXT NOT NULL DEFAULT '',
                    cta_url       TEXT NOT NULL DEFAULT '',
                    trigger_tags  JSONB NOT NULL DEFAULT '[]'::jsonb,
                    active        BOOLEAN NOT NULL DEFAULT TRUE,
                    starts_at     TIMESTAMPTZ,
                    ends_at       TIMESTAMPTZ,
                    priority      INTEGER NOT NULL DEFAULT 0,
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                """
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS offers_active_idx "
                "ON offers (tenant_id, active, priority DESC);"
            )

            # LEADS + CALLBACK REQUESTS (Phase 6 / Epic D, task 045) — captured by
            # the gated agentic-growth tools (capture_lead / request_callback). The
            # concierge writes a row only when the relevant knob is ON; a fresh
            # fork captures nothing. These hold operator sales data (the visitor's
            # own contact details, by design) — super-admin reads them via the
            # Leads / Callbacks APIs. Also in migration 0014.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS leads (
                    id           BIGSERIAL PRIMARY KEY,
                    tenant_id    INTEGER NOT NULL DEFAULT 1,
                    name         TEXT NOT NULL DEFAULT '',
                    email        TEXT NOT NULL DEFAULT '',
                    phone        TEXT NOT NULL DEFAULT '',
                    interest     TEXT NOT NULL DEFAULT '',
                    message      TEXT NOT NULL DEFAULT '',
                    source       TEXT NOT NULL DEFAULT 'ai_chat',
                    visitor_id   VARCHAR(100) NOT NULL DEFAULT '',
                    status       TEXT NOT NULL DEFAULT 'new',
                    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS leads_recent_idx
                    ON leads (tenant_id, created_at DESC);

                CREATE TABLE IF NOT EXISTS callback_requests (
                    id             BIGSERIAL PRIMARY KEY,
                    tenant_id      INTEGER NOT NULL DEFAULT 1,
                    name           TEXT NOT NULL DEFAULT '',
                    phone          TEXT NOT NULL DEFAULT '',
                    preferred_time TEXT NOT NULL DEFAULT '',
                    reason         TEXT NOT NULL DEFAULT '',
                    ai_summary     TEXT NOT NULL DEFAULT '',
                    visitor_id     VARCHAR(100) NOT NULL DEFAULT '',
                    status         TEXT NOT NULL DEFAULT 'new',
                    created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS callbacks_recent_idx
                    ON callback_requests (tenant_id, created_at DESC);
                """
            )

            # VISITOR PERSONAS (Phase 6 / Epic E, task 046) — super-admin-defined
            # specialist agents (sales / support / booking / …) the visitor
            # concierge can route a turn to. Each persona augments the system
            # prompt (prompt_suffix), constrains the tool set (tool_names jsonb;
            # [] = all tools), and may pin a model. A cheap classifier picks the
            # persona per turn ONLY when the 'visitor_persona_router_enabled' knob
            # is on; off = single-agent behavior (unchanged). Also migration 0015.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS visitor_personas (
                    id            BIGSERIAL PRIMARY KEY,
                    tenant_id     INTEGER NOT NULL DEFAULT 1,
                    persona_key   VARCHAR(40) NOT NULL,
                    label         TEXT NOT NULL DEFAULT '',
                    prompt_suffix TEXT NOT NULL DEFAULT '',
                    tool_names    JSONB NOT NULL DEFAULT '[]'::jsonb,
                    model         TEXT NOT NULL DEFAULT '',
                    enabled       BOOLEAN NOT NULL DEFAULT TRUE,
                    sort_order    INTEGER NOT NULL DEFAULT 0,
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (tenant_id, persona_key)
                );
                CREATE INDEX IF NOT EXISTS visitor_personas_enabled_idx
                    ON visitor_personas (tenant_id, enabled, sort_order);
                """
            )

            # MEETINGS (Phase 6 / Epic F, task 047) — meeting/booking requests the
            # concierge takes via the gated book_meeting tool. status flows
            # 'requested' → 'booked' (set when a connected Calendar MCP confirms
            # an event; calendar_event_id holds the provider id). When no calendar
            # is connected the row is simply stored as 'requested' for the team to
            # action. Nothing is written unless the 'Meetings' knob is on. Also in
            # migration 0017.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS meetings (
                    id                BIGSERIAL PRIMARY KEY,
                    tenant_id         INTEGER NOT NULL DEFAULT 1,
                    name              TEXT NOT NULL DEFAULT '',
                    email             TEXT NOT NULL DEFAULT '',
                    phone             TEXT NOT NULL DEFAULT '',
                    requested_time    TEXT NOT NULL DEFAULT '',
                    start_iso         TEXT NOT NULL DEFAULT '',
                    duration_minutes  INTEGER NOT NULL DEFAULT 30,
                    notes             TEXT NOT NULL DEFAULT '',
                    status            TEXT NOT NULL DEFAULT 'requested',
                    calendar_event_id TEXT NOT NULL DEFAULT '',
                    visitor_id        VARCHAR(100) NOT NULL DEFAULT '',
                    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS meetings_recent_idx
                    ON meetings (tenant_id, created_at DESC);
                """
            )

            # VOICE CALLS (Phase 6 / Epic F, task 049) — one row per inbound
            # Twilio Voice call routed to the AI concierge. The live media bridge
            # (Twilio <Stream> ↔ a realtime voice model) is the credential/infra
            # leg, deferred to an operator runbook; this table + the webhooks log
            # and track calls so the feature is observable. Nothing happens unless
            # the 'live_call_enabled' knob is on. Also in migration 0018.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS voice_calls (
                    id            BIGSERIAL PRIMARY KEY,
                    tenant_id     INTEGER NOT NULL DEFAULT 1,
                    call_sid      VARCHAR(64) NOT NULL DEFAULT '',
                    from_number   TEXT NOT NULL DEFAULT '',
                    to_number     TEXT NOT NULL DEFAULT '',
                    status        TEXT NOT NULL DEFAULT 'initiated',
                    summary       TEXT NOT NULL DEFAULT '',
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS voice_calls_recent_idx
                    ON voice_calls (tenant_id, created_at DESC);
                CREATE INDEX IF NOT EXISTS voice_calls_sid_idx
                    ON voice_calls (call_sid);
                """
            )

            # =========================================================
            # RESEARCH & CONTENT ENGINE (Phase 8 / task 062)
            # =========================================================
            # The shared "Sources" layer + content pipeline. Gather (scraper /
            # web / KB / MCP / Datahub) writes research_sources; Deep Research
            # synthesizes research_reports (cited); the Content Studio turns a
            # report into content_drafts (review-gated) that publish into the
            # existing content tables; publish_capabilities are super-admin-
            # defined output channels (mcp / webhook / http_api / python).
            # Everything is gated by default-OFF AI Control knobs, so a fresh
            # fork is unaffected. Also in migration 0026.
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS research_reports (
                    id           BIGSERIAL PRIMARY KEY,
                    tenant_id    INTEGER NOT NULL DEFAULT 1,
                    topic        TEXT NOT NULL DEFAULT '',
                    question     TEXT NOT NULL DEFAULT '',
                    summary      TEXT NOT NULL DEFAULT '',
                    key_points   JSONB NOT NULL DEFAULT '[]'::jsonb,
                    citations    JSONB NOT NULL DEFAULT '[]'::jsonb,
                    status       TEXT NOT NULL DEFAULT 'draft',
                    model        TEXT NOT NULL DEFAULT '',
                    created_by   TEXT NOT NULL DEFAULT '',
                    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS research_reports_recent_idx
                    ON research_reports (tenant_id, created_at DESC);

                CREATE TABLE IF NOT EXISTS research_sources (
                    id           BIGSERIAL PRIMARY KEY,
                    tenant_id    INTEGER NOT NULL DEFAULT 1,
                    report_id    BIGINT REFERENCES research_reports(id) ON DELETE CASCADE,
                    source_type  TEXT NOT NULL DEFAULT 'web',
                    url          TEXT NOT NULL DEFAULT '',
                    title        TEXT NOT NULL DEFAULT '',
                    content_text TEXT NOT NULL DEFAULT '',
                    content_hash TEXT NOT NULL DEFAULT '',
                    fetched_at   TIMESTAMPTZ,
                    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS research_sources_report_idx
                    ON research_sources (report_id);
                CREATE INDEX IF NOT EXISTS research_sources_hash_idx
                    ON research_sources (tenant_id, content_hash);

                CREATE TABLE IF NOT EXISTS content_drafts (
                    id              BIGSERIAL PRIMARY KEY,
                    tenant_id       INTEGER NOT NULL DEFAULT 1,
                    content_type    TEXT NOT NULL DEFAULT 'blog',
                    title           TEXT NOT NULL DEFAULT '',
                    body            TEXT NOT NULL DEFAULT '',
                    meta            JSONB NOT NULL DEFAULT '{}'::jsonb,
                    source_report_id BIGINT REFERENCES research_reports(id) ON DELETE SET NULL,
                    status          TEXT NOT NULL DEFAULT 'draft',
                    target_table    TEXT NOT NULL DEFAULT '',
                    target_id       BIGINT,
                    created_by      TEXT NOT NULL DEFAULT '',
                    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS content_drafts_recent_idx
                    ON content_drafts (tenant_id, status, created_at DESC);

                CREATE TABLE IF NOT EXISTS publish_capabilities (
                    id               BIGSERIAL PRIMARY KEY,
                    tenant_id        INTEGER NOT NULL DEFAULT 1,
                    name             TEXT NOT NULL DEFAULT '',
                    kind             TEXT NOT NULL DEFAULT 'webhook',
                    description      TEXT NOT NULL DEFAULT '',
                    encrypted_config TEXT NOT NULL DEFAULT '',
                    enabled          BOOLEAN NOT NULL DEFAULT FALSE,
                    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );

                -- Visual assets (Phase 8 / task 066): images, diagrams, and
                -- clips generated for a content draft. Scaffold: a pluggable
                -- provider fills url/storage_key/status; the no-spend default
                -- just records the plan (status='planned').
                CREATE TABLE IF NOT EXISTS content_assets (
                    id           BIGSERIAL PRIMARY KEY,
                    tenant_id    INTEGER NOT NULL DEFAULT 1,
                    draft_id     BIGINT REFERENCES content_drafts(id) ON DELETE CASCADE,
                    report_id    BIGINT REFERENCES research_reports(id) ON DELETE SET NULL,
                    asset_type   TEXT NOT NULL DEFAULT 'image',
                    provider     TEXT NOT NULL DEFAULT 'placeholder',
                    prompt       TEXT NOT NULL DEFAULT '',
                    spec         JSONB NOT NULL DEFAULT '{}'::jsonb,
                    storage_key  TEXT NOT NULL DEFAULT '',
                    url          TEXT NOT NULL DEFAULT '',
                    status       TEXT NOT NULL DEFAULT 'planned',
                    created_by   TEXT NOT NULL DEFAULT '',
                    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS content_assets_draft_idx
                    ON content_assets (draft_id);

                -- Publish audit log (Phase 8 / task 067): one row per outbound
                -- publish attempt through a capability. detail never stores
                -- secrets (config is redacted before logging).
                CREATE TABLE IF NOT EXISTS publish_log (
                    id            BIGSERIAL PRIMARY KEY,
                    tenant_id     INTEGER NOT NULL DEFAULT 1,
                    capability_id BIGINT REFERENCES publish_capabilities(id) ON DELETE SET NULL,
                    draft_id      BIGINT REFERENCES content_drafts(id) ON DELETE SET NULL,
                    kind          TEXT NOT NULL DEFAULT '',
                    status        TEXT NOT NULL DEFAULT '',
                    detail        TEXT NOT NULL DEFAULT '',
                    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
                );
                CREATE INDEX IF NOT EXISTS publish_log_recent_idx
                    ON publish_log (tenant_id, created_at DESC);
                """
            )
    finally:
        conn.close()


