@app.route("/admin/api/embed-keys/<int:kid>", methods=["PUT"])
@admin_required
def admin_update_embed_key(kid):
    d = request.get_json() or {}
    sets, vals = [], []
    if "label" in d:
        sets.append("label = %s")
        vals.append(d["label"])
    if "origin_allowlist" in d:
        sets.append("origin_allowlist = %s::jsonb")
        vals.append(json.dumps(d["origin_allowlist"]))
    if "enabled" in d:
        sets.append("enabled = %s")
        vals.append(bool(d["enabled"]))
    if not sets:
        return jsonify({"error": "No fields"}), 400
    vals.extend([kid, current_tenant_id()])
    row = execute_db(
        "UPDATE tenant_embed_keys SET " + ", ".join(sets)
        + " WHERE id = %s AND tenant_id = %s RETURNING *", tuple(vals))
    if not row:
        return jsonify({"error": "Not found"}), 404
    return jsonify(row)


@app.route("/admin/api/embed-keys/<int:kid>", methods=["DELETE"])
@admin_required
def admin_delete_embed_key(kid):
    execute_db("DELETE FROM tenant_embed_keys WHERE id = %s AND tenant_id = %s",
               (kid, current_tenant_id()))
    return jsonify({"success": True})


# -----------------------------------------------------------------------------
# Chat-only mode (super-admin gated)
# -----------------------------------------------------------------------------
# Some clients want ONLY the AI chat embedded on their OWN pre-existing website
# — not the Replit-hosted public landing page. The embeddable widget already
# supports that (per-client publishable embed keys + origin allowlist + the
# /embed/loader.js snippet). What this adds is a switch to turn OFF the public
# marketing site so a chat-only client doesn't also expose a full landing page
# at the root URL.
#
# When `site_settings.chat_only_mode` is TRUE, the public website routes (the
# landing page, standalone /p/<slug> pages, pretty per-section URLs, blog
# posts, the static front-end bundle, etc.) return a minimal placeholder
# instead of the full site. Everything the embedded chat and the operator
# need keeps working — the chat API, chatbot settings, the embed loader and
# widget assets, uploaded media, the admin dashboard, and health probes.
#
# The flag is read on EVERY request (in a before_request hook), so the value
# is cached for a few seconds to avoid a DB round-trip per request. The cache
# is invalidated immediately whenever the toggle is saved.
#
# Default is FALSE, and any error (e.g. the column missing on an older install
# that hasn't run the migration yet) FAILS OPEN — the public site stays
# visible — so we never accidentally hide an operator's whole website.

# Path prefixes that MUST keep working when chat-only mode is ON. These cover
# the admin dashboard + login, every API (chat, chatbot-settings, embeddable
# endpoints, …), the cross-origin embed loader + widget assets, uploaded
# media the chat may reference, and any framework static files.
_CHAT_ONLY_ALLOWED_PREFIXES = (
    "/admin",       # dashboard, login, /admin/sso, and all /admin/api/* endpoints
    "/api",         # chat, chatbot-settings, forms, products, checkout, stripe webhook
    "/embed",       # /embed/loader.js — the cross-origin widget loader
    "/widget",      # /widget/chat-ui.js|css, voice.js — widget assets
    "/uploads",     # user-uploaded images the chat/gallery cards may reference
    "/static",      # any framework static assets
    "/bundle.",     # fingerprinted JS bundle the widget/loader may pull
    # Machine-to-machine endpoints that MUST keep working regardless of whether
    # the public marketing site is visible — hiding these behind the HTML
    # placeholder would silently swallow real webhook/automation deliveries or
    # break plugin distribution (the upstream would see a 200 and assume success).
    "/webhooks",    # Resend + Twilio (SMS/voice) status & inbound webhooks
    "/automations", # /automations/hook/<token> — inbound automation triggers
    "/plugin",      # plugin update.json / download / onboarding distribution
)

# Exact paths that must stay reachable when chat-only mode is ON: health
# probes (so deployments don't flap) and common root-level asset requests.
_CHAT_ONLY_ALLOWED_EXACT = (
    "/healthz", "/health", "/favicon.ico", "/robots.txt",
)

# Tiny TTL cache so the per-request flag check isn't a DB hit every time.
_CHAT_ONLY_CACHE = {"val": None, "ts": 0.0}
_CHAT_ONLY_CACHE_TTL_SEC = 10.0


def _chat_only_mode_enabled():
    """Return True if the super-admin has turned the public site OFF.

    Cached for a few seconds. Fails OPEN (returns False) on any error —
    including the column not existing on an install that hasn't run the
    0022 migration — so a DB blip can never hide the whole public site."""
    now = _time.time()
    cached = _CHAT_ONLY_CACHE["val"]
    if cached is not None and (now - _CHAT_ONLY_CACHE["ts"]) < _CHAT_ONLY_CACHE_TTL_SEC:
        return cached
    val = False
    try:
        row = query_db(
            "SELECT chat_only_mode FROM site_settings WHERE id = 1",
            fetchone=True,
        )
        if row:
            val = bool(row.get("chat_only_mode"))
    except Exception:
        val = False
    _CHAT_ONLY_CACHE["val"] = val
    _CHAT_ONLY_CACHE["ts"] = now
    return val


def _chat_only_invalidate_cache():
    """Force the next _chat_only_mode_enabled() call to re-read the DB.
    Called right after the toggle is saved so the change takes effect now."""
    _CHAT_ONLY_CACHE["val"] = None
    _CHAT_ONLY_CACHE["ts"] = 0.0


# Minimal, industry-agnostic placeholder shown at the root URL (and other
# public pages) while chat-only mode is ON. Deliberately neutral — no
# business name or marketing content — since the real delivery is the chat
# embedded on the client's own website.
_CHAT_ONLY_PLACEHOLDER_HTML = (
    "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\">"
    "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
    "<meta name=\"robots\" content=\"noindex\">"
    "<title>Chat available</title>"
    "<style>html,body{height:100%;margin:0}"
    "body{display:flex;align-items:center;justify-content:center;"
    "font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;"
    "background:#0f172a;color:#e2e8f0;text-align:center;padding:1.5rem}"
    ".box{max-width:30rem}"
    "h1{font-size:1.25rem;font-weight:600;margin:0 0 .5rem}"
    "p{font-size:.95rem;line-height:1.5;color:#94a3b8;margin:0}</style>"
    "</head><body><div class=\"box\">"
    "<h1>This page isn't available here.</h1>"
    "<p>The assistant is available directly on our website.</p>"
    "</div></body></html>"
)


def _chat_only_placeholder_response():
    """Build the minimal placeholder response (HTTP 200 so health checks and
    uptime monitors that hit '/' stay green)."""
    resp = make_response(_CHAT_ONLY_PLACEHOLDER_HTML, 200)
    resp.headers["Content-Type"] = "text/html; charset=utf-8"
    # Don't let proxies/browsers cache the placeholder — toggling the mode
    # off should restore the real site immediately.
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.before_request
def _enforce_chat_only_mode():
    """When chat-only mode is ON, hide the public marketing site.

    Returns the minimal placeholder for any public page request while
    letting admin, APIs, the embed loader/widget assets, uploads, and
    health probes through untouched. When the mode is OFF this is a no-op,
    so existing installs behave exactly as before."""
    try:
        path = request.path or ""
    except Exception:
        return None
    if not _chat_only_mode_enabled():
        return None
    # Never interfere with CORS preflight — the embed widget relies on it.
    if request.method == "OPTIONS":
        return None
    for prefix in _CHAT_ONLY_ALLOWED_PREFIXES:
        if path == prefix or path.startswith(prefix if prefix.endswith(".") else prefix + "/"):
            return None
    if path in _CHAT_ONLY_ALLOWED_EXACT:
        return None
    # Static assets (css/js/images/fonts) must keep loading so the embedded
    # concierge served at /embed/concierge can still pull /styles.css, the agent
    # avatar image, fonts, etc. while the public marketing pages are hidden.
    # Marketing pages are extensionless (/, /p/<slug>, /<section>), so allowing
    # dotted asset paths never re-exposes the site itself — only inert assets.
    _lp = path.lower()
    if "." in _lp and _lp.rsplit(".", 1)[-1] in (
        "css", "js", "mjs", "png", "jpg", "jpeg", "gif", "svg", "webp",
        "ico", "woff", "woff2", "ttf", "otf", "map", "webmanifest",
    ):
        return None
    # Everything else is a public-site page → show the placeholder instead.
    return _chat_only_placeholder_response()


@app.route("/admin/api/site-mode", methods=["GET"])
@admin_required
def admin_get_site_mode():
    """Return the current chat-only-mode flag for the dashboard toggle.

    Read-only and resilient: if the column doesn't exist yet (migration
    not run) it reports False rather than erroring."""
    val = False
    try:
        row = query_db(
            "SELECT chat_only_mode FROM site_settings WHERE id = 1",
            fetchone=True,
        )
        if row:
            val = bool(row.get("chat_only_mode"))
    except Exception:
        val = False
    return jsonify({"chat_only_mode": val})


@app.route("/admin/api/site-mode", methods=["PUT"])
@admin_required
def admin_set_site_mode():
    """Turn chat-only mode on/off. Super-admin role ONLY — the same hard
    server-side boundary used by the other white-label / embed endpoints
    (the template hiding the tab is only cosmetic; THIS is the real gate)."""
    guard = _require_super_admin_role()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    val = bool(d.get("chat_only_mode"))
    execute_db(
        "UPDATE site_settings SET chat_only_mode = %s WHERE id = 1",
        (val,),
    )
    _chat_only_invalidate_cache()
    return jsonify({"chat_only_mode": val})


# ---- WordPress-embedded admin SSO ----------------------------------------
# The WP plugin mints a single-use, short-lived HMAC token (the identical scheme
# below) with the shared SSO_SIGNING_SECRET and iframes /admin/sso?token=...; we
# verify it, establish the admin session, and redirect into /admin. Token format
# (PHP and Python agree exactly): payload {tid, exp, jti} → b64url(json) +
# "." + b64url(HMAC-SHA256(b64, secret)). No secret configured → SSO disabled.
import time as _sso_time

_SSO_SIGNING_SECRET = os.environ.get("SSO_SIGNING_SECRET", "").strip()
_SSO_MAX_TTL_SECONDS = 60


def _sso_b64u_decode(s):
    pad = "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s + pad)


def _sso_sign(b64_payload, secret):
    import hmac as _hmac
    return base64.urlsafe_b64encode(
        _hmac.new(secret.encode("utf-8"), b64_payload.encode("ascii"),
                  hashlib.sha256).digest()).rstrip(b"=").decode("ascii")


def _sso_claim_jti(jti, exp):
    """Record the jti once (single-use). Returns True only if THIS call claimed
    it. Fails open to allowing the login if the DB is briefly unavailable."""
    try:
        row = execute_db(
            "INSERT INTO sso_used_jtis (jti, expires_at) VALUES (%s, to_timestamp(%s)) "
            "ON CONFLICT (jti) DO NOTHING RETURNING jti", (jti, exp))
        return row is not None
    except Exception as e:
        print(f"[sso] jti claim failed (allowing): {e}")
        return True


def _sso_verify_token(token):
    """Return the tenant_id for a valid, unused, unexpired token, else None.
    Constant-time signature check; rejects expired / over-long / replayed tokens."""
    import hmac as _hmac
    secret = _SSO_SIGNING_SECRET
    if not secret or not token or "." not in token:
        return None
    b64, _, sig = token.partition(".")
    if not _hmac.compare_digest(sig, _sso_sign(b64, secret)):
        return None
    try:
        payload = json.loads(_sso_b64u_decode(b64))
    except Exception:
        return None
    now = _sso_time.time()
    exp = payload.get("exp", 0)
    if not isinstance(exp, (int, float)) or exp <= now:
        return None
    if exp - now > _SSO_MAX_TTL_SECONDS + 5:
        return None
    jti, tid = payload.get("jti"), payload.get("tid")
    if not jti or tid is None:
        return None
    if not _sso_claim_jti(jti, exp):
        return None
    return int(tid)


@app.route("/admin/sso", methods=["GET"])
def admin_sso():
    """Single-use SSO entry for the WordPress-embedded admin iframe. Verifies the
    plugin's signed token, establishes the admin session, and redirects to /admin.
    403 on a missing/forged/expired/replayed token."""
    if not _SSO_SIGNING_SECRET:
        return jsonify({"error": "SSO is not configured"}), 503
    tid = _sso_verify_token(request.args.get("token", ""))
    if tid is None:
        return jsonify({"error": "invalid or expired SSO token"}), 403
    session["admin_logged_in"] = True
    # The WordPress plugin embeds the hosted admin FOR THE CLIENT, so an SSO
    # login is always the restricted client role — never super_admin. The
    # platform owner logs in directly with ADMIN_PASSWORD instead.
    session["admin_role"] = "client"
    session.permanent = True
    return redirect("/admin")


def _sso_verify_signature_only(token):
    """Verify an SSO token's signature + expiry WITHOUT consuming its jti.

    Used only by the connection-test diagnostics endpoint so that testing the
    connection doesn't burn a real single-use token (and doesn't establish a
    session). Returns True/False. Never reveals the secret."""
    import hmac as _hmac
    secret = _SSO_SIGNING_SECRET
    if not secret or not token or "." not in token:
        return False
    b64, _, sig = token.partition(".")
    if not _hmac.compare_digest(sig, _sso_sign(b64, secret)):
        return False
    try:
        payload = json.loads(_sso_b64u_decode(b64))
    except Exception:
        return False
    now = _sso_time.time()
    exp = payload.get("exp", 0)
    if not isinstance(exp, (int, float)) or exp <= now:
        return False
    if exp - now > _SSO_MAX_TTL_SECONDS + 5:
        return False
    # Mirror the real verifier's structural checks (minus jti consumption) so a
    # token reported "valid" here would also pass the real /admin/sso login.
    jti, tid = payload.get("jti"), payload.get("tid")
    if not jti or tid is None:
        return False
    try:
        int(tid)
    except (TypeError, ValueError):
        return False
    return True


@app.route("/embed/diagnostics", methods=["GET"])
def embed_diagnostics():
    """Connection test for the WordPress plugin (and any other embedder).

    Validates, in one call, the three things an embed install depends on:
      1. embed_key  — resolves to an enabled tenant key (`valid`/`invalid`/`disabled`)
      2. origin     — the request Origin is on that key's allowlist
                      (`allowed`/`not_allowed`/`not_checked` when no Origin sent)
      3. sso        — if an `sso_token` is supplied, its signature verifies against
                      the platform's SSO_SIGNING_SECRET (`valid`/`invalid`).  The
                      jti is NOT consumed, so this is safe to run repeatedly.

    Safe to expose unauthenticated: embed keys are publishable (`pk_...`) and
    already appear in page source, so confirming validity leaks nothing; the SSO
    check only confirms a token the caller already signed verifies — it never
    reveals the secret."""
    out = {
        "platform": True,
        "embed_key": "missing",
        "origin": "not_checked",
        "sso": "not_checked",
    }

    key = (request.args.get("embed_key", "")
           or request.headers.get("X-Embed-Key", "")).strip()
    if key:
        from admin_ai_platform.embed_auth import (
            _resolve_key, _origin_allowed, _request_origin)
        row = _resolve_key(key)
        if not row:
            out["embed_key"] = "invalid"
        elif not row.get("enabled"):
            out["embed_key"] = "disabled"
        else:
            out["embed_key"] = "valid"
            origin = _request_origin()
            if origin:
                out["origin_value"] = origin
                out["origin"] = ("allowed"
                                 if _origin_allowed(origin, row.get("origin_allowlist"))
                                 else "not_allowed")

    sso_token = request.args.get("sso_token", "").strip()
    if not _SSO_SIGNING_SECRET:
        out["sso"] = "platform_not_configured"
    elif sso_token:
        out["sso"] = "valid" if _sso_verify_signature_only(sso_token) else "invalid"

    out["ok"] = (
        out["embed_key"] == "valid"
        and out["origin"] in ("allowed", "not_checked")
        and out["sso"] in ("valid", "not_checked", "platform_not_configured")
    )
    return jsonify(out)


# ---- WordPress plugin self-hosted auto-updates ---------------------------
# WordPress only auto-updates plugins listed on wordpress.org. Ours is private,
# so the plugin polls these PUBLIC endpoints (the same flow WP uses internally):
# /plugin/update.json reports the latest version + download URL; /plugin/download
# serves the client-facing plugin zip (contains NO platform source). To publish a
# new version: bump the plugin's Version: header, run scripts/build_plugin.py
# (writes plugin_dist/manifest.json + the zip), and deploy.
_PLUGIN_DIST_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "plugin_dist")
_PLUGIN_ZIP_RE = re.compile(r"^[A-Za-z0-9._-]+\.zip$")


@app.route("/plugin/update.json", methods=["GET"])
def plugin_update_manifest():
    """Public update manifest the WordPress plugin polls. 404 until a release is
    published.

    SECURITY: WordPress treats the manifest's download_url as the trusted source
    of the update package, so we must NOT derive it from spoofable request
    headers (Host / X-Forwarded-Host). Instead we build it from the platform's
    TRUSTED canonical base — _public_base_url() prefers the admin-configured
    canonical URL, then PUBLIC_BASE_URL, then the Replit-managed hostname, and
    only falls back to the request host when nothing is configured (local/dev).
    We also pin the zip name to the regex-validated manifest value."""
    manifest_path = os.path.join(_PLUGIN_DIST_DIR, "manifest.json")
    if not os.path.exists(manifest_path):
        return jsonify({"error": "no plugin release published"}), 404
    try:
        with open(manifest_path) as f:
            data = json.load(f)
    except Exception as e:
        capture_exc(e, "plugin_update_manifest")
        return jsonify({"error": "manifest unreadable"}), 500
    zip_name = data.get("zip", "ai-concierge.zip")
    if not _PLUGIN_ZIP_RE.match(zip_name):
        return jsonify({"error": "invalid release artifact"}), 500
    base = (_public_base_url() or "").rstrip("/")
    if not base:
        # Last-resort dev fallback only when nothing trusted is configured.
        base = request.url_root.rstrip("/") if request else ""
    data["download_url"] = base + "/plugin/download/" + zip_name
    resp = jsonify(data)
    resp.headers["Cache-Control"] = "public, max-age=300"
    return resp


@app.route("/plugin/download/<path:filename>", methods=["GET"])
def plugin_download(filename):
    """Serve a published plugin zip from plugin_dist/. Restricted to *.zip names
    (the client-facing plugin — no platform source is ever exposed)."""
    if not _PLUGIN_ZIP_RE.match(filename):
        abort(404)
    resp = send_from_directory(_PLUGIN_DIST_DIR, filename, as_attachment=True)
    resp.headers["Cache-Control"] = "public, max-age=300"
    return resp


# =============================================================================
# WORDPRESS PLUGIN MANAGEMENT  (super-admin tab)
# =============================================================================
# A super-admin-only surface to: publish new plugin versions (bump + build the
# zip/manifest), read the keys a client needs for setup (platform URL, embed key,
# tenant id, SSO secret), and mint shareable onboarding links so a client can
# self-serve the download + step-by-step install instructions at /plugin/onboard.
import secrets as _wp_secrets


def _wp_plugin_versions():
    """(source_version, released_version) — the version in the plugin source vs.
    the version currently published in plugin_dist/manifest.json (None if no
    release has been built yet)."""
    source_version = None
    try:
        import scripts.build_plugin as _bp
        source_version = _bp.read_version()
    except Exception as e:
        print(f"[wp-plugin] could not read source version: {e}")
    released = None
    manifest_path = os.path.join(_PLUGIN_DIST_DIR, "manifest.json")
    if os.path.exists(manifest_path):
        try:
            with open(manifest_path) as f:
                released = (json.load(f) or {}).get("version")
        except Exception:
            pass
    return source_version, released


@app.route("/admin/api/wp-plugin/status", methods=["GET"])
@admin_required
def wp_plugin_status():
    """Snapshot for the WP Plugin tab: versions, whether a release/SSO secret is
    configured, the canonical platform URL, and the tenant list (for the key +
    onboarding-link generators)."""
    guard = _require_super_admin_role()
    if guard:
        return guard
    source_version, released = _wp_plugin_versions()
    tenants = query_db("SELECT id, name FROM tenants ORDER BY id") or []
    has_release = os.path.exists(os.path.join(_PLUGIN_DIST_DIR, "manifest.json"))
    return jsonify({
        "source_version": source_version,
        "released_version": released,
        "has_release": has_release,
        "update_available": bool(source_version and released and source_version != released),
        "sso_configured": bool(_SSO_SIGNING_SECRET),
        "platform_url": _public_base_url() or (request.url_root.rstrip("/") if request else ""),
        "tenants": tenants,
        "zip_name": "ai-concierge.zip",
    })


@app.route("/admin/api/wp-plugin/build", methods=["POST"])
@admin_required
def wp_plugin_build():
    """Publish a release. Optionally bump the version first, then (re)build the
    zip + manifest into plugin_dist/. NOTE: this writes to the project files —
    in the Replit workspace that persists via checkpoints; a deployed instance
    needs a republish to pick up the new release."""
    guard = _require_super_admin_role()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    new_version = (d.get("version") or "").strip()
    try:
        import importlib
        import scripts.build_plugin as _bp
        importlib.reload(_bp)  # pick up any prior in-process edits
        bumped = None
        if new_version:
            old, new = _bp.bump_version(new_version)
            bumped = {"old": old, "new": new}
        info = _bp.build()
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    except Exception as e:
        capture_exc(e, "wp_plugin_build")
        print(f"[wp-plugin] build failed: {e}")
        return jsonify({"error": "Build failed. Check the server logs."}), 500
    return jsonify({"ok": True, "bumped": bumped, "version": info["version"],
                    "file_count": info["file_count"], "files": info["files"]})


@app.route("/admin/api/wp-plugin/sso-secret", methods=["GET"])
@admin_required
def wp_plugin_sso_secret():
    """Reveal the SSO signing secret to the super admin so they can paste it into
    a client's plugin settings. Gated to super_admin only; never exposed to a
    client SSO session or the public."""
    guard = _require_super_admin_role()
    if guard:
        return guard
    return jsonify({"configured": bool(_SSO_SIGNING_SECRET),
                    "secret": _SSO_SIGNING_SECRET or ""})


def _wp_onboard_url(token):
    base = _public_base_url() or (request.url_root.rstrip("/") if request else "")
    return f"{base}/plugin/onboard/{token}"


@app.route("/admin/api/wp-plugin/onboarding-links", methods=["GET"])
@admin_required
def wp_onboarding_links_list():
    guard = _require_super_admin_role()
    if guard:
        return guard
    rows = query_db("SELECT * FROM wp_onboarding_links ORDER BY id DESC") or []
    for r in rows:
        r["url"] = _wp_onboard_url(r["token"])
    return jsonify({"links": rows})


@app.route("/admin/api/wp-plugin/onboarding-links", methods=["POST"])
@admin_required
def wp_onboarding_links_create():
    guard = _require_super_admin_role()
    if guard:
        return guard
    d = request.get_json(silent=True) or {}
    token = _wp_secrets.token_urlsafe(24)

    # Tenant must exist — otherwise the link would prefill a meaningless id.
    try:
        tenant_id = int(d.get("tenant_id") or 1)
    except (TypeError, ValueError):
        return jsonify({"error": "tenant_id must be a number"}), 400
    if not query_db("SELECT id FROM tenants WHERE id=%s", (tenant_id,), fetchone=True):
        return jsonify({"error": "Unknown tenant"}), 400

    # Embed key is optional, but if supplied it must exist, be enabled, and
    # belong to the same tenant — a mismatched key produces a broken widget.
    embed_key = (d.get("embed_key") or "").strip()
    if embed_key:
        key_row = query_db(
            "SELECT id, enabled FROM tenant_embed_keys WHERE embed_key=%s AND tenant_id=%s",
            (embed_key, tenant_id), fetchone=True)
        if not key_row:
            return jsonify({"error": "Embed key not found for this tenant"}), 400
        if key_row.get("enabled") is False:
            return jsonify({"error": "Embed key is disabled"}), 400

    # Parse include_sso strictly so a JSON string like "false" can't be coerced
    # to True and accidentally embed the GLOBAL SSO secret in a public page.
    include_sso = d.get("include_sso", False)
    if not isinstance(include_sso, bool):
        return jsonify({"error": "include_sso must be true or false"}), 400

    expires_days = d.get("expires_days")
    expires_at = None
    if expires_days:
        try:
            days = max(1, int(expires_days))
            expires_at = datetime.utcnow() + timedelta(days=days)
        except (TypeError, ValueError):
            expires_at = None
    row = execute_db(
        "INSERT INTO wp_onboarding_links (token, tenant_id, label, embed_key, "
        " include_sso, expires_at) VALUES (%s,%s,%s,%s,%s,%s) RETURNING *",
        (token, tenant_id, (d.get("label") or "").strip(),
         embed_key, include_sso, expires_at))
    row["url"] = _wp_onboard_url(row["token"])
    return jsonify(row), 201


@app.route("/admin/api/wp-plugin/onboarding-links/<int:lid>", methods=["DELETE"])
@admin_required
def wp_onboarding_links_revoke(lid):
    guard = _require_super_admin_role()
    if guard:
        return guard
    execute_db("UPDATE wp_onboarding_links SET revoked=TRUE WHERE id=%s", (lid,))
    return jsonify({"success": True})


@app.route("/plugin/onboard/<token>", methods=["GET"])
def plugin_onboard(token):
    """Public, no-login client onboarding page. Resolves a shareable token and
    renders the plugin download + the client's pre-filled setup values + install
    instructions. Bad/expired/revoked tokens get a friendly error page."""
    row = query_db("SELECT * FROM wp_onboarding_links WHERE token=%s",
                   (token,), fetchone=True) if token else None
    valid = bool(row) and not row.get("revoked")
    if valid and row.get("expires_at"):
        try:
            if row["expires_at"] < datetime.utcnow():
                valid = False
        except TypeError:
            pass
    if not valid:
        return render_template("plugin_onboard.html", valid=False), 404
    execute_db("UPDATE wp_onboarding_links SET view_count=view_count+1, "
               "last_viewed_at=NOW() WHERE id=%s", (row["id"],))
    _, released = _wp_plugin_versions()
    base = _public_base_url() or (request.url_root.rstrip("/") if request else "")
    sso_secret = _SSO_SIGNING_SECRET if (row.get("include_sso") and _SSO_SIGNING_SECRET) else ""
    return render_template(
        "plugin_onboard.html",
        valid=True,
        label=row.get("label") or "",
        platform_url=base,
        embed_key=row.get("embed_key") or "",
        tenant_id=row.get("tenant_id") or 1,
        sso_secret=sso_secret,
        include_sso=bool(row.get("include_sso")),
        sso_configured=bool(_SSO_SIGNING_SECRET),
        version=released,
        download_url=f"{base}/plugin/download/ai-concierge.zip",
    )


@app.route("/admin/login", methods=["GET", "POST"])
def admin_login():
    """
    GET: Show the login form.
    POST: Validate the password and log in.

    Brute-force throttle: after _LOGIN_MAX_FAILS bad attempts from the same
    IP inside _LOGIN_WINDOW_SEC, further attempts return HTTP 429 with a
    Retry-After header until the window slides past. Successful login clears
    the IP from the attempts table.
    """
    error = None
    if request.method == "POST":
        ip = _client_ip()
        allowed, retry_after = _login_throttle_check(ip)
        if not allowed:
            mins = max(1, retry_after // 60)
            resp = render_template(
                "admin/login.html",
                error=f"Too many failed attempts. Try again in about {mins} minute(s).",
            )
            return resp, 429, {"Retry-After": str(retry_after)}
        password = request.form.get("password", "")
        email = (request.form.get("email", "") or "").strip().lower()
        # Two credentials, one form. ADMIN_PASSWORD → super_admin (full panel +
        # control tab); CLIENT_PASSWORD → client (only enabled tabs). super_admin
        # wins if the two passwords happen to be equal. We always overwrite
        # admin_role on success so a shared browser can't carry a stale role from
        # a previous login of the other kind.
        role = None
        rbac_user = None
        # RBAC (gap §6.3): if an email is supplied, try per-user accounts FIRST. Strictly
        # additive + fail-safe — any miss or error falls through to the unchanged
        # ADMIN_PASSWORD / CLIENT_PASSWORD flow below, which stays the break-glass login.
        if email:
            try:
                rbac_user = rbac_authenticate(email, password)
            except Exception:
                rbac_user = None
        if rbac_user is not None:
            role = rbac_user.get("role") or "admin"
        elif password == ADMIN_PASSWORD:
            role = "super_admin"
        elif CLIENT_PASSWORD and password == CLIENT_PASSWORD:
            role = "client"
        if role is not None:
            _login_throttle_clear(ip)
            session["admin_logged_in"] = True
            session["admin_role"] = role
            if rbac_user is not None:
                session["admin_user_id"] = rbac_user.get("id")
                session["admin_email"] = rbac_user.get("email")
                try:
                    rbac_note_login(rbac_user.get("id"))
                except Exception:
                    pass
            else:
                session.pop("admin_user_id", None)
                session.pop("admin_email", None)
            session.permanent = True
            return redirect(url_for("admin_dashboard"))
        else:
            _login_throttle_record_failure(ip)
            error = "Invalid password. Please try again."

    return render_template("admin/login.html", error=error)


@app.route("/admin/logout")
def admin_logout():
    """Log out of the admin dashboard and redirect to login."""
    # Audit the implicit super-admin lock that happens at logout, but
    # only if this session was actually unlocked at the time.
    if session.get("super_admin_unlocked_at"):
        _audit_super_admin("auto_lock", "logout")
    session.pop("admin_logged_in", None)
    session.pop("admin_role", None)
    session.pop("admin_user_id", None)
    session.pop("admin_email", None)
    session.pop("_csrf_token", None)
    session.pop("super_admin_unlocked_at", None)
    return redirect(url_for("admin_login"))


# -----------------------------------------------------------------------------
# Super-admin lock (Tier 8)
# -----------------------------------------------------------------------------
# Optional second-factor for the most dangerous admin tabs:
#   - Plans & Features  (toggle major features for the whole tenant)
#   - Performance       (regenerate image variants, etc.)
#   - Developer console (test SMTP/SMS/Velo, swap LLM provider, …)
#   - Secrets           (read/write env vars, including API keys)
#
# Activated by setting the SUPER_ADMIN_KEY environment variable. When set,
# a logged-in admin must additionally POST the key to
# /admin/api/super-admin/unlock before any of the protected endpoints
# return data. The unlock lasts _SUPER_ADMIN_UNLOCK_TTL_SEC (30 min)
# and is stored in the Flask session.
#
# When SUPER_ADMIN_KEY is NOT set the lock is OFF — the admin password
# alone is sufficient (so we never silently lock an operator out of
# their own dashboard).
_SUPER_ADMIN_PROTECTED_PREFIXES = (
    "/admin/api/secrets/",       # /status, /set, /unset
    "/admin/api/performance",    # /performance and /performance/...
    "/admin/api/devconsole/",    # snapshot, test-provider, test-email, …
    "/admin/api/tenant/features",# /features and /features/<name>
    # NOTE: /admin/api/llm-provider is NOT here — it backs a separate
    # "LLM Provider" tab and is intentionally outside this lock's
    # scope. Add only when locking that tab is also wired up in the UI.
)


def _super_admin_key():
    # .strip() so a stray trailing newline/space accidentally pasted into the
    # SUPER_ADMIN_KEY secret value can't cause a permanent mismatch. The key the
    # operator types into the unlock box is also stripped (see super_admin_unlock),
    # so without this a copy-paste with a trailing newline would always be rejected
    # even when the visible characters are correct.
    return (os.environ.get("SUPER_ADMIN_KEY") or "").strip()


def _super_admin_lock_enabled():
    """The lock is only active when a key is configured. If the env
    var is unset we fail open (admin password alone is enough)."""
    return bool(_super_admin_key())


def _super_admin_unlocked():
    """True if the current session has unlocked super-admin within the
    last _SUPER_ADMIN_UNLOCK_TTL_SEC. When the lock is disabled this
    always returns True so guarded endpoints behave normally."""
    if not _super_admin_lock_enabled():
        return True
    ts = session.get("super_admin_unlocked_at")
    if not ts:
        return False
    try:
        return (_time.time() - float(ts)) < _SUPER_ADMIN_UNLOCK_TTL_SEC
    except (TypeError, ValueError):
        return False


@app.before_request
def _enforce_super_admin_lock():
    """Reject API calls into a protected section when the session
    isn't unlocked. Runs after CSRF + auth checks (which are also
    before_request hooks) so by the time we reach here the caller is
    a logged-in admin with a valid CSRF token. Page routes (the HTML
    shell of /admin) are never blocked — only the API endpoints that
    return sensitive data."""
    try:
        path = request.path or ""
    except Exception:
        return None
    # Only gate API calls from a logged-in admin. Public, anonymous,
    # and Velo/webhook traffic is unaffected.
    if not session.get("admin_logged_in"):
        return None
    # The status / unlock / lock endpoints themselves must stay
    # reachable while locked, otherwise the operator could never
    # unlock or even see whether the lock is active.
    if path.startswith("/admin/api/super-admin/"):
        return None
    for prefix in _SUPER_ADMIN_PROTECTED_PREFIXES:
        if path.startswith(prefix):
            if not _super_admin_unlocked():
                # If this session HAD an unlock that just expired,
                # audit the auto-lock exactly once (pop the stale ts
                # so we don't re-audit on every subsequent request)
                # and include the original unlock time so an operator
                # can correlate it with the prior unlock event.
                stale_ts = session.pop("super_admin_unlocked_at", None)
                if stale_ts and _audit_expiry_should_emit(stale_ts):
                    _audit_super_admin(
                        "auto_lock", "ttl_expired",
                        f"unlocked_at={float(stale_ts):.0f}",
                    )
                return jsonify({
                    "error": "super_admin_required",
                    "message": "This section is locked. Enter the super-admin key to unlock.",
                }), 401
            # Sliding TTL: every authenticated access to a protected
            # endpoint refreshes the unlock window. The session expires
            # only after _SUPER_ADMIN_UNLOCK_TTL_SEC of *inactivity*.
            # The /super-admin/status polling endpoint is excluded
            # above so periodic UI status checks don't keep the
            # session alive forever.
            if _super_admin_lock_enabled():
                session["super_admin_unlocked_at"] = _time.time()
            break
    return None


@app.route("/admin/api/super-admin/status", methods=["GET"])
@admin_required
def super_admin_status():
    """Return the current lock state so the dashboard can decide
    whether to show the unlock prompt. Safe to call any time —
    never returns the key itself, just enabled/unlocked flags."""
    enabled = _super_admin_lock_enabled()
    unlocked = _super_admin_unlocked()
    ts = session.get("super_admin_unlocked_at") or 0
    return jsonify({
        "enabled": enabled,
        "unlocked": unlocked,
        "expires_at": (float(ts) + _SUPER_ADMIN_UNLOCK_TTL_SEC) if (enabled and unlocked) else None,
        "ttl_seconds": _SUPER_ADMIN_UNLOCK_TTL_SEC,
        "protected_prefixes": list(_SUPER_ADMIN_PROTECTED_PREFIXES),
    })


@app.route("/admin/api/super-admin/unlock", methods=["POST"])
@admin_required
def super_admin_unlock():
    """Verify the submitted key against SUPER_ADMIN_KEY and, on
    success, mark this session unlocked for the next 30 min.
    Throttled to 5 failures per 5 min per IP. Both successes and
    failures are logged at WARNING/INFO so they show up in the
    workflow log alongside other auth events."""
    if not _super_admin_lock_enabled():
        # Lock isn't configured; everything is already accessible.
        return jsonify({"ok": True, "enabled": False, "unlocked": True}), 200
    ip = _client_ip()
    allowed, retry_after = _super_admin_throttle_check(ip)
    if not allowed:
        _audit_super_admin("unlock", "throttled", f"retry_after={retry_after}")
        mins = max(1, retry_after // 60)
        return jsonify({
            "ok": False,
            "error": "throttled",
            "retry_after": retry_after,
            "message": f"Too many failed attempts. Try again in about {mins} minute(s).",
        }), 429
    data = request.get_json(silent=True) or {}
    provided = (data.get("key") or "").strip()
    expected = _super_admin_key()
    if not provided or not secrets.compare_digest(provided, expected):
        _super_admin_throttle_record_failure(ip)
        app.logger.warning("super-admin unlock FAILED from ip=%s", ip)
        _audit_super_admin(
            "unlock", "invalid_key",
            "empty_key" if not provided else None,
        )
        return jsonify({
            "ok": False,
            "error": "invalid_key",
            "message": "Incorrect super-admin key.",
        }), 401
    _super_admin_throttle_clear(ip)
    now = _time.time()
    session["super_admin_unlocked_at"] = now
    app.logger.info("super-admin unlock OK from ip=%s", ip)
    _audit_super_admin("unlock", "success")
    return jsonify({
        "ok": True,
        "enabled": True,
        "unlocked": True,
        "expires_at": now + _SUPER_ADMIN_UNLOCK_TTL_SEC,
    })


@app.route("/admin/api/super-admin/lock", methods=["POST"])
@admin_required
def super_admin_lock():
    """Manually re-lock the session (e.g. operator clicks
    'Lock now' before stepping away). Always returns ok."""
    # Only audit if we were actually unlocked — clicking "Lock now"
    # while already locked shouldn't add noise to the audit trail.
    if session.get("super_admin_unlocked_at"):
        _audit_super_admin("lock", "manual")
    session.pop("super_admin_unlocked_at", None)
    return jsonify({"ok": True, "unlocked": False})


@app.route("/admin/api/super-admin/audit", methods=["GET"])
@admin_required
def super_admin_audit_list():
    """Return the most recent super-admin lock events.

    Query: ?limit=N (default 50, capped at 200).

    Endpoint sits under /admin/api/super-admin/* which is exempt from
    the super-admin lock itself (see _enforce_super_admin_lock), so
    the Developer tab can render the panel even when locked. The data
    is non-secret (no keys, no session tokens) — only IPs, user
    agents, action labels, and outcomes — so this is safe to expose
    to any logged-in admin."""
    try:
        limit = int(request.args.get("limit", 50) or 50)
    except (TypeError, ValueError):
        limit = 50
    limit = max(1, min(limit, 200))
    conn = None
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, ts, ip, user_agent, action, outcome, reason "
                "FROM super_admin_audit ORDER BY ts DESC LIMIT %s",
                (limit,),
            )
            rows = [
                {
                    "id": r[0],
                    "ts": r[1].isoformat() if r[1] else None,
                    "ip": r[2],
                    "user_agent": r[3],
                    "action": r[4],
                    "outcome": r[5],
                    "reason": r[6],
                }
                for r in cur.fetchall()
            ]
        return jsonify({"ok": True, "rows": rows})
    except Exception as e:
        # Most likely cause on a fresh branch: migration not yet run
        # (super_admin_audit table doesn't exist). Surface that rather
        # than 500ing — the UI can render an inline hint.
        msg = f"{type(e).__name__}: {e}"
        return jsonify({"ok": False, "error": msg, "rows": []}), 200
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


# -----------------------------------------------------------------------------
# CSRF protection (Tier 7)
# -----------------------------------------------------------------------------
# Per-session token validated on every state-changing request to the admin
# surface. The dashboard SPA picks up the token from a <meta> tag rendered
# into admin/dashboard.html and a tiny window.fetch wrapper auto-injects it
# as `X-CSRF-Token` on same-origin admin requests. Form posts may also send
# the token as `csrf_token` field.
#
# Deliberately NOT protected:
#   - Public /api/* (anonymous; no session = no CSRF surface)
#   - VELO endpoints under /api/velo/*  (Bearer-token auth)
#   - Webhook endpoints                  (HMAC-verified payloads)
#   - /admin/login & /admin/logout       (login CSRF is moot when the password
#                                         IS the credential — an attacker who
#                                         knows the password is already in)
#   - /setup wizard                      (password-gated, install-once,
#                                         404 once `installation_bootstrapped_at`
#                                         is set)
#   - GET / HEAD / OPTIONS               (idempotent by HTTP contract)
_CSRF_PROTECTED_METHODS = {"POST", "PUT", "PATCH", "DELETE"}
# /admin/api/join is exempt because it carries no session — the single-use invite TOKEN in
# the body is the authentication (like a password-reset link), so a session CSRF token can't
# exist yet. The token's high entropy + single-use + expiry are the protection. (RBAC §6.3)
_CSRF_EXEMPT_PATHS = {"/admin/login", "/admin/logout", "/admin/api/join"}


def _csrf_token():
    """Per-session CSRF token, generated lazily on first read."""
    tok = session.get("_csrf_token")
    if not tok:
        tok = secrets.token_urlsafe(32)
        session["_csrf_token"] = tok
    return tok


def _csrf_should_check(path, method):
    if method not in _CSRF_PROTECTED_METHODS:
        return False
    if not path.startswith("/admin"):
        return False
    if path in _CSRF_EXEMPT_PATHS:
        return False
    return True


@app.before_request
def _csrf_validate_request():
    """Reject state-changing admin requests that lack a valid CSRF token.

    Runs before the route handler (and before @admin_required's auth check
    for unauthenticated callers). For unauthenticated callers we defer to
    @admin_required so the user sees the standard 401-or-redirect rather
    than a confusing CSRF error.
    """
    try:
        path = request.path or ""
        method = (request.method or "GET").upper()
    except Exception:
        return None
    if not _csrf_should_check(path, method):
        return None
    if not session.get("admin_logged_in"):
        # Let @admin_required do its thing — auth boundary first, then CSRF.
        return None
    expected = session.get("_csrf_token")
    if not expected:
        return jsonify({
            "error": "CSRF token missing from session. Please reload the admin page.",
            "csrf_failed": True,
        }), 403
    # Prefer the header (used by the dashboard SPA's fetch wrapper). Only
    # touch request.form for actual form-encoded payloads — accessing it
    # on a JSON or binary body would needlessly trigger Flask's form
    # parser (slow, allocates, and broadens the DoS surface for large
    # multipart bodies on every admin request).
    provided = request.headers.get("X-CSRF-Token")
    if not provided:
        ct = (request.content_type or "").lower()
        if "form-urlencoded" in ct or "multipart/form-data" in ct:
            try:
                provided = request.form.get("csrf_token")
            except Exception:
                provided = None
    if not provided or not secrets.compare_digest(str(provided), str(expected)):
        return jsonify({
            "error": "CSRF token invalid or missing.",
            "csrf_failed": True,
        }), 403
    return None


@app.context_processor
def _inject_csrf_token():
    """Make `csrf_token` available to all rendered templates without per-call plumbing."""
    try:
        return {"csrf_token": _csrf_token()}
    except Exception:
        return {"csrf_token": ""}


@app.route("/admin/api/csrf-token", methods=["GET"])
@admin_required
def admin_get_csrf_token():
    """Refresh handle for the dashboard SPA after a long idle (token rotation hook)."""
    return jsonify({"csrf_token": _csrf_token()})


# -----------------------------------------------------------------------------
# Liveness probe for container orchestrators (Docker HEALTHCHECK, K8s, Render,
# Fly.io, Railway). Deliberately does NOT touch the database — this is a
# liveness check ("is the worker process up?"), not a readiness check. A DB
# blip should not cause every replica to be killed and restarted.
# -----------------------------------------------------------------------------
@app.route("/healthz")
def healthz():
    return ("ok", 200, {"Content-Type": "text/plain; charset=utf-8"})


# =============================================================================
# JS BUNDLE — fingerprinted, immutably-cached, single-request asset
# =============================================================================
# script.js + voice.js concatenated and minified into one in-memory blob,
# served from a content-fingerprinted URL like /bundle.{sha256[:12]}.min.js.
# The hash is derived from the minified bytes at first access and stays
# stable for the lifetime of the worker process — when the source files
# change at deploy time, the hash changes, the URL changes, and any cached
# HTML pointing at the old URL naturally 404s and forces a fresh fetch.
# Lets us serve the bundle with `Cache-Control: max-age=31536000, immutable`
# (one year, no revalidation) without ever serving stale code.
#
# Route order: this is registered above serve_static() so the wildcard SPA
# fallback can't shadow it. An old-hash request returns 404 (rather than
# silently serving the current bundle from a wrong-hash URL) so caches
# stay honest.

@app.route("/bundle.<bundle_hash>.min.js")
def serve_js_bundle(bundle_hash):
    state = asset_bundle.get_bundle()
    if bundle_hash != state["hash"]:
        # Wrong hash = client cached HTML pointing at a since-redeployed
        # bundle. 404 forces them to refetch HTML, which carries the new
        # hash. Safer than serving the current bundle from a wrong-hash
        # URL (would let the stale URL get cached forever as if valid).
        return ("Stale bundle hash", 404, {"Content-Type": "text/plain"})
    response = make_response(state["content_bytes"])
    response.headers["Content-Type"] = "application/javascript; charset=utf-8"
    response.headers["Cache-Control"] = "public, max-age=31536000, immutable"
    response.headers["Vary"] = "Accept-Encoding"
    return response


# =============================================================================
# FIRST-RUN WIZARD (Tier 3 — onboarding)
# =============================================================================
# A browser-based form that lets a non-technical operator configure a fresh
# install without ever touching JSON. Submits to bootstrap_install (Tier 2)
# server-side, so VELO_AGENT_KEY never leaves the worker.
#
# Lifecycle:
#   * /setup is reachable ONLY while site_settings.site_name still equals the
#     seed default 'My Site'. After the first successful bootstrap, the route
#     returns 404 forever (until somebody manually resets site_name in the DB).
#   * The wizard ALWAYS sets site_name on submit, so the gate naturally closes.
#
# Security model:
#   * Public-fresh-install hijack guard: submit requires the operator's
#     ADMIN_PASSWORD. Without it, anyone who finds /setup on a freshly-deployed
#     public host could lock the install with their own values.
#   * Brute-force throttle reuses the existing _login_throttle helpers so
#     guess attempts on ADMIN_PASSWORD here count against the same per-IP
#     budget as /admin/login.
# =============================================================================
import json as _wizard_json
import os.path as _wizard_path


def _is_install_bootstrapped() -> bool:
    """Has this install ever been provisioned?

    Returns True (→ /setup is closed) iff site_settings.installation_bootstrapped_at
    is non-NULL. The column is set to NOW() at the end of a successful wizard
    run and reset to NULL if the wizard fails partway, so the gate flips on
    success and stays open for retries on failure.

    Fail-closed on DB error: returns True so a transient hiccup never
    accidentally re-opens the wizard on a configured production install.
    A previous version sentinel-checked site_name == 'My Site', which broke
    if the operator legitimately named their business "My Site".
    """
    try:
        row = query_db(
            "SELECT installation_bootstrapped_at FROM site_settings WHERE id = 1",
            fetchone=True,
        )
        if not row:
            return False  # singleton row missing → fresh install
        return row.get("installation_bootstrapped_at") is not None
    except Exception:
        return True


def _list_wizard_presets():
    """Names (without .json) of every starter template in onboarding_templates/."""
    out = []
    presets_dir = _wizard_path.join(
        os.path.dirname(__file__), "onboarding_templates"
    )
    try:
        for fname in sorted(os.listdir(presets_dir)):
            if fname.endswith(".json"):
                out.append(fname[:-5])
    except Exception:
        pass
    return out


@app.route("/setup", methods=["GET"])
def setup_wizard_get():
    if _is_install_bootstrapped():
        abort(404)
    return render_template(
        "setup_wizard.html",
        presets=_list_wizard_presets(),
    )


@app.route("/setup/preset/<name>", methods=["GET"])
def setup_wizard_preset(name):
    """Return a starter template JSON for the form to pre-fill from."""
    if _is_install_bootstrapped():
        abort(404)
    # Whitelist on the path component to block any traversal trick.
    safe = "".join(c for c in name if c.isalnum() or c in "-_")
    if safe != name:
        abort(400)
    path = _wizard_path.join(
        os.path.dirname(__file__), "onboarding_templates", f"{safe}.json"
    )
    if not _wizard_path.exists(path):
        abort(404)
    try:
        with open(path, "r", encoding="utf-8") as f:
            return jsonify(_wizard_json.load(f))
    except Exception as e:
        capture_exc(e, "setup_wizard_preset")
        return jsonify({"error": str(e)}), 500


@app.route("/setup", methods=["POST"])
def setup_wizard_post():
    # Declare before any use — Python requires global at top of function scope.
    global ADMIN_PASSWORD

    if _is_install_bootstrapped():
        abort(404)

    # Rate-limit the setup endpoint — same budget as /admin/login so brute-
    # forcing the setup_key doesn't get a separate free attempt pool.
    ip = _client_ip()
    allowed, retry_after = _login_throttle_check(ip)
    if not allowed:
        return jsonify({
            "error": f"Too many failed attempts. Try again in about {max(1, retry_after // 60)} minute(s).",
            "retry_after": retry_after,
        }), 429

    # setup_key authenticates the operator against the CURRENT ADMIN_PASSWORD
    # (defaults to "admin" on a fresh install — operators should pre-set
    # ADMIN_PASSWORD in the environment before deploying to production).
    setup_key = request.form.get("setup_key", "")
    if setup_key != ADMIN_PASSWORD:
        _login_throttle_record_failure(ip)
        return jsonify({"error": "Invalid setup authorization key."}), 401
    _login_throttle_clear(ip)

    # admin_password is the NEW password the wizard will write.  Required and
    # must be at least 8 characters.  It is a separate field from setup_key so
    # the operator can authenticate with the old password and change it in one
    # atomic provisioning step.
    pw = request.form.get("admin_password", "")
    if len(pw) < 8:
        return jsonify({"error": "New admin password must be at least 8 characters."}), 400

    raw_tpl = request.form.get("template_json", "").strip()
    if not raw_tpl:
        return jsonify({"error": "template_json field is required."}), 400
    try:
        tpl = _wizard_json.loads(raw_tpl)
    except _wizard_json.JSONDecodeError as e:
        return jsonify({"error": f"template_json is not valid JSON: {e}"}), 400
    if not isinstance(tpl, dict) or not tpl:
        return jsonify({"error": "template_json must be a non-empty object."}), 400

    # Server-side guard on the one truly required field. The browser form
    # has `required` on site_name but a crafted POST could bypass it and
    # persist site_name="" — which would make every subsequent _is_install_bootstrapped
    # check think the install is bootstrapped (column is set), but the
    # public site would render a blank business name. Reject up-front.
    site_name_in = (
        (tpl.get("settings") or {}).get("site_settings") or {}
    ).get("site_name", "")
    if not isinstance(site_name_in, str) or not site_name_in.strip():
        return jsonify({
            "error": "settings.site_settings.site_name is required and must be a non-empty string.",
        }), 400

    # Ensure the singleton site_settings row exists before we attempt the
    # atomic claim. On a fresh install the table is empty, so the UPDATE
    # below would match zero rows and wrongly report "already finished".
    try:
        execute_db(
            "INSERT INTO site_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING"
        )
    except Exception as e:
        capture_exc(e, "setup_wizard_post")
        return jsonify({"error": f"Could not initialise site_settings row: {e}"}), 500

    # Atomic claim. Two concurrent POSTs would both pass the earlier gate
    # check (TOCTOU), so we have to claim the bootstrap slot in a single
    # SQL statement. The conditional UPDATE returns a row only for the
    # first request to win the race; everything else gets rowcount=0 and
    # returns 409 without running bootstrap_install.
    try:
        claimed = execute_db(
            "UPDATE site_settings SET installation_bootstrapped_at = NOW() "
            "WHERE id = 1 AND installation_bootstrapped_at IS NULL "
            "RETURNING id"
        )
    except Exception as e:
        capture_exc(e, "setup_wizard_post")
        return jsonify({"error": f"Could not reserve setup slot: {e}"}), 500
    if not claimed:
        return jsonify({"error": "Setup is already in progress or has finished."}), 409

    # Local helper: release the claim. Returns (ok, error_str). If the
    # release itself fails the install would be permanently locked, so we
    # surface that to the caller rather than silently swallowing it — the
    # operator gets a one-line SQL command they can run to recover.
    def _release_claim():
        try:
            execute_db(
                "UPDATE site_settings SET installation_bootstrapped_at = NULL WHERE id = 1"
            )
            return True, None
        except Exception as exc:
            return False, str(exc)

    # Call bootstrap_install directly. The @velo_command decorator returns
    # the function unchanged, so calling it here bypasses the HTTP layer's
    # confirmation gate — which is correct, because the wizard's submit IS
    # the operator's confirmation, and the per-IP password gate above is
    # the actual "are you authorized" check.
    from velo_handlers import bootstrap_install
    try:
        summary = bootstrap_install({"template": tpl})
    except Exception as e:
        capture_exc(e, "setup_wizard_post")
        released, rel_err = _release_claim()
        return jsonify({
            "ok": False,
            "error": f"Bootstrap raised: {e}",
            "rollback_failed": not released,
            "manual_recovery_sql": (
                "UPDATE site_settings SET installation_bootstrapped_at = NULL WHERE id = 1;"
            ) if not released else None,
            "rollback_error": rel_err,
        }), 500

    if summary.get("error") or not summary.get("ok"):
        released, rel_err = _release_claim()
        return jsonify({
            "ok": False,
            "error": summary.get("error") or "Bootstrap reported errors.",
            "summary": summary,
            "rollback_failed": not released,
            "manual_recovery_sql": (
                "UPDATE site_settings SET installation_bootstrapped_at = NULL WHERE id = 1;"
            ) if not released else None,
            "rollback_error": rel_err,
        }), 400

    # ---- Write secrets to the local .env file (before and regardless of
    #      bootstrap outcome, since secrets are idempotent writes) --------
    raw_secrets = request.form.get("secrets_json", "").strip()
    secrets_written = []
    secrets_errors = []
    if raw_secrets:
        try:
            secrets_dict = _wizard_json.loads(raw_secrets)
            if isinstance(secrets_dict, dict):
                from env_manager import set_var, EnvManagerError
                for skey, sval in secrets_dict.items():
                    if sval and str(sval).strip():
                        try:
                            # force_override=True so setup-time values win even
                            # if the host already has a value (e.g. Replit Secret).
                            set_var(str(skey), str(sval).strip(), force_override=True)
                            secrets_written.append(skey)
                        except EnvManagerError as se:
                            secrets_errors.append({"key": skey, "error": str(se)})
                        except Exception as se:
                            secrets_errors.append({"key": skey, "error": str(se)})
        except Exception:
            pass  # Malformed secrets_json — silently skip, not fatal.

    # ---- Write ADMIN_PASSWORD — this is the provisioning step that sets the
    #      super-admin credential for all future logins.  Must happen after
    #      bootstrap so a partial failure doesn't leave a new password without
    #      a working install.  Reload the module-level variable so the current
    #      worker process doesn't need a restart to use the new credential.
    #
    #      FATAL: if the write fails the install is in an inconsistent state
    #      (bootstrapped flag set, but no usable credential written).  Release
    #      the bootstrap claim so the operator can re-run setup after fixing
    #      the env_manager problem (e.g. file-permission issue). ----
    try:
        from env_manager import set_var as _sv
        _sv("ADMIN_PASSWORD", pw, force_override=True)
        secrets_written.append("ADMIN_PASSWORD")
        # Reload module-level cache so the current process accepts the new pw.
        ADMIN_PASSWORD = pw
    except Exception as _pw_err:
        capture_exc(_pw_err, "setup_wizard_post")
        released, rel_err = _release_claim()
        return jsonify({
            "ok": False,
            "error": f"Could not persist admin password: {_pw_err}. "
                     "Setup has been rolled back — fix the env_manager error "
                     "and re-run the wizard.",
            "rollback_failed": not released,
            "manual_recovery_sql": (
                "UPDATE site_settings SET installation_bootstrapped_at = NULL WHERE id = 1;"
            ) if not released else None,
            "rollback_error": rel_err,
        }), 500

    # ---- Write CLIENT_PASSWORD if provided ----------------------------------
    client_pw = request.form.get("client_password", "").strip()
    if client_pw:
        try:
            from env_manager import set_var
            set_var("CLIENT_PASSWORD", client_pw, force_override=True)
            secrets_written.append("CLIENT_PASSWORD")
        except Exception:
            pass  # Non-fatal.

    return jsonify({
        "ok": True,
        "summary": summary,
        "secrets_written": secrets_written,
        "secrets_errors": secrets_errors,
        "redirect": url_for("admin_login"),
    })


@app.route("/setup/catalogue", methods=["GET"])
def setup_wizard_catalogue():
    """Return machine-readable catalogue for the setup wizard.

    Exposes skills, features, page sections, and env-var metadata so the
    wizard can populate its toggles client-side.  Gated by
    _is_install_bootstrapped() — once the site is set up this 404s like
    every other /setup route.  No admin auth required (the wizard is only
    reachable on a brand-new, unconfigured install).
    """
    if _is_install_bootstrapped():
        abort(404)

    # Agent skills (builtin + any already-registered customs).
    skills = []
    try:
        rows = query_db(
            "SELECT name, display_name, description, category, builtin, enabled "
            "FROM agent_skills ORDER BY builtin DESC, category, name"
        )
        skills = [dict(r) for r in rows] if rows else []
    except Exception:
        pass

    # Feature registry (from the in-process constant).
    features = [
        {"name": n, "label": lbl, "tier": tier, "default": dflt, "group": grp}
        for n, lbl, tier, dflt, grp in _FEATURE_REGISTRY
    ]

    # Page sections from DB (seeded at startup).
    page_sections = []
    try:
        rows = query_db(
            "SELECT slug, title, section_type, enabled, sort_order "
            "FROM page_sections WHERE section_type = 'builtin' ORDER BY sort_order, slug"
        )
        page_sections = [dict(r) for r in rows] if rows else []
    except Exception:
        pass

    # Env-var catalogue (metadata + current status, never values).
    from env_manager import KNOWN_VARS, get_status
    env_vars = []
    try:
        for row in get_status():
            env_vars.append({
                "key": row["key"],
                "category": row["category"],
                "level": row["level"],
                "description": row["description"],
                "sensitive": row["sensitive"],
                "url": row.get("url", ""),
                "set": row["set"],
                "source": row["source"],
            })
    except Exception:
        env_vars = [
            {"key": v["key"], "category": v["category"], "level": v["level"],
             "description": v["description"], "sensitive": v["sensitive"],
             "url": v.get("url", ""), "set": False, "source": "unset"}
            for v in KNOWN_VARS
        ]

    return jsonify({
        "skills": skills,
        "features": features,
        "page_sections": page_sections,
        "env_vars": env_vars,
    })


# -----------------------------------------------------------------------------
# Live API-key validation for the Secrets step of the setup wizard.
#
# Admins paste provider API keys into step 8 of the wizard. Without feedback
# they don't learn a key is wrong until the platform is running and a feature
# silently fails. This helper does a cheap, read-only "ping" against each
# provider to confirm the key authenticates BEFORE provisioning finishes.
#
# Contract: every branch returns a dict {"status": ..., "message": ...} where
# status is one of:
#   "valid"       — provider accepted the key
#   "invalid"     — provider rejected the key (bad / revoked credential)
#   "unsupported" — we have no ping for this key (e.g. DATABASE_URL, emails)
#   "error"       — we couldn't reach the provider (network / timeout / 5xx)
#
# Validation NEVER blocks provisioning — it is purely advisory. The wizard
# warns on failures but still lets the operator launch.
# -----------------------------------------------------------------------------
_VALIDATE_KEY_TIMEOUT = 8.0


def _vk_interpret(resp, valid_codes=(200,), invalid_codes=(401, 403)):
    """Map an HTTP response to a validation result. 2xx (or the supplied
    valid_codes) → valid; 401/403 → invalid credential; anything else →
    error (the key might be fine but we couldn't confirm)."""
    code = resp.status_code
    if code in valid_codes or 200 <= code < 300:
        return {"status": "valid", "message": "Key verified successfully."}
    if code in invalid_codes:
        return {"status": "invalid", "message": "Provider rejected this key (unauthorized)."}
    return {"status": "error",
            "message": f"Couldn't confirm — provider returned HTTP {code}."}


def _validate_provider_key(key, value, extra=None):
    """Ping the matching provider for ``key`` to confirm ``value`` works.

    ``extra`` carries companion fields some providers need to validate a
    single credential (e.g. Twilio needs both the account SID and the auth
    token). Returns a result dict — see the section header for the contract.
    Wraps every network call so a flaky provider can never raise into the
    request handler.
    """
    extra = extra or {}
    key = (key or "").strip().upper()
    value = (value or "").strip()
    if not value:
        return {"status": "error", "message": "No value provided."}

    try:
        with httpx.Client(timeout=_VALIDATE_KEY_TIMEOUT) as client:
            if key == "OPENAI_API_KEY":
                r = client.get("https://api.openai.com/v1/models",
                               headers={"Authorization": f"Bearer {value}"})
                return _vk_interpret(r)

            if key == "ANTHROPIC_API_KEY":
                r = client.get("https://api.anthropic.com/v1/models",
                               headers={"x-api-key": value,
                                        "anthropic-version": "2023-06-01"})
                return _vk_interpret(r)

            if key == "ELEVENLABS_API_KEY":
                r = client.get("https://api.elevenlabs.io/v1/user",
                               headers={"xi-api-key": value})
                return _vk_interpret(r)

            if key == "RESEND_API_KEY":
                r = client.get("https://api.resend.com/domains",
                               headers={"Authorization": f"Bearer {value}"})
                return _vk_interpret(r)

            if key in ("STRIPE_SECRET_KEY", "STRIPE_TEST_SECRET_KEY"):
                r = client.get("https://api.stripe.com/v1/account",
                               auth=(value, ""))
                return _vk_interpret(r)

            if key == "STRIPE_PUBLISHABLE_KEY" or key == "STRIPE_TEST_PUBLISHABLE_KEY":
                # Publishable keys can't be authenticated server-side; just
                # sanity-check the prefix so an obviously wrong paste is caught.
                if value.startswith("pk_"):
                    return {"status": "valid",
                            "message": "Looks like a publishable key (format check only)."}
                return {"status": "invalid",
                        "message": "Publishable keys should start with 'pk_'."}

            if key in ("TWILIO_ACCOUNT_SID", "TWILIO_AUTH_TOKEN"):
                # Twilio authenticates the SID + token as a pair. Pull the
                # companion field from ``extra`` so verifying either input
                # checks the whole credential.
                if key == "TWILIO_ACCOUNT_SID":
                    sid, token = value, (extra.get("token") or "").strip()
                else:
                    sid, token = (extra.get("sid") or "").strip(), value
                if not sid or not token:
                    return {"status": "unsupported",
                            "message": "Enter both the Account SID and Auth Token to verify Twilio."}
                r = client.get(
                    f"https://api.twilio.com/2010-04-01/Accounts/{sid}.json",
                    auth=(sid, token))
                return _vk_interpret(r)

            if key == "BRAVE_SEARCH_API_KEY":
                r = client.get("https://api.search.brave.com/res/v1/web/search",
                               params={"q": "ping"},
                               headers={"X-Subscription-Token": value,
                                        "Accept": "application/json"})
                # Brave returns 422 for a malformed/forbidden subscription.
                return _vk_interpret(r, invalid_codes=(401, 403, 422))

            if key == "YELP_API_KEY":
                r = client.get("https://api.yelp.com/v3/businesses/search",
                               params={"location": "New York", "limit": 1},
                               headers={"Authorization": f"Bearer {value}"})
                return _vk_interpret(r)

            if key == "GOOGLE_PLACES_API_KEY":
                r = client.get(
                    "https://maps.googleapis.com/maps/api/place/findplacefromtext/json",
                    params={"input": "ping", "inputtype": "textquery", "key": value})
                # Google always returns HTTP 200; the real verdict is in the
                # JSON "status" field.
                try:
                    data = r.json()
                except Exception:
                    return {"status": "error", "message": "Unexpected response from Google."}
                gstatus = (data.get("status") or "").upper()
                if gstatus in ("OK", "ZERO_RESULTS"):
                    return {"status": "valid", "message": "Key verified successfully."}
                if gstatus in ("REQUEST_DENIED", "INVALID_REQUEST"):
                    return {"status": "invalid",
                            "message": data.get("error_message") or "Google rejected this key."}
                return {"status": "error",
                        "message": f"Couldn't confirm — Google returned '{gstatus}'."}

            if key == "TRIPADVISOR_API_KEY":
                r = client.get(
                    "https://api.content.tripadvisor.com/api/v1/location/search",
                    params={"key": value, "searchQuery": "ping"},
                    headers={"Accept": "application/json"})
                return _vk_interpret(r)

    except httpx.TimeoutException:
        return {"status": "error", "message": "Provider timed out — couldn't verify right now."}
    except httpx.RequestError as e:
        return {"status": "error", "message": f"Couldn't reach provider: {e.__class__.__name__}."}
    except Exception as e:
        return {"status": "error", "message": f"Validation failed: {e.__class__.__name__}."}

    # No ping registered for this key (config values, passwords, URLs, etc.).
    return {"status": "unsupported", "message": "This value can't be verified automatically."}


@app.route("/setup/validate-key", methods=["POST"])
def setup_validate_key():
    """Live-validate a single provider API key during the setup wizard.

    Pre-auth (the wizard is only reachable on a fresh install) and gated by
    _is_install_bootstrapped() like every other /setup route, so it 404s once
    the platform is provisioned. Read-only: it never writes the value, it just
    pings the provider so the operator gets instant feedback. Validation is
    advisory only and never blocks provisioning.

    POST (not GET) on purpose: the body carries live API secrets, so it must
    never travel in the URL where it would land in server/access logs, browser
    history, proxy logs, or a Referer header. Credentials go in the JSON body.
    """
    if _is_install_bootstrapped():
        abort(404)

    data = request.get_json(silent=True) or {}
    key = (str(data.get("key") or "")).strip()
    value = (str(data.get("value") or "")).strip()
    if not key:
        return jsonify({"status": "error", "message": "Missing 'key' parameter."}), 400
    if not value:
        return jsonify({"status": "error", "message": "No value provided to verify."}), 400

    # Companion fields for providers whose credential is a pair (Twilio).
    extra = {
        "sid": (str(data.get("sid") or "")).strip(),
        "token": (str(data.get("token") or "")).strip(),
    }

    result = _validate_provider_key(key, value, extra)
    result["key"] = key
    return jsonify(result)


# =============================================================================
# SEO HELPERS — Build meta tags and structured data from database settings
# =============================================================================
# These functions read SEO settings from the site_settings table and produce
# HTML strings that are injected into index.html server-side, so search engine
# crawlers see proper meta tags without needing JavaScript execution.

def _esc(s):
    """
    HTML-escape a string for safe use in meta tag attributes.
    Prevents XSS if SEO fields contain special characters.
    """
    return html_module.escape(str(s), quote=True)


def _build_seo_meta_html(overrides=None):
    """
    Build the complete SEO meta tags HTML block from database settings.
    Returns an HTML string containing: title, meta description, keywords,
    robots directive, canonical URL, Open Graph tags, Twitter Card tags,
    and favicon links. Falls back to site_settings values if SEO-specific
    fields are empty.

    overrides: optional dict used by standalone-page rendering at /p/<slug>
      AND per-section pretty URLs at /<section_slug> (Task #69).
      Recognised keys: "title", "description", "og_image". Non-empty
      overrides win over the site_settings cascade. The override title
      is also suffixed with "| <site_name>" so search results stay
      attributable to the brand.
    """
    settings = query_db("SELECT * FROM site_settings WHERE id = 1", fetchone=True)
    if not settings:
        settings = {}
    overrides = overrides or {}

    # Determine SEO values with cascading fallbacks
    site_name = settings.get("site_name", "My Site")
    title = (overrides.get("title") or "").strip()
    if title:
        # Suffix the brand so /p/<slug> tabs are still recognisable
        if site_name and site_name not in title:
            title = f"{title} | {site_name}"
    else:
        title = (settings.get("seo_meta_title") or "").strip()
    if not title:
        # Fall back to site name + subtitle for the page title
        subtitle = settings.get("site_subtitle", "")
        title = f"{site_name} — {subtitle}" if subtitle else site_name

    description = (overrides.get("description") or "").strip()
    if not description:
        description = (settings.get("seo_meta_description") or "").strip()
    if not description:
        # Fall back to the hero description text
        description = settings.get("hero_description", "")

    keywords = (settings.get("seo_keywords") or "").strip()
    # og:image cascades override → site-wide → packaged default. Same
    # pattern as title/description so per-section pretty URLs (Task #69)
    # can ship a custom social-share preview card without each admin
    # having to re-set the site-wide image first.
    og_image = (overrides.get("og_image") or "").strip()
    if not og_image:
        og_image = (settings.get("seo_og_image") or "").strip() or "/ai_concierge.png"
    twitter_handle = (settings.get("seo_twitter_handle") or "").strip()
    canonical_url = (settings.get("seo_canonical_url") or "").strip()
    robots = (settings.get("seo_robots") or "").strip() or "index, follow"
    site_name = settings.get("site_name", "My Site")

    lines = []

    # --- Core meta tags ---
    lines.append('  <!-- SEO Meta Tags — Injected server-side from database settings -->')
    lines.append(f'  <title>{_esc(title)}</title>')
    lines.append(f'  <meta name="description" content="{_esc(description)}">')
    if keywords:
        lines.append(f'  <meta name="keywords" content="{_esc(keywords)}">')
    lines.append(f'  <meta name="robots" content="{_esc(robots)}">')
    if canonical_url:
        lines.append(f'  <link rel="canonical" href="{_esc(canonical_url)}">')

    # --- Favicon ---
    lines.append('  <!-- Favicon — Shows next to the URL in browser tabs and on smartphone home screens -->')
    lines.append('  <link rel="icon" type="image/png" href="/ai_concierge.png">')
    lines.append('  <link rel="apple-touch-icon" href="/ai_concierge.png">')

    # --- Open Graph tags (for Facebook, LinkedIn, etc.) ---
    lines.append('  <!-- Open Graph Tags — For social media sharing -->')
    lines.append(f'  <meta property="og:title" content="{_esc(title)}">')
    lines.append(f'  <meta property="og:description" content="{_esc(description)}">')
    lines.append('  <meta property="og:type" content="website">')
    lines.append(f'  <meta property="og:image" content="{_esc(og_image)}">')
    if canonical_url:
        lines.append(f'  <meta property="og:url" content="{_esc(canonical_url)}">')
    lines.append(f'  <meta property="og:site_name" content="{_esc(site_name)}">')

    # --- Twitter Card tags ---
    lines.append('  <!-- Twitter Card Tags -->')
    lines.append('  <meta name="twitter:card" content="summary_large_image">')
    lines.append(f'  <meta name="twitter:title" content="{_esc(title)}">')
    lines.append(f'  <meta name="twitter:description" content="{_esc(description)}">')
    lines.append(f'  <meta name="twitter:image" content="{_esc(og_image)}">')
    if twitter_handle:
        # Ensure handle starts with @
        handle = twitter_handle if twitter_handle.startswith("@") else f"@{twitter_handle}"
        lines.append(f'  <meta name="twitter:site" content="{_esc(handle)}">')

    return "\n".join(lines)


def _build_json_ld():
    """
    Build JSON-LD structured data for search engine rich results.
    Returns an HTML string containing two <script type="application/ld+json"> blocks:
      1. Organization schema — site name, URL, logo, and social profiles
      2. WebSite schema — site name, URL, and description
    These help Google and other search engines understand the site's identity
    and display enhanced search results (knowledge panels, sitelinks, etc.).
    """
    settings = query_db("SELECT * FROM site_settings WHERE id = 1", fetchone=True) or {}

    site_name = settings.get("site_name", "My Site")
    canonical_url = (settings.get("seo_canonical_url") or "").strip()
    og_image = (settings.get("seo_og_image") or "").strip() or "/ai_concierge.png"
    description = (settings.get("seo_meta_description") or "").strip() or settings.get("hero_description", "")

    # Build social profile URLs array from the social_links JSONB column
    social_links = settings.get("social_links", {})
    if isinstance(social_links, str):
        try:
            social_links = json.loads(social_links)
        except Exception:
            social_links = {}
    same_as = [url for url in social_links.values() if url and isinstance(url, str)]

    # Organization schema — tells search engines who operates this site
    org_data = {
        "@context": "https://schema.org",
        "@type": "Organization",
        "name": site_name,
        "url": canonical_url or "/",
        "logo": og_image,
    }
    if same_as:
        org_data["sameAs"] = same_as

    # WebSite schema — tells search engines about the site itself
    website_data = {
        "@context": "https://schema.org",
        "@type": "WebSite",
        "name": site_name,
        "url": canonical_url or "/",
        "description": description,
    }

    lines = []
    lines.append('  <!-- JSON-LD Structured Data — Injected server-side for SEO -->')
    lines.append(f'  <script type="application/ld+json">{json.dumps(org_data)}</script>')
    lines.append(f'  <script type="application/ld+json">{json.dumps(website_data)}</script>')

    return "\n".join(lines)


# =============================================================================
# PUBLIC ROUTES — Serve the static HTML site
# =============================================================================

def _hex_to_rgb_triple(hex_color, fallback="6 11 20"):
    """'#060b14' -> '6 11 20' (space-separated rgb for use inside rgba()).
    Returns the fallback (default theme bg) on any parse failure."""
    try:
        s = (hex_color or "").strip().lstrip("#")
        if len(s) == 3:
            s = "".join(c * 2 for c in s)
        if len(s) != 6:
            return fallback
        return f"{int(s[0:2], 16)} {int(s[2:4], 16)} {int(s[4:6], 16)}"
    except Exception:
        return fallback


def _build_theme_vars_style():
    """Return a `<style>:root{...}</style>` block carrying every theme-driven
    CSS custom property, built from the resolved active theme (legacy
    columns + active site_themes overlay). Injected into the served HTML
    BEFORE first paint so the loading screen, glass surfaces, corner radii
    and motion timing all match the admin-configured theme on frame 1
    instead of flashing the stylesheet defaults."""
    try:
        t = _resolve_active_theme() or {}
        bg          = t.get("theme_bg") or "#060b14"
        section1    = t.get("theme_section1") or "#0a0f1a"
        section2    = t.get("theme_section2") or "#060b14"
        accent      = t.get("theme_accent") or "#c9a96e"
        text_color  = t.get("theme_text") or "#e4e4e7"
        glass_bg    = t.get("theme_glass_bg") or "rgba(255,255,255,0.03)"
        glass_brd   = t.get("theme_glass_border") or "rgba(255,255,255,0.08)"
        font_serif  = t.get("theme_font_serif") or "Playfair Display"
        font_sans   = t.get("theme_font_sans") or "DM Sans"
        # Numeric tokens come from _resolve_active_theme too (it already
        # SELECTs them and applies the site_themes palette_json overlay
        # when an active theme is set), so we read them straight from `t`
        # and only fall back to defaults for None — 0 is a legitimate
        # value (e.g. radius_rem=0 for sharp corners).
        def _f(k, d):
            v = t.get(k)
            try: return float(v) if v is not None else d
            except (TypeError, ValueError): return d
        def _i(k, d):
            v = t.get(k)
            try: return int(v) if v is not None else d
            except (TypeError, ValueError): return d
        loading_a   = _f("theme_loading_bg_alpha", 0.85)
        glass_blur  = _i("theme_glass_blur_px",    24)
        radius_rem  = _f("theme_radius_rem",       1.0)
        trans_sec   = _f("theme_transition_sec",   0.6)
        bg_rgb      = _hex_to_rgb_triple(bg)
        # Brand-identity tokens (Task #61). The gradient var is ALWAYS
        # emitted — when the toggle is off OR no secondary color is set
        # we just emit the solid accent, so any rule that uses
        # --accent-gradient gets a safe color fallback instead of
        # `none` (which `background:` interprets as transparent).
        accent_2    = (t.get("theme_accent_secondary") or "").strip()
        gradient_on = bool(t.get("theme_accent_gradient")) and bool(accent_2)
        if gradient_on:
            accent_grad = f"linear-gradient(135deg,{accent},{accent_2})"
        else:
            accent_grad = accent
        # Logo image becomes a CSS var so the .logo-mode-image badge can
        # render the uploaded image as a background-image on first paint
        # (no JS required). Only emit when the active mode actually uses
        # an image; otherwise emit `none` so any stray rule that reads
        # the var degrades safely.
        logo_mode  = (t.get("theme_logo_mode") or "monogram").strip().lower()
        logo_image = (t.get("theme_logo_image") or "").strip()
        if logo_mode in ("image", "lockup") and logo_image:
            # Sanitize the URL: only allow protocol-relative, absolute
            # paths (/uploads/...) and http(s) URLs, and quote-escape
            # double quotes. Anything else falls back to no image.
            safe = logo_image.replace('"', "%22")
            if safe.startswith(("/", "http://", "https://", "//")):
                logo_image_css = f'url("{safe}")'
            else:
                logo_image_css = "none"
        else:
            logo_image_css = "none"
        # Motion-personality token (Task #62). The named easing curves
        # below are the source of truth; styles.css consumes them via
        # var(--ease-active) which we set here based on theme_easing.
        # Falling back to the existing --ease-smooth value keeps the
        # default install identical to before this token was added.
        easing_name = (t.get("theme_easing") or "gentle").strip().lower()
        ease_curves = {
            "snappy":    "cubic-bezier(0.4, 0, 0.2, 1)",
            "gentle":    "cubic-bezier(0.22, 1, 0.36, 1)",
            "bouncy":    "cubic-bezier(0.34, 1.56, 0.64, 1)",
            "editorial": "cubic-bezier(0.65, 0, 0.35, 1)",
        }
        ease_active = ease_curves.get(easing_name, ease_curves["gentle"])

        # Layout & rhythm tokens (Task #63 / items 6, 7, 9, 16). The
        # density multiplier scales every --space-* value via a single
        # --space-scale var that styles.css multiplies into the spacing
        # scale, so changing density resizes section padding, gaps and
        # header rhythm site-wide without touching individual rules.
        # The frame inset becomes a px var that .landing-section's
        # horizontal padding adds to its base --space-xl, exposing more
        # of the page bg through the existing background-clip:content-box
        # rule (Task #60). Both default to no-op so installs that pre-
        # date the columns paint identically to before.
        density_name = (t.get("theme_density") or "comfortable").strip().lower()
        density_scale = {
            "compact":     0.75,
            "comfortable": 1.0,
            "spacious":    1.25,
        }.get(density_name, 1.0)
        try:
            frame_inset = int(t.get("theme_section_frame_inset") or 0)
        except (TypeError, ValueError):
            frame_inset = 0
        frame_inset = max(0, min(32, frame_inset))
        # Overall-size (zoom) factor. 1.0 = 100% (no zoom); < 1 zooms out
        # (smaller components), > 1 zooms in (bigger). Applied as CSS `zoom`
        # on the document root below so EVERYTHING scales proportionally
        # (cards, type, spacing, chat widget). Clamped 0.5–1.5 so a stray
        # value can't make the site unusable. Injected before first paint
        # so there's no resize flash on load.
        ui_scale = _f("theme_ui_scale", 1.0)
        ui_scale = max(0.5, min(1.5, ui_scale))
        # Chat-pill size factor — scoped to the chatbot pill/launcher only
        # (see the .chatbot-bar / .chatbot-launcher zoom rules in styles.css
        # which read this var). Clamped 0.7–1.4 so the pill stays tappable
        # and readable. 1.0 = 100%.
        chat_pill_scale = _f("theme_chat_pill_scale", 1.0)
        chat_pill_scale = max(0.7, min(1.4, chat_pill_scale))
        # Personality (Task #64 / item 11) — admin-picked progress-bar
        # color. When empty we deliberately OMIT the variable so the
        # CSS fallback chain (var(--scroll-progress-color, var(--color-
        # accent))) tracks live accent changes after a save without
        # needing a full reload. Only emit when the admin set a custom
        # hex. _resolve_active_theme already validated the format.
        scroll_progress_color = (t.get("theme_scroll_progress_color") or "").strip()
        progress_color_decl = (
            f"--scroll-progress-color:{scroll_progress_color};"
            if scroll_progress_color else ""
        )
        return (
            "<style id=\"theme-vars-injected\">:root{"
            f"--color-bg:{bg};"
            f"--color-bg-rgb:{bg_rgb};"
            f"--color-section-1:{section1};"
            f"--color-section-2:{section2};"
            f"--color-accent:{accent};"
            f"--color-accent-secondary:{accent_2 or accent};"
            f"--accent-gradient:{accent_grad};"
            f"--color-text:{text_color};"
            f"--glass-bg:{glass_bg};"
            f"--glass-border:{glass_brd};"
            f"--glass-blur:{glass_blur}px;"
            f"--radius:{radius_rem}rem;"
            f"--loading-bg-alpha:{loading_a};"
            f"--transition-medium:{trans_sec}s;"
            f"--font-serif:'{font_serif}',Georgia,serif;"
            f"--font-sans:'{font_sans}',-apple-system,BlinkMacSystemFont,sans-serif;"
            f"--logo-image:{logo_image_css};"
            f"--ease-active:{ease_active};"
            f"--space-scale:{density_scale};"
            f"--ui-scale:{ui_scale};"
            f"--chat-pill-scale:{chat_pill_scale};"
            f"--section-frame-inset:{frame_inset}px;"
            # Personality (Task #64 / item 11) — scroll-progress bar color.
            # Only emitted when admin set a custom hex; otherwise the CSS
            # rule's var(--scroll-progress-color, var(--color-accent))
            # fallback tracks live accent updates without a page reload.
            f"{progress_color_decl}"
            "}"
            # Apply the overall-size factor as CSS `zoom` on the root so
            # every component scales together. Reads the --ui-scale var set
            # above; live admin saves update it via script.js without reload.
            "html{zoom:var(--ui-scale,1);}"
            "</style>"
        )
    except Exception as e:
        print(f"[serve_index] theme vars injection failed: {e}; serving without")
        return ""


def _build_active_font_link():
    """Return a single `<link rel="stylesheet">` tag for the active
    theme's serif+sans Google Fonts pair, so first paint already has
    the right typefaces and the browser doesn't waste a roundtrip on
    the previously-hardcoded Playfair+DM Sans @import.

    Falls back to Playfair Display + DM Sans (the original defaults)
    when the active theme leaves either field blank. Returns an empty
    string on any failure — the page still renders, just with the
    browser's default fonts until script.js's loadAndApplyTheme
    eventually injects the link itself."""
    try:
        t = _resolve_active_theme() or {}
        serif = (t.get("theme_font_serif") or "").strip() or "Playfair Display"
        sans  = (t.get("theme_font_sans")  or "").strip() or "DM Sans"
        # De-dup if both happen to be the same family (unusual but
        # possible with a custom theme — saves one URL parameter).
        names = [serif] if serif == sans else [serif, sans]
        # Google Fonts API v2 expects "+" for spaces and accepts a
        # weight range that covers our typography scale.
        params = "&".join(
            f"family={n.replace(' ', '+')}:wght@300;400;500;600;700"
            for n in names
        )
        href = f"https://fonts.googleapis.com/css2?{params}&display=swap"
        # Preconnect hints are already injected globally by
        # _build_preconnect_hints_html() — don't emit them again here
        # or the browser sees redundant hints in <head>.
        return f'<link id="theme-fonts-injected" rel="stylesheet" href="{href}">'
    except Exception as e:
        print(f"[serve_index] font link injection failed: {e}; serving without")
        return ""


def _build_preconnect_hints_html():
    """Return a block of <link rel="preconnect"> + <link rel="dns-prefetch">
    hints for the third-party origins this template loads from. Injected
    into <head> server-side BEFORE the parser-blocking <script> tags below
    so the DNS+TCP+TLS handshakes start in parallel with HTML parsing —
    saves ~30-300 ms per origin on cold-cache loads, which matters most
    on the very first paint when the connection cost is fully unhidden.
    Optimization #10.

    Why these specific origins (every page load hits all six):
      - unpkg.com               Lucide icons (parser-blocking <script> in head)
      - cdnjs.cloudflare.com    Three.js + DOMPurify (two head <script> tags)
      - cdn.jsdelivr.net        Three.js CSS3DRenderer (head <script>)
      - js.stripe.com           Stripe SDK (head <script>; loads on every
                                page even when storefront is disabled)
      - fonts.googleapis.com    Google Fonts CSS (loaded dynamically by
                                script.js loadGoogleFont() after theme fetch)
      - fonts.gstatic.com       Actual font files; needs `crossorigin`
                                because the CSS spec fetches font files as
                                anonymous-CORS — a preconnect WITHOUT
                                crossorigin would warm a different connection
                                pool that the font fetch never uses, wasting
                                the hint entirely.

    Why preconnect AND dns-prefetch: preconnect (DNS+TCP+TLS) is supported
    by every modern browser. dns-prefetch (DNS only) is the harmless
    fallback for the few legacy browsers that don't support preconnect;
    modern browsers ignore the dns-prefetch line when a matching preconnect
    is present, so listing both costs nothing.

    Hardcoded list rather than introspected because the script tags these
    mirror are themselves hardcoded in public/index.html — keep them in
    sync if you add/remove a third-party head script. The cost of a
    leftover preconnect for a removed origin is one unused TCP connection
    held open for ~10 seconds; the cost of a missing preconnect for a
    new origin is the full handshake on the critical path. Err toward
    keeping the list (and updating it during reviews)."""
    return (
        '<link rel="preconnect" href="https://fonts.googleapis.com">'
        '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>'
        '<link rel="preconnect" href="https://unpkg.com">'
        '<link rel="preconnect" href="https://cdnjs.cloudflare.com">'
        '<link rel="preconnect" href="https://cdn.jsdelivr.net">'
        '<link rel="preconnect" href="https://js.stripe.com">'
        '<link rel="dns-prefetch" href="https://fonts.googleapis.com">'
        '<link rel="dns-prefetch" href="https://fonts.gstatic.com">'
        '<link rel="dns-prefetch" href="https://unpkg.com">'
        '<link rel="dns-prefetch" href="https://cdnjs.cloudflare.com">'
        '<link rel="dns-prefetch" href="https://cdn.jsdelivr.net">'
        '<link rel="dns-prefetch" href="https://js.stripe.com">'
    )


def _build_loading_initials_and_name():
    """Return (initials, site_name) so the loading-screen badge + caption
    render with the real values on first paint instead of flashing CS /
    Loading. Falls back to the historic placeholders on any error."""
    try:
        s = query_db(
            "SELECT logo_initials, site_name FROM site_settings WHERE id = 1",
            fetchone=True,
        ) or {}
        initials = (s.get("logo_initials") or "CS").strip() or "CS"
        name     = (s.get("site_name") or "Loading").strip() or "Loading"
        # html-escape to prevent breakout via admin-set values.
        from html import escape as _h
        return _h(initials), _h(name)
    except Exception:
        return "CS", "Loading"


@app.route("/")
def serve_index(initial_section_dom_id=None, seo_overrides=None):
    """Serve the main public homepage.

    `initial_section_dom_id` is forwarded by serve_section() (Task #67)
    when the homepage is reached via a pretty per-section URL like
    /podcast or /events. It ends up as `data-initial-section="<id>"`
    on <html> so script.js's _scrollToHashOnLoad can deep-link to that
    section on first paint without polluting the URL with a #hash.
    Defaults to None on the canonical "/" path so the homepage isn't
    pinned to any specific section.

    `seo_overrides` is forwarded by serve_section() (Task #69) when the
    matched page_sections row carries non-empty seo_title /
    seo_description / seo_image — these win over the homepage's
    site-wide cascade in _build_seo_meta_html so each /<section_slug>
    URL gets its own search-result snippet and social-share preview.
    Defaults to None on the canonical "/" path so the homepage keeps
    using the site-wide SEO settings as before."""
    return _render_app_shell_response(
        initial_section_dom_id=initial_section_dom_id,
        seo_overrides=seo_overrides,
    )


@app.route("/p/<string:slug>")
def serve_standalone_page(slug):
    """
    GET /p/<slug>
    Render an admin-authored standalone page using the same shell, top
    nav, footer, theme, and JS bundle as the homepage. The page's
    assigned page_sections (joined via page_section_assignments) are
    the only ones rendered — every other built-in section is hidden
    server-side via inline display:none to avoid first-paint flash;
    custom sections are filtered the same way client-side.

    404 for unknown or disabled slugs. The /p/ namespace prefix avoids
    any collision with the public catch-all "/<path:filename>" that
    serves static files out of public/.
    """
    page = query_db(
        "SELECT id, slug, title, meta_description "
        "FROM pages WHERE slug = %s AND enabled = TRUE",
        (slug,), fetchone=True,
    )
    if not page:
        abort(404)
    rows = query_db(
        "SELECT section_id FROM page_section_assignments "
        "WHERE page_id = %s ORDER BY sort_order ASC, id ASC",
        (page["id"],),
    ) or []
    section_ids = [r["section_id"] for r in rows]
    return _render_app_shell_response(page=page, section_ids=section_ids)


def _render_app_shell_response(page=None, section_ids=None, initial_section_dom_id=None, seo_overrides=None, embed_key=None):
    """
    Serve the public site HTML shell with SEO meta tags injected
    server-side. Used by both the homepage at "/" (page=None) and
    admin-authored standalone pages at "/p/<slug>" (page set).

    Source preference order:
      1. The active design row in site_designs (if site_settings.active_design_id
         is set and the row exists). This is what admin "publishes" from the
         Website tab.
      2. public/index.html on disk — the safe shipped fallback.

    Either source then has SEO + JSON-LD placeholders replaced so crawlers
    see proper meta tags without needing JavaScript execution.

    page / section_ids: when set, the response is rendered as a
    standalone page — the SEO title and description are overridden to
    match the page row, the <html> element gains data-page-mode,
    data-page-id, data-page-slug and data-page-section-ids attributes,
    and built-in sections that aren't assigned are hidden inline so
    the user never sees them flash before script.js applies the
    standalone-mode filter.

    `initial_section_dom_id` is set when this function is invoked from
    the pretty-URL section route (`/<section_slug>`, see serve_section,
    Task #67). The DOM id ends up as `data-initial-section="<id>"` on
    the <html> element so public/script.js's _scrollToHashOnLoad can
    scroll the visitor to that section on first paint without needing
    a URL hash. Defaults to None on the canonical "/" path so the
    regular homepage isn't pinned to any specific section. Mutually
    exclusive with the standalone-page mode (serve_section never
    targets /p/<slug>).
    """
    try:
        html_content = None

        # 1) Try the admin-published active design row.
        try:
            active = query_db(
                "SELECT s.active_design_id AS aid, d.html AS html "
                "FROM site_settings s "
                "LEFT JOIN site_designs d ON d.id = s.active_design_id "
                "WHERE s.id = 1",
                fetchone=True,
            )
            if active and active.get("aid") and (active.get("html") or "").strip():
                html_content = active["html"]
        except Exception as e:
            # Brand-new install or migration in flight — fall through to disk.
            print(f"[serve_index] active design lookup failed, using disk: {e}")

        # 2) Fall back to the file on disk.
        if html_content is None:
            index_path = os.path.join(app.static_folder, "index.html")
            with open(index_path, "r", encoding="utf-8") as f:
                html_content = f.read()

        # Cache-bust the linked stylesheet so visitors on Mobile Safari /
        # other aggressive caches always pick up the latest styles.css
        # without having to clear their cache. Applied here (not just on
        # disk) so admin-published designs in site_designs — which still
        # carry the original unversioned <link rel="stylesheet"
        # href="/styles.css"> snapshot — also get the fresh marker. Bump
        # _STYLES_CSS_VERSION whenever public/styles.css ships a visible
        # change that needs to invalidate cached copies.
        _STYLES_CSS_VERSION = "20260608g"
        html_content = re.sub(
            r'href="/styles\.css(?:\?[^"]*)?"',
            f'href="/styles.css?v={_STYLES_CSS_VERSION}"',
            html_content,
        )

        # Inject SEO meta tags (replaces the <!-- SEO_META_INJECT --> placeholder in <head>)
        # On standalone pages, the page row's title/meta_description win
        # over the homepage SEO cascade so each /p/<slug> tab has its
        # own search-result title and social-share description. Per-
        # section pretty URLs (Task #69) pass their own seo_overrides
        # in via serve_section so /<section_slug> URLs get their own
        # title, description, and og:image too. Standalone-page mode
        # always wins over a caller-supplied override (the two are
        # mutually exclusive in practice — serve_section never targets
        # /p/<slug>).
        if page is not None:
            seo_overrides = {
                "title": (page.get("title") or "").strip(),
                "description": (page.get("meta_description") or "").strip(),
            }
        seo_html = _build_seo_meta_html(seo_overrides)
        html_content = html_content.replace("<!-- SEO_META_INJECT -->", seo_html)

        # Inject JSON-LD structured data (replaces the <!-- JSON_LD_INJECT --> placeholder before </head>)
        json_ld_html = _build_json_ld()
        html_content = html_content.replace("<!-- JSON_LD_INJECT -->", json_ld_html)

        # Inject preconnect / dns-prefetch hints for the third-party origins
        # this template loads from (Optimization #10). Disk/legacy-design
        # dual-path: prefer the placeholder (designs created on/after April
        # 2026 have it), otherwise insert RIGHT AFTER the opening <head>
        # tag for backward compat with admin-published designs that were
        # saved before this placeholder existed.
        #
        # Why right-after-<head> and not right-before-</head> like the
        # theme_vars fallback: preconnect hints are POSITION-SENSITIVE.
        # The browser only starts handshakes when the parser encounters
        # the link tag, so a preconnect inserted AFTER a parser-blocking
        # <script src="https://..."> tag is too late — the script's own
        # handshake has already started serially. Theme vars are
        # position-insensitive (CSS variables resolve at compute time
        # regardless of declaration order in head), so its before-</head>
        # fallback is fine for theme vars but would be a no-op here.
        # Pinned by TestServedHomepage::test_preconnect_appears_before_blocking_scripts
        # and TestLegacyDesignFallback::test_fallback_inserts_right_after_head_open.
        preconnect_html = _build_preconnect_hints_html()
        if preconnect_html:
            if "<!-- PRECONNECT_HINTS_INJECT -->" in html_content:
                html_content = html_content.replace(
                    "<!-- PRECONNECT_HINTS_INJECT -->", preconnect_html
                )
            else:
                # Find the opening <head> tag (handles `<head>` and
                # `<head class="...">` etc.) and inject immediately after.
                head_open = re.search(r"<head\b[^>]*>", html_content, flags=re.IGNORECASE)
                if head_open:
                    insertion = head_open.end()
                    html_content = (
                        html_content[:insertion]
                        + "\n  "
                        + preconnect_html
                        + html_content[insertion:]
                    )
                else:
                    # Pathological case: no <head> at all. Drop in before
                    # </head> as a last resort so the hints exist somewhere.
                    html_content = html_content.replace(
                        "</head>", preconnect_html + "\n</head>", 1
                    )

        # Inject :root CSS vars from the active theme so the loading screen
        # and every other themed surface paints the right colors on the
        # very first frame instead of flashing the stylesheet defaults.
        # The disk-template path uses the explicit placeholder; any
        # admin-published design row stored in site_designs predates this
        # placeholder, so we fall back to inserting the style block right
        # before </head> (where it still wins over the linked stylesheet).
        theme_style = _build_theme_vars_style()
        # Build the active-pair font <link> alongside the theme vars so
        # they're injected together. The link must come BEFORE the style
        # block (browsers parse <head> top-down and a font-family rule
        # only resolves once the @font-face declarations from the linked
        # stylesheet are available).
        font_link = _build_active_font_link()
        injection = (font_link + theme_style) if (font_link or theme_style) else ""
        if injection:
            if "<!-- THEME_VARS_INJECT -->" in html_content:
                html_content = html_content.replace(
                    "<!-- THEME_VARS_INJECT -->", injection
                )
            else:
                html_content = html_content.replace(
                    "</head>", injection + "\n</head>", 1
                )

        # task 092 P1 — boot browser Sentry on the public site (mirrors the
        # admin shell via the SAME _build_frontend_sentry_html() builder). The
        # builder always returns at least the tiny appReportError no-op shim (so
        # the swept-in JS call sites are safe even with Sentry off), plus the SDK
        # loader when a DSN is set. Legacy designs saved before the placeholder
        # existed get the before-</head> fallback (the loader is async +
        # self-guarded, so its position in <head> is not sensitive like the
        # preconnect hints are).
        sentry_html = _build_frontend_sentry_html()
        if "<!-- SENTRY_INJECT -->" in html_content:
            html_content = html_content.replace("<!-- SENTRY_INJECT -->", sentry_html)
        elif sentry_html:
            html_content = html_content.replace("</head>", sentry_html + "\n</head>", 1)

        # ----------------------------------------------------------------
        # First-paint logo treatment + accent-gradient body class injection
        # (Task #61). The CSS variants in styles.css and the hidden-image
        # rendering BOTH key off `<body class="logo-mode-X">`, so without
        # this server-side step the page would flash the default monogram
        # before script.js applies the right class. Same goes for the
        # accent-gradient surface treatment.
        #
        # We rewrite the FIRST `<body ...>` tag to merge our brand classes
        # into any existing class attribute (some admin-published designs
        # already set body classes for layout/scroll behavior).
        # ----------------------------------------------------------------
        try:
            tt = _resolve_active_theme() or {}
            mode_raw = (tt.get("theme_logo_mode") or "monogram").strip().lower()
            mode = mode_raw if mode_raw in ("monogram", "image", "wordmark", "lockup") else "monogram"
            brand_classes = ["logo-mode-" + mode]
            if tt.get("theme_accent_gradient") and (tt.get("theme_accent_secondary") or "").strip():
                brand_classes.append("theme-accent-gradient")
            extra = " ".join(brand_classes)

            def _merge_body_class(m):
                # Group 1 = full attribute string between `<body` and `>`,
                # which may already contain class="..." plus other attrs.
                attrs = m.group(1) or ""
                cls_match = re.search(r'\bclass\s*=\s*"([^"]*)"', attrs)
                if cls_match:
                    merged = (cls_match.group(1) + " " + extra).strip()
                    new_attrs = attrs[:cls_match.start()] + f'class="{merged}"' + attrs[cls_match.end():]
                else:
                    new_attrs = attrs + f' class="{extra}"'
                return f"<body{new_attrs}>"

            html_content = re.sub(
                r'<body([^>]*)>',
                _merge_body_class,
                html_content,
                count=1,
            )

            # ----------------------------------------------------------
            # Surface-treatment data-* attrs on the root <html> element
            # (Task #62 / items 3, 5, 12, 13). The CSS variants in
            # styles.css ([data-card-style], [data-loading-mode],
            # [data-photo-filter]) all key off the <html> element so
            # the rules apply to BOTH the loading screen (which lives
            # outside <main>) and the rest of the page. Setting them
            # here ensures first paint already has the right surface
            # treatment instead of flashing the defaults before
            # script.js's loadAndApplyTheme runs.
            #
            # `theme_card_style`, `theme_easing`, `theme_photo_filter`,
            # and `theme_loading_mode` were already whitelisted in
            # _resolve_active_theme(), so the values we read here are
            # guaranteed to be one of the documented enum members.
            # ----------------------------------------------------------
            cs = (tt.get("theme_card_style")   or "editorial").strip().lower() or "editorial"
            ez = (tt.get("theme_easing")       or "gentle").strip().lower()    or "gentle"
            pf = (tt.get("theme_photo_filter") or "none").strip().lower()      or "none"
            lm = (tt.get("theme_loading_mode") or "logo_name").strip().lower() or "logo_name"
            # Layout & rhythm data-* attrs (Task #63 / items 6, 7, 9, 16).
            # Same first-paint pattern as the surface-treatment block —
            # CSS variants in styles.css ([data-density], [data-header-align],
            # [data-hero-layout]) all key off <html> so the right rhythm,
            # header alignment and hero structure paint on frame 1 instead
            # of flashing the defaults before script.js's loadAndApplyTheme
            # runs. _resolve_active_theme already whitelists every value
            # so the strings we emit here are guaranteed to be one of the
            # documented enum members.
            dn = (tt.get("theme_density")      or "comfortable").strip().lower() or "comfortable"
            ha = (tt.get("theme_header_align") or "centered").strip().lower()    or "centered"
            hl = (tt.get("hero_layout_mode")   or "full_bleed").strip().lower()  or "full_bleed"
            # Personality data-* attrs (Task #64 / items 10, 11, 14, 15).
            # Same first-paint pattern: CSS variants + applyPersonality
            # both key off these attrs on <html>, so the cursor mode,
            # progress-bar visibility, nav style, and chatbot placement
            # all paint correctly on frame 1 instead of flashing the
            # baseline before script.js runs.
            cum  = (tt.get("theme_cursor_mode")       or "native").strip().lower()         or "native"
            sp   = "1" if tt.get("theme_scroll_progress") else "0"
            nvs  = (tt.get("theme_nav_style")         or "floating_glass").strip().lower() or "floating_glass"
            cbp  = (tt.get("theme_chatbot_placement") or "bottom_center").strip().lower() or "bottom_center"
            html_attrs = (
                f' data-card-style="{cs}"'
                f' data-easing="{ez}"'
                f' data-photo-filter="{pf}"'
                f' data-loading-mode="{lm}"'
                f' data-density="{dn}"'
                f' data-header-align="{ha}"'
                f' data-hero-layout="{hl}"'
                f' data-cursor-mode="{cum}"'
                f' data-scroll-progress="{sp}"'
                f' data-nav-style="{nvs}"'
                f' data-chatbot-placement="{cbp}"'
            )
            # Standalone-page markers (Task #71). When set, script.js's
            # applySectionOrder() filters and reorders sections to the
            # page's assignment list, and renderSectionNavMenu() builds
            # cross-page anchor URLs (e.g. "/#section-faq") so the
            # in-hero menu still navigates back to the homepage.
            if page is not None:
                ids_csv = ",".join(str(int(x)) for x in (section_ids or []))
                html_attrs += (
                    ' data-page-mode="standalone"'
                    f' data-page-id="{int(page["id"])}"'
                    f' data-page-slug="{_esc(page["slug"])}"'
                    f' data-page-section-ids="{ids_csv}"'
                )

            # Pretty-URL initial section (Task #67). When the homepage is
            # reached via /<section_slug> instead of "/", we pin a
            # data-initial-section attr on <html> so script.js's
            # _scrollToHashOnLoad can deep-link to that section on first
            # paint without polluting the URL with a #hash. Quoted via a
            # tight regex elsewhere; the value is a DOM id we resolved
            # ourselves (built-in map or section-custom-<int>) so it is
            # safe to interpolate directly. Mutually exclusive with the
            # standalone-page block above (serve_section only ever
            # targets the homepage shell).
            if initial_section_dom_id:
                html_attrs += f' data-initial-section="{initial_section_dom_id}"'

            def _merge_html_attrs(m):
                attrs = m.group(1) or ""
                # Strip any pre-existing surface-treatment + layout/rhythm
                # + personality + standalone-page + initial-section
                # data-* attrs so re-renders don't accumulate duplicates
                # if the placeholder file ever ships with these
                # attributes.
                attrs = re.sub(
                    r'\s+data-(card-style|easing|photo-filter|loading-mode|density|header-align|hero-layout|cursor-mode|scroll-progress|nav-style|chatbot-placement|page-mode|page-id|page-slug|page-section-ids|initial-section)\s*=\s*"[^"]*"',
                    "",
                    attrs,
                )
                return f"<html{attrs}{html_attrs}>"

            html_content = re.sub(
                r'<html([^>]*)>',
                _merge_html_attrs,
                html_content,
                count=1,
            )

            # Server-side hero branching for first paint (Task #63 / item 16):
            # swap the entire <section id="section-hero">…</section> in the
            # static index.html with the per-mode fragment so the right DOM
            # ships from the very first byte. Live mode changes use
            # /api/hero-fragment + outerHTML swap (see applyLayoutRhythm).
            try:
                fragment = _render_hero_fragment(hl)
                new_html, n = re.subn(
                    r'<section\b[^>]*\bid="section-hero"[^>]*>.*?</section>',
                    lambda m: fragment,
                    html_content,
                    count=1,
                    flags=re.DOTALL,
                )
                if n:
                    html_content = new_html
            except Exception as e:
                print(f"[serve_index] hero fragment swap failed: {e}; continuing")
        except Exception as e:
            print(f"[serve_index] body brand-class injection failed: {e}; serving without")

        # Inject loading-screen initials + site name so the boot overlay
        # never shows the literal placeholders "CS" / "Loading" before the
        # API responds. Same disk/db dual-path: prefer the placeholder,
        # otherwise rewrite the badge text in place via a tight regex
        # scoped to the loading badge / loading site-name elements.
        initials, site_name = _build_loading_initials_and_name()
        if "<!-- LOADING_INITIALS_INJECT -->" in html_content:
            html_content = html_content.replace(
                "<!-- LOADING_INITIALS_INJECT -->", initials
            )
        else:
            html_content = re.sub(
                r'(<[^>]+id="loading-logo-badge"[^>]*>)[^<]*(</)',
                lambda m: m.group(1) + initials + m.group(2),
                html_content, count=1,
            )
        if "<!-- LOADING_NAME_INJECT -->" in html_content:
            html_content = html_content.replace(
                "<!-- LOADING_NAME_INJECT -->", site_name
            )
        else:
            html_content = re.sub(
                r'(<[^>]+id="loading-site-name"[^>]*>)[^<]*(</)',
                lambda m: m.group(1) + site_name + m.group(2),
                html_content, count=1,
            )

        # Inject the minified JS bundle <script> tag in place of the
        # original two `<script src="/script.js">` and `<script src="/voice.js">`
        # tags. Same disk/db dual-path as the other inject blocks above:
        # the disk template carries the explicit placeholder; admin-saved
        # designs in site_designs predate it and still inline the original
        # two script tags, so we fall back to a regex rewrite that swaps
        # the first `<script src="/script.js"></script>` for the bundle
        # tag and removes any subsequent `<script src="/voice.js"></script>`.
        # Any failure here is non-fatal — the served HTML still carries
        # working JS via the original two tags (or in the placeholder
        # path, the homepage gracefully degrades to no JS, which is
        # surfaced loudly by tests rather than silently in prod).
        try:
            bundle_tag = asset_bundle.bundle_script_tag()
            if "<!-- JS_BUNDLE_INJECT -->" in html_content:
                html_content = html_content.replace(
                    "<!-- JS_BUNDLE_INJECT -->", bundle_tag, 1
                )
            else:
                # Tolerant regex: matches `<script src="/script.js">` AND
                # `<script defer src="/script.js" type="text/javascript">`
                # AND single-quote / whitespace-around-= / cache-bust
                # query-string variants. Admin-saved designs in
                # site_designs may carry any of these — staying brittle
                # would silently skip the optimisation for those designs.
                script_re = re.compile(
                    r'<script\b[^>]*\bsrc\s*=\s*["\']\/script\.js(?:\?[^"\']*)?["\'][^>]*>\s*</script>',
                    re.IGNORECASE,
                )
                voice_re = re.compile(
                    r'<script\b[^>]*\bsrc\s*=\s*["\']\/voice\.js(?:\?[^"\']*)?["\'][^>]*>\s*</script>',
                    re.IGNORECASE,
                )
                if script_re.search(html_content):
                    html_content = script_re.sub(bundle_tag, html_content, count=1)
                    html_content = voice_re.sub("", html_content, count=1)
                elif voice_re.search(html_content):
                    html_content = voice_re.sub(bundle_tag, html_content, count=1)
        except Exception as e:
            print(f"[serve_index] JS bundle injection failed: {e}; falling back to source files")

        # Standalone-page section filter (Task #71). For /p/<slug>, every
        # built-in section that ISN'T in the page's assignment list gets
        # an inline `display: none` baked into its <section> tag so the
        # user never sees those sections flash before script.js runs its
        # standalone-mode filter. Custom sections aren't in this HTML
        # at all (they're rendered by JS into a container) so the
        # client-side filter handles them.
        if page is not None:
            try:
                assigned = set(int(x) for x in (section_ids or []))
                builtins = query_db(
                    "SELECT id, slug FROM page_sections WHERE section_type = 'built_in'"
                ) or []
                for s in builtins:
                    if s["id"] in assigned:
                        continue
                    # The footer is the only built-in whose DOM id breaks
                    # the section-<slug> convention (it's #site-footer, an
                    # historical artefact). Map it explicitly so it gets
                    # pre-hidden too — otherwise standalone pages flash a
                    # full footer before the JS filter runs.
                    if s["slug"] == "footer":
                        sid = "site-footer"
                        tag_name = "footer"
                    else:
                        sid = f'section-{s["slug"]}'
                        tag_name = "section"
                    # Tag every <section ... id="section-<slug>" ...> with
                    # display:none. Two regexes cover both cases: an
                    # existing style="..." attribute we prepend into, and
                    # a section with no style attribute at all (we add
                    # one). The pattern intentionally tolerates other
                    # attributes between id="..." and style="...". For
                    # the footer the tag is <footer> instead of
                    # <section> — handled by the tag_name set above.
                    pattern_with_style = re.compile(
                        r'(<' + tag_name + r'\b[^>]*\bid="' + re.escape(sid) + r'"[^>]*\bstyle=")',
                        re.IGNORECASE,
                    )
                    if pattern_with_style.search(html_content):
                        html_content = pattern_with_style.sub(
                            r'\1display: none !important; ',
                            html_content, count=1,
                        )
                    else:
                        pattern_no_style = re.compile(
                            r'(<' + tag_name + r'\b[^>]*\bid="' + re.escape(sid) + r'")',
                            re.IGNORECASE,
                        )
                        html_content = pattern_no_style.sub(
                            r'\1 style="display: none !important;"',
                            html_content, count=1,
                        )
            except Exception as e:
                print(f"[_render_app_shell_response] standalone-page pre-hide failed: {e}; continuing")

        # The HTML embeds the content-fingerprinted JS bundle <script> tag.
        # If the browser caches this HTML, a reload keeps serving the OLD
        # bundle URL even after a deploy/restart changes the bundle — so the
        # visitor never gets new front-end code. Force revalidation on every
        # load (the bundle itself stays forever-cacheable via its hashed URL),
        # so a single refresh always fetches the latest bundle.
        # Embed widget mode: when served at /embed/concierge with a VALID key,
        # inject the key + a tiny fetch wrapper so the concierge's SAME-ORIGIN
        # /api/* calls carry X-Embed-Key. This ties the embedded session to its
        # key (validated by _embed_auth) so the embed key control model applies
        # to the iframe flow. The homepage at "/" passes embed_key=None and so
        # injects nothing — it stays keyless / first-party (behavior unchanged).
        # Best-effort: any failure leaves the page working without the header.
        if embed_key:
            try:
                safe_key = json.dumps(str(embed_key))
                inject = (
                    "<script>(function(){"
                    "window.__AAP_EMBED_KEY__=" + safe_key + ";"
                    "var k=window.__AAP_EMBED_KEY__;"
                    "if(!k||!window.fetch)return;"
                    "var _f=window.fetch;"
                    "window.fetch=function(input,init){try{"
                    "var u=(typeof input===\"string\")?input:((input&&input.url)||\"\");"
                    "var api=(u.indexOf(\"/api/\")===0)||"
                    "(u.indexOf(location.origin+\"/api/\")===0);"
                    "if(api){init=init||{};"
                    "var h=new Headers((init&&init.headers)||"
                    "((typeof input!==\"string\"&&input&&input.headers)||{}));"
                    "if(!h.has(\"X-Embed-Key\"))h.set(\"X-Embed-Key\",k);"
                    "init.headers=h;}}catch(e){}"
                    "return _f.call(this,input,init);};"
                    "})();</script>"
                )
                if "</head>" in html_content:
                    html_content = html_content.replace(
                        "</head>", inject + "\n</head>", 1)
                else:
                    html_content = inject + html_content
            except Exception as e:
                print(f"[serve_index] embed key injection failed: {e}; continuing")

        resp = Response(html_content, mimetype="text/html")
        resp.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
        return resp
    except Exception:
        # Last-resort fallback: serve the raw file if everything else fails.
        return send_from_directory("public", "index.html")


# =============================================================
# PUBLIC BLOG PAGE — Individual blog post pages
# =============================================================

@app.route("/blog/<string:slug>")
def serve_blog_post(slug):
    """
    GET /blog/<slug>
    Serves a standalone blog post page with the same dark theme and
    frosted glass aesthetic as the main site. Injects SEO meta tags
    (seo_title, seo_description, cover_image as og:image) for each post.
    Returns 404 if the post doesn't exist or isn't published.
    """
    # Fetch the blog post by slug — only published posts are visible
    post = query_db(
        "SELECT * FROM blog_posts WHERE slug = %s AND status = 'published'",
        (slug,), fetchone=True
    )
    if not post:
        return "Post not found", 404

    # Fetch site settings for branding (site name, theme colors, etc.)
    settings = query_db("SELECT * FROM site_settings WHERE id = 1", fetchone=True) or {}

    # Build theme colors dict for the blog post template (mirrors chat theme injection)
    theme_colors = {
        "bg": settings.get("theme_bg", "#060b14") or "#060b14",
        "accent": settings.get("theme_accent", "#c9a96e") or "#c9a96e",
        "text": settings.get("theme_text", "#e4e4e7") or "#e4e4e7",
        "glass_bg": settings.get("theme_glass_bg", "rgba(255,255,255,0.03)") or "rgba(255,255,255,0.03)",
        "glass_border": settings.get("theme_glass_border", "rgba(255,255,255,0.08)") or "rgba(255,255,255,0.08)",
        "font_serif": settings.get("theme_font_serif", "Playfair Display") or "Playfair Display",
        "font_sans": settings.get("theme_font_sans", "DM Sans") or "DM Sans",
    }

    return render_template(
        "blog_post.html",
        post=post,
        settings=settings,
        theme=theme_colors
    )


# =============================================================
# PUBLIC EVENT PAGE — Individual event detail pages
# =============================================================

@app.route("/event/<string:slug>")
def serve_event_page(slug):
    """
    GET /event/<slug>
    Serves a standalone event page with the same dark theme + frosted
    glass aesthetic as the rest of the public site, including SEO meta
    tags and a built-in RSVP form (when capacity isn't already full).
    Returns 404 if the event is missing or in draft status.
    """
    event = query_db(
        """SELECT e.*,
                  COALESCE((SELECT SUM(guests) FROM event_rsvps r
                            WHERE r.event_id = e.id
                              AND r.payment_status NOT IN ('expired','failed')), 0)::int AS rsvp_count
           FROM events e
           WHERE e.slug = %s AND e.status IN ('published', 'cancelled')""",
        (slug,), fetchone=True
    )
    if not event:
        return "Event not found", 404

    settings = query_db("SELECT * FROM site_settings WHERE id = 1", fetchone=True) or {}
    theme_colors = {
        "bg": settings.get("theme_bg", "#060b14") or "#060b14",
        "accent": settings.get("theme_accent", "#c9a96e") or "#c9a96e",
        "text": settings.get("theme_text", "#e4e4e7") or "#e4e4e7",
        "glass_bg": settings.get("theme_glass_bg", "rgba(255,255,255,0.03)") or "rgba(255,255,255,0.03)",
        "glass_border": settings.get("theme_glass_border", "rgba(255,255,255,0.08)") or "rgba(255,255,255,0.08)",
        "font_serif": settings.get("theme_font_serif", "Playfair Display") or "Playfair Display",
        "font_sans": settings.get("theme_font_sans", "DM Sans") or "DM Sans",
    }
    return render_template(
        "event.html",
        event=event,
        settings=settings,
        theme=theme_colors
    )


# =============================================================
# PUBLIC PRETTY-URL SECTION ROUTES (Task #67)
# =============================================================
#
# Mirrors the JS BUILTIN_SECTION_MAP in public/script.js (~L1513).
# Mapping must stay in sync — the section route below uses these to
# translate the URL slug into the DOM id that script.js scrolls to.
# Keys are the `slug` column values seeded in init_db (~L2972 onward);
# values are the corresponding `<section id="...">` ids in
# public/index.html. Custom sections (section_type == 'custom') don't
# appear here — they always resolve to "section-custom-<id>".
BUILTIN_SECTION_DOM_ID = {
    "hero":           "section-hero",
    "highlights":     "section-highlights",
    "experiences":    "section-experiences",
    "testimonials":   "section-testimonials",
    "team":           "section-team",
    "faq":            "section-faq",
    "blog":           "section-blog",
    "events":         "section-events",
    "business-info":  "section-business-info",
    "video-gallery":  "section-video-gallery",
    "podcast":        "section-podcast",
    "store":          "section-store",
    "services":       "section-services",
    # Footer is intentionally excluded — it isn't a navigable section,
    # it's the page chrome at the bottom. /footer should 404.
}


def _resolve_section_dom_id(section_row):
    """Translate a page_sections row into the DOM id script.js will scroll to.

    Returns None for rows that have no scrollable target (footer, or a
    built-in slug we don't have a DOM mapping for). Custom sections
    always resolve to `section-custom-<id>` to match the id naming used
    by applySectionOrder() in public/script.js.
    """
    if not section_row:
        return None
    stype = (section_row.get("section_type") or "").strip()
    slug = (section_row.get("slug") or "").strip()
    if stype == "built_in":
        return BUILTIN_SECTION_DOM_ID.get(slug)
    if stype == "custom":
        sid = section_row.get("id")
        if sid is None:
            return None
        return f"section-custom-{int(sid)}"
    return None


@app.route("/<section_slug>")
def serve_section(section_slug):
    """
    GET /<section_slug>

    Pretty per-section URL that serves the homepage shell with a deep
    link to the matching section anchor.

    Behaviour matrix:
      - slug exists + enabled + has DOM mapping → 200 homepage with
        data-initial-section pinned on <html>
      - slug exists + DISABLED → 302 redirect to "/" (visitors don't
        see a broken hidden anchor)
      - slug exists but isn't navigable (footer) → 404
      - slug is UNKNOWN → falls through to serve_static, which tries
        the file on disk and (per the existing SPA convention in
        serve_static) returns the homepage HTML 200 if no file
        matches. This is intentional so existing legitimate asset
        requests like /styles.css and /favicon.ico keep resolving and
        random URLs get the same SPA fallback they always did.

    Why fall through instead of an immediate 404: Flask's URL converter
    ranking puts our `string` slug rule ahead of the catch-all
    `<path:filename>` for single-segment requests, so /styles.css would
    otherwise hit this handler before serve_static gets a chance.

    On match we call serve_index(initial_section_dom_id=<dom id>) so
    public/script.js's _scrollToHashOnLoad sees the
    `data-initial-section` attribute on <html> and snaps the viewport
    to the right section on first paint without polluting the URL with
    a #hash.
    """
    # Cheap pre-filter: a slug never contains a dot. Anything dotted is
    # either a static asset (foo.css) or a robots.txt-style probe — let
    # serve_static handle it so this route stays focused on real slugs.
    if "." in section_slug or "/" in section_slug:
        return serve_static(section_slug)

    # Reserved single-segment routes that already exist on this app —
    # these are registered with their own @app.route decorators
    # elsewhere, so Werkzeug routes them directly and they never hit
    # serve_section. Listed here purely as documentation: /admin,
    # /setup, /healthz, /robots.txt, /sitemap.xml.

    try:
        row = query_db(
            "SELECT id, slug, section_type, enabled, "
            "seo_title, seo_description, seo_image "
            "FROM page_sections "
            "WHERE slug = %s",
            (section_slug,),
            fetchone=True,
        )
    except Exception as e:
        # Brand-new install or migration in flight — treat as no-match
        # rather than 500ing on the visitor. The static fallback then
        # takes over so /styles.css etc still works.
        print(f"[serve_section] page_sections lookup failed for {section_slug!r}: {e}")
        return serve_static(section_slug)

    if not row:
        # Slug isn't a known section — could legitimately be a static
        # asset request (e.g. /favicon.ico) or just an unknown URL.
        # Fall through to serve_static so existing SPA-style behaviour
        # (asset → file, anything else → homepage) is preserved.
        return serve_static(section_slug)

    if not row.get("enabled"):
        # The section exists but the admin turned it off. We can't deep
        # link to a hidden anchor (script.js would try to scroll to a
        # display:none element), so redirect to "/" — search engines
        # see the 302 and visitors land on the homepage instead of
        # staring at a broken section. Per Task #67 spec the alternate
        # acceptable behaviour is a 404; redirect was chosen because
        # the section IS still part of the site (just hidden) so a 404
        # is misleading.
        return redirect("/", code=302)

    dom_id = _resolve_section_dom_id(row)
    if not dom_id:
        # Section exists and is enabled but isn't navigable (footer
        # is the only built-in slug that hits this branch). 404 is
        # the right answer — there's nothing to deep-link TO.
        return ("Section not found", 404)

    # Per-section SEO overrides (Task #69). Pull the three nullable
    # columns off the row and pass them to serve_index — _build_seo_meta_html
    # cascades each one to the site-wide settings when empty so unconfigured
    # sections behave exactly as before. We keep the dict around even when
    # every value is empty; that way a partially-configured section
    # (e.g. only seo_title set) still benefits from the override path
    # without us re-doing the per-key emptiness check downstream.
    seo_overrides = {
        "title":       (row.get("seo_title") or "").strip(),
        "description": (row.get("seo_description") or "").strip(),
        "og_image":    (row.get("seo_image") or "").strip(),
    }
    return serve_index(initial_section_dom_id=dom_id, seo_overrides=seo_overrides)


@app.route("/<path:filename>")
def serve_static(filename):
    """
    Serve any static file from the /public directory.
    This handles CSS, JS, images, fonts, etc.
    Falls through to serve_index() if the file doesn't exist (SPA-style fallback).
    """
    try:
        return send_from_directory("public", filename)
    except Exception:
        # SPA fallback — serve the SEO-injected index for unknown paths
        return serve_index()


