def lookup_knowledge_base(query=None, limit=6, **_extra):
    """Visitor KB search (Phase 6 / Epic B). Semantic search over the documents
    the operator uploaded AND scoped to the visitor (audience 'visitor' or
    'both' — admin-only docs are never returned here). Returns excerpts with a
    `source` marker the agent can cite. Empty when no visitor-scoped docs match
    (the agent then just answers without citations). Never raises."""
    q = (query or "").strip()
    if not q:
        return []
    try:
        k = max(1, min(int(limit or 6), 10))
    except Exception:
        k = 6
    try:
        chunks = rag.retrieve(q, tenant_id=current_tenant_id(), top_k=k,
                              session_id="visitor_kb", surface="visitor") or []
    except Exception as e:
        print(f"[visitor_kb] retrieve failed: {e}")
        return []
    return [
        {
            "source":  c.get("filename") or "document",
            "page":    c.get("page_number"),
            "content": _trim_text(c.get("content_text"), 1200),
            "score":   round(float(c.get("score") or 0.0), 4),
        }
        for c in chunks
    ]


def subscribe_newsletter(email=None, full_name=None, **_extra):
    """Visitor newsletter signup (Phase 6 / Epic D, task 043).

    Adds the visitor's email to the `subscribers` list and returns a
    self-service preferences link. GATED by the 'newsletter_signup_enabled' AI
    Control knob (default OFF, master-switch-aware): when off the tool declines,
    so a fresh fork never silently captures signups.

    Consent-safe: a person who PREVIOUSLY UNSUBSCRIBED is never silently
    re-opted-in — they're handed their preferences link to opt back in
    themselves. Already-subscribed people are a no-op (idempotent). Validates
    the email; never raises (returns a structured {ok, message} the agent
    relays to the visitor)."""
    try:
        if not get_ai_setting("newsletter_signup_enabled"):
            return {"ok": False, "message": "Newsletter signup isn't available right now."}
        addr = (email or "").strip().lower()
        if not _email_re_check(addr):
            return {"ok": False, "message": "I need a valid email address to subscribe you."}
        name = (full_name or "").strip()[:200]
        tid = current_tenant_id()  # noqa: F841 — reserved for when subscribers is tenant-scoped
        existing = query_db(
            "SELECT id, opt_in, unsubscribed_at FROM subscribers "
            "WHERE LOWER(email)=%s LIMIT 1", (addr,), fetchone=True)
        if existing:
            sid = existing["id"]
            # Respect a prior opt-out: do NOT flip them back on automatically.
            if existing.get("unsubscribed_at") or not existing.get("opt_in"):
                return {
                    "ok": True, "already": True, "resubscribe": True,
                    "manage_url": _prefs_url(sid),
                    "message": ("It looks like you previously unsubscribed. You can "
                                "re-subscribe and manage your preferences here: "
                                + _prefs_url(sid)),
                }
            return {
                "ok": True, "already": True,
                "manage_url": _prefs_url(sid),
                "message": ("You're already subscribed! You can manage your "
                            "preferences here: " + _prefs_url(sid)),
            }
        row = execute_db(
            "INSERT INTO subscribers (email, full_name, list_name, source, "
            " opt_in, opt_in_email) VALUES (%s,%s,'newsletter','ai_chat',TRUE,TRUE) "
            "RETURNING id", (addr, name))
        sid = row["id"] if row else None
        if not sid:
            return {"ok": False, "message": "Sorry, I couldn't complete the signup just now."}
        return {
            "ok": True, "subscribed": True,
            "manage_url": _prefs_url(sid),
            "message": ("You're subscribed — thank you! You can update or cancel "
                        "your preferences anytime here: " + _prefs_url(sid)),
        }
    except Exception as e:
        print(f"[newsletter] subscribe failed: {type(e).__name__}: {e}")
        return {"ok": False, "message": "Sorry, I couldn't complete the signup just now."}


# Per-process outbound-notify throttle (task 045 hardening). Even though team
# notifications only reach the operator's own address, a public visitor (once
# the knob is on) could drive the LLM to fire many notify_team / capture_lead
# calls per minute — flooding the inbox and, for SMS, running up real cost. We
# cap outbound team notifications per tenant per 60s window. Configurable.
_NOTIFY_RL_LOCK = threading.Lock()
_NOTIFY_RL_HITS = {}   # tenant_id -> list[timestamps within the window]


def _notify_rate_ok(tenant_id):
    """True if another team notification is allowed for this tenant right now.
    Sliding 60s window, cap from TEAM_NOTIFY_MAX_PER_MIN (default 10)."""
    try:
        cap = max(1, int(os.environ.get("TEAM_NOTIFY_MAX_PER_MIN", "10") or 10))
    except (TypeError, ValueError):
        cap = 10
    now = _time.time()
    with _NOTIFY_RL_LOCK:
        hits = [t for t in _NOTIFY_RL_HITS.get(tenant_id, []) if now - t < 60.0]
        if len(hits) >= cap:
            _NOTIFY_RL_HITS[tenant_id] = hits
            return False
        hits.append(now)
        _NOTIFY_RL_HITS[tenant_id] = hits
        return True


# Current visitor turn's conversation context (task 048). Set by the visitor
# loop around tool dispatch so context-aware tools (request_callback) can build
# an AI handoff summary, WITHOUT threading it through every tool signature.
# A ContextVar is per-execution-context so concurrent requests stay isolated;
# it's None outside a visitor turn (e.g. admin calls, tests) → summary skipped.
_CHAT_TURN_CTX = contextvars.ContextVar("chat_turn_ctx", default=None)


def _set_chat_turn_ctx(history, message, visitor_id=""):
    """Stash the current turn's context; returns the token to reset with."""
    return _CHAT_TURN_CTX.set({
        "history": history or [],
        "message": message or "",
        "visitor_id": visitor_id or "",
    })


def _handoff_summary(model=None):
    """Generate a short AI summary of the CURRENT chat turn's conversation for a
    team handoff. Reads the turn context (_CHAT_TURN_CTX); returns "" when there's
    no context or on any failure (fail-open — never blocks the callback)."""
    ctx = _CHAT_TURN_CTX.get()
    if not ctx or not openai_client:
        return ""
    try:
        mdl = (model or "").strip() or "gpt-4o-mini"
        if mdl.lower().startswith("claude"):
            mdl = "gpt-4o-mini"
        # Build a compact transcript from recent history + the latest message.
        lines = []
        for h in (ctx.get("history") or [])[-12:]:
            role = "Visitor" if (h.get("role") != "agent") else "Concierge"
            txt = (h.get("content") or "").strip()
            if txt:
                lines.append(f"{role}: {txt}")
        if ctx.get("message"):
            lines.append(f"Visitor: {ctx['message']}")
        transcript = "\n".join(lines)[:6000]
        if not transcript:
            return ""
        resp = openai_client.with_options(timeout=15.0).chat.completions.create(
            model=mdl, max_tokens=180, temperature=0.2,
            messages=[
                {"role": "system", "content": (
                    "Summarize this website chat for a teammate who will call the "
                    "visitor back. 2-3 sentences: what they want, any specifics "
                    "(dates, budget, product), and how urgent it seems. No preamble.")},
                {"role": "user", "content": transcript},
            ])
        try:
            record_chat_cost_from_response(
                resp, surface="visitor_chat", provider="openai", model=mdl)
        except Exception:
            pass
        return (resp.choices[0].message.content or "").strip()[:2000]
    except Exception as e:
        print(f"[handoff] summary failed: {type(e).__name__}: {e}")
        return ""


def _notify_team(subject, message_text):
    """Send a team notification to the OPERATOR-configured destination(s) only
    (task 045). The recipient is NEVER taken from the visitor/agent — only the
    team_notify_email / team_notify_sms settings — so this can't be abused to
    message arbitrary third parties. Returns (sent_any, channels). Fail-open:
    a provider error on one channel is logged and skipped, never raised."""
    channels = []
    if not get_ai_setting("team_notifications_enabled"):
        return False, channels
    # Throttle outbound volume per tenant (inbox-flood / SMS-cost protection).
    if not _notify_rate_ok(current_tenant_id()):
        print("[notify_team] rate limit hit — skipping outbound notification")
        return False, channels
    subject = (subject or "AI concierge notification").strip()[:200]
    body = (message_text or "").strip()[:4000]
    email_to = (get_ai_setting("team_notify_email") or "").strip()
    sms_to = (get_ai_setting("team_notify_sms") or "").strip()
    if email_to:
        try:
            html_body = (
                '<div style="font-family:Arial,sans-serif">'
                f'<p>{html_module.escape(body).replace(chr(10), "<br>")}</p>'
                '<hr><p style="font-size:12px;color:#6b7280">'
                'Sent by your AI concierge.</p></div>'
            )
            messaging.send_email(email_to, subject, html_body, text_body=body)
            channels.append("email")
        except Exception as e:
            print(f"[notify_team] email failed: {type(e).__name__}: {e}")
    if sms_to:
        try:
            messaging.send_sms(sms_to, f"{subject}: {body}"[:600])
            channels.append("sms")
        except Exception as e:
            print(f"[notify_team] sms failed: {type(e).__name__}: {e}")
    return bool(channels), channels


def capture_lead(name=None, email=None, phone=None, interest=None, message=None, **_extra):
    """Capture a sales lead the visitor provides (Phase 6 / Epic D, task 045).
    GATED by 'lead_capture_enabled' (default OFF, master-switch-aware). Needs at
    least an email or phone. Stores the visitor's own contact details (operator
    sales data) and optionally notifies the team. Never raises."""
    try:
        if not get_ai_setting("lead_capture_enabled"):
            return {"ok": False, "message": "Lead capture isn't available right now."}
        nm = (name or "").strip()[:200]
        em = (email or "").strip().lower()[:320]
        ph = (phone or "").strip()[:50]
        if not em and not ph:
            return {"ok": False, "message": "I need at least an email or phone number to save your details."}
        if em and not _email_re_check(em):
            return {"ok": False, "message": "That email doesn't look valid — could you double-check it?"}
        row = execute_db(
            "INSERT INTO leads (tenant_id, name, email, phone, interest, message, source) "
            "VALUES (%s,%s,%s,%s,%s,%s,'ai_chat') RETURNING id",
            (current_tenant_id(), nm, em, ph, (interest or "").strip()[:300],
             (message or "").strip()[:4000]))
        if not row:
            return {"ok": False, "message": "Sorry, I couldn't save your details just now."}
        # Best-effort team notification (its own gate; never blocks the capture).
        try:
            summary = (f"New lead captured:\nName: {nm or '-'}\nEmail: {em or '-'}\n"
                       f"Phone: {ph or '-'}\nInterest: {(interest or '-')}\n"
                       f"Message: {(message or '-')}")
            _notify_team("New lead from your AI concierge", summary)
        except Exception:
            pass
        return {"ok": True, "message": "Thanks — I've passed your details to the team. They'll be in touch."}
    except Exception as e:
        print(f"[capture_lead] failed: {type(e).__name__}: {e}")
        return {"ok": False, "message": "Sorry, I couldn't save your details just now."}


def request_callback(name=None, phone=None, preferred_time=None, reason=None, **_extra):
    """Log a callback request (Phase 6 / Epic D, task 045). GATED by
    'callback_requests_enabled' (default OFF, master-switch-aware). Needs a
    phone number. Optionally notifies the team. Never raises."""
    try:
        if not get_ai_setting("callback_requests_enabled"):
            return {"ok": False, "message": "Callback requests aren't available right now."}
        nm = (name or "").strip()[:200]
        ph = (phone or "").strip()[:50]
        if not ph:
            return {"ok": False, "message": "I need a phone number to arrange a callback."}
        when = (preferred_time or "").strip()[:200]
        why = (reason or "").strip()[:2000]
        # Task 048: optional AI handoff summary of the conversation so the team
        # has context before calling back. Gated; fail-open to "".
        ai_summary = ""
        if get_ai_setting("handoff_summary_enabled"):
            ai_summary = _handoff_summary(get_ai_setting("handoff_summary_model"))
        row = execute_db(
            "INSERT INTO callback_requests (tenant_id, name, phone, preferred_time, "
            " reason, ai_summary) VALUES (%s,%s,%s,%s,%s,%s) RETURNING id",
            (current_tenant_id(), nm, ph, when, why, ai_summary))
        if not row:
            return {"ok": False, "message": "Sorry, I couldn't log your callback request just now."}
        try:
            summary = (f"Callback requested:\nName: {nm or '-'}\nPhone: {ph}\n"
                       f"Preferred time: {when or '-'}\nReason: {why or '-'}")
            if ai_summary:
                summary += f"\n\nAI summary of the chat:\n{ai_summary}"
            _notify_team("Callback request from your AI concierge", summary)
        except Exception:
            pass
        return {"ok": True, "message": "Got it — I've asked the team to call you back. Thanks!"}
    except Exception as e:
        print(f"[request_callback] failed: {type(e).__name__}: {e}")
        return {"ok": False, "message": "Sorry, I couldn't log your callback request just now."}


def _normalize_meeting_time(requested_time, start_iso=None):
    """Return a valid ISO 8601 / RFC 3339 timestamp for the calendar, or "".

    Primary path: the model supplies `start_iso` (it can compute it from the
    visitor's phrasing + today's date); we VALIDATE it parses before trusting
    it — never send unvalidated text to a calendar API. Fallback: best-effort
    parse of the free-text `requested_time` via python-dateutil IF it's
    installed (optional dep). Anything we can't validate → "" (store-only)."""
    from datetime import datetime as _dt
    cand = (start_iso or "").strip()
    if cand:
        try:
            _dt.fromisoformat(cand.replace("Z", "+00:00"))
            return cand  # valid — keep the model's original (offset/Z preserved)
        except Exception:
            pass
    txt = (requested_time or "").strip()
    if txt:
        try:
            from dateutil import parser as _dup  # optional; absent → skip
            return _dup.parse(txt).isoformat()
        except Exception:
            pass
    return ""


def _meeting_calendar_push(name, email, start_iso, duration_minutes, notes):
    """OPTIONAL live calendar push (task 047). When a Calendar MCP server is
    configured (meeting_calendar_mcp_server), call its create-event tool with a
    VALIDATED ISO start and return the created event id. Fail-open: returns ""
    when no server is configured, no valid start, the server isn't found, or the
    call errors — the booking is still recorded as 'requested'.

    OPERATOR RUNBOOK: connect a Calendar MCP server in the Connectors tab whose
    create-event tool accepts {summary, start, duration_minutes, attendee_email,
    description} (start is RFC 3339), then set meeting_calendar_mcp_server (+
    optionally meeting_calendar_tool) in AI Control."""
    server_name = (get_ai_setting("meeting_calendar_mcp_server") or "").strip()
    if not server_name or not (start_iso or "").strip():
        return ""
    tool = (get_ai_setting("meeting_calendar_tool") or "").strip() or "create_event"
    try:
        server = query_db(
            "SELECT * FROM mcp_servers WHERE name=%s AND enabled=TRUE",
            (server_name,), fetchone=True)
        if not server:
            print(f"[book_meeting] calendar MCP '{server_name}' not found/enabled — store-only")
            return ""
        result, err = _mcp_call_tool(server, tool, {
            "summary": f"Meeting with {name or email or 'website visitor'}",
            "start": start_iso,
            "duration_minutes": duration_minutes,
            "attendee_email": email,
            "description": notes or "",
        })
        if err or not isinstance(result, dict):
            print(f"[book_meeting] calendar push failed: {err}")
            return ""
        # Best-effort id extraction from common shapes.
        ev = result.get("structuredContent") or {}
        eid = (ev.get("id") or ev.get("event_id") or result.get("id") or "")
        return str(eid)[:200]
    except Exception as e:
        print(f"[book_meeting] calendar push error: {type(e).__name__}: {e}")
        return ""


def book_meeting(name=None, email=None, requested_time=None, start_iso=None,
                 notes=None, duration_minutes=None, phone=None, **_extra):
    """Book / request a meeting the visitor wants (Phase 6 / Epic F, task 047).
    GATED by 'meetings_enabled' (default OFF, master-switch-aware). Needs an
    email and a requested time. Records the request; if a Calendar MCP server is
    configured AND we have a valid ISO start time it also creates a real event
    (status → 'booked'), else stores it as 'requested' for the team. Optionally
    notifies the team. Never raises.

    `requested_time` is the visitor's phrasing (kept for display); `start_iso`
    is the RFC 3339 timestamp the model computes from it — validated before any
    calendar push so we never send a calendar API free text (task 051)."""
    try:
        if not get_ai_setting("meetings_enabled"):
            return {"ok": False, "message": "Meeting booking isn't available right now."}
        nm = (name or "").strip()[:200]
        em = (email or "").strip().lower()[:320]
        when = (requested_time or "").strip()[:200]
        if not em or not _email_re_check(em):
            return {"ok": False, "message": "I need a valid email address to book a meeting."}
        if not when:
            return {"ok": False, "message": "What date and time would you like to meet?"}
        try:
            dur = int(duration_minutes) if duration_minutes else int(
                get_ai_setting("meeting_default_duration_minutes") or 30)
        except (TypeError, ValueError):
            dur = 30
        dur = max(5, min(dur, 480))
        ph = (phone or "").strip()[:50]
        nt = (notes or "").strip()[:2000]
        iso = _normalize_meeting_time(when, start_iso)[:64]
        # Optional live calendar event (fail-open to store-only; only with a
        # valid ISO start so we never push free text to a calendar API).
        event_id = _meeting_calendar_push(nm, em, iso, dur, nt)
        status = "booked" if event_id else "requested"
        row = execute_db(
            "INSERT INTO meetings (tenant_id, name, email, phone, requested_time, "
            " start_iso, duration_minutes, notes, status, calendar_event_id) "
            "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING id",
            (current_tenant_id(), nm, em, ph, when, iso, dur, nt, status, event_id))
        if not row:
            return {"ok": False, "message": "Sorry, I couldn't book that just now."}
        try:
            summary = (f"Meeting {status}:\nName: {nm or '-'}\nEmail: {em}\n"
                       f"Requested time: {when}\nDuration: {dur} min\nNotes: {nt or '-'}")
            _notify_team(f"Meeting {status} via your AI concierge", summary)
        except Exception:
            pass
        if status == "booked":
            return {"ok": True, "booked": True,
                    "message": f"You're booked for {when}. A calendar invite is on its way to {em}."}
        return {"ok": True, "requested": True,
                "message": f"Thanks — I've sent your meeting request for {when} to the team; they'll confirm shortly."}
    except Exception as e:
        print(f"[book_meeting] failed: {type(e).__name__}: {e}")
        return {"ok": False, "message": "Sorry, I couldn't book that just now."}


def notify_team(subject=None, message=None, **_extra):
    """Send a notification to the business's own team (Phase 6 / Epic D, task
    045). GATED by 'team_notifications_enabled' (default OFF). The recipient is
    fixed by operator config — the agent supplies only subject + message, so it
    can't message third parties. Use sparingly (genuinely time-sensitive things
    the team should see). Never raises."""
    try:
        if not get_ai_setting("team_notifications_enabled"):
            return {"ok": False, "message": "Team notifications aren't enabled."}
        sent, channels = _notify_team(subject, message)
        if sent:
            return {"ok": True, "message": "I've notified the team.", "channels": channels}
        return {"ok": False, "message": "I couldn't reach the team right now."}
    except Exception as e:
        print(f"[notify_team] failed: {type(e).__name__}: {e}")
        return {"ok": False, "message": "I couldn't reach the team right now."}


def lookup_offers(interest=None, limit=3, **_extra):
    """Surface active promotions/deals the operator defined (Phase 6 / Epic D,
    task 044). GATED by the 'offers_enabled' AI Control knob (default OFF,
    master-switch-aware): returns [] when off, so nothing is ever surfaced
    unless a super-admin opts in AND has live offers.

    Only returns offers that are active and within their optional
    starts_at/ends_at window. `interest` (a topic the visitor cares about)
    biases toward offers whose trigger_tags match — but offers with NO tags
    are always eligible (general promos). Highest priority first. Never raises."""
    try:
        if not get_ai_setting("offers_enabled"):
            return []
        try:
            k = max(1, min(int(limit or 3), 10))
        except Exception:
            k = 3
        tid = current_tenant_id()
        rows = query_db(
            "SELECT id, title, description, code, cta_url, trigger_tags, priority "
            "FROM offers WHERE tenant_id=%s AND active=TRUE "
            "  AND (starts_at IS NULL OR starts_at <= NOW()) "
            "  AND (ends_at   IS NULL OR ends_at   >= NOW()) "
            "ORDER BY priority DESC, id DESC", (tid,)) or []
        want = (interest or "").strip().lower()
        scored = []
        for r in rows:
            tags = [str(t).strip().lower() for t in _vp_as_list(r.get("trigger_tags"))]
            matched = bool(tags) and bool(want) and any(
                want in t or t in want for t in tags)
            # A TAGGED offer is shown only when the visitor's interest matches a
            # tag. An UNTAGGED (general) offer is always eligible. When no
            # interest is given we surface everything active.
            if tags and want and not matched:
                continue
            scored.append({
                "title": r.get("title"),
                "description": _trim_text(r.get("description"), 600),
                "code": r.get("code") or None,
                "url": r.get("cta_url") or None,
                "_targeted": matched,
                "_priority": int(r.get("priority") or 0),
            })
        # Targeted offers first, then by priority; strip internal sort keys.
        scored.sort(key=lambda o: (o["_targeted"], o["_priority"]), reverse=True)
        out = []
        for o in scored[:k]:
            o.pop("_targeted", None)
            o.pop("_priority", None)
            out.append(o)
        return out
    except Exception as e:
        print(f"[offers] lookup failed: {type(e).__name__}: {e}")
        return []


def lookup_testimonials(query=None, min_rating=None, limit=5):
    """Customer reviews / testimonials. Useful for social proof."""
    sql = (
        "SELECT reviewer_name, reviewer_role, content, rating "
        "FROM testimonials WHERE 1=1"
    )
    params = []
    if min_rating:
        sql += " AND rating >= %s"
        params.append(int(min_rating))
    if query:
        sql += " AND (content ILIKE %s OR reviewer_name ILIKE %s)"
        q = f"%{query}%"
        params.extend([q, q])
    sql += " ORDER BY sort_order ASC LIMIT %s"
    params.append(max(1, min(int(limit or 5), 30)))
    rows = query_db(sql, tuple(params)) or []
    return [
        {
            "reviewer": r["reviewer_name"],
            "role": r.get("reviewer_role"),
            "content": _trim_text(r.get("content"), 500),
            "rating": r.get("rating"),
        }
        for r in rows
    ]


def lookup_business_info():
    """Business contact details, address, and weekly hours."""
    biz = query_db(
        "SELECT business_phone, business_email, business_address, "
        "business_hours FROM site_settings WHERE id = 1",
        fetchone=True,
    )
    if not biz:
        return {}
    out = {
        "phone": biz.get("business_phone") or None,
        "email": biz.get("business_email") or None,
        "address": biz.get("business_address") or None,
    }
    hours = biz.get("business_hours")
    if hours and isinstance(hours, list):
        out["hours"] = [
            {"day": h.get("day"), "open": h.get("open"), "close": h.get("close")}
            for h in hours
            if h.get("day")
        ]
    return out


def lookup_custom_section_items(section_slug=None, section_id=None):
    """Items inside an admin-created custom section (cards_grid,
    stats_counter, icon_features, etc.)."""
    base_sql = (
        "SELECT csi.title, csi.subtitle, csi.content, csi.image_url, "
        "csi.link_url, csi.link_text, csi.icon, ps.slug as section_slug, "
        "ps.title as section_title, ps.template "
        "FROM custom_section_items csi "
        "JOIN page_sections ps ON ps.id = csi.section_id "
        "WHERE ps.enabled = TRUE"
    )
    if section_id:
        rows = query_db(
            base_sql + " AND ps.id = %s ORDER BY csi.sort_order ASC",
            (int(section_id),),
        ) or []
    elif section_slug:
        rows = query_db(
            base_sql + " AND ps.slug = %s ORDER BY csi.sort_order ASC",
            (section_slug,),
        ) or []
    else:
        return []
    return [
        {
            "title": r.get("title"),
            "subtitle": _trim_text(r.get("subtitle"), 200),
            "content": _trim_text(r.get("content"), 600),
            "icon": r.get("icon"),
            "image_url": r.get("image_url") or None,
            "link_url": r.get("link_url") or None,
            "link_text": r.get("link_text") or None,
        }
        for r in rows
    ]


def lookup_generated_page(slug=None, topic=None, limit=5):
    """Look up saved AI-generated pages (published or draft).

    Two modes:
      • slug  — exact match on a known slug, returns one row of
                {slug, title, summary, prompt}.
      • topic — full-text search over title+prompt+summary+search_text,
                returns up to `limit` candidate matches with their
                slug + title + summary + ai_score + reuse_count.

    The visitor agent uses topic-mode BEFORE falling back to
    generatePage so a previously-saved page gets reused
    (instant, free) instead of regenerated (slow, costs tokens).
    """
    if slug:
        page = query_db(
            "SELECT slug, title, summary, prompt FROM generated_pages "
            "WHERE slug = %s AND status IN ('published', 'draft')",
            (slug,), fetchone=True,
        )
        return page or {}
    q = (topic or "").strip()
    if not q:
        return {"matches": [], "count": 0}
    try:
        lim = max(1, min(int(limit or 5), 10))
    except Exception:
        lim = 5
    rows = query_db(
        "SELECT id, slug, title, summary, ai_score, reuse_count "
        "FROM generated_pages "
        "WHERE status IN ('published', 'draft') AND "
        "      to_tsvector('english', "
        "          coalesce(title,'') || ' ' || "
        "          coalesce(prompt,'') || ' ' || "
        "          coalesce(summary,'') || ' ' || "
        "          coalesce(search_text,'')) "
        "      @@ plainto_tsquery('english', %s) "
        "ORDER BY ai_score DESC, reuse_count DESC, updated_at DESC "
        "LIMIT %s",
        (q[:200], lim),
    ) or []
    return {
        "matches": [
            {"slug": r.get("slug") or "",
             "title": r.get("title") or "",
             "summary": (r.get("summary") or "")[:280],
             "ai_score": int(r.get("ai_score") or 0),
             "reuse_count": int(r.get("reuse_count") or 0)}
            for r in rows
        ],
        "count": len(rows),
    }


def _resolve_presentation_slug(slug):
    """Resolve a slug string to one enabled presentation row, with a
    graceful fuzzy fallback. The visitor agent occasionally emits an
    abbreviated slug — e.g. it sees a deck titled 'Thetasync Deck'
    (slug 'thetasync-deck') and emits start_presentation with slug
    'thetasync'. Without this helper that 404s and the deck silently
    fails to open. Lookup order:
      1. Exact slug match.
      2. Prefix: slug LIKE '<input>-%' or '<input>%'.
      3. Substring: slug LIKE '%<input>%'.
      4. Title substring (last resort).
    Inputs shorter than 3 chars only do step 1 — '%a%' would match
    almost anything. Returns the row dict or None."""
    s = (slug or "").strip().lower()
    if not s:
        return None
    cols = (
        "id, slug, title, description, cover_image_url, "
        "auto_play, display_mode, ai_narrate_mode, source"
    )
    # 1. Exact slug — return immediately if enabled.
    row = query_db(
        f"SELECT {cols}, enabled FROM presentations "
        "WHERE LOWER(slug) = %s",
        (s,),
        fetchone=True,
    )
    if row:
        if row.get("enabled"):
            row.pop("enabled", None)
            return row
        # Exact slug exists but admin disabled it. Don't silently
        # fuzzy-fall-back to a *different* deck — that would mask a
        # genuine "I disabled this on purpose" admin action and serve
        # the wrong content. Caller (public endpoint) should 404.
        print(f"[presentations] slug '{slug}' exists but is disabled — not fuzzy-falling-back")
        return None
    if len(s) < 3:
        return None
    # Escape LIKE metacharacters in user input so a slug like '50%_off'
    # doesn't accidentally over-broaden the wildcard match.
    esc = s.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    # 2. Prefix — prefer shorter (closer) slugs, then oldest id.
    row = query_db(
        f"SELECT {cols} FROM presentations WHERE enabled = TRUE "
        "  AND (LOWER(slug) LIKE %s ESCAPE '\\' OR LOWER(slug) LIKE %s ESCAPE '\\') "
        "ORDER BY LENGTH(slug) ASC, id ASC LIMIT 1",
        (esc + "-%", esc + "%"),
        fetchone=True,
    )
    if row:
        print(f"[presentations] fuzzy slug '{slug}' → '{row['slug']}' (prefix)")
        return row
    # 3. Substring on slug.
    row = query_db(
        f"SELECT {cols} FROM presentations WHERE enabled = TRUE "
        "  AND LOWER(slug) LIKE %s ESCAPE '\\' "
        "ORDER BY LENGTH(slug) ASC, id ASC LIMIT 1",
        ("%" + esc + "%",),
        fetchone=True,
    )
    if row:
        print(f"[presentations] fuzzy slug '{slug}' → '{row['slug']}' (substring)")
        return row
    # 4. Title substring as last resort.
    row = query_db(
        f"SELECT {cols} FROM presentations WHERE enabled = TRUE "
        "  AND LOWER(title) LIKE %s ESCAPE '\\' "
        "ORDER BY LENGTH(slug) ASC, id ASC LIMIT 1",
        ("%" + esc + "%",),
        fetchone=True,
    )
    if row:
        print(f"[presentations] fuzzy slug '{slug}' → '{row['slug']}' (title)")
    return row


def lookup_presentation(slug=None, query=None, limit=10):
    """Look up an enabled presentation deck. If `slug` is given, returns one
    full deck with all slides (so the AI can decide whether to launch it).
    Otherwise returns a short list of available decks (slug + title +
    description + slide count) for browsing.

    Slug lookup is fuzzy via _resolve_presentation_slug, so an
    abbreviated guess like 'thetasync' resolves to 'thetasync-deck'
    and the AI gets back the canonical slug it should use in the
    follow-up start_presentation command."""
    if slug:
        p = _resolve_presentation_slug(slug)
        if not p:
            return {}
        slides = query_db(
            "SELECT order_index, title, body, image_url, narration_text "
            "FROM presentation_slides WHERE presentation_id = %s "
            "ORDER BY order_index ASC, id ASC",
            (p["id"],),
        ) or []
        # _next_action is an inline nudge to the model. Without it, the
        # visitor agent occasionally calls lookup_presentation, sees the
        # deck data, then exits with an empty reply instead of emitting
        # the launch command — leaving the visitor staring at nothing
        # after they say "yes please". The instruction sits right next to
        # the slug in context, which the model follows much more reliably
        # than the equivalent line in the system prompt.
        canon_slug = p["slug"]
        return {
            "slug": canon_slug,
            "title": p["title"],
            "description": p["description"],
            "auto_play": bool(p["auto_play"]),
            "slide_count": len(slides),
            "slides": [
                {
                    "order_index": s["order_index"],
                    "title": s["title"],
                    "body": s["body"],
                }
                for s in slides
            ],
            "_next_action": (
                "If the visitor has agreed to see this deck (e.g. said "
                "'yes', 'sure', 'go ahead', or it has auto_play=true), "
                "your VERY NEXT reply must include this exact code block "
                "on its own line — using the slug value above:\n"
                "```command\n"
                f'{{"action": "start_presentation", "slug": "{canon_slug}"}}\n'
                "```\n"
                "Do NOT call lookup_presentation again with the same slug "
                "— you already have the deck data."
            ),
        }
    rows = query_db(
        "SELECT slug, title, description, "
        "(SELECT COUNT(*) FROM presentation_slides "
        " WHERE presentation_id = presentations.id) AS slide_count "
        "FROM presentations WHERE enabled = TRUE "
        + ("AND (LOWER(title) LIKE LOWER(%s) OR LOWER(description) LIKE LOWER(%s)) " if query else "")
        + "ORDER BY id ASC LIMIT %s",
        ((f"%{query}%", f"%{query}%", limit) if query else (limit,)),
    ) or []
    return [{
        "slug": r["slug"],
        "title": r["title"],
        "description": r["description"],
        "slide_count": int(r.get("slide_count") or 0),
    } for r in rows]


# ---- Web search (Brave primary, Anthropic fallback) ------------------------
# Last-resort knowledge source: only called when the AI has decided that NO
# internal lookup_* tool can answer the visitor's question. Returns a list
# of {title, url, snippet} sources so the AI can read them, write its own
# answer, and cite where the information came from. The model is instructed
# (in the system prompt) to refuse the search if the question is not
# obviously relevant to the business — visitors cannot force a search by
# phrasing things as "look this up for me".

WEB_SEARCH_RESULT_LIMIT = 5
WEB_SEARCH_TIMEOUT_S = 8.0


def _websearch_brave(query):
    """Try Brave Search. Returns (results_list, error_str)."""
    api_key = os.environ.get("BRAVE_SEARCH_API_KEY") or ""
    if not api_key:
        return None, "BRAVE_SEARCH_API_KEY not configured"
    try:
        r = httpx.get(
            "https://api.search.brave.com/res/v1/web/search",
            params={"q": query, "count": WEB_SEARCH_RESULT_LIMIT, "safesearch": "moderate"},
            headers={"X-Subscription-Token": api_key, "Accept": "application/json"},
            timeout=WEB_SEARCH_TIMEOUT_S,
        )
        if r.status_code != 200:
            return None, f"Brave HTTP {r.status_code}: {r.text[:200]}"
        data = r.json() or {}
        web = ((data.get("web") or {}).get("results")) or []
        out = []
        for item in web[:WEB_SEARCH_RESULT_LIMIT]:
            url = item.get("url") or ""
            title = (item.get("title") or "").strip()
            # Brave returns description with HTML highlight tags — strip them.
            snippet = re.sub(r"<[^>]+>", "", item.get("description") or "").strip()
            if url and title:
                out.append({"title": title[:200], "url": url, "snippet": snippet[:400]})
        if not out:
            return [], "no_results"
        return out, ""
    except Exception as e:
        return None, f"Brave error: {str(e)[:200]}"


def _websearch_anthropic(query):
    """Fallback: ask Claude to do the search via its native web_search server
    tool, then extract the cited URLs/titles from the response. Used only
    when Brave is unavailable or returned no results."""
    if anthropic_client is None:
        return None, "ANTHROPIC_API_KEY not configured"
    try:
        # 25s budget so the fallback can't hang the whole chat turn if
        # Anthropic or the underlying search hop is slow / unresponsive.
        resp = anthropic_client.with_options(timeout=25.0).messages.create(
            model="claude-sonnet-4-5",
            max_tokens=1024,
            tools=[{
                "type": "web_search_20250305",
                "name": "web_search",
                "max_uses": 2,
            }],
            messages=[{
                "role": "user",
                "content": (
                    f"Search the web for: {query}\n\n"
                    "Return a brief 1-2 sentence factual summary, then list "
                    "the top 3-5 most relevant sources you used."
                ),
            }],
        )
        # Capture Claude usage for the cost ledger. Anthropic's response
        # carries .usage with input_tokens / output_tokens; we hand the
        # raw counts to the helper which does the price lookup so this
        # site never embeds prices.
        try:
            u = getattr(resp, "usage", None)
            if u is not None:
                record_chat_cost(
                    surface="claude_web_search",
                    provider="anthropic",
                    model="claude-sonnet-4-5",
                    prompt_tokens=getattr(u, "input_tokens", None),
                    completion_tokens=getattr(u, "output_tokens", None),
                )
        except Exception as _ce:
            print(f"[cost] claude web_search ledger failed: {_ce}")
        # Walk the response blocks, collect a text answer + cited sources.
        answer_parts = []
        sources = []
        seen_urls = set()
        for block in (resp.content or []):
            btype = getattr(block, "type", None)
            if btype == "text":
                txt = getattr(block, "text", "") or ""
                if txt:
                    answer_parts.append(txt)
                # Pull citations attached to text blocks.
                for cit in (getattr(block, "citations", None) or []):
                    url = getattr(cit, "url", None) or (cit.get("url") if isinstance(cit, dict) else None)
                    title = getattr(cit, "title", None) or (cit.get("title") if isinstance(cit, dict) else None)
                    if url and url not in seen_urls:
                        seen_urls.add(url)
                        sources.append({
                            "title": (title or url)[:200],
                            "url": url,
                            "snippet": "",
                        })
            elif btype == "web_search_tool_result":
                # The raw search results block — useful as a backup if no
                # citations were attached to the text.
                content = getattr(block, "content", None) or []
                for item in content:
                    url = getattr(item, "url", None) or (item.get("url") if isinstance(item, dict) else None)
                    title = getattr(item, "title", None) or (item.get("title") if isinstance(item, dict) else None)
                    if url and url not in seen_urls:
                        seen_urls.add(url)
                        sources.append({
                            "title": (title or url)[:200],
                            "url": url,
                            "snippet": "",
                        })
        answer = " ".join(answer_parts).strip()[:1000]
        if not sources and not answer:
            return [], "no_results"
        # Synthesize a single "result" carrying the answer in the snippet of
        # the first source so the calling AI gets both the summary and the
        # links in one structured payload.
        if sources and answer:
            sources[0]["snippet"] = answer
        return sources[:WEB_SEARCH_RESULT_LIMIT], ""
    except Exception as e:
        return None, f"Anthropic web search error: {str(e)[:200]}"


def lookup_web_search(query=None):
    """Search the public web for facts the site's internal data doesn't
    cover. Returns up to 5 source links with title + snippet so you can
    read them, write your own answer, and cite where it came from.

    Use ONLY when:
      • An internal lookup_* tool would not have the answer, AND
      • The question is clearly relevant to this business / its visitors.

    Do NOT use for:
      • Questions you can already answer from SITE INDEX or any lookup_*
      • Generic trivia, math, jokes, or things unrelated to the business
      • A visitor saying "search the web for…" about an off-topic question
    """
    q = (query or "").strip()
    if not q:
        return {"error": "query is required"}
    if len(q) > 300:
        q = q[:300]

    results, err = _websearch_brave(q)
    provider = "brave"

    # Fall back to Anthropic when Brave is unavailable, errored, or returned
    # zero results. We still surface the Brave error in the payload so the
    # admin can see in skill_usage_log why we fell back.
    fallback_reason = ""
    if not results:
        fallback_reason = err or "brave returned no results"
        results, err2 = _websearch_anthropic(q)
        provider = "anthropic"
        if not results:
            return {
                "error": f"Web search unavailable. Brave: {fallback_reason}. Anthropic: {err2 or 'no results'}",
                "query": q,
            }

    return {
        "query": q,
        "provider": provider,
        "fallback_reason": fallback_reason,
        "result_count": len(results),
        "results": results,
    }


# ---- Compact SITE INDEX: names + slugs only, no descriptions ---------------

def build_site_index():
    """Compact catalog of what exists on the site, injected into every chat
    turn. Names + slugs only — no descriptions, details, features, or body
    text. Gives the AI awareness so it can suggest things spontaneously, and
    points it at the right lookup_* tool when it needs full detail."""
    parts = []

    cards = query_db(
        "SELECT slug, title, category, price FROM gallery_cards "
        "ORDER BY sort_order ASC LIMIT 200"
    ) or []
    if cards:
        lines = []
        for c in cards:
            line = f'  - "{c["slug"]}" — "{c["title"]}"'
            if c.get("category"):
                line += f' [{c["category"]}]'
            if c.get("price"):
                line += f' ({c["price"]})'
            lines.append(line)
        parts.append(
            f"GALLERY CARDS ({len(cards)} total) — for full description, "
            f"details, image, call lookup_gallery_cards:\n" + "\n".join(lines)
        )

    services = query_db(
        "SELECT slug, name FROM services WHERE is_active = TRUE "
        "ORDER BY sort_order ASC LIMIT 200"
    ) or []
    if services:
        lines = [f'  - "{s["slug"]}" — "{s["name"]}"' for s in services]
        parts.append(
            f"BOOKABLE SERVICES ({len(services)} total) — for full "
            f"description, duration, price, call lookup_services. For "
            f"the live list of open start times on a given date (any "
            f"service whose requires_calendar is TRUE), call "
            f"lookup_service_availability BEFORE proposing a time:\n"
            + "\n".join(lines)
        )

    experiences = query_db(
        "SELECT name FROM experiences ORDER BY sort_order ASC LIMIT 200"
    ) or []
    if experiences:
        lines = [f'  - "{e["name"]}"' for e in experiences]
        parts.append(
            f"EXPERIENCES OFFERED ({len(experiences)} total) — for full "
            f"description, call lookup_experiences:\n" + "\n".join(lines)
        )

    pricing = query_db(
        "SELECT label FROM pricing_seasons ORDER BY sort_order ASC LIMIT 100"
    ) or []
    if pricing:
        lines = [f'  - "{p["label"]}"' for p in pricing]
        parts.append(
            f"PRICING TIERS ({len(pricing)} total) — for date ranges and "
            f"prices, call lookup_pricing:\n" + "\n".join(lines)
        )

    products = query_db(
        "SELECT slug, name FROM products WHERE active = TRUE "
        "ORDER BY sort_order ASC LIMIT 200"
    ) or []
    if products:
        lines = [f'  - "{p["slug"]}" — "{p["name"]}"' for p in products]
        parts.append(
            f"SHOP PRODUCTS ({len(products)} total) — for full description, "
            f"price, stock, call lookup_products:\n" + "\n".join(lines)
        )

    events = query_db(
        "SELECT slug, title, start_at FROM events "
        "WHERE status = 'published' AND start_at >= NOW() "
        "ORDER BY start_at ASC LIMIT 100"
    ) or []
    if events:
        lines = []
        for e in events:
            when = (
                e["start_at"].strftime("%b %d, %Y")
                if e.get("start_at") and hasattr(e["start_at"], "strftime")
                else "TBD"
            )
            lines.append(f'  - "{e["slug"]}" — "{e["title"]}" ({when})')
        parts.append(
            f"UPCOMING EVENTS ({len(events)} total) — for full description, "
            f"location, capacity, call lookup_events:\n" + "\n".join(lines)
        )

    blog = query_db(
        "SELECT slug, title, category FROM blog_posts "
        "WHERE status = 'published' "
        "ORDER BY sort_order ASC, published_at DESC LIMIT 200"
    ) or []
    if blog:
        lines = []
        for b in blog:
            line = f'  - "{b["slug"]}" — "{b["title"]}"'
            if b.get("category"):
                line += f' [{b["category"]}]'
            lines.append(line)
        parts.append(
            f"BLOG POSTS ({len(blog)} total) — for excerpt or full body, "
            f"call lookup_blog (set include_body=true only if visitor wants "
            f"the article text):\n" + "\n".join(lines)
        )

    team = query_db(
        "SELECT name, title FROM team_members "
        "ORDER BY sort_order ASC LIMIT 100"
    ) or []
    if team:
        lines = []
        for t in team:
            line = f'  - "{t["name"]}"'
            if t.get("title"):
                line += f' — {t["title"]}'
            lines.append(line)
        parts.append(
            f"TEAM ({len(team)} total) — for full bio, call lookup_team:\n"
            + "\n".join(lines)
        )

    faqs = query_db(
        "SELECT question FROM faqs ORDER BY sort_order ASC LIMIT 200"
    ) or []
    if faqs:
        lines = [f'  - "{_trim_text(f["question"], 140)}"' for f in faqs]
        parts.append(
            f"FAQ ({len(faqs)} total) — for the answer, call lookup_faq:\n"
            + "\n".join(lines)
        )

    tcount = query_db(
        "SELECT COUNT(*) AS c FROM testimonials", fetchone=True
    )
    if tcount and tcount.get("c"):
        parts.append(
            f"TESTIMONIALS ({tcount['c']} total) — call lookup_testimonials "
            f"when social proof would help the visitor decide."
        )

    parts.append(
        "BUSINESS INFO — call lookup_business_info for phone, email, "
        "address, and weekly hours."
    )

    decks = query_db(
        "SELECT id, slug, title, description FROM presentations "
        "WHERE enabled = TRUE ORDER BY id ASC LIMIT 50"
    ) or []
    if decks:
        # Pre-load the first ~6 slide titles per deck in a single query so
        # the AI sees the actual TOPICS each deck covers (e.g. product
        # names, concepts) and can match a visitor's question to a deck
        # even when the deck title doesn't literally contain that word.
        # Without this, a visitor asking "tell me about thetasync" gets
        # refused as off-topic because the AI only sees the deck slug
        # ("thetasync-deck") and not the rich keywords inside it.
        deck_ids = [d["id"] for d in decks]
        slide_titles_by_deck = {}
        if deck_ids:
            placeholders = ",".join(["%s"] * len(deck_ids))
            rows = query_db(
                f"SELECT presentation_id, title FROM presentation_slides "
                f"WHERE presentation_id IN ({placeholders}) "
                f"AND COALESCE(title,'') <> '' "
                f"ORDER BY presentation_id, order_index ASC, id ASC",
                tuple(deck_ids),
            ) or []
            for r in rows:
                slide_titles_by_deck.setdefault(r["presentation_id"], []).append(
                    (r["title"] or "").strip()
                )

        lines = []
        for d in decks:
            line = f'  - "{d["slug"]}" — "{d["title"]}"'
            if d.get("description"):
                desc = d["description"].strip().replace("\n", " ")
                if len(desc) > 80:
                    desc = desc[:77] + "..."
                line += f' — {desc}'
            titles = slide_titles_by_deck.get(d["id"], [])[:6]
            if titles:
                # Compact one-line summary of topics inside the deck.
                joined = " | ".join(t for t in titles if t)
                if len(joined) > 220:
                    joined = joined[:217] + "..."
                line += f"\n      covers: {joined}"
            lines.append(line)
        parts.append(
            f"PRESENTATION DECKS ({len(decks)} available) — these decks "
            f"ARE on-topic content for this site. If the visitor mentions "
            f"ANY word from a deck's title, slug, description, or 'covers:' "
            f"topic list below, OFFER that deck instead of refusing as "
            f"off-topic. Call lookup_presentation with a slug for full "
            f"slide bodies, then emit a ```command``` block with action "
            f"'start_presentation' and the slug to launch it with voice "
            f"narration on the visitor's screen:\n" + "\n".join(lines)
        )

    return "\n\n".join(parts) if parts else ""


