# ====================================================================
# Automations admin tools — read + propose-approve write surface so
# the Admin Assist AI can build / edit / toggle / delete automations
# on behalf of the owner. Mirrors the MCP pattern (dedicated tools +
# their own executor branch + ADMIN_DEDICATED_WRITE_TABLES guard).
# ====================================================================
def _admin_validate_automation_call_skill_steps(steps):
    """For every call_skill step, ensure skill_name resolves to an
    enabled row in agent_skills — gives the AI a clean error at
    *propose* time so a bad skill_name never reaches the approval
    queue. Returns an error string or None."""
    needed = set()
    for i, s in enumerate(steps or [], start=1):
        if not isinstance(s, dict):
            continue
        if (s.get("kind") or "").strip() != "call_skill":
            continue
        cfg = s.get("config") or {}
        skill_name = (cfg.get("skill_name") or "").strip()
        if not skill_name:
            return (f"Step {i} (call_skill) requires a non-empty "
                    f"skill_name.")
        needed.add(skill_name)
    if not needed:
        return None
    try:
        rows = query_db(
            "SELECT name FROM agent_skills "
            "WHERE enabled = true AND name = ANY(%s)",
            (list(needed),),
        ) or []
    except Exception as e:
        return f"Could not validate skill_names: {str(e)[:100]}"
    found = {r["name"] for r in rows}
    missing = sorted(needed - found)
    if missing:
        return (f"call_skill steps reference unknown or disabled "
                f"skills: {missing}. Use admin_list_skills to find a "
                f"valid name.")
    return None


def _admin_propose_validate_automation_payload(data):
    """Run the inbound payload through the canonical
    `_validate_automation_payload` (same checks the editor uses) PLUS
    the call_skill skill-name guard. Returns (clean_payload,
    error_str). On error, clean_payload is None."""
    try:
        clean = _validate_automation_payload(data)
    except ValueError as e:
        return None, str(e)
    err = _admin_validate_automation_call_skill_steps(
        clean["action_steps"])
    if err:
        return None, err
    return clean, None


def _automation_step_summary(step, idx):
    """Human-friendly one-line summary of an action step for the
    pending-action preview text shown in the approval card."""
    kind = (step.get("kind") or "").strip() or "?"
    name_label = (step.get("name") or "").strip()
    cfg = step.get("config") or {}
    if kind == "call_skill":
        sn = (cfg.get("skill_name") or "").strip() or "?"
        ok = (cfg.get("output_key") or "").strip()
        bits = [f"call_skill → {sn}"]
        if ok:
            bits.append(f"output_key={ok}")
        return (f"  {idx}. "
                + (name_label + " — " if name_label else "")
                + " ".join(bits))
    return (f"  {idx}. {kind}"
            + (f" — {name_label}" if name_label else ""))


def _admin_tool_list_automations(**_):
    """Return a compact list of every automation row (most-recent
    first, capped at 200) suitable for the AI to scan."""
    rows = query_db(
        "SELECT id, name, description, enabled, trigger_type, "
        "       last_run_at, last_run_status, "
        "       jsonb_array_length(COALESCE(action_steps, '[]'::jsonb)) "
        "         AS step_count "
        "FROM automations ORDER BY id DESC LIMIT 200"
    ) or []
    out = []
    for r in rows:
        out.append({
            "id": r["id"],
            "name": r.get("name") or "",
            "description": r.get("description") or "",
            "enabled": bool(r.get("enabled")),
            "trigger_type": r.get("trigger_type") or "manual",
            "step_count": int(r.get("step_count") or 0),
            "last_run_at": (r.get("last_run_at").isoformat()
                            if r.get("last_run_at") else None),
            "last_run_status": r.get("last_run_status") or "",
        })
    return {"automations": out, "count": len(out)}


def _admin_tool_get_automation(automation_id=None, **_):
    """Return ONE automation in the same shape the editor sees, with
    sensitive trigger_config secrets masked."""
    if automation_id is None:
        return {"error": "automation_id is required"}
    try:
        aid = int(automation_id)
    except Exception:
        return {"error": "automation_id must be an integer"}
    row = query_db("SELECT * FROM automations WHERE id = %s",
                   (aid,), fetchone=True)
    if not row:
        return {"error": f"No automation with id={aid}"}
    return _redact_automation_for_editor(_row_automation(row))


def _admin_tool_propose_create_automation(name=None, description="",
                                           enabled=False,
                                           trigger_type="manual",
                                           trigger_config=None,
                                           action_steps=None,
                                           _session_id="", **_):
    """Propose creating a new automation row. Validates the full
    payload up-front so the approval card never holds a malformed
    automation."""
    payload, err = _admin_propose_validate_automation_payload({
        "name": name, "description": description, "enabled": enabled,
        "trigger_type": trigger_type,
        "trigger_config": trigger_config or {},
        "action_steps": action_steps or [],
    })
    if err:
        return {"error": err}
    step_lines = [_automation_step_summary(s, i)
                  for i, s in enumerate(payload["action_steps"],
                                        start=1)] or ["  (no steps)"]
    preview = (f"Create automation '{payload['name']}'\n"
               f"  trigger: {payload['trigger_type']}\n"
               f"  enabled: {payload['enabled']}\n"
               f"  steps:\n" + "\n".join(step_lines))
    return _admin_create_pending(
        _session_id, "insert",
        target_table="automations",
        payload={"automation_payload": payload},
        preview=preview[:2000],
    )


def _admin_tool_propose_update_automation(automation_id=None, name=None,
                                            description=None,
                                            enabled=None,
                                            trigger_type=None,
                                            trigger_config=None,
                                            action_steps=None,
                                            _session_id="", **_):
    """Propose editing an existing automation. Each parameter is
    optional — anything left as None falls through to the saved
    value, so the AI can change just one field without resubmitting
    the whole automation."""
    if automation_id is None:
        return {"error": "automation_id is required"}
    try:
        aid = int(automation_id)
    except Exception:
        return {"error": "automation_id must be an integer"}
    existing = query_db("SELECT * FROM automations WHERE id = %s",
                        (aid,), fetchone=True)
    if not existing:
        return {"error": f"No automation with id={aid}"}
    merged = {
        "name": (name if name is not None
                 else existing.get("name")),
        "description": (description if description is not None
                        else existing.get("description")),
        "enabled": (bool(enabled) if enabled is not None
                    else bool(existing.get("enabled"))),
        "trigger_type": (trigger_type if trigger_type is not None
                         else existing.get("trigger_type")),
        "trigger_config": (trigger_config if trigger_config is not None
                           else (existing.get("trigger_config") or {})),
        "action_steps": (action_steps if action_steps is not None
                         else (existing.get("action_steps") or [])),
    }
    payload, err = _admin_propose_validate_automation_payload(merged)
    if err:
        return {"error": err}
    changes = []
    if name is not None and name != (existing.get("name") or ""):
        changes.append(f"name: '{existing.get('name')}' → "
                       f"'{payload['name']}'")
    if (description is not None
            and description != (existing.get("description") or "")):
        changes.append("description (rewritten)")
    if (enabled is not None
            and bool(enabled) != bool(existing.get("enabled"))):
        changes.append(f"enabled: {existing.get('enabled')} → "
                       f"{payload['enabled']}")
    if (trigger_type is not None
            and trigger_type != (existing.get("trigger_type") or "")):
        changes.append(f"trigger_type: "
                       f"{existing.get('trigger_type')} → "
                       f"{payload['trigger_type']}")
    if trigger_config is not None:
        changes.append("trigger_config (rewritten)")
    if action_steps is not None:
        changes.append(f"action_steps → "
                       f"{len(payload['action_steps'])} step(s)")
    if not changes:
        return {"error": ("No fields to update — every parameter "
                          "matched the saved value.")}
    preview = (f"Update automation #{aid} '{payload['name']}':\n  "
               + "\n  ".join(changes))
    return _admin_create_pending(
        _session_id, "update",
        target_table="automations", target_id=aid,
        payload={"automation_payload": payload},
        preview=preview[:2000],
    )


def _admin_tool_propose_toggle_automation(automation_id=None,
                                            enabled=None,
                                            _session_id="", **_):
    """Propose flipping the enabled flag on one automation. A simpler
    approval card than a full update."""
    if automation_id is None or enabled is None:
        return {"error": "automation_id and enabled are required"}
    try:
        aid = int(automation_id)
    except Exception:
        return {"error": "automation_id must be an integer"}
    existing = query_db(
        "SELECT name, enabled FROM automations WHERE id = %s",
        (aid,), fetchone=True)
    if not existing:
        return {"error": f"No automation with id={aid}"}
    new_state = bool(enabled)
    if bool(existing.get("enabled")) == new_state:
        return {"error": (f"Automation #{aid} is already "
                          f"{'enabled' if new_state else 'disabled'}.")}
    preview = (f"{'Enable' if new_state else 'Disable'} "
               f"automation #{aid} '{existing.get('name') or ''}'")
    return _admin_create_pending(
        _session_id, "update",
        target_table="automations", target_id=aid,
        payload={"toggle_enabled": new_state},
        preview=preview,
    )


def _admin_tool_propose_delete_automation(automation_id=None,
                                            _session_id="", **_):
    """Propose deleting one automation. Cascades to automation_runs
    and automation_versions through the existing FK setup."""
    if automation_id is None:
        return {"error": "automation_id is required"}
    try:
        aid = int(automation_id)
    except Exception:
        return {"error": "automation_id must be an integer"}
    existing = query_db("SELECT name FROM automations WHERE id = %s",
                        (aid,), fetchone=True)
    if not existing:
        return {"error": f"No automation with id={aid}"}
    preview = (f"Delete automation #{aid} "
               f"'{existing.get('name') or ''}' and ALL of its run "
               f"history + saved versions (cascade).")
    return _admin_create_pending(
        _session_id, "delete",
        target_table="automations", target_id=aid,
        payload={},
        preview=preview,
    )


def _admin_execute_automation_pending(action_row, payload):
    """Dedicated executor for approved `automations` CRUD actions —
    handles the webhook_token rotation + version snapshot + redacted
    secret merge that the generic field-map executor cannot. Returns
    (result_dict, error_str)."""
    a_type = action_row.get("action_type")
    rid = action_row.get("target_id")

    if a_type == "insert":
        clean, err = _admin_propose_validate_automation_payload(
            payload.get("automation_payload") or {})
        if err:
            return None, err
        token = (automations.generate_webhook_token()
                 if clean["trigger_type"] == "webhook" else "")
        try:
            row = execute_db(
                "INSERT INTO automations "
                "(name, description, enabled, trigger_type, "
                " trigger_config, action_steps, webhook_token) "
                "VALUES (%s, %s, %s, %s, %s::jsonb, %s::jsonb, %s) "
                "RETURNING id",
                (clean["name"], clean["description"], clean["enabled"],
                 clean["trigger_type"],
                 json.dumps(clean["trigger_config"]),
                 json.dumps(clean["action_steps"]),
                 token),
            )
            new_id = (row or {}).get("id")
            if new_id is not None:
                _save_automation_version(
                    new_id, _automation_snapshot(clean),
                    note="Created via Admin AI",
                )
            return ({"inserted_id": new_id, "table": "automations",
                     "name": clean["name"]}, None)
        except Exception as e:
            return None, str(e)[:400]

    if a_type == "update":
        if rid is None:
            return None, "missing target_id"
        # Toggle path — single-field flip, no full payload involved.
        if "toggle_enabled" in payload:
            new_state = bool(payload.get("toggle_enabled"))
            try:
                row = execute_db(
                    "UPDATE automations "
                    "SET enabled=%s, updated_at=NOW(), "
                    "    next_scheduled_at = CASE "
                    "       WHEN %s = FALSE THEN NULL "
                    "       ELSE next_scheduled_at END "
                    "WHERE id=%s RETURNING id",
                    (new_state, new_state, rid),
                )
                if not row:
                    return None, f"No automation #{rid}"
                return ({"rows_affected": 1, "table": "automations",
                         "row_id": rid, "enabled": new_state}, None)
            except Exception as e:
                return None, str(e)[:400]
        # Full update path.
        clean, err = _admin_propose_validate_automation_payload(
            payload.get("automation_payload") or {})
        if err:
            return None, err
        existing = query_db(
            "SELECT trigger_type, trigger_config, webhook_token "
            "FROM automations WHERE id = %s",
            (rid,), fetchone=True)
        if not existing:
            return None, f"No automation #{rid}"
        # When the trigger type is unchanged, fall back to the
        # existing trigger secret if the AI didn't actually re-paste
        # a new one (mirrors the editor's behaviour with masked
        # signature_secret values).
        if existing.get("trigger_type") == clean["trigger_type"]:
            _merge_preserved_trigger_secrets(
                clean["trigger_config"],
                existing.get("trigger_config") or {},
            )
        token = existing.get("webhook_token") or ""
        if clean["trigger_type"] == "webhook" and not token:
            token = automations.generate_webhook_token()
        elif clean["trigger_type"] != "webhook":
            token = ""
        try:
            execute_db(
                "UPDATE automations SET "
                " name=%s, description=%s, enabled=%s, "
                " trigger_type=%s, trigger_config=%s::jsonb, "
                " action_steps=%s::jsonb, webhook_token=%s, "
                " updated_at=NOW(), "
                " next_scheduled_at = CASE "
                "    WHEN trigger_type <> %s THEN NULL "
                "    ELSE next_scheduled_at END "
                "WHERE id=%s",
                (clean["name"], clean["description"], clean["enabled"],
                 clean["trigger_type"],
                 json.dumps(clean["trigger_config"]),
                 json.dumps(clean["action_steps"]),
                 token, clean["trigger_type"], rid),
            )
            _save_automation_version(
                rid, _automation_snapshot(clean),
                note="Updated via Admin AI",
            )
            return ({"rows_affected": 1, "table": "automations",
                     "row_id": rid}, None)
        except Exception as e:
            return None, str(e)[:400]

    if a_type == "delete":
        if rid is None:
            return None, "missing target_id"
        try:
            row = execute_db(
                "DELETE FROM automations WHERE id=%s RETURNING id",
                (rid,))
            if not row:
                return None, f"No automation #{rid}"
            return ({"rows_affected": 1, "table": "automations",
                     "row_id": rid}, None)
        except Exception as e:
            return None, str(e)[:400]

    return None, f"Unsupported action_type for automations: {a_type}"


# =============================================================
# GENERATED-PAGE CURATION + MARKETING INSIGHTS
# =============================================================
# Tools the admin AI uses to manage the AI-generated page
# library (review / publish / archive) and to mine visitor
# chats + page library for SEO + marketing opportunities.
# Read-only tools return immediately; write actions
# (publish / archive / draft_*) route through the standard
# pending-actions approval flow with action_type='update'
# (publish/archive) or 'insert' (drafts) so the existing
# _admin_execute_pending dispatcher already knows how to
# execute them after the owner clicks Approve.

_PAGE_SLUG_SAFE_RE = re.compile(r"[^a-z0-9-]+")
_HTML_SCRIPT_RE   = re.compile(r"<script[\s\S]*?</script>", re.IGNORECASE)
_HTML_STYLE_RE    = re.compile(r"<style[\s\S]*?</style>",   re.IGNORECASE)
_HTML_TAG_RE      = re.compile(r"<[^>]+>")
_WS_RE            = re.compile(r"\s+")
_DEHYPHEN_RE      = re.compile(r"-+")

# Visitor-question keywords pruned out before counting topics.
_INSIGHT_STOP = set((
    "a an and are as at be been but by can cant could couldnt did "
    "didn didnt do does doesnt doing dont down for from get got had "
    "has have having he her here him his how i id im in into is isnt "
    "it its just kind let me my no not of off on once one or our out "
    "over please should so some still such tell than thanks the their "
    "them then there these they this those through to too us very "
    "want was wasnt we well were what when where which while who why "
    "will with would wouldnt you your yours yes more know about ".split()
))


def _curation_strip_html(html):
    """Crude HTML→text extractor — strips <script>/<style> blocks then
    every tag, collapses whitespace, caps at 4000 chars so a 200KB
    page doesn't blow up the search_text column."""
    if not html:
        return ""
    text = _HTML_SCRIPT_RE.sub(" ", html)
    text = _HTML_STYLE_RE.sub(" ", text)
    text = _HTML_TAG_RE.sub(" ", text)
    text = _WS_RE.sub(" ", text).strip()
    return text[:4000]


def _curation_safe_slug(s, max_len=180):
    """Lowercase, hyphenate, strip unsafe chars. Used by
    publish_generated_page when the admin AI doesn't supply a slug."""
    if not s:
        return ""
    s2 = s.strip().lower().replace("&", " and ")
    s2 = _PAGE_SLUG_SAFE_RE.sub("-", s2).strip("-")
    s2 = _DEHYPHEN_RE.sub("-", s2)
    return s2[:max_len]


# ---- Page-curation reads -------------------------------------------

def _admin_tool_list_generated_pages(status=None, limit=20,
                                     since_days=None, **_):
    """List AI-generated pages with curation metadata. Filterable by
    status (draft/published/archived) and recency. Defaults to the
    20 most-recent of any status — admin AI's starting point for
    'review my page library'."""
    try:
        lim = max(1, min(int(limit or 20), 100))
    except Exception:
        lim = 20
    where = ["1=1"]
    args = []
    if status and status in ("draft", "published", "archived"):
        where.append("status = %s")
        args.append(status)
    if since_days:
        try:
            d = max(1, min(int(since_days), 365))
            where.append("created_at >= NOW() - %s::interval")
            args.append(f"{d} days")
        except Exception:
            pass
    rows = query_db(
        "SELECT id, slug, title, status, ai_score, reuse_count, "
        "       last_served_at, length(html) AS html_chars, "
        "       length(prompt) AS prompt_chars, "
        "       length(coalesce(summary,'')) AS summary_chars, "
        "       length(coalesce(search_text,'')) AS search_text_chars, "
        "       source_visitor_id, source_session_id, "
        "       created_at, updated_at "
        "FROM generated_pages WHERE " + " AND ".join(where)
        + " ORDER BY created_at DESC LIMIT %s",
        tuple(args + [lim]),
    ) or []
    out = []
    for r in rows:
        out.append({
            "id": r["id"],
            "slug": r.get("slug") or "",
            "title": r.get("title") or "",
            "status": r.get("status") or "",
            "ai_score": int(r.get("ai_score") or 0),
            "reuse_count": int(r.get("reuse_count") or 0),
            "last_served_at": (r["last_served_at"].isoformat()
                                if r.get("last_served_at") else None),
            "html_chars": int(r.get("html_chars") or 0),
            "prompt_chars": int(r.get("prompt_chars") or 0),
            "summary_chars": int(r.get("summary_chars") or 0),
            "search_text_chars": int(r.get("search_text_chars") or 0),
            "source_visitor_id": r.get("source_visitor_id") or "",
            "source_session_id": r.get("source_session_id") or "",
            "created_at": (r["created_at"].isoformat()
                           if r.get("created_at") else None),
        })
    return {"pages": out, "count": len(out)}


def _admin_tool_review_generated_page(page_id=None, **_):
    """Fetch one generated page with prompt + stripped excerpt + a
    `signals` dict (looks_thin, very_long, no_summary,
    already_published, similar_published_count, days_old) so the
    admin AI can reason about publish/edit/archive without fetching
    the (potentially huge) raw HTML."""
    if page_id is None:
        return {"error": "page_id is required"}
    try:
        pid = int(page_id)
    except Exception:
        return {"error": "page_id must be an integer"}
    page = query_db(
        "SELECT id, title, slug, status, prompt, summary, search_text, "
        "       html, ai_score, reuse_count, last_served_at, "
        "       source_visitor_id, source_session_id, created_at, "
        "       updated_at, "
        "       EXTRACT(DAY FROM (NOW() - created_at))::int AS days_old "
        "FROM generated_pages WHERE id = %s",
        (pid,), fetchone=True,
    )
    if not page:
        return {"error": f"Generated page #{pid} not found"}
    html = page.get("html") or ""
    text = page.get("search_text") or _curation_strip_html(html)
    excerpt = text[:600]
    title_seed = (page.get("title") or "").strip()[:80]
    prompt_seed = (page.get("prompt") or "").strip()[:200]
    seed = (title_seed + " " + prompt_seed).strip()
    similar = []
    if seed:
        try:
            similar = query_db(
                "SELECT id, slug, title, ai_score, reuse_count "
                "FROM generated_pages "
                "WHERE id <> %s AND status = 'published' AND "
                "      to_tsvector('english', "
                "          coalesce(title,'') || ' ' || "
                "          coalesce(prompt,'') || ' ' || "
                "          coalesce(summary,'') || ' ' || "
                "          coalesce(search_text,'')) "
                "      @@ plainto_tsquery('english', %s) "
                "ORDER BY reuse_count DESC LIMIT 5",
                (pid, seed[:200]),
            ) or []
        except Exception:
            similar = []
    days_old = page.get("days_old")
    signals = {
        "looks_thin": len(html) < 500,
        "very_long": len(html) > 60000,
        "no_summary": not (page.get("summary") or "").strip(),
        "already_published": page.get("status") == "published",
        "similar_published_count": len(similar),
        "days_old": int(days_old) if days_old is not None else None,
    }
    return {
        "id": page["id"],
        "title": page.get("title") or "",
        "slug": page.get("slug") or "",
        "status": page.get("status") or "",
        "prompt": page.get("prompt") or "",
        "summary": page.get("summary") or "",
        "search_text_excerpt": excerpt,
        "html_chars": len(html),
        "ai_score": int(page.get("ai_score") or 0),
        "reuse_count": int(page.get("reuse_count") or 0),
        "last_served_at": (page["last_served_at"].isoformat()
                            if page.get("last_served_at") else None),
        "source_visitor_id": page.get("source_visitor_id") or "",
        "source_session_id": page.get("source_session_id") or "",
        "created_at": (page["created_at"].isoformat()
                       if page.get("created_at") else None),
        "signals": signals,
        "similar_published": [
            {"id": s["id"], "slug": s.get("slug") or "",
             "title": s.get("title") or "",
             "ai_score": int(s.get("ai_score") or 0),
             "reuse_count": int(s.get("reuse_count") or 0)}
            for s in similar
        ],
    }


# ---- Page-curation writes (approval-gated) -------------------------

def _admin_tool_propose_publish_generated_page(
        page_id=None, slug=None, title=None, summary=None,
        search_text=None, ai_score=None, _session_id="", **_):
    """Propose publishing one generated page. Sets status='published',
    repairs the slug, fills summary + search_text + ai_score so the
    visitor agent's FTS lookup can find it. Routed through the
    standard approval flow as an UPDATE on generated_pages."""
    if page_id is None:
        return {"error": "page_id is required"}
    try:
        pid = int(page_id)
    except Exception:
        return {"error": "page_id must be an integer"}
    page = query_db(
        "SELECT id, slug, title, status, html, prompt, summary, "
        "       search_text, ai_score "
        "FROM generated_pages WHERE id = %s",
        (pid,), fetchone=True,
    )
    if not page:
        return {"error": f"Generated page #{pid} not found"}
    new_title = (title or page.get("title") or "").strip()[:200] or "Untitled Page"
    base_slug = (slug or page.get("slug")
                 or _curation_safe_slug(new_title)
                 or f"page-{pid}")
    base_slug = _curation_safe_slug(base_slug) or f"page-{pid}"
    new_summary = (summary or page.get("summary") or "").strip()[:600]
    if not new_summary:
        # Seed summary from prompt when AI didn't provide one.
        new_summary = (page.get("prompt") or "").strip()[:600]
    new_search_text = (search_text
                       or page.get("search_text")
                       or _curation_strip_html(page.get("html") or ""))[:4000]
    try:
        new_score = (max(0, min(int(ai_score), 100))
                     if ai_score is not None
                     else int(page.get("ai_score") or 0))
    except Exception:
        new_score = int(page.get("ai_score") or 0)
    fields = {
        "status": "published",
        "slug": base_slug,
        "title": new_title,
        "summary": new_summary,
        "search_text": new_search_text,
        "ai_score": new_score,
    }
    parts = [f"  {k} = {_admin_short(v, 80)}" for k, v in fields.items()]
    preview = (f"PUBLISH generated page #{pid} "
               f"(was status='{page.get('status') or 'draft'}'):\n"
               + "\n".join(parts))
    return _admin_create_pending(
        _session_id, "update",
        target_table="generated_pages", target_id=pid,
        payload={"fields": fields},
        preview=preview,
    )


def _admin_tool_propose_archive_generated_page(
        page_id=None, reason="", _session_id="", **_):
    """Propose archiving one generated page (status='archived') with
    a one-line reason captured for future analysis. Routed as an
    UPDATE through the standard approval flow."""
    if page_id is None:
        return {"error": "page_id is required"}
    try:
        pid = int(page_id)
    except Exception:
        return {"error": "page_id must be an integer"}
    page = query_db(
        "SELECT id, slug, title, status FROM generated_pages WHERE id = %s",
        (pid,), fetchone=True,
    )
    if not page:
        return {"error": f"Generated page #{pid} not found"}
    fields = {
        "status": "archived",
        "archive_reason": (reason or "").strip()[:500] or "No reason given",
    }
    preview = (f"ARCHIVE generated page #{pid} "
               f"({page.get('title') or '(untitled)'}, "
               f"was status='{page.get('status') or 'draft'}'). "
               f"Reason: {fields['archive_reason']}")
    return _admin_create_pending(
        _session_id, "update",
        target_table="generated_pages", target_id=pid,
        payload={"fields": fields},
        preview=preview,
    )


# ---- Marketing insights (reads) ------------------------------------

def _admin_tool_analyze_chat_topics(days=14, limit=15, **_):
    """Mine the last N days of visitor chat for what people keep
    asking about. Returns top keyword clusters with frequency, a
    sample message, and how many already-published generated pages
    mention that keyword (so the AI can flag content gaps)."""
    try:
        d = max(1, min(int(days or 14), 180))
    except Exception:
        d = 14
    try:
        lim = max(3, min(int(limit or 15), 40))
    except Exception:
        lim = 15
    msgs = query_db(
        "SELECT id, content, created_at FROM chat_messages "
        "WHERE role = 'user' AND created_at >= NOW() - %s::interval "
        "ORDER BY created_at DESC LIMIT 2000",
        (f"{d} days",),
    ) or []
    counts = {}
    samples = {}
    for m in msgs:
        words = re.findall(r"[a-zA-Z]{4,}",
                           (m.get("content") or "").lower())
        seen = set()
        for w in words:
            if w in _INSIGHT_STOP or w in seen:
                continue
            seen.add(w)
            counts[w] = counts.get(w, 0) + 1
            if w not in samples:
                samples[w] = (m.get("content") or "")[:160]
    top = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)[:lim]
    out = []
    for kw, n in top:
        if n < 2:
            continue
        try:
            existing = query_db(
                "SELECT COUNT(*) AS c FROM generated_pages "
                "WHERE status = 'published' AND "
                "      to_tsvector('english', "
                "          coalesce(title,'') || ' ' || "
                "          coalesce(prompt,'') || ' ' || "
                "          coalesce(summary,'') || ' ' || "
                "          coalesce(search_text,'')) "
                "      @@ plainto_tsquery('english', %s)",
                (kw,), fetchone=True,
            ) or {}
            ec = int(existing.get("c") or 0)
        except Exception:
            ec = 0
        out.append({
            "keyword": kw,
            "mentions": n,
            "sample_message": samples.get(kw, ""),
            "published_pages_with_keyword": ec,
            "is_content_gap": ec == 0,
        })
    # Cache the run so repeat questions in the same window can be deduped.
    try:
        execute_db(
            "INSERT INTO marketing_insights_log "
            "(insight_type, window_start, window_end, summary_json) "
            "VALUES (%s, NOW() - %s::interval, NOW(), %s::jsonb)",
            ("analyze_chat_topics", f"{d} days",
             json.dumps({"top": out, "messages_scanned": len(msgs)})),
        )
    except Exception:
        pass
    return {
        "window_days": d,
        "messages_scanned": len(msgs),
        "topics": out,
    }


def _admin_tool_analyze_page_library(**_):
    """Reuse + freshness stats for published generated pages.
    Returns per-status counts plus the top 30 most-reused and the
    bottom 10 least-reused so the admin AI can suggest which pages
    are earning their keep and which to prune."""
    rows = query_db(
        "SELECT id, slug, title, ai_score, reuse_count, last_served_at, "
        "       created_at, length(html) AS html_chars "
        "FROM generated_pages WHERE status = 'published' "
        "ORDER BY reuse_count DESC, last_served_at DESC NULLS LAST "
        "LIMIT 30"
    ) or []
    bottom = query_db(
        "SELECT id, slug, title, reuse_count, last_served_at, created_at "
        "FROM generated_pages WHERE status = 'published' "
        "ORDER BY reuse_count ASC, created_at ASC LIMIT 10"
    ) or []
    counts = query_db(
        "SELECT status, COUNT(*) AS c FROM generated_pages GROUP BY status"
    ) or []

    def _row(r, with_html=False):
        out = {
            "id": r["id"],
            "slug": r.get("slug") or "",
            "title": r.get("title") or "",
            "reuse_count": int(r.get("reuse_count") or 0),
            "last_served_at": (r["last_served_at"].isoformat()
                                if r.get("last_served_at") else None),
            "created_at": (r["created_at"].isoformat()
                            if r.get("created_at") else None),
        }
        if "ai_score" in r:
            out["ai_score"] = int(r.get("ai_score") or 0)
        if with_html and "html_chars" in r:
            out["html_chars"] = int(r.get("html_chars") or 0)
        return out

    return {
        "by_status": {r["status"]: int(r["c"]) for r in counts},
        "top_reused": [_row(r, with_html=True) for r in rows],
        "least_reused": [_row(r) for r in bottom],
    }


def _admin_tool_suggest_seo_improvements(days=30, **_):
    """Combine chat-topic mining and the page library to surface the
    highest-value content gaps: keywords visitors ask about that have
    NO matching published page, FAQ, or blog post. Returns a priority
    list the admin AI can hand off to draft_blog_post / draft_faq_entry."""
    topics = _admin_tool_analyze_chat_topics(days=days, limit=25)
    gaps = []
    for t in topics.get("topics", []):
        if not t.get("is_content_gap"):
            continue
        kw = t["keyword"]
        try:
            faq_hits = query_db(
                "SELECT COUNT(*) AS c FROM faqs "
                "WHERE LOWER(question) LIKE %s OR LOWER(answer) LIKE %s",
                (f"%{kw}%", f"%{kw}%"), fetchone=True,
            ) or {}
            fc = int(faq_hits.get("c") or 0)
        except Exception:
            fc = 0
        try:
            blog_hits = query_db(
                "SELECT COUNT(*) AS c FROM blog_posts "
                "WHERE status = 'published' AND "
                "      (LOWER(title) LIKE %s OR LOWER(content) LIKE %s)",
                (f"%{kw}%", f"%{kw}%"), fetchone=True,
            ) or {}
            bc = int(blog_hits.get("c") or 0)
        except Exception:
            bc = 0
        if fc + bc > 0:
            continue  # Already covered.
        gaps.append({
            "keyword": kw,
            "visitor_mentions": t["mentions"],
            "sample_question": t.get("sample_message", ""),
            "suggestion": (
                f"Visitors are asking about '{kw}' "
                f"({t['mentions']} times in the last {days} days) "
                "but no published page, FAQ, or blog post covers it. "
                "Consider drafting one."
            ),
            "recommended_action": (
                "draft_faq_entry" if t["mentions"] < 5
                else "draft_blog_post"
            ),
        })
    return {
        "window_days": days,
        "gap_count": len(gaps),
        "gaps": gaps[:15],
    }


# ---- Marketing drafts (approval-gated) -----------------------------

def _admin_tool_propose_draft_blog_post(
        title=None, body=None, slug=None, excerpt=None,
        category=None, tags=None, seo_title=None,
        seo_description=None, _session_id="", **_):
    """Queue a new draft blog_posts row for owner approval. Admin AI
    composes `body` itself and passes it in — this tool does NOT
    make a sub-LLM call. status defaults to 'draft' so nothing goes
    public until the owner edits + flips it to 'published'."""
    if not (title or "").strip():
        return {"error": "title is required"}
    if not (body or "").strip():
        return {"error": "body is required (compose the post text "
                         "yourself and pass it in)"}
    t = title.strip()[:200]
    s = (_curation_safe_slug(slug or t)
         or f"post-{int(_time.time())}")
    fields = {
        "title": t,
        "slug": s,
        "content": body.strip()[:50000],
        "excerpt": (excerpt or "").strip()[:500],
        "category": (category or "").strip()[:80],
        "tags": (tags or "").strip()[:200],
        "seo_title": (seo_title or t).strip()[:200],
        "seo_description": (seo_description or excerpt or "").strip()[:300],
        "status": "draft",
    }
    parts = [f"  {k} = {_admin_short(v, 80)}" for k, v in fields.items()]
    preview = ("INSERT INTO blog_posts a new draft post:\n"
               + "\n".join(parts))
    return _admin_create_pending(
        _session_id, "insert",
        target_table="blog_posts", payload={"fields": fields},
        preview=preview,
    )


def _admin_tool_propose_draft_faq_entry(
        question=None, answer=None, sort_order=None,
        _session_id="", **_):
    """Queue a new faqs row for owner approval. Admin AI composes the
    answer text and passes it in."""
    if not (question or "").strip():
        return {"error": "question is required"}
    if not (answer or "").strip():
        return {"error": "answer is required (compose it yourself)"}
    fields = {
        "question": question.strip()[:500],
        "answer": answer.strip()[:5000],
    }
    if sort_order is not None:
        try:
            fields["sort_order"] = int(sort_order)
        except Exception:
            pass
    parts = [f"  {k} = {_admin_short(v, 80)}" for k, v in fields.items()]
    preview = ("INSERT INTO faqs a new entry:\n" + "\n".join(parts))
    return _admin_create_pending(
        _session_id, "insert",
        target_table="faqs", payload={"fields": fields},
        preview=preview,
    )


def _admin_tool_propose_create_site_design(name=None, html=None,
                                            notes="", model_used="",
                                            publish=True,
                                            _session_id="", **_):
    """Propose creating a NEW site design (a complete homepage HTML
    document). The AI must compose the FULL HTML in its turn and pass
    it here — this tool is what wires the "build me a website" flow
    end-to-end. Goes through the standard approve card; nothing is
    written until the owner clicks Approve.

    publish (default True): when True, approving the action ALSO flips
    the site's active homepage to this new design in the same atomic
    step (no separate Website-tab visit needed). Pass publish=False ONLY
    when the owner explicitly says they want a draft preview without
    going live yet ('save it as a draft', 'don't publish yet', 'just
    show me a preview first')."""
    if not isinstance(name, str) or not name.strip():
        return {"error": ("name is required (e.g. "
                          "'Futuristic Hero v1')")}
    if not isinstance(html, str) or not html.strip():
        return {"error": ("html is required — pass the COMPLETE "
                          "<html> document, not a markdown plan or a "
                          "snippet.")}
    html = html.strip()
    low = html.lower()
    if "<html" not in low or "</html>" not in low:
        return {"error": ("html must be a complete document. Wrap your "
                          "content in "
                          "<!doctype html><html>...</html> with a "
                          "<head> and a <body>.")}
    if "<head" not in low or "</head>" not in low:
        return {"error": ("html is missing a <head>...</head> block "
                          "(needed for the title and inline styles).")}
    if "<body" not in low or "</body>" not in low:
        return {"error": "html is missing a <body>...</body> block"}
    if not low.lstrip().startswith("<!doctype html"):
        return {"error": ("html must start with '<!doctype html>' "
                          "(case-insensitive) so browsers render in "
                          "standards mode.")}
    if len(html) > 600_000:
        return {"error": (f"html is too large ({len(html):,} chars > "
                          f"600,000 char limit). Trim inline assets or "
                          f"split into multiple designs.")}
    will_publish = bool(publish)
    fields = {
        "name":       name.strip()[:200],
        "html":       html,
        "notes":      (notes or "").strip()[:2000],
        "model_used": (model_used or "ai_chat").strip()[:80],
        "source":     "ai_chat",
        # The row is born as 'draft'; if publish=True the executor flips
        # it to 'published' atomically right after the INSERT (see
        # _admin_execute_pending insert branch's site_designs hook).
        "status":     "draft",
    }
    if will_publish:
        preview = (f"Create AND PUBLISH site design '{fields['name']}' "
                   f"({len(html):,} chars HTML) — approving will make "
                   f"this the LIVE homepage immediately.")
    else:
        preview = (f"Create site design '{fields['name']}' "
                   f"({len(html):,} chars HTML, status=draft, "
                   f"source=ai_chat) — saved as draft only; publish "
                   f"separately from the Website tab.")
    if fields["notes"]:
        preview += f"\n  notes: {fields['notes'][:200]}"
    payload = {"fields": fields}
    if will_publish:
        # Sibling key (NOT inside fields) — the insert executor reads
        # this flag and chains _publish_atomic in the same approve.
        payload["_publish_after_insert"] = True
    return _admin_create_pending(
        _session_id, "insert",
        target_table="site_designs",
        payload=payload,
        preview=preview[:2000],
    )


def _admin_tool_propose_publish_site_design(design_id=None,
                                             _session_id="", **_):
    """Propose publishing an EXISTING site design (one that's already
    in the site_designs table, e.g. an earlier draft) so it becomes the
    live homepage. Use this when the owner asks 'publish design 3', 'go
    live with the futuristic one', 'switch the homepage to the design
    you made yesterday'. Atomic with _publish_atomic — flips
    site_settings.active_design_id and marks the row published in one
    transaction. Approval-gated."""
    if design_id is None:
        return {"error": "design_id is required"}
    try:
        did = int(design_id)
    except Exception:
        return {"error": "design_id must be an integer"}
    row = query_db(
        "SELECT id, name, status FROM site_designs WHERE id=%s",
        (did,), fetchone=True,
    )
    if not row:
        return {"error": f"Site design #{did} not found"}
    cur_active = (query_db(
        "SELECT active_design_id FROM site_settings WHERE id=1",
        fetchone=True,
    ) or {}).get("active_design_id")
    if cur_active == did:
        return {"error": (f"Site design #{did} ('{row.get('name')}') "
                          f"is already the active homepage. Nothing to "
                          f"publish.")}
    preview = (f"PUBLISH site design #{did} ('{row.get('name')}') — "
               f"approving will make this the LIVE homepage "
               f"(was status='{row.get('status') or 'draft'}'"
               + (f", currently active: #{cur_active}" if cur_active
                  else ", currently no active design") + ").")
    return _admin_create_pending(
        _session_id, "publish_site_design",
        target_table="site_designs", target_id=did,
        payload={"design_id": did},
        preview=preview[:2000],
    )


def _admin_tool_propose_create_site_theme(name=None, palette=None,
                                           fonts=None, notes="",
                                           _session_id="", **_):
    """Propose creating a NEW named theme (palette + fonts) directly in
    the site_themes table. Use this when the owner asks for a theme
    by name ('a futuristic dark theme', 'a coastal pastel theme'). The
    palette dict accepts keys: bg, text, accent, section1, section2,
    glass_bg, glass_border. The fonts dict accepts keys: serif, sans.
    Anything else is ignored. The new row lands as status='draft' so
    the owner can preview it in the Themes tab before publishing."""
    if not isinstance(name, str) or not name.strip():
        return {"error": ("name is required (e.g. "
                          "'Futuristic Neon')")}
    palette = palette or {}
    fonts = fonts or {}
    if not isinstance(palette, dict):
        return {"error": "palette must be a JSON object"}
    if not isinstance(fonts, dict):
        return {"error": "fonts must be a JSON object"}
    allowed_pal = {"bg", "text", "accent",
                   "section1", "section2",
                   "glass_bg", "glass_border"}
    allowed_fonts = {"serif", "sans"}
    palette_clean = {k: str(v).strip()
                     for k, v in palette.items()
                     if k in allowed_pal and str(v or "").strip()}
    fonts_clean = {k: str(v).strip()
                   for k, v in fonts.items()
                   if k in allowed_fonts and str(v or "").strip()}
    if not palette_clean and not fonts_clean:
        return {"error": ("palette or fonts must contain at least one "
                          "value. Allowed palette keys: bg, text, "
                          "accent, section1, section2, glass_bg, "
                          "glass_border. Allowed fonts keys: serif, "
                          "sans.")}
    fields = {
        "name":         name.strip()[:200],
        "palette_json": json.dumps(palette_clean),
        "fonts_json":   json.dumps(fonts_clean),
        "notes":        (notes or "").strip()[:2000],
        "source":       "ai_chat",
        "status":       "draft",
    }
    pal_lines = "\n".join(f"  {k} = {v}"
                          for k, v in palette_clean.items())
    font_lines = "\n".join(f"  font_{k} = {v}"
                           for k, v in fonts_clean.items())
    preview = (f"Create theme '{fields['name']}' (status=draft, "
               f"source=ai_chat)")
    if pal_lines:
        preview += f"\nPalette:\n{pal_lines}"
    if font_lines:
        preview += f"\nFonts:\n{font_lines}"
    if fields["notes"]:
        preview += f"\nnotes: {fields['notes'][:200]}"
    return _admin_create_pending(
        _session_id, "insert",
        target_table="site_themes",
        payload={"fields": fields},
        preview=preview[:2000],
    )


