# =============================================================
# ADMIN CRUD — PRESENTATIONS (Phase A: Agentic Skills)
# =============================================================
# A presentation is an ordered deck of slides the AI can launch on
# behalf of a visitor. Each slide carries a title, body, optional
# image, and optional narration_text the voice agent reads aloud.
# The public site fetches one deck at a time via GET /api/presentations/
# <slug>; the admin UI uses these CRUD endpoints to build them.

import re as _re

# NOTE: a presentations-specific `_slugify(value)` used to live here, but it was
# DEAD CODE — two later module-level `def _slugify(...)` (pages/sections and
# products) shadowed it, so every call site (incl. the deck routes below)
# already resolved to the products variant at line ~31xxx. Removing it changes
# no runtime behavior (Track B / task 078, piece #3: 3-way _slugify collision
# resolved down to the single canonical def). The deck routes' _slugify(...)
# calls continue to use that canonical def, which is what they already used.


@app.route("/admin/api/presentations", methods=["GET"])
@admin_required
def admin_list_presentations():
    """GET all presentations with their slide counts."""
    rows = query_db(
        "SELECT p.*, "
        "  (SELECT COUNT(*) FROM presentation_slides WHERE presentation_id = p.id) "
        "  AS slide_count "
        "FROM presentations p ORDER BY p.id DESC"
    ) or []
    return jsonify(rows)


@app.route("/admin/api/presentations/<int:pid>", methods=["GET"])
@admin_required
def admin_get_presentation(pid):
    """GET one presentation with its full slide list."""
    p = query_db("SELECT * FROM presentations WHERE id = %s", (pid,), fetchone=True)
    if not p:
        return jsonify({"error": "Presentation not found"}), 404
    slides = query_db(
        "SELECT * FROM presentation_slides WHERE presentation_id = %s "
        "ORDER BY order_index ASC, id ASC",
        (pid,),
    ) or []
    p["slides"] = slides
    return jsonify(p)


@app.route("/admin/api/presentations", methods=["POST"])
@admin_required
def admin_create_presentation():
    """POST — Create a new presentation deck (slides added separately)."""
    data = request.get_json() or {}
    title = (data.get("title") or "").strip()
    if not title:
        return jsonify({"error": "Title is required"}), 400
    slug = (data.get("slug") or "").strip() or _slugify(title)
    # Ensure slug is unique by suffixing -2, -3 ... if needed.
    base = slug
    n = 2
    while query_db(
        "SELECT 1 FROM presentations WHERE slug = %s",
        (slug,),
        fetchone=True,
    ):
        slug = f"{base}-{n}"
        n += 1
    # display_mode / ai_narrate_mode are validated against a small allow-list
    # so a malformed payload can never poke a junk value into the column.
    display_mode = (data.get("display_mode") or "rich").strip().lower()
    if display_mode not in ("rich", "original"):
        display_mode = "rich"
    ai_narrate_mode = (data.get("ai_narrate_mode") or "manual").strip().lower()
    if ai_narrate_mode not in ("manual", "auto"):
        ai_narrate_mode = "manual"
    p = execute_db(
        """INSERT INTO presentations
             (slug, title, description, cover_image_url, source, auto_play, enabled,
              display_mode, ai_narrate_mode)
           VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
           RETURNING *""",
        (
            slug,
            title,
            data.get("description") or "",
            data.get("cover_image_url") or "",
            data.get("source") or "admin",
            bool(data.get("auto_play")),
            bool(data.get("enabled", True)),
            display_mode,
            ai_narrate_mode,
        ),
    )
    return jsonify(p), 201


@app.route("/admin/api/presentations/<int:pid>", methods=["PUT"])
@admin_required
def admin_update_presentation(pid):
    """PUT — Update a presentation's metadata (not slides)."""
    data = request.get_json() or {}
    display_mode = (data.get("display_mode") or "rich").strip().lower()
    if display_mode not in ("rich", "original"):
        display_mode = "rich"
    ai_narrate_mode = (data.get("ai_narrate_mode") or "manual").strip().lower()
    if ai_narrate_mode not in ("manual", "auto"):
        ai_narrate_mode = "manual"
    p = execute_db(
        """UPDATE presentations SET
             title = %s,
             description = %s,
             cover_image_url = %s,
             auto_play = %s,
             enabled = %s,
             display_mode = %s,
             ai_narrate_mode = %s
           WHERE id = %s RETURNING *""",
        (
            data.get("title") or "",
            data.get("description") or "",
            data.get("cover_image_url") or "",
            bool(data.get("auto_play")),
            bool(data.get("enabled", True)),
            display_mode,
            ai_narrate_mode,
            pid,
        ),
    )
    if not p:
        return jsonify({"error": "Presentation not found"}), 404
    return jsonify(p)


@app.route("/admin/api/presentations/<int:pid>", methods=["DELETE"])
@admin_required
def admin_delete_presentation(pid):
    """DELETE — Remove a deck (cascades to its slides)."""
    count = execute_db("DELETE FROM presentations WHERE id = %s", (pid,))
    if count == 0:
        return jsonify({"error": "Presentation not found"}), 404
    return jsonify({"success": True})


@app.route("/admin/api/presentations/<int:pid>/slides", methods=["POST"])
@admin_required
def admin_add_slide(pid):
    """POST — Add a slide to a deck. order_index defaults to (max+1)."""
    parent = query_db(
        "SELECT id FROM presentations WHERE id = %s",
        (pid,),
        fetchone=True,
    )
    if not parent:
        return jsonify({"error": "Presentation not found"}), 404
    data = request.get_json() or {}
    if data.get("order_index") is None:
        nxt = query_db(
            "SELECT COALESCE(MAX(order_index), -1) + 1 AS n "
            "FROM presentation_slides WHERE presentation_id = %s",
            (pid,),
            fetchone=True,
        )
        order_index = int((nxt or {}).get("n", 0))
    else:
        order_index = int(data.get("order_index"))
    s = execute_db(
        """INSERT INTO presentation_slides
             (presentation_id, order_index, title, body, image_url, narration_text)
           VALUES (%s, %s, %s, %s, %s, %s) RETURNING *""",
        (
            pid,
            order_index,
            data.get("title") or "",
            data.get("body") or "",
            data.get("image_url") or "",
            data.get("narration_text") or "",
        ),
    )
    return jsonify(s), 201


# ---------------------------------------------------------------------------
# Helpers for the deck-import endpoint below.
#
# We accept many slide formats (PowerPoint, Keynote, OpenDocument, Word,
# images) and want every one of them to end up as one rendered image per
# slide so the deck looks pixel-perfect in "original" display mode. The
# pipeline is always: (Office format) -> LibreOffice -> PDF -> PyMuPDF
# -> per-page JPG. Direct PDF and image uploads skip the appropriate
# steps but feed into the same final shape.
# ---------------------------------------------------------------------------

def _convert_office_to_pdf(file_bytes, ext, timeout=180):
    """Run LibreOffice headless to convert PowerPoint / Keynote / etc. to PDF.

    Returns (pdf_bytes, error_string). On success error_string is None.
    A per-call temp UserInstallation profile prevents two simultaneous
    imports from clobbering each other's LibreOffice state.
    """
    import subprocess
    import tempfile
    import shutil
    soffice = shutil.which("soffice") or shutil.which("libreoffice")
    if not soffice:
        return None, "Office conversion unavailable: LibreOffice is not installed on the server."
    tmpdir = tempfile.mkdtemp(prefix="deckconv_")
    profile = tempfile.mkdtemp(prefix="sofficeprof_")
    src = os.path.join(tmpdir, f"input.{ext}")
    try:
        with open(src, "wb") as fh:
            fh.write(file_bytes)
        try:
            proc = subprocess.run(
                [
                    soffice, "--headless", "--norestore", "--nologo",
                    "--nofirststartwizard",
                    f"-env:UserInstallation=file://{profile}",
                    "--convert-to", "pdf", "--outdir", tmpdir, src,
                ],
                capture_output=True, timeout=timeout, check=False,
            )
        except subprocess.TimeoutExpired:
            return None, (
                f"Conversion timed out after {timeout}s. Try a smaller "
                f"deck, or save the file as PDF first and re-upload."
            )
        out_pdf = os.path.join(tmpdir, "input.pdf")
        if not os.path.exists(out_pdf) or os.path.getsize(out_pdf) == 0:
            err = (proc.stderr or b"").decode("utf-8", "ignore").strip()[:300]
            hint = ""
            if ext == "key":
                hint = " (Apple Keynote files often need to be exported from Keynote as PDF or PPTX before upload — LibreOffice can't always read .key directly.)"
            return None, f"Could not convert this {ext.upper()} file to a deck. {err}{hint}"
        with open(out_pdf, "rb") as fh:
            return fh.read(), None
    except Exception as e:
        return None, f"Conversion failed: {str(e)[:300]}"
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)
        shutil.rmtree(profile, ignore_errors=True)


MAX_IMPORT_PAGES = 200  # hard cap to keep huge decks from running away


def _render_pdf_to_slide_rows(pdf_bytes, created_files, fitz_mod, pil_image_mod):
    """Rasterize each PDF page to a JPG, save it to UPLOAD_FOLDER, and
    return one slide_row dict per page.

    Each row has the shape the import endpoint expects:
        {title, body, image_url, narration_text}

    Returns (slide_rows, error_string, http_status). On success
    error_string is None and http_status is 200. http_status is 400 for
    bad input (malformed/oversized PDF) and 500 for server-side IO
    problems so the caller can return an honest status code instead of
    blanket-400'ing real server failures.

    Files written to disk are appended to `created_files` so the caller
    can clean them up if a later step (DB insert) fails.
    """
    import io as _io
    try:
        doc = fitz_mod.open(stream=pdf_bytes, filetype="pdf")
    except Exception as e:
        return [], f"Could not read the rendered PDF: {str(e)[:300]}", 400
    if doc.page_count > MAX_IMPORT_PAGES:
        try: doc.close()
        except Exception: pass
        return [], (
            f"This deck has {doc.page_count} pages, which exceeds the "
            f"{MAX_IMPORT_PAGES}-page import limit. Split it into smaller "
            f"decks and import each one separately."
        ), 400
    rows = []
    try:
        # 2x render matrix gives ~144 DPI; we then downscale wide pages
        # to cap at 1600px so storage stays sane on big decks.
        base_matrix = fitz_mod.Matrix(2.0, 2.0)
        for page in doc:
            pix = page.get_pixmap(matrix=base_matrix, alpha=False)
            img = pil_image_mod.frombytes(
                "RGB", [pix.width, pix.height], pix.samples
            )
            if img.width > 1600:
                new_h = int(img.height * 1600 / img.width)
                img = img.resize((1600, new_h), pil_image_mod.LANCZOS)
            buf = _io.BytesIO()
            img.save(buf, format="JPEG", quality=85, optimize=True)
            unique_name = f"{secrets.token_hex(8)}.jpg"
            try:
                storage.get_storage().write_bytes(
                    unique_name, buf.getvalue(), content_type="image/jpeg"
                )
                created_files.append(unique_name)
            except Exception as _e:
                capture_exc(_e, "_render_pdf_to_slide_rows")
                # Storage write failure is a server-side problem, not the
                # admin's fault — return 500 so they don't think their
                # file is malformed.
                return rows, f"Could not save page image: {_e}", 500
            narration = (page.get_text("text") or "").strip()
            rows.append({
                "title": "",
                "body": "",
                "image_url": f"/uploads/{unique_name}",
                "narration_text": narration[:5000],
            })
    except Exception as e:
        capture_exc(e, "_render_pdf_to_slide_rows")
        # Rendering loop blew up after we'd already validated the PDF
        # opened — that means something internal failed (PyMuPDF crash,
        # corrupt page object, etc.), not bad user input.
        return rows, f"Failed while rendering the deck pages: {str(e)[:300]}", 500
    finally:
        try:
            doc.close()
        except Exception:
            pass
    return rows, None, 200


def _extract_pptx_notes(pptx_bytes):
    """Return a list of speaker-notes strings, one per slide, in order.

    Used as a bonus pass for .pptx uploads so the AI narration field is
    pre-populated from the owner's existing speaker notes. Returns []
    silently if python-pptx isn't installed or the file isn't readable.
    """
    try:
        from pptx import Presentation as _PPTXPresentation
    except ImportError:
        return []
    import io as _io
    try:
        prs = _PPTXPresentation(_io.BytesIO(pptx_bytes))
    except Exception:
        return []
    notes = []
    for slide in prs.slides:
        try:
            if (
                slide.has_notes_slide
                and slide.notes_slide
                and slide.notes_slide.notes_text_frame
            ):
                notes.append(
                    (slide.notes_slide.notes_text_frame.text or "").strip()
                )
            else:
                notes.append("")
        except Exception:
            notes.append("")
    return notes


@app.route("/admin/api/presentations/import", methods=["POST"])
@admin_required
def admin_import_presentation():
    """POST — Build a deck from a pre-built file the admin uploads.

    Accepts multipart with `files` (one or more) plus optional form fields
    `title`, `description`, `enabled`, `auto_play`. Supported inputs:

      - PDF (single file): each page is rendered to a JPG image (capped at
        1600px wide) and stored as one image-only slide. Page text is
        captured as the narration_text fallback.
      - PPTX (single file): one slide per slide; first text shape becomes
        the title, remaining text shapes become the body, speaker notes
        become narration_text. PowerPoint visual layout is NOT rendered —
        the admin is told to save as PDF first if pixel-perfect fidelity
        matters.
      - JPG/PNG/WEBP (one or more): each image becomes one image-only
        slide, ordered by filename.

    Returns {id, slug, title, slides_created, warnings:[...]} on success.
    """
    files = request.files.getlist("files") or []
    if not files and "file" in request.files:
        files = [request.files["file"]]
    files = [f for f in files if f and f.filename]
    if not files:
        return jsonify({"error": "No files provided"}), 400

    # Detect file kind by extension. We refuse mixed kinds because each
    # kind hits a different conversion path. "office" is the umbrella for
    # any format LibreOffice can convert to PDF — PowerPoint, Keynote,
    # OpenDocument, Word, etc. — which we then render to per-slide images
    # via the same PDF pipeline as a direct .pdf upload.
    OFFICE_EXTS = {"pptx", "ppt", "key", "odp", "doc", "docx", "odt", "rtf"}
    IMAGE_EXTS = {"jpg", "jpeg", "png", "webp"}
    kinds = set()
    upload_ext = ""  # the extension of the (single) office/pdf upload, if any
    for f in files:
        ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
        if ext == "pdf":
            kinds.add("pdf")
            upload_ext = ext
        elif ext in OFFICE_EXTS:
            kinds.add("office")
            upload_ext = ext
        elif ext in IMAGE_EXTS:
            kinds.add("image")
        else:
            return jsonify({
                "error": f"Unsupported file type: .{ext}. Supported: PDF, "
                f"PowerPoint (.ppt/.pptx), Keynote (.key), OpenDocument "
                f"(.odp/.odt), Word (.doc/.docx/.rtf), or images (.jpg/.png/.webp)."
            }), 400
    if len(kinds) > 1:
        return jsonify({"error": "Mix of file types — upload either one document (PDF, PowerPoint, Keynote, etc.) or a set of images, not a combination."}), 400
    kind = kinds.pop()
    if kind in ("pdf", "office") and len(files) != 1:
        return jsonify({"error": "Upload one document file at a time. (Image sets can be multiple files.)"}), 400

    # ----- Metadata defaults --------------------------------------------------
    title = (request.form.get("title") or "").strip()
    if not title:
        base_name = files[0].filename.rsplit(".", 1)[0]
        title = _re.sub(r"[_\-]+", " ", base_name).strip().title() or "Imported Deck"
    description = (request.form.get("description") or "").strip()
    enabled = (request.form.get("enabled") or "true").lower() != "false"
    auto_play = (request.form.get("auto_play") or "false").lower() == "true"

    warnings = []
    slide_rows = []  # accumulator: dicts with title/body/image_url/narration_text
    created_files = []  # storage subpaths we wrote during extraction; we
                        # delete these if anything fails before COMMIT, so a
                        # half-finished import never leaves orphaned uploads
                        # (works for both local-disk and S3 backends).

    def _cleanup_created_files():
        _store = storage.get_storage()
        for _p in created_files:
            try:
                _store.delete(_p)
            except Exception:
                pass

    # ----- PDF / Office -> image per page ------------------------------------
    # Both paths funnel into the same renderer: any PDF (direct upload OR
    # the output of the LibreOffice converter for PowerPoint/Keynote/etc.)
    # gets rasterized to one JPG per page and saved as one image-only slide.
    # That image is what "original display mode" shows full-bleed.
    if kind in ("pdf", "office"):
        try:
            import fitz  # PyMuPDF
        except ImportError as e:
            capture_exc(e, "admin_import_presentation")
            return jsonify({"error": "Deck import unavailable: PyMuPDF not installed."}), 500
        try:
            from PIL import Image as _PILImage
        except ImportError as e:
            capture_exc(e, "admin_import_presentation")
            return jsonify({"error": "Deck import unavailable: Pillow not installed."}), 500

        src_bytes = files[0].read()
        if kind == "office":
            # Hand the file to LibreOffice headless; it returns a normal PDF
            # we can rasterize with the existing PyMuPDF pipeline below.
            pdf_bytes, conv_err = _convert_office_to_pdf(src_bytes, upload_ext)
            if conv_err:
                return jsonify({"error": conv_err}), 400
            if upload_ext == "key":
                warnings.append("Apple Keynote files are converted via LibreOffice; complex animations or custom fonts may not render perfectly. Review the imported slides and re-export from Keynote as PDF if needed.")
        else:
            pdf_bytes = src_bytes

        slide_rows, render_err, render_status = _render_pdf_to_slide_rows(
            pdf_bytes, created_files, fitz, _PILImage
        )
        if render_err:
            _cleanup_created_files()
            return jsonify({"error": render_err}), render_status

        # PPTX bonus: also pull speaker notes (LibreOffice strips them
        # from the rendered PDF). Notes become the AI-narration starting
        # point so the owner doesn't have to re-type them.
        if kind == "office" and upload_ext == "pptx":
            try:
                notes_per_slide = _extract_pptx_notes(src_bytes)
                for i, n in enumerate(notes_per_slide):
                    if i < len(slide_rows) and n:
                        slide_rows[i]["narration_text"] = n[:5000]
            except Exception:
                # Notes are a bonus, not a hard requirement — never fail
                # the import just because notes extraction tripped.
                pass

    # ----- Image set: one slide per image, sorted by filename ----------------
    else:  # kind == "image"
        sorted_files = sorted(files, key=lambda f: f.filename.lower())
        for f in sorted_files:
            ext = f.filename.rsplit(".", 1)[-1].lower()
            unique_name = f"{secrets.token_hex(8)}.{ext}"
            try:
                storage.get_storage().write_fileobj(unique_name, f)
                created_files.append(unique_name)
            except Exception as e:
                capture_exc(e, "admin_import_presentation")
                _cleanup_created_files()
                return jsonify({"error": f"Could not save uploaded image: {str(e)[:300]}"}), 500
            slide_rows.append({
                "title": "",
                "body": "",
                "image_url": f"/uploads/{unique_name}",
                "narration_text": "",
            })

    if not slide_rows:
        _cleanup_created_files()
        return jsonify({"error": "No slides could be extracted from the upload."}), 400

    # ----- Persist deck + slides (single transaction) ------------------------
    # We open a manual transaction (autocommit off) so the deck row + every
    # slide row commit together. If anything fails, we ROLLBACK and also
    # delete every page image / source image we wrote during extraction so
    # the upload folder doesn't accumulate orphans.
    slug = _slugify(title)
    base = slug
    n = 2
    while query_db("SELECT 1 FROM presentations WHERE slug = %s", (slug,), fetchone=True):
        slug = f"{base}-{n}"
        n += 1
    cover = next((row.get("image_url") for row in slide_rows if row.get("image_url")), "")
    conn = get_db()
    conn.autocommit = False
    deck_id = None
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(
                """INSERT INTO presentations
                     (slug, title, description, cover_image_url, source, auto_play, enabled)
                   VALUES (%s, %s, %s, %s, 'admin', %s, %s)
                   RETURNING id""",
                (slug, title, description, cover, auto_play, enabled),
            )
            deck_id = cur.fetchone()["id"]
            for idx, row in enumerate(slide_rows):
                cur.execute(
                    """INSERT INTO presentation_slides
                         (presentation_id, order_index, title, body, image_url, narration_text)
                       VALUES (%s, %s, %s, %s, %s, %s)""",
                    (deck_id, idx, row["title"], row["body"], row["image_url"], row["narration_text"]),
                )
        conn.commit()
    except Exception as e:
        capture_exc(e, "admin_import_presentation")
        try: conn.rollback()
        except Exception: pass
        _cleanup_created_files()
        return jsonify({"error": f"Could not save deck to the database: {str(e)[:300]}"}), 500
    finally:
        try: conn.autocommit = True
        except Exception: pass
        try: conn.close()
        except Exception: pass

    return jsonify({
        "id": deck_id,
        "slug": slug,
        "title": title,
        "slides_created": len(slide_rows),
        "warnings": warnings,
    }), 201


@app.route("/admin/api/presentations/<int:pid>/generate-narration", methods=["POST"])
@admin_required
def admin_generate_narration(pid):
    """POST /admin/api/presentations/<pid>/generate-narration

    Use the LLM to write a short conversational voice script for each
    slide based on its title and body, with optional context from the
    surrounding slides for narrative flow. Saves the result to
    presentation_slides.narration_text.

    Body:
      {
        "force":     bool   # if true, overwrite existing narration_text;
                            # if false (default), only fill empty rows
        "slide_ids": [int]  # optional: limit to specific slide IDs;
                            # default = all slides in the deck
      }

    Response: { "updated": <int>, "skipped": <int>, "errors": [str] }
    """
    body = request.get_json() or {}
    force = bool(body.get("force"))
    raw_only_ids = body.get("slide_ids") or []
    # Validate slide_ids defensively — admin UI always sends ints, but a
    # hand-crafted/buggy client could send strings or junk and an unguarded
    # int() coerce would 500 instead of returning a useful error.
    if not isinstance(raw_only_ids, list):
        return jsonify({"error": "slide_ids must be an array of integers"}), 400
    only_ids = []
    for x in raw_only_ids:
        try:
            only_ids.append(int(x))
        except (TypeError, ValueError):
            return jsonify({"error": f"slide_ids contains a non-integer value: {x!r}"}), 400

    deck = query_db(
        "SELECT id, title, description FROM presentations WHERE id = %s",
        (pid,), fetchone=True,
    )
    if not deck:
        return jsonify({"error": "Presentation not found"}), 404

    # Pull image_url too — we feed the actual rendered slide image to the
    # vision model so it can SEE what's on screen instead of guessing
    # from empty title/body fields (the common case for imported PDF /
    # PowerPoint decks where the slide IS the image).
    slides = query_db(
        "SELECT id, order_index, title, body, image_url, narration_text "
        "FROM presentation_slides WHERE presentation_id = %s "
        "ORDER BY order_index ASC, id ASC",
        (pid,),
    ) or []
    if not slides:
        return jsonify({"updated": 0, "skipped": 0, "errors": ["No slides in this deck."]})

    # Pick the slides to (re)narrate. When force=false (default) we only
    # touch slides whose narration_text is empty so re-clicking the
    # button never overwrites the owner's hand-edited scripts.
    target_ids = set(only_ids) if only_ids else None
    targets = []
    for s in slides:
        if target_ids is not None and s["id"] not in target_ids:
            continue
        if not force and (s.get("narration_text") or "").strip():
            continue
        targets.append(s)

    if not targets:
        return jsonify({"updated": 0, "skipped": len(slides), "errors": []})

    # ----- Per-slide context-aware vision pass --------------------------------
    # We make ONE call per target slide so the model can:
    #   1. SEE the rendered slide via vision (huge win for image-only decks)
    #   2. Receive the deck title/description as overall arc context
    #   3. See the previous + next slide's content for narrative continuity
    #   4. See any existing extracted text (PDF text or speaker notes) as
    #      a hint of what the slide is "about" without forcing the model
    #      to read it verbatim
    # Calls are run in parallel with a small worker pool so a 15-slide
    # deck completes in roughly the same wall-clock time as 2-3 slides
    # would take serially. We bound concurrency to be polite to the API.
    deck_title       = (deck.get("title") or "").strip()
    deck_description = (deck.get("description") or "").strip()

    # Capture URL root NOW, before threading: Flask's request context is
    # not available inside worker threads. We won't actually use the URL
    # (we base64-inline the image instead — see below) but we may fall
    # back to URL passthrough for slides that reference an external image.
    try:
        url_root = request.url_root.rstrip("/")
    except Exception:
        url_root = ""

    def _short_summary(s, cap=180):
        """Compact one-liner of what's on slide `s`, used as adjacent-
        slide context. Prefers title, then body. Deliberately does NOT
        fall back to narration_text — on a re-run with force=true that
        column may already contain LLM-written narration, and feeding
        prior LLM output back into the prompt creates a feedback loop
        where the model mimics its own previous style instead of
        writing fresh from the slide image. For image-only PDF imports
        we accept that the only signal for adjacency is the slide
        position number, which is honest."""
        title = (s.get("title") or "").strip()
        if title:
            return title[:cap]
        body = (s.get("body") or "").strip()
        if body:
            return body[:cap]
        return "(image-only slide — no parsed text)"

    def _image_data_url_for(slide):
        """Return a data: URL for the slide's image so the vision API
        can see it without making an outbound HTTP fetch back to us
        (which would fail on private/locked-down deployments).
        Returns None when there's no usable image."""
        img = (slide.get("image_url") or "").strip()
        if not img:
            return None
        # External URLs (admin pasted a CDN link, etc.) — pass through.
        if img.startswith(("http://", "https://")):
            return img
        # Local-style /uploads/<file> URL — read bytes via the storage
        # backend (disk or S3) and base64-encode for the vision API.
        if img.startswith("/uploads/"):
            rel = img[len("/uploads/"):]
            # Belt-and-braces: image_url comes from our own import code,
            # but defend against an admin pasting a crafted ../traversal.
            # The storage layer also rejects '..' but we double-check here
            # so a hostile input fails closed (returns None) instead of
            # raising into the caller's try/except as a 500.
            if not rel or rel.startswith("/") or ".." in rel.split("/"):
                return None
            try:
                raw = storage.get_storage().read_bytes(rel)
            except Exception:
                return None
            if raw is None:
                return None
            ext = (rel.rsplit(".", 1)[-1] or "jpg").lower()
            mime = {"jpg": "image/jpeg", "jpeg": "image/jpeg",
                    "png": "image/png",  "webp": "image/webp",
                    "gif": "image/gif"}.get(ext, "image/jpeg")
            import base64 as _b64
            return f"data:{mime};base64,{_b64.b64encode(raw).decode('ascii')}"
        return None

    def _build_user_content(slide):
        """Assemble the multimodal user-message content for one slide:
        text context + the rendered slide image when available."""
        pos   = slide["order_index"] + 1
        total = len(slides)
        idx   = slide["order_index"]
        prev_s = slides[idx - 1] if idx - 1 >= 0 else None
        next_s = slides[idx + 1] if idx + 1 < total else None

        lines = [
            f'DECK: "{deck_title}"',
            f"DECK DESCRIPTION: {deck_description or '(none provided)'}",
            f"SLIDE POSITION: {pos} of {total}",
        ]
        if prev_s:
            lines.append(f"PREVIOUS SLIDE ({pos-1} of {total}): {_short_summary(prev_s)}")
        if next_s:
            lines.append(f"NEXT SLIDE ({pos+1} of {total}): {_short_summary(next_s)}")

        title_txt = (slide.get("title") or "").strip()
        body_txt  = (slide.get("body")  or "").strip()
        narr_txt  = (slide.get("narration_text") or "").strip()
        if title_txt:
            lines.append(f"\nTHIS SLIDE'S TITLE: {title_txt}")
        if body_txt:
            lines.append(f"THIS SLIDE'S BODY:\n{body_txt[:4000]}")
        # Show extracted/raw text only when we don't already have
        # structured title+body — it's most useful for image-only PDF
        # imports where it's the only textual signal we have.
        if not title_txt and not body_txt and narr_txt:
            lines.append(f"EXTRACTED TEXT FROM THIS SLIDE (raw, may be noisy):\n{narr_txt[:4000]}")

        # Position-aware framing — the opening, middle, and closing
        # slides each call for a different speaking posture. Without
        # this nudge the model writes every slide identically, which
        # is exactly what made earlier auto-narrations sound robotic.
        if pos == 1:
            position_hint = (
                "POSITION ROLE: This is the OPENING slide. Hook the "
                "audience in one sharp idea (a question, a striking "
                "claim, a single concrete example). Do NOT greet "
                "('Hello', 'Good morning', 'Welcome'). Do NOT pre-"
                "announce the agenda ('today we'll cover X, Y, Z'). "
                "Set the stakes with substance."
            )
        elif pos == total:
            position_hint = (
                "POSITION ROLE: This is the FINAL slide. Land ONE "
                "takeaway or call to action — the single thing you "
                "want the audience to leave with. Do NOT summarize "
                "the whole deck. Do NOT say 'in conclusion' or "
                "'as we wrap up'."
            )
        else:
            position_hint = (
                f"POSITION ROLE: Middle slide ({pos} of {total}). "
                "Open straight on the substance — no transition "
                "phrases ('next', 'now', 'moving on', 'building on "
                "that'), no recap of earlier slides."
            )
        lines.append("\n" + position_hint)

        lines.append(
            "\nTASK: Speak the substance of this slide in 2-3 sentences "
            "(30-60 words). Use real specifics visible in the image — "
            "named products, real numbers, concrete examples — never "
            "vague abstractions like 'powerful concept' or "
            "'transformative experience'. Vary your opener; do NOT "
            "start with 'This slide', 'Here', 'As we', 'Let's', "
            "'Today', 'Now', 'In this', or any meta-narrator phrase. "
            "Output ONLY the spoken sentences."
        )

        content = [{"type": "text", "text": "\n".join(lines)}]
        img_url = _image_data_url_for(slide)
        if img_url:
            content.append({
                "type": "image_url",
                "image_url": {"url": img_url, "detail": "low"},
            })
        return content

    # System message — defines the speaking persona, the absolute
    # banned-phrase list, and BAD/GOOD examples. The earlier prompt
    # only said "no filler" which the model interpreted loosely; it
    # kept producing meta-narrator openers ("This slide poses…", "As
    # we explore…", "Here we see…") because those *sound* like a
    # presenter to it. Banning them by name and showing the
    # rewritten alternative is the only thing that reliably moves
    # output style for gpt-4o-mini.
    # Editable from the admin "AI Prompts" tab (key: presentation_narration).
    sys_msg = get_prompt("presentation_narration", SLIDE_NARRATION_PROMPT)

    def _strip_image(content_list):
        """Return a copy of multimodal content with image_url parts
        removed — used when the LLM provider rejects vision input."""
        return [c for c in content_list if c.get("type") != "image_url"]

    def _gen_one(slide):
        content = _build_user_content(slide)
        had_image = any(c.get("type") == "image_url" for c in content)
        # Attempt 1: full multimodal (vision) request.
        try:
            resp = openai_client.chat.completions.create(
                model="gpt-4o-mini",   # supports vision
                messages=[
                    {"role": "system", "content": sys_msg},
                    {"role": "user",   "content": content},
                ],
                temperature=0.7,
                max_tokens=220,
            )
            record_chat_cost_from_response(resp, surface="deck_narration",
                                           model="gpt-4o-mini")
            txt = (resp.choices[0].message.content or "").strip()
            if txt:
                return slide["id"], txt, None
            # Empty response with image — try again text-only below.
            first_err = "model returned empty narration"
        except Exception as e:
            first_err = str(e)[:300]
            print(
                f"[generate-narration] slide={slide['id']} pos={slide['order_index']+1} "
                f"vision-call failed: {first_err}"
            )
        # Attempt 2: text-only fallback. Some LLM proxies don't support
        # image_url content parts; instead of giving up, drop the image
        # and retry so the admin still gets *some* narration written
        # from the slide's text context (deck title, position, body,
        # extracted text, adjacent slide summaries).
        if had_image:
            try:
                resp = openai_client.chat.completions.create(
                    model="gpt-4o-mini",
                    messages=[
                        {"role": "system", "content": sys_msg},
                        {"role": "user",   "content": _strip_image(content)},
                    ],
                    temperature=0.7,
                    max_tokens=220,
                )
                record_chat_cost_from_response(resp, surface="deck_narration",
                                               model="gpt-4o-mini")
                txt = (resp.choices[0].message.content or "").strip()
                if txt:
                    return slide["id"], txt, None
            except Exception as e2:
                print(
                    f"[generate-narration] slide={slide['id']} pos={slide['order_index']+1} "
                    f"text-only fallback also failed: {str(e2)[:300]}"
                )
                return slide["id"], "", f"vision: {first_err}; text-only: {str(e2)[:240]}"
        return slide["id"], "", first_err

    print(
        f"[generate-narration] deck={pid} force={force} "
        f"slides_total={len(slides)} targets={len(targets)} "
        f"first_target_image_url={(targets[0].get('image_url') if targets else None)!r}"
    )

    from concurrent.futures import ThreadPoolExecutor, as_completed
    results = {}            # slide_id -> narration string
    per_slide_errors = {}   # slide_id -> error string
    # 5 workers keeps us comfortably under most rate limits while still
    # making a 15-slide deck feel snappy (~3 sequential batches).
    # Track future -> slide so a worker crash that escapes _gen_one's
    # try/except (theoretically impossible, but belt-and-braces) still
    # gets attributed to the right slide for the human-readable error.
    with ThreadPoolExecutor(max_workers=5) as ex:
        future_to_slide = {ex.submit(_gen_one, s): s for s in targets}
        for fut in as_completed(future_to_slide):
            slide = future_to_slide[fut]
            try:
                sid, narr, err = fut.result()
            except Exception as e:
                per_slide_errors[slide["id"]] = f"thread crashed: {str(e)[:240]}"
                continue
            if err:
                per_slide_errors[sid] = err
            elif narr:
                results[sid] = narr

    # ----- Persist + collect human-readable errors ---------------------------
    updated = 0
    errors = []
    for s in targets:
        sid = s["id"]
        pos = s["order_index"] + 1
        narr = results.get(sid)
        if not narr:
            err = per_slide_errors.get(sid) or "model returned no narration"
            errors.append(f"slide {pos}: {err}")
            continue
        try:
            execute_db(
                "UPDATE presentation_slides SET narration_text = %s WHERE id = %s",
                (narr, sid),
            )
            updated += 1
        except Exception as e:
            errors.append(f"slide {pos}: db save failed ({str(e)[:200]})")

    return jsonify({
        "updated": updated,
        "skipped": len(slides) - len(targets),
        "errors": errors,
    })


@app.route("/admin/api/slides/<int:sid>", methods=["PUT"])
@admin_required
def admin_update_slide(sid):
    """PUT — Update one slide."""
    data = request.get_json() or {}
    s = execute_db(
        """UPDATE presentation_slides SET
             order_index = %s, title = %s, body = %s,
             image_url = %s, narration_text = %s
           WHERE id = %s RETURNING *""",
        (
            int(data.get("order_index", 0)),
            data.get("title") or "",
            data.get("body") or "",
            data.get("image_url") or "",
            data.get("narration_text") or "",
            sid,
        ),
    )
    if not s:
        return jsonify({"error": "Slide not found"}), 404
    return jsonify(s)


@app.route("/admin/api/slides/<int:sid>", methods=["DELETE"])
@admin_required
def admin_delete_slide(sid):
    """DELETE one slide."""
    count = execute_db("DELETE FROM presentation_slides WHERE id = %s", (sid,))
    if count == 0:
        return jsonify({"error": "Slide not found"}), 404
    return jsonify({"success": True})


# ---- Public — visitor-facing presentation fetch -----------------------------

@app.route("/api/presentations/<slug>", methods=["GET"])
def public_get_presentation(slug):
    """GET /api/presentations/<slug> — fetch one enabled deck for the
    visitor-side overlay player. Returns deck metadata + ordered slides
    including narration_text (the voice agent will speak it).

    Uses _resolve_presentation_slug so that the visitor agent can emit
    an abbreviated slug (e.g. 'thetasync' for 'thetasync-deck') and
    still successfully open the deck instead of silently 404-ing."""
    p = _resolve_presentation_slug(slug)
    if not p:
        return jsonify({"error": "Presentation not found"}), 404
    slides = query_db(
        "SELECT id, order_index, title, body, image_url, narration_text "
        "FROM presentation_slides WHERE presentation_id = %s "
        "ORDER BY order_index ASC, id ASC",
        (p["id"],),
    ) or []
    return jsonify({
        "slug": p["slug"],
        "title": p["title"],
        "description": p["description"],
        "cover_image_url": p["cover_image_url"],
        "auto_play": bool(p["auto_play"]),
        # display_mode tells the player whether to overlay the parsed
        # title+body styling ('rich'), or just show the original imported
        # slide image full-bleed with no text on top ('original').
        "display_mode": (p.get("display_mode") or "rich"),
        "ai_narrate_mode": (p.get("ai_narrate_mode") or "manual"),
        "slides": slides,
    })


# =============================================================
# ADMIN — AGENT SKILLS REGISTRY + LLM PROVIDER SETTINGS
# =============================================================
# The Skills tab in admin uses these endpoints to (a) toggle each
# skill on/off (powering get_active_chat_tools), (b) view recent
# skill_usage_log activity, and (c) pick the active LLM provider.

@app.route("/admin/api/skills", methods=["GET"])
@admin_required
def admin_list_skills():
    """GET all registered skills + the recent usage count per skill."""
    skills = query_db(
        "SELECT s.*, "
        "  COALESCE(u.recent_calls, 0) AS recent_calls "
        "FROM agent_skills s "
        "LEFT JOIN ("
        "  SELECT skill_name, COUNT(*) AS recent_calls "
        "  FROM skill_usage_log "
        "  WHERE created_at > NOW() - INTERVAL '7 days' "
        "  GROUP BY skill_name"
        ") u ON u.skill_name = s.name "
        "ORDER BY s.category ASC, s.name ASC"
    ) or []
    return jsonify(skills)


_SKILL_NAME_RE = _re.compile(r"^[a-z][a-z0-9_]{1,59}$")


def _normalize_custom_skill_payload(data, *, partial=False):
    """Validate + normalize an admin-supplied custom-skill payload.

    Returns (cleaned_dict, error_str). On success error_str is None. When
    `partial=True` (PUT path) only fields actually present are validated;
    when False (POST path) every required field must be there.
    """
    out = {}
    name = (data.get("name") or "").strip().lower()
    if name or not partial:
        if not _SKILL_NAME_RE.match(name or ""):
            return None, ("Name must start with a lowercase letter and use only "
                          "lowercase letters, digits, and underscores (max 60 chars).")
        out["name"] = name
    if "display_name" in data or not partial:
        out["display_name"] = (data.get("display_name") or "").strip()[:200]
    if "description" in data or not partial:
        desc = (data.get("description") or "").strip()
        if not desc and not partial:
            return None, "Description is required so the AI knows when to call this skill."
        out["description"] = desc[:2000]
    if "category" in data or not partial:
        out["category"] = (data.get("category") or "custom").strip().lower()[:40] or "custom"
    if "enabled" in data:
        # Strict truthy parsing — bool("false") is True in Python, so coerce
        # common string forms first for non-UI API callers.
        v = data.get("enabled")
        if isinstance(v, str):
            out["enabled"] = v.strip().lower() in ("true", "1", "yes", "on")
        else:
            out["enabled"] = bool(v)
    if "response_text" in data or not partial:
        rt = (data.get("response_text") or "").strip()
        if not rt and not partial:
            return None, "Response text is required for a custom skill."
        out["response_text"] = rt[:8000]
    return out, None


@app.route("/admin/api/skills", methods=["POST"])
@admin_required
def admin_create_skill():
    """POST — Create a new admin-defined custom skill (builtin = false).

    Body: {name, display_name, description, category, response_text,
    enabled?}. The skill becomes a no-arg tool the chat AI can call;
    when invoked it returns the configured response_text verbatim.
    """
    data = request.get_json() or {}
    cleaned, err = _normalize_custom_skill_payload(data, partial=False)
    if err:
        return jsonify({"error": err}), 400
    # Refuse names that collide with a builtin — the dispatcher would
    # match the builtin first, so the custom row would be unreachable.
    if cleaned["name"] in CHAT_LOOKUP_FUNCTIONS or cleaned["name"] in {
        (t.get("function") or {}).get("name") for t in CHAT_TOOLS
    }:
        return jsonify({"error": f"'{cleaned['name']}' is reserved by a builtin skill — choose a different name."}), 400
    if query_db("SELECT 1 FROM agent_skills WHERE name = %s", (cleaned["name"],), fetchone=True):
        return jsonify({"error": f"A skill named '{cleaned['name']}' already exists."}), 409
    config_json = json.dumps({"response_text": cleaned["response_text"]})
    enabled = cleaned.get("enabled", True)
    # Guard against the check-then-insert race: two simultaneous POSTs of
    # the same name would both pass the SELECT above and one of the
    # INSERTs would then violate the UNIQUE(name) constraint. Catch that
    # and turn it into the same friendly 409 the precheck returns.
    try:
        row = execute_db(
            """INSERT INTO agent_skills
                 (name, display_name, description, category, builtin, enabled, config_json)
               VALUES (%s, %s, %s, %s, false, %s, %s::jsonb)
               RETURNING *""",
            (cleaned["name"], cleaned["display_name"] or cleaned["name"].replace("_", " ").title(),
             cleaned["description"], cleaned["category"], enabled, config_json),
        )
    except psycopg2.IntegrityError:
        return jsonify({"error": f"A skill named '{cleaned['name']}' already exists."}), 409
    return jsonify(row), 201


@app.route("/admin/api/skills/<int:sid>", methods=["PUT"])
@admin_required
def admin_update_skill(sid):
    """PUT — Update a skill. Both builtin and custom skills accept the
    same editable fields:

    - enabled, display_name, description, category, response_text
      (rewritten into config_json), and config_json (raw).

    The only immutable field is `name` (it's the identifier the model
    passes back when calling the tool). For builtin skills, response_text
    is treated as an OPTIONAL OVERRIDE: when set, the dispatcher returns
    that text verbatim instead of running the live Python lookup; when
    blank, the live lookup runs as before.

    Backward-compatible with the original toggle-only payload
    {enabled: true/false}.
    """
    existing = query_db("SELECT * FROM agent_skills WHERE id = %s", (sid,), fetchone=True)
    if not existing:
        return jsonify({"error": "Skill not found"}), 404
    data = request.get_json() or {}
    cleaned, err = _normalize_custom_skill_payload(
        {k: v for k, v in data.items() if k != "name"},  # name is immutable
        partial=True,
    )
    if err:
        return jsonify({"error": err}), 400

    # Builtins now accept the same fields as custom skills:
    #   - category: free-text grouping label (preserved across restarts
    #     by sync_skills_to_db's COALESCE(NULLIF(...)) pattern).
    #   - response_text: optional override. When set, the dispatcher
    #     returns this verbatim instead of running the Python function;
    #     when blank, the live code lookup runs as before.
    # The skill's `name` is still immutable (filtered out above) because
    # it's the identifier the model passes back when calling the tool.

    sets, params = [], []
    for col in ("display_name", "description", "category", "enabled"):
        if col in cleaned:
            sets.append(f"{col} = %s")
            params.append(cleaned[col])

    # Two paths for config_json: a raw payload (legacy callers) OR the
    # response_text field. Both builtins and customs go through the
    # response_text path now — for customs it IS the skill's behavior,
    # for builtins it's an optional override (blank = use code).
    raw_config = data.get("config_json")
    if "response_text" in cleaned:
        existing_cfg = existing.get("config_json") or {}
        if isinstance(existing_cfg, str):
            try: existing_cfg = json.loads(existing_cfg)
            except Exception: existing_cfg = {}
        existing_cfg["response_text"] = cleaned["response_text"]
        sets.append("config_json = %s::jsonb")
        params.append(json.dumps(existing_cfg))
    elif raw_config is not None:
        sets.append("config_json = %s::jsonb")
        params.append(json.dumps(raw_config))

    if not sets:
        return jsonify(existing)
    # Snapshot the row BEFORE we overwrite it so the Recent Changes
    # panel can revert dashboard-driven edits, not just admin-chat ones.
    try:
        _admin_snapshot_row("agent_skills", sid, None,
                            "Updated from admin dashboard")
    except Exception as _e:
        print(f"[snapshot] agent_skills update {sid}: {_e}")
    params.append(sid)
    s = execute_db(
        f"UPDATE agent_skills SET {', '.join(sets)} WHERE id = %s RETURNING *",
        tuple(params),
    )
    if not s:
        return jsonify({"error": "Skill not found"}), 404
    return jsonify(s)


@app.route("/admin/api/skills/<int:sid>", methods=["DELETE"])
@admin_required
def admin_delete_skill(sid):
    """DELETE — Remove a custom skill. Builtin skills cannot be deleted
    (they would be re-inserted on the next startup by sync_skills_to_db,
    so deletion is a confusing no-op). Disable them instead."""
    row = query_db("SELECT id, name, builtin FROM agent_skills WHERE id = %s", (sid,), fetchone=True)
    if not row:
        return jsonify({"error": "Skill not found"}), 404
    if row.get("builtin"):
        return jsonify({
            "error": "Builtin skills cannot be deleted — they are defined in code and would reappear on next restart. Disable the skill instead.",
        }), 400
    try:
        _admin_snapshot_row("agent_skills", sid, None,
                            "Deleted from admin dashboard")
    except Exception as _e:
        print(f"[snapshot] agent_skills delete {sid}: {_e}")
    execute_db("DELETE FROM agent_skills WHERE id = %s", (sid,))
    return jsonify({"deleted": True, "id": sid, "name": row["name"]})


