# --------------- Chatbot Settings CRUD ---------------

@app.route("/admin/api/chatbot-settings", methods=["GET"])
@admin_required
def admin_get_chatbot():
    """GET the current chatbot settings + feature visibility flags."""
    settings = query_db("SELECT * FROM chatbot_settings WHERE id = 1", fetchone=True) or {}
    out = dict(settings)
    # Prompt privacy: the raw system prompt is the operator's IP. A client
    # (non super-admin) gets a fully working AI but must never see the prompt
    # text, so we redact it from the payload here. This server-side strip is
    # the REAL boundary — hiding the textarea in the template is only cosmetic.
    if not _is_super_admin():
        out.pop("system_prompt", None)
    # Surface feature visibility so the UI can hide gated controls without a
    # second round-trip. The frontend uses _features.agent_scope_slider to
    # decide whether to render the Scope Tightness slider.
    out["_features"] = {
        "agent_scope_slider": tenant_has_feature("agent_scope_slider"),
    }
    return jsonify(out)


@app.route("/admin/api/chatbot-settings", methods=["PUT"])
@admin_required
def admin_update_chatbot():
    """
    PUT /admin/api/chatbot-settings
    Update the chatbot configuration including system_prompt and agent_scope_tightness.
    """
    data = request.get_json()
    try:
        _admin_snapshot_row("chatbot_settings", 1, None,
                            "Updated from admin dashboard")
    except Exception as _e:
        print(f"[snapshot] chatbot_settings: {_e}")
    # Validate agent_scope_tightness — fall back to 'balanced' on garbage so
    # we never store an unknown value that would later confuse the prompt.
    scope_in = (data.get("agent_scope_tightness") or "balanced").strip().lower()
    if scope_in not in _AGENT_SCOPE_VALUES:
        scope_in = "balanced"
    # Capture the previous system_prompt so we can detect a real edit and
    # bump the semantic-cache content_version (which mass-invalidates all
    # cache rows tied to the old prompt — they may now be wrong).  Only
    # the prompt matters here; agent_name / greeting / mode don't change
    # what the AI should answer with.
    _prev_prompt = ""
    _prev_brand = ""
    _prev_row = {}
    try:
        _prev_row = query_db(
            "SELECT system_prompt, brand_voice FROM chatbot_settings WHERE id = 1",
            fetchone=True,
        ) or {}
        _prev_prompt = (_prev_row.get("system_prompt") or "").strip()
        _prev_brand = (_prev_row.get("brand_voice") or "").strip()
    except Exception:
        _prev_prompt = ""
        _prev_brand = ""
    # Prompt privacy: only the super-admin may change the prompt text. A client
    # save keeps whatever prompt is already stored (we ignore their value)
    # rather than blanking it — this is the write-side half of the boundary.
    if _is_super_admin():
        _system_prompt_value = data.get("system_prompt", "")
    else:
        _system_prompt_value = (_prev_row.get("system_prompt") or "")
    # Brand Voice, by contrast, is CLIENT-EDITABLE — every admin may set it.
    # If the field is omitted from the payload, keep whatever is stored rather
    # than blanking it.
    if "brand_voice" in data:
        _brand_voice_value = data.get("brand_voice") or ""
    else:
        _brand_voice_value = (_prev_row.get("brand_voice") or "")
    # task 101 §3.2 — proactive greeting auto-open delay (seconds; 0 = off). Clamped
    # 0..600 so a stray value can't pin the widget open instantly or after an hour.
    try:
        _auto_open = max(0, min(int(data.get("auto_open_seconds") or 0), 600))
    except (TypeError, ValueError):
        _auto_open = 0
    settings = execute_db(
        """UPDATE chatbot_settings SET
             enabled = %s, mode = %s, agent_name = %s, agent_role = %s,
             agent_avatar = %s, greeting = %s, quick_prompts = %s::jsonb,
             api_endpoint = %s, embed_code = %s, system_prompt = %s,
             brand_voice = %s,
             agent_scope_tightness = %s,
             theme = %s::jsonb,
             auto_open_seconds = %s,
             updated_at = NOW()
           WHERE id = 1 RETURNING *""",
        (
            data.get("enabled", False),
            data.get("mode", "builtin"),
            data.get("agent_name", "AI Assistant"),
            data.get("agent_role", "Assistant"),
            data.get("agent_avatar", "A"),
            data.get("greeting", ""),
            json.dumps(data.get("quick_prompts", [])),
            data.get("api_endpoint", "/api/chat"),
            data.get("embed_code", ""),
            _system_prompt_value,
            _brand_voice_value,
            scope_in,
            # Visual theme for the public chat widget (JSONB). Stored as-is;
            # the public side reads it with per-key fallbacks, so an empty {}
            # means "use the built-in look".
            json.dumps(data.get("theme") or {}),
            _auto_open,
        )
    )
    # Bump the cache content_version when the system_prompt OR brand_voice
    # actually changed so old cache rows (generated under the OLD wording)
    # stop being served.  Best-effort — never block the settings save on it.
    try:
        _new_prompt = (_system_prompt_value or "").strip()
        _new_brand = (_brand_voice_value or "").strip()
        if _new_prompt != _prev_prompt or _new_brand != _prev_brand:
            _v = semantic_cache.bump_content_version()
            print(
                f"[chatbot-settings] system_prompt changed → "
                f"semantic cache content_version → {_v}"
            )
    except Exception as _bv_e:
        print(f"[chatbot-settings] cache bump failed: {_bv_e}")
    # Prompt privacy: the RETURNING * row carries the prompt text — redact it
    # from the response for clients so a save can't be used to read it.
    out = dict(settings) if settings else {}
    if not _is_super_admin():
        out.pop("system_prompt", None)
    return jsonify(out)


