# --------------- AI Knowledge Cache (semantic response cache) ---------------
#
# These endpoints power the "Knowledge Cache" tab in the admin dashboard
# (templates/admin/dashboard.html).  The core logic lives in
# semantic_cache.py — these routes are thin wrappers that handle auth,
# input validation, and JSON shaping.
#
# What the admin sees in this tab:
#   * Stats banner   — # entries, hit count, est tokens & TTS chars saved
#   * Settings       — enable toggle + similarity threshold slider
#   * Top entries    — table of cached Q&A rows w/ delete buttons
#   * Backfill       — walk old chat_messages → seed the cache
#   * Purge stale    — delete rows tied to a prior content_version
#   * Purge ALL      — nuke the whole table (asks for confirmation in UI)


@app.route("/admin/api/ai-cache/stats", methods=["GET"])
@admin_required
def admin_ai_cache_stats():
    """Aggregate counters for the dashboard banner."""
    return jsonify(semantic_cache.get_stats())


@app.route("/admin/api/ai-cache/settings", methods=["GET", "PUT"])
@admin_required
def admin_ai_cache_settings():
    """GET or update the enable flag + similarity threshold."""
    if request.method == "GET":
        return jsonify(semantic_cache.get_cache_settings(force_refresh=True))
    data = request.get_json(silent=True) or {}
    enabled = data.get("cache_enabled")
    threshold = data.get("cache_threshold")
    # Coerce threshold defensively — sliders sometimes send strings.
    if threshold is not None:
        try:
            threshold = float(threshold)
        except (TypeError, ValueError):
            return jsonify({"error": "cache_threshold must be a number"}), 400
        if threshold < 0.80 or threshold > 0.99:
            return jsonify(
                {"error": "cache_threshold must be between 0.80 and 0.99"}
            ), 400
    if enabled is not None:
        # Coerce explicitly — a naive bool() would treat the string
        # "false" as truthy, silently flipping the cache on.  Accept
        # actual booleans + the obvious truthy/falsy string forms,
        # reject anything else loudly.
        if isinstance(enabled, bool):
            pass
        elif isinstance(enabled, (int, float)):
            enabled = bool(enabled)
        elif isinstance(enabled, str):
            v = enabled.strip().lower()
            if v in ("true", "1", "yes", "on"):
                enabled = True
            elif v in ("false", "0", "no", "off", ""):
                enabled = False
            else:
                return jsonify(
                    {"error": "cache_enabled must be a boolean"}
                ), 400
        else:
            return jsonify(
                {"error": "cache_enabled must be a boolean"}
            ), 400
    out = semantic_cache.set_settings(enabled=enabled, threshold=threshold)
    return jsonify(out)


@app.route("/admin/api/ai-cache/entries", methods=["GET"])
@admin_required
def admin_ai_cache_entries():
    """List cache entries for the admin table.

    Query params:
        limit (int, 1..500) — default 100
        sort  (hits | recent | stale) — default hits
    """
    try:
        limit = int(request.args.get("limit", 100))
    except (TypeError, ValueError):
        limit = 100
    sort = (request.args.get("sort") or "hits").strip().lower()
    rows = semantic_cache.list_entries(limit=limit, sort=sort)
    # Truncate long bodies before sending — the UI shows excerpts and
    # offers a "view full" expand-on-click, but the JSON over the wire
    # stays small.  300 chars is enough to spot what kind of answer it
    # is without dumping a 4KB blob per row.
    for r in rows:
        q = r.get("query_text") or ""
        a = r.get("response_text") or ""
        r["query_excerpt"] = q if len(q) <= 300 else (q[:300] + "…")
        r["response_excerpt"] = a if len(a) <= 300 else (a[:300] + "…")
        r["response_length"] = len(a)
        # ISO timestamps so the JS can format with toLocaleString().
        for k in ("last_hit_at", "created_at"):
            if r.get(k) is not None:
                try:
                    r[k] = r[k].isoformat()
                except Exception:
                    r[k] = str(r[k])
    return jsonify({"entries": rows, "count": len(rows)})


@app.route("/admin/api/ai-cache/<int:cache_id>", methods=["DELETE"])
@admin_required
def admin_ai_cache_delete(cache_id):
    """Delete a single cache row (admin saw bad data and wants it gone)."""
    ok = semantic_cache.delete_entry(cache_id)
    if not ok:
        return jsonify({"error": "Entry not found"}), 404
    return jsonify({"ok": True, "id": cache_id})


@app.route("/admin/api/ai-cache/purge", methods=["POST"])
@admin_required
def admin_ai_cache_purge():
    """Bulk delete.  body: {"scope": "stale"|"all"}.

    "stale" — drop rows whose content_version is below the current one
              (i.e. answers generated under a prior system_prompt).
    "all"   — drop EVERY row.  UI must confirm before calling.
    """
    data = request.get_json(silent=True) or {}
    scope = (data.get("scope") or "stale").strip().lower()
    if scope not in ("stale", "all"):
        return jsonify({"error": "scope must be 'stale' or 'all'"}), 400
    deleted = semantic_cache.purge(scope=scope)
    return jsonify({"ok": True, "scope": scope, "deleted": deleted})


@app.route("/admin/api/ai-cache/backfill", methods=["POST"])
@admin_required
def admin_ai_cache_backfill():
    """Walk recent chat_messages user→assistant pairs and seed the cache.

    Useful right after the feature ships (when the table is empty) or
    after a content_version bump (when most entries became stale).
    Honours should_cache_response, so PII / tool-driven / command-bearing
    answers are skipped.

    Query/body param: limit (1..2000) — number of conversations to scan.
    """
    try:
        limit = int(request.args.get("limit") or
                    (request.get_json(silent=True) or {}).get("limit") or 200)
    except (TypeError, ValueError):
        limit = 200
    out = semantic_cache.backfill_from_history(limit=limit)
    return jsonify(out)


@app.route("/admin/api/ai-cache/bump-version", methods=["POST"])
@admin_required
def admin_ai_cache_bump_version():
    """Manually invalidate every existing cache row.

    Use after editing site content (hours, prices, services) without
    touching the system_prompt — the prompt-edit path bumps automatically,
    everything else needs a manual click.
    """
    new_v = semantic_cache.bump_content_version()
    return jsonify({"ok": True, "content_version": new_v})


# ---------------------------------------------------------------------------
# Tier 10 — admin UI for snapshot / clone (HTTP wrapper around scripts/snapshot.py).
#
# Tier 5 shipped the snapshot engine as a CLI (`python scripts/snapshot.py`)
# and Tier 6 extended it to admin records. Tier 10 makes the same machinery
# reachable from the Clone & Snapshot tab in the admin dashboard for
# operators who don't have shell access on the server.
#
# Three surfaces, all delegating to scripts.snapshot.build_snapshot so the
# CLI and the UI can never drift out of agreement on what gets exported,
# what's redacted, and how the JSON is shaped:
#   GET  /admin/api/onboarding/snapshot          — full JSON, optional ?download=1
#   GET  /admin/api/onboarding/snapshot/summary  — counters only (cheap)
# Plus a VELO command `export_install_snapshot` (read-only, no confirmation)
# defined in velo_handlers.py — same payload, fetched by the master agent.
#
# All three are GET-only so the Tier 7 CSRF middleware is a no-op for them
# (CSRF only validates POST/PUT/PATCH/DELETE). Auth is the @admin_required
# decorator (session cookie) on the routes; the VELO command is gated by
# Bearer token in the VELO surface.
# ---------------------------------------------------------------------------

def _parse_snapshot_args():
    """Translate the dashboard's checkbox query-string into the argparse-
    Namespace shape that scripts.snapshot.build_snapshot expects.

    UI semantics differ slightly from the CLI defaults — the CLI biases
    toward minimal output (safe for piping to stdout); the UI defaults to
    the agency-clone use case (admin records ON, content OFF, secrets OFF
    — operator can change any of these via the form):

      include_admin_records=1 → args.include_admin = True
      include_content=1       → args.include_content = ""  (CLI sentinel
                                for "default content set" = services + team)
      include_content=1 with
        content_types=blog,services
                              → args.include_content = "blog,services"
      include_admin_secrets=1 → args.include_admin_secrets = True

    Strict bool parsing: "0" / "false" / "no" / "" all resolve to False
    so a typo in the query string can't accidentally export secrets."""
    def _bool(name, default=False):
        v = (request.args.get(name) or "").strip().lower()
        if not v:
            return default
        return v in ("1", "true", "yes", "on")

    include_content = _bool("include_content", False)
    raw_types = (request.args.get("content_types") or "").strip()
    if include_content:
        # Empty string is a sentinel in the CLI for "use default set"
        # (services + team). Honor a comma list when supplied.
        content_arg = raw_types if raw_types else ""
    else:
        content_arg = None  # CLI sentinel for "no content"

    return SimpleNamespace(
        tenant_id=int(request.args.get("tenant_id") or 1),
        include_admin=_bool("include_admin_records", True),
        include_admin_secrets=_bool("include_admin_secrets", False),
        # Receivers fill in their own admin email by editing the JSON
        # before applying — the source install's admin identity should
        # not be carried into a clone.
        include_admin_user=False,
        include_content=content_arg,
        include_all_content=False,
        no_content=(not include_content),
    )


@app.route("/admin/api/onboarding/snapshot", methods=["GET"])
@admin_required
def admin_onboarding_snapshot():
    """Return a snapshot of this install in bootstrap_install template
    shape. With ?download=1 returns it as a file attachment named
    snapshot-<site-slug>-<YYYYMMDD>.json so the operator can drop it
    into onboarding_templates/ on a sibling install."""
    from scripts import snapshot as _snap
    args = _parse_snapshot_args()
    snap, errors = _snap.build_snapshot(args)
    if errors:
        # Surface section-level read errors as a non-fatal warnings
        # block on the snapshot itself, mirroring the CLI's exit-code-2
        # "partial snapshot still written" behaviour.
        snap.setdefault("$warnings", []).extend(errors)

    if (request.args.get("download") or "").strip().lower() in ("1", "true", "yes"):
        body = _snap.json.dumps(
            snap, indent=2, ensure_ascii=False, default=_snap._json_default,
        ).encode("utf-8")
        # Build a slug from the site name (if available) so multiple
        # downloads are easy to tell apart in the operator's Downloads folder.
        site_name = (
            (snap.get("settings") or {}).get("site_settings") or {}
        ).get("site_name") or "install"
        slug = re.sub(r"[^a-z0-9]+", "-", site_name.lower()).strip("-") or "install"
        stamp = datetime.utcnow().strftime("%Y%m%d")
        resp = app.response_class(body, mimetype="application/json")
        resp.headers["Content-Disposition"] = (
            f'attachment; filename="snapshot-{slug}-{stamp}.json"'
        )
        # Block intermediaries from caching a snapshot — even without
        # admin secrets it carries the operator's full business config.
        resp.headers["Cache-Control"] = "no-store"
        return resp

    # Inline JSON path — Flask's jsonify can't handle Decimal/datetime,
    # so re-use the same _json_default fallback as the download path.
    # Same install-private content as the download path → same no-store
    # so a CDN or shared-cache can never serve another viewer's snapshot.
    body = _snap.json.dumps(snap, ensure_ascii=False, default=_snap._json_default)
    resp = app.response_class(body, mimetype="application/json")
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.route("/admin/api/onboarding/snapshot/summary", methods=["GET"])
@admin_required
def admin_onboarding_snapshot_summary():
    """Cheap counters / preview for a snapshot without re-rendering the
    full JSON in the browser. Same opts as the full endpoint."""
    from scripts import snapshot as _snap
    args = _parse_snapshot_args()
    snap, errors = _snap.build_snapshot(args)
    summary = _snap.summarize(snap)
    if errors:
        summary["warnings"] = errors
    # Counters reveal install-private metadata (settings keys, per-table
    # row counts, enabled feature flags) — match the full-snapshot path
    # and forbid intermediate caching.
    resp = jsonify(summary)
    resp.headers["Cache-Control"] = "no-store"
    return resp


# --------------- Image Upload ---------------

UPLOAD_FOLDER = os.path.join(os.path.dirname(os.path.abspath(__file__)), "uploads")
# Hard cap on a single uploaded file. Videos can be large, but we don't
# want a hostile upload to fill the disk in one shot. 100 MB is enough
# for short product/marketing videos and high-quality MP3s.
app.config["MAX_CONTENT_LENGTH"] = 100 * 1024 * 1024
ALLOWED_EXTENSIONS = {"jpg", "jpeg", "png", "gif", "webp"}
# Allowed media extensions for the general Media Library — covers images,
# short videos, and audio clips that businesses commonly need (logos,
# product photos, marketing clips, podcast episodes, voice intros).
ALLOWED_VIDEO_EXTENSIONS = {"mp4", "webm", "mov", "m4v"}
ALLOWED_AUDIO_EXTENSIONS = {"mp3", "wav", "ogg", "m4a", "aac"}
ALLOWED_MEDIA_EXTENSIONS = ALLOWED_EXTENSIONS | ALLOWED_VIDEO_EXTENSIONS | ALLOWED_AUDIO_EXTENSIONS

def _classify_media(ext):
    """Return ('image'|'video'|'audio'|None, mime_type) for an extension."""
    ext = (ext or "").lower()
    image_mime = {"jpg": "image/jpeg", "jpeg": "image/jpeg", "png": "image/png",
                  "gif": "image/gif", "webp": "image/webp"}
    video_mime = {"mp4": "video/mp4", "webm": "video/webm", "mov": "video/quicktime",
                  "m4v": "video/x-m4v"}
    audio_mime = {"mp3": "audio/mpeg", "wav": "audio/wav", "ogg": "audio/ogg",
                  "m4a": "audio/mp4", "aac": "audio/aac"}
    if ext in image_mime: return ("image", image_mime[ext])
    if ext in video_mime: return ("video", video_mime[ext])
    if ext in audio_mime: return ("audio", audio_mime[ext])
    return (None, None)
os.makedirs(UPLOAD_FOLDER, exist_ok=True)


# =============================================================================
# Uploads CDN routing — Optimization #5 (April 2026)
# =============================================================================
# Tier 9 added a pluggable storage backend (`storage.py`); Optimization #4
# added responsive WebP variants. This optimization wires those together so
# the operator can put a CDN (CloudFront / Cloudflare / Bunny / Fastly /
# anything) in front of /uploads/ and stop serving image bytes from the
# Flask origin entirely.
#
# Two layers, both gated on `UPLOADS_PUBLIC_BASE_URL` being set:
#
#   1. ORIGIN REDIRECT (safety net) — when set, /uploads/<file> returns 301
#      to <base>/uploads/<file>. Catches any traffic that didn't come
#      through the frontend's CDN-aware imgAttrs helper: cached HTML in
#      browser histories, externally-shared image links, RSS readers
#      fetching blog cover images, social-media unfurlers, anything. The
#      301 itself is cached so subsequent requests skip the origin.
#
#   2. FRONTEND REWRITE (perf optimization) — /api/page-bundle exposes the
#      base in `uploads_public_base_url`; imgSrcset / imgAttrs prepend it
#      so freshly-rendered <img> tags point straight at the CDN with zero
#      origin round-trip. See public/script.js IMG_UPLOADS_BASE.
#
# CACHE-CONTROL — Filenames are content-hashed (16-hex stems for originals,
# `<stem>-<width>.webp` for variants), so a given URL never changes its
# bytes. We send `public, max-age=86400` (1 day) on originals and the
# stronger `public, max-age=2592000, immutable` (30 days) on variants.
# This is a meaningful perf win on its own, even before the operator sets
# up a CDN — repeat visitors stop re-fetching every image on every page
# load. Contracts (`/uploads/contracts/...`) are deliberately left alone:
# they're operator-uploaded business documents that may want stricter
# cache / CDN treatment in the future.
#
# ORIGIN-PULL BYPASS — When the operator's CDN is configured to point its
# origin BACK at the Flask app (vs the bucket directly), the CDN's pulls
# through /uploads/ would loop forever if we redirected them. The CDN
# sets `X-CDN-Origin-Pull: 1` on origin requests and serve_upload skips
# the redirect on that header. Bunny CDN: "Custom Headers". Cloudflare:
# a Page Rule or a Worker. CloudFront: an Origin Custom Header.
# =============================================================================
_UPLOADS_REDIRECT_BYPASS_HEADER = "X-CDN-Origin-Pull"
_UPLOADS_CDN_PULL_SECRET_ENV = "UPLOADS_CDN_PULL_SECRET"
_UPLOADS_CACHE_HEADER_ORIGINAL = "public, max-age=86400"
_UPLOADS_CACHE_HEADER_VARIANT = "public, max-age=2592000, immutable"
_UPLOADS_REDIRECT_CACHE_HEADER = "public, max-age=86400"


def _uploads_public_base():
    """Return the CDN / public-bucket prefix from env, or '' if unset.
    Trailing slashes stripped so callers can append `/uploads/<file>`
    without producing `//uploads/...`. Read at request time (not module
    import time) so tests can monkeypatch the env var per-test."""
    return (os.environ.get("UPLOADS_PUBLIC_BASE_URL") or "").rstrip("/")


def _is_origin_pull_request():
    """True when the request is the CDN reaching back to origin to fill
    its cache. Operator configures their CDN to set the bypass header
    on origin requests so the redirect handler doesn't bounce them back
    to the CDN (which would loop forever).

    Hardening: when `UPLOADS_CDN_PULL_SECRET` env var is set, the header
    value must equal the secret to bypass — defends against malicious
    clients that would otherwise trick origin into serving bytes by
    faking `X-CDN-Origin-Pull: 1` (a performance-degradation attack).
    Compared with `secrets.compare_digest` to avoid timing-oracle leaks.
    When the env var is unset (default), any header value of `1` works,
    backward-compatible with the simple operator setup."""
    header_value = (request.headers.get(_UPLOADS_REDIRECT_BYPASS_HEADER) or "").strip()
    if not header_value:
        return False
    secret = (os.environ.get(_UPLOADS_CDN_PULL_SECRET_ENV) or "").strip()
    if secret:
        return secrets.compare_digest(header_value, secret)
    return header_value == "1"


def _base_points_at_self(base):
    """True when `base` parses to the same host:port as the inbound
    request — i.e. the operator misconfigured `UPLOADS_PUBLIC_BASE_URL`
    to point back at this same Flask app. Without this guard, every
    /uploads/ request would 301 back to itself until the browser hits
    its redirect-chain limit (~20) and gives up. With the guard, we
    log once and serve bytes from origin (degraded perf, working site)
    instead of breaking every page load. The CDN's normal origin-pull
    case is already handled separately by `_is_origin_pull_request()`,
    so this guard fires only on real misconfiguration."""
    if not base:
        return False
    try:
        parsed = urllib.parse.urlsplit(base)
    except Exception:
        return False
    base_host = (parsed.netloc or "").lower()
    if not base_host:
        return False
    request_host = (request.host or "").lower()
    return base_host == request_host


@app.route("/uploads/<path:filename>")
def serve_upload(filename):
    """Serve uploaded media via the configured storage backend (local
    disk or S3-compatible bucket). The S3 backend transparently falls
    back to disk for files written before the migration, so existing
    /uploads/<file> URLs in the DB keep working post-cutover.

    Optimization #4: when the request matches the responsive-WebP
    variant naming convention (`<stem>-<width>.webp`) and the variant
    isn't already in storage, synthesize it on the fly from any
    matching source image. This lets the frontend `imgSrcset()` helper
    point at variants for ALL existing uploads — pre-Opt-4 files get
    optimized the first time a viewer requests one, post-Opt-4 files
    are pre-warmed at upload time. `ensure_variant_on_demand` is a
    no-op for non-variant URLs and never raises (it logs and returns
    False), so the legacy serve path is unaffected on every other
    request.

    Optimization #5: when `UPLOADS_PUBLIC_BASE_URL` is set, redirect to
    the CDN instead of serving bytes — UNLESS the request carries the
    `X-CDN-Origin-Pull` header (the CDN reaching back to fill its
    cache, in which case we must serve bytes or we'd loop). Variant
    generation runs BEFORE the redirect so the CDN's origin pull
    (whatever its origin is configured to be — bucket directly or this
    same Flask app) finds the variant in storage. Cache-Control on the
    byte-serving path is `public, max-age=2592000, immutable` for
    variants and `public, max-age=86400` for originals — both filenames
    are content-hashed so a given URL truly never changes its bytes."""
    if image_optimize.is_variant_filename(filename):
        try:
            image_optimize.ensure_variant_on_demand(filename)
        except Exception as e:
            app.logger.exception("on-demand variant generation failed for %s: %s", filename, e)

    base = _uploads_public_base()
    if base and not _is_origin_pull_request() and not _base_points_at_self(base):
        target = f"{base}/uploads/{filename}"
        resp = redirect(target, code=301)
        resp.headers["Cache-Control"] = _UPLOADS_REDIRECT_CACHE_HEADER
        return resp

    resp = storage.get_storage().serve(filename)
    if image_optimize.is_variant_filename(filename):
        resp.headers["Cache-Control"] = _UPLOADS_CACHE_HEADER_VARIANT
    else:
        resp.headers["Cache-Control"] = _UPLOADS_CACHE_HEADER_ORIGINAL
    return resp


@app.route("/admin/api/upload-image", methods=["POST"])
@admin_required
def admin_upload_image():
    """POST /admin/api/upload-image — Upload an image file, return its URL."""
    if "file" not in request.files:
        return jsonify({"error": "No file provided"}), 400
    f = request.files["file"]
    if not f.filename:
        return jsonify({"error": "No file selected"}), 400
    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({"error": f"File type .{ext} not allowed. Use jpg, png, gif, or webp."}), 400

    unique_name = f"{secrets.token_hex(8)}.{ext}"
    _, mime = _classify_media(ext)
    _store = storage.get_storage()
    _store.write_fileobj(unique_name, f, content_type=mime)
    file_size = _store.size(unique_name) or 0

    # Opt #4: pre-warm responsive WebP variants (400/800/1600 widths).
    # Skipped for gif/webp/non-images — see image_optimize for the
    # rules. Best-effort: any failure is logged and swallowed so we
    # never fail an upload over a downstream optimization.
    #
    # Defense-first: delete any pre-existing variants whose URLs match
    # what we're about to generate. Same-name re-uploads are rare with
    # token_hex(8) names (256-bit space) but happen via snapshot
    # restore, manual overwrite, or bulk import. Without the cleanup
    # the variants would carry the OLD bytes for up to 30 days because
    # they're served `immutable, max-age=2592000`. The delete is a
    # no-op (~3 exists() probes) when no variants exist.
    try:
        image_optimize.delete_variants(unique_name)
        image_optimize.generate_webp_variants(unique_name)
    except Exception as e:
        app.logger.exception("variant pre-warm failed for %s: %s", unique_name, e)

    execute_db(
        "INSERT INTO uploaded_images (filename, original_name, file_size, media_type, mime_type) "
        "VALUES (%s, %s, %s, 'image', %s) RETURNING id",
        (unique_name, f.filename, file_size, mime or "")
    )

    return jsonify({"url": f"/uploads/{unique_name}", "filename": unique_name})


# --------------- Media Library (images, videos, audio) ---------------

@app.route("/admin/api/media", methods=["GET"])
@admin_required
def admin_list_media():
    """GET /admin/api/media — List all uploaded media. Optional ?type=image|video|audio filter."""
    media_type = (request.args.get("type") or "").strip().lower()
    if media_type in ("image", "video", "audio"):
        rows = query_db(
            "SELECT id, filename, original_name, file_size, media_type, mime_type, uploaded_at "
            "FROM uploaded_images WHERE media_type = %s ORDER BY uploaded_at DESC",
            (media_type,)
        )
    else:
        rows = query_db(
            "SELECT id, filename, original_name, file_size, media_type, mime_type, uploaded_at "
            "FROM uploaded_images ORDER BY uploaded_at DESC"
        )
    # Add public URL for convenience.
    for r in rows:
        r["url"] = f"/uploads/{r['filename']}"
        if r.get("uploaded_at"):
            r["uploaded_at"] = r["uploaded_at"].isoformat()
    return jsonify(rows)


@app.route("/admin/api/media/upload", methods=["POST"])
@admin_required
def admin_upload_media():
    """POST /admin/api/media/upload — Upload one or more media files (images, videos, audio).
    Accepts multipart 'files' (multiple) or 'file' (single). Returns list of saved media records."""
    files = request.files.getlist("files") or []
    if not files and "file" in request.files:
        files = [request.files["file"]]
    if not files:
        return jsonify({"error": "No files provided"}), 400

    saved = []
    errors = []
    for f in files:
        if not f or not f.filename:
            continue
        ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
        if ext not in ALLOWED_MEDIA_EXTENSIONS:
            errors.append({"filename": f.filename, "error": f".{ext} not allowed"})
            continue
        media_type, mime = _classify_media(ext)
        if not media_type:
            errors.append({"filename": f.filename, "error": "Unknown media type"})
            continue
        unique_name = f"{secrets.token_hex(8)}.{ext}"
        _store = storage.get_storage()
        _store.write_fileobj(unique_name, f, content_type=mime)
        size = _store.size(unique_name) or 0

        # Opt #4: pre-warm responsive WebP variants for image uploads.
        # `generate_webp_variants` short-circuits on non-jpg/png/jpeg
        # so it's safe to call unconditionally for every media type;
        # the explicit guard here just avoids the read_bytes for
        # videos and audio.
        #
        # `delete_variants` first sweeps any stale variants left over
        # from an earlier upload that reused the same filename (e.g.
        # restore-from-snapshot, manual overwrite). Skipping the
        # cleanup would leave browsers serving 30-day-cached old bytes
        # at the same URLs the new variants get. No-op for fresh names.
        if media_type == "image":
            try:
                image_optimize.delete_variants(unique_name)
                image_optimize.generate_webp_variants(unique_name)
            except Exception as e:
                app.logger.exception("variant pre-warm failed for %s: %s", unique_name, e)

        row = query_db(
            "INSERT INTO uploaded_images (filename, original_name, file_size, media_type, mime_type) "
            "VALUES (%s, %s, %s, %s, %s) RETURNING id, uploaded_at",
            (unique_name, f.filename, size, media_type, mime),
            fetchone=True
        )
        saved.append({
            "id": row["id"],
            "filename": unique_name,
            "original_name": f.filename,
            "file_size": size,
            "media_type": media_type,
            "mime_type": mime,
            "url": f"/uploads/{unique_name}",
            "uploaded_at": row["uploaded_at"].isoformat() if row.get("uploaded_at") else None,
        })

    return jsonify({"saved": saved, "errors": errors})


@app.route("/admin/api/media/<int:media_id>", methods=["DELETE"])
@admin_required
def admin_delete_media(media_id):
    """DELETE /admin/api/media/<id> — Remove a media file from disk and DB."""
    row = query_db("SELECT filename FROM uploaded_images WHERE id = %s", (media_id,), fetchone=True)
    if not row:
        return jsonify({"error": "Not found"}), 404
    # Best-effort file removal — DB delete is the source of truth.
    try:
        storage.get_storage().delete(row["filename"])
    except Exception:
        pass
    execute_db("DELETE FROM uploaded_images WHERE id = %s", (media_id,))
    return jsonify({"ok": True})


# --------------- Performance / Site-Operations Dashboard -------------------
#
# Read-only diagnostics + a single bulk action (regenerate WebP variants).
# Powers the "Performance" tab in the admin UI — gathers the runtime state
# of the site-perf optimisations into one JSON response so the operator can
# see what's configured / running / stale at a glance, without grepping
# logs or env vars. Self-service replacement for "ssh in and check".

@app.route("/admin/api/performance", methods=["GET"])
@admin_required
def admin_performance_stats():
    """GET /admin/api/performance — JSON snapshot of site-perf state.

    Returns six sections, one per optimisation. Any section that errors
    is returned with an `{"error": "..."}` marker so the UI can render
    the rest of the page even if one block fails.
    """
    return jsonify(_collect_performance_stats())


@app.route("/admin/api/dev-health", methods=["GET"])
@admin_required
def admin_dev_health():
    """Developer health KPIs (task 099, gap §6.4): error count (24h, from sentry_alerts),
    DB size, process uptime, and AI-turn p95 latency (ai_activity_log.duration_ms — the
    available proxy; general HTTP latency isn't instrumented). Super-admin only (infra
    detail); each metric is its own try/except → fail-open to None so one bad query
    never blanks the rest."""
    guard = _require_super_admin_role()
    if guard:
        return guard
    out = {"error_24h": None, "db_size_bytes": None, "uptime_seconds": None, "p95_latency_ms": None}
    try:
        out["error_24h"] = int((query_db(
            "SELECT COUNT(*) AS n FROM sentry_alerts WHERE received_at >= NOW() - INTERVAL '24 hours'",
            fetchone=True) or {}).get("n") or 0)
    except Exception:
        pass
    try:
        out["db_size_bytes"] = int((query_db(
            "SELECT pg_database_size(current_database()) AS b", fetchone=True) or {}).get("b") or 0)
    except Exception:
        pass
    try:
        out["uptime_seconds"] = max(0, int(_time.time() - VELO_APP_START_TIME))
    except Exception:
        pass
    try:
        r = query_db(
            "SELECT PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY duration_ms) AS p95 "
            "FROM ai_activity_log "
            "WHERE created_at >= NOW() - INTERVAL '24 hours' AND duration_ms IS NOT NULL",
            fetchone=True) or {}
        out["p95_latency_ms"] = int(r["p95"]) if r.get("p95") is not None else None
    except Exception:
        pass
    return jsonify(out)


# Tables an admin may export as CSV (task 099, gap §6.5). HARD-CODED whitelist — the
# <table> path param is validated against this set before it's ever put in SQL, so the
# SELECT interpolation below is injection-safe.
_CSV_EXPORT_TABLES = {
    "leads", "subscribers", "orders", "callback_requests", "meetings",
    "form_submissions", "visitor_profiles", "products", "pages", "blog_posts", "events",
}


@app.route("/admin/api/export/<table>.csv", methods=["GET"])
@admin_required
def admin_export_csv(table):
    """Export a whitelisted table as a CSV download (task 099, gap §6.5). Super-admin
    only (several of these hold PII). Bounded to 10k rows. The table name is validated
    against _CSV_EXPORT_TABLES before use, so the interpolation is safe."""
    guard = _require_super_admin_role()
    if guard:
        return guard
    if table not in _CSV_EXPORT_TABLES:
        return jsonify({"error": "Unknown or non-exportable table."}), 400
    import csv as _csv
    import io as _io
    try:
        rows = query_db("SELECT * FROM %s ORDER BY id DESC LIMIT 10000" % table) or []
        buf = _io.StringIO()
        if rows:
            writer = _csv.DictWriter(buf, fieldnames=list(rows[0].keys()), extrasaction="ignore")
            writer.writeheader()
            for r in rows:
                writer.writerow({k: ("" if v is None else v) for k, v in r.items()})
        return Response(buf.getvalue(), mimetype="text/csv",
                        headers={"Content-Disposition": 'attachment; filename="%s.csv"' % table})
    except Exception as e:
        capture_exc(e, "admin_export_csv")
        return jsonify({"error": "export_failed"}), 500


@app.route("/admin/api/performance/regenerate-image-variants", methods=["POST"])
@admin_required
def admin_regenerate_image_variants():
    """POST — Force-refresh ALL WebP variants for the local uploads dir.

    Iterates over every JPEG/PNG file at the uploads root, deletes each
    file's existing variants, and regenerates them at the current width
    breakpoints (400 / 800 / 1600). The escape-hatch for the cases the
    upload-time defense in `delete_variants` can't catch:

      * Sources replaced by shell / snapshot / object-store sync (the
        write didn't go through the upload route, so the per-upload
        cleanup never ran)
      * `_RESPONSIVE_WIDTHS` changed in image_optimize.py (variants at
        the OLD widths are now orphaned and the NEW widths are missing)
      * Bulk debugging: WebP encoder upgrade, Pillow upgrade, etc.

    Local-storage backend ONLY. For S3 backends, list the bucket via
    your CDN tooling and call `delete_variants` + `generate_webp_variants`
    in a script — we don't enumerate buckets here to keep the operation
    deterministic and bounded (a bucket of 100k images would time out
    the request and rack up egress).

    Synchronous: runs in the request handler. Typical small library
    (~50 images) finishes in 1-3 seconds. Tab UI disables the button
    and shows a spinner while running.
    """
    backend_name = storage.get_storage().name
    if backend_name != "local":
        return jsonify({
            "error": ("Bulk regenerate is local-storage-only. "
                      "S3 backends should script per-file regeneration."),
            "backend": backend_name,
        }), 400

    from pathlib import Path
    uploads_dir = Path(__file__).resolve().parent / "uploads"
    if not uploads_dir.exists():
        return jsonify({
            "regenerated": 0, "skipped": 0, "errors": 0, "total_scanned": 0,
        })

    regenerated = 0
    skipped = 0
    errors = 0
    total = 0
    for p in uploads_dir.iterdir():
        if not p.is_file():
            continue
        # Variants get rewritten as a side-effect of regenerating their
        # source — don't process them as inputs (would otherwise try to
        # decode a WebP and emit warnings).
        if image_optimize.is_variant_filename(p.name):
            continue
        ext = p.suffix.lower().lstrip(".")
        if ext not in {"jpg", "jpeg", "png"}:
            continue
        total += 1
        try:
            image_optimize.delete_variants(p.name)
            generated = image_optimize.generate_webp_variants(p.name)
            if generated:
                regenerated += 1
            else:
                # Source decoded but produced no variants — typically
                # a sub-400 px thumbnail (no upscaling rule kicks in).
                skipped += 1
        except Exception:
            app.logger.exception("regenerate failed for %s", p.name)
            errors += 1

    return jsonify({
        "regenerated": regenerated,
        "skipped": skipped,
        "errors": errors,
        "total_scanned": total,
    })


def _collect_performance_stats():
    """Gather all stats for the Performance tab. Per-section try/except
    so one broken backend (e.g. DB unreachable) doesn't 500 the whole
    page — each section returns its own data or an `{"error": ...}`."""
    return {
        "bundle": _stats_bundle(),
        "images": _stats_images(),
        "db_pool": _stats_db_pool(),
        "cdn_uploads": _stats_cdn_uploads(),
        "api_cache": _stats_api_cache(),
        "preconnect": _stats_preconnect(),
    }


def _stats_bundle():
    """JS bundle: hash, size, savings %, source list (Opt #11)."""
    try:
        b = asset_bundle.get_bundle()
        raw = b.get("raw_size") or 0
        mn = b.get("min_size") or 0
        return {
            "url": b.get("url"),
            "hash": b.get("hash"),
            "raw_size_bytes": raw,
            "min_size_bytes": mn,
            "savings_pct": round((1 - mn / raw) * 100, 1) if raw else 0,
            "sources": list(b.get("sources") or []),
        }
    except Exception as e:
        return {"error": str(e)}


def _stats_images():
    """Image library: backend, DB row count, on-disk file counts (Opt #4/5)."""
    try:
        backend = storage.get_storage().name
        try:
            row = query_db(
                "SELECT COUNT(*) AS c FROM uploaded_images WHERE media_type = 'image'"
            )
            uploaded_in_db = (row[0]["c"] if row else 0)
        except Exception:
            uploaded_in_db = None

        originals_on_disk = None
        variants_on_disk = None
        if backend == "local":
            from pathlib import Path
            uploads_dir = Path(__file__).resolve().parent / "uploads"
            if uploads_dir.exists():
                try:
                    originals = 0
                    variants = 0
                    for p in uploads_dir.iterdir():
                        if not p.is_file():
                            continue
                        if image_optimize.is_variant_filename(p.name):
                            variants += 1
                        elif p.suffix.lower().lstrip(".") in {"jpg", "jpeg", "png"}:
                            originals += 1
                    originals_on_disk = originals
                    variants_on_disk = variants
                except OSError:
                    pass

        return {
            "backend": backend,
            "uploaded_images_in_db": uploaded_in_db,
            "originals_on_disk": originals_on_disk,
            "variants_on_disk": variants_on_disk,
            "regenerate_supported": (backend == "local"),
        }
    except Exception as e:
        return {"error": str(e)}


def _stats_db_pool():
    """Connection pool: configured min/max + whether overridden by env (Opt #9)."""
    try:
        return {
            "configured_min": _DB_POOL_MIN,
            "configured_max": _DB_POOL_MAX,
            "min_via_env": bool((os.environ.get("DB_POOL_MIN") or "").strip()),
            "max_via_env": bool((os.environ.get("DB_POOL_MAX") or "").strip()),
        }
    except Exception as e:
        return {"error": str(e)}


def _stats_cdn_uploads():
    """CDN for /uploads: configured base URL + whether the strict-mode
    pull-secret is set (Opt #5)."""
    try:
        base = (os.environ.get("UPLOADS_PUBLIC_BASE_URL") or "").strip().rstrip("/")
        return {
            "configured": bool(base),
            "base_url": base,
            "secret_set": bool((os.environ.get("UPLOADS_CDN_PULL_SECRET") or "").strip()),
        }
    except Exception as e:
        return {"error": str(e)}


def _stats_api_cache():
    """Public API cache headers: which endpoints, what TTL (Opt #3)."""
    try:
        return {
            "endpoint_count": len(_CACHEABLE_API_PATHS),
            "endpoints": sorted(_CACHEABLE_API_PATHS),
            "max_age_seconds": 60,
            "stale_while_revalidate_seconds": 300,
            "admin_bypass_note": (
                "Caching is automatically skipped for any request "
                "carrying a session cookie, so logged-in admins always "
                "see fresh content."
            ),
        }
    except Exception as e:
        return {"error": str(e)}


def _stats_preconnect():
    """Third-party origins receiving preconnect+dns-prefetch hints (Opt #10).
    Parses the same HTML the homepage gets, so this surfaces any drift
    if `_build_preconnect_hints_html` ever changes."""
    try:
        html = _build_preconnect_hints_html()
        origins = sorted(set(re.findall(r'https://([\w.-]+)', html)))
        return {
            "origins": origins,
            "origin_count": len(origins),
        }
    except Exception as e:
        return {"error": str(e)}


# =============================================================================
# DEVELOPER CONSOLE (Admin → Developer tab)
# =============================================================================
# Powers an embedded "runbook + service health" tab so operators don't
# need to grep replit.md or shell into the box to diagnose a problem.
# Three thin endpoints:
#
#   GET  /admin/api/devconsole/snapshot        — read-only state, no network
#   POST /admin/api/devconsole/test-provider   — fires ONE provider probe
#   POST /admin/api/devconsole/test-email      — sends test email to ADMIN_EMAIL
#   POST /admin/api/devconsole/test-sms        — sends test SMS to ADMIN_PHONE
#   POST /admin/api/devconsole/reregister-velo — re-runs the boot-time call
#
# Auth: every route is @admin_required. POSTs are CSRF-checked by the
# middleware (no extra work). Test-send routes deliberately target the
# admin's own email/phone — never an arbitrary recipient — so the button
# can't be repurposed as an outbound spam vector if the session leaks.

@app.route("/admin/api/devconsole/snapshot", methods=["GET"])
@admin_required
def admin_devconsole_snapshot():
    """GET — small bundle of state the runbook + health panels need.
    No outbound network calls; safe to refresh frequently."""
    perf = _collect_performance_stats()

    # Derive small counts from the perf stats we already collected so the
    # runbook cards can show live numbers without re-querying the backend.
    bundle = perf.get("bundle") or {}
    images = perf.get("images") or {}
    api_cache = perf.get("api_cache") or {}
    preconnect = perf.get("preconnect") or {}

    # Scheduler liveness — messaging.py owns the in-process scheduler.
    # We can't introspect the thread directly without exposing internals,
    # so we surface a coarse "module loaded" signal. The dev tab adds
    # context that this only confirms the import path, not active ticks.
    scheduler_loaded = False
    try:
        scheduler_loaded = bool(getattr(messaging, "_scheduler_started", False))
    except Exception:
        scheduler_loaded = False

    velo_master = (os.environ.get("VELO_MASTER_URL") or "").strip()
    velo_key = (os.environ.get("VELO_AGENT_KEY") or "").strip()

    return jsonify({
        "providers": devconsole.provider_summary(),
        "runbook_state": {
            "image_variants_supported": bool(images.get("regenerate_supported")),
            "originals_on_disk": images.get("originals_on_disk"),
            "variants_on_disk": images.get("variants_on_disk"),
            "preconnect_count": preconnect.get("origin_count"),
            "bundle_source_count": len(bundle.get("sources") or []),
            "cacheable_endpoint_count": api_cache.get("endpoint_count"),
            "feature_flag_count": len(_FEATURE_REGISTRY),
            "admin_email_set": bool((os.environ.get("ADMIN_EMAIL") or "").strip()),
            "admin_phone_set": bool((os.environ.get("ADMIN_PHONE") or "").strip()),
            "velo_master_url_set": bool(velo_master),
            "velo_agent_key_set": bool(velo_key),
            "scheduler_loaded": scheduler_loaded,
            "site_url": (os.environ.get("SITE_URL") or "").strip(),
        },
    })


@app.route("/admin/api/devconsole/test-provider", methods=["POST"])
@admin_required
def admin_devconsole_test_provider():
    """POST — fire a single provider probe and return its result.
    Body: {"provider": "openai"}. Each probe is a cheap free-tier
    request (account fetch, model list, or 1-result search)."""
    body = request.get_json(silent=True) or {}
    name = (body.get("provider") or "").strip()
    if not name:
        return jsonify({"error": "provider name required"}), 400
    if name not in devconsole.PROVIDERS:
        return jsonify({
            "error": f"unknown provider: {name}",
            "known": devconsole.PROVIDERS,
        }), 400
    result = devconsole.probe(name)
    result["provider"] = name
    return jsonify(result)


@app.route("/admin/api/devconsole/test-email", methods=["POST"])
@admin_required
def admin_devconsole_test_email():
    """POST — send a tiny test email to ADMIN_EMAIL. Recipient is fixed
    to the admin contact so this can't be used as an open relay even
    if the admin session leaks."""
    to_email = (os.environ.get("ADMIN_EMAIL") or "").strip()
    if not to_email:
        return jsonify({"error": "ADMIN_EMAIL is not set"}), 400
    try:
        result = messaging.send_email(
            to_email,
            "Developer Console — test email",
            "<p>This is a self-test from the admin Developer Console. "
            "If you received this, Resend is wired up correctly.</p>",
            text_body=("This is a self-test from the admin Developer "
                       "Console. If you received this, Resend is wired "
                       "up correctly."),
        )
        return jsonify({
            "ok": True,
            "to": to_email,
            "provider_id": result.get("id"),
        })
    except messaging.MessagingError as e:
        capture_exc(e, "admin_devconsole_test_email")
        return jsonify({"ok": False, "to": to_email, "error": str(e)}), 502


@app.route("/admin/api/devconsole/test-sms", methods=["POST"])
@admin_required
def admin_devconsole_test_sms():
    """POST — send a tiny test SMS to ADMIN_PHONE. Same fixed-recipient
    safety as test-email."""
    to_phone = (os.environ.get("ADMIN_PHONE") or "").strip()
    if not to_phone:
        return jsonify({"error": "ADMIN_PHONE is not set"}), 400
    try:
        result = messaging.send_sms(
            to_phone,
            "Self-test from the admin Developer Console. "
            "Twilio is wired up correctly.",
        )
        # Even though the recipient is fixed to ADMIN_PHONE, this still
        # bills against Twilio — write a ledger row so the cost dashboard
        # accounts for it. surface=sms_devconsole_test keeps it visually
        # distinct from real outbound traffic. record_sms_cost never
        # raises (it swallows internally) so a ledger failure can't 500
        # the test-send button.
        record_sms_cost(
            surface="sms_devconsole_test",
            provider="twilio",
            to_number=to_phone,
            message_sid=result.get("sid") or "",
            segments=result.get("num_segments"),
        )
        return jsonify({
            "ok": True,
            "to": to_phone,
            "provider_sid": result.get("sid"),
            "segments": result.get("num_segments"),
        })
    except messaging.MessagingError as e:
        capture_exc(e, "admin_devconsole_test_sms")
        return jsonify({"ok": False, "to": to_phone, "error": str(e)}), 502


@app.route("/admin/api/devconsole/reregister-velo", methods=["POST"])
@admin_required
def admin_devconsole_reregister_velo():
    """POST — re-run the boot-time agent registration. Use after
    rotating VELO_AGENT_KEY or pointing at a new VELO_MASTER_URL."""
    if not (os.environ.get("VELO_MASTER_URL") or "").strip():
        return jsonify({
            "ok": False,
            "error": "VELO_MASTER_URL is not set; nothing to register against.",
        }), 400
    try:
        register_with_velo(force=True)
        return jsonify({"ok": True})
    except Exception as e:
        capture_exc(e, "admin_devconsole_reregister_velo")
        return jsonify({"ok": False, "error": str(e)}), 502


# =============================================================
# ADMIN: STRIPE CONSOLE
# =============================================================
# Routes that back the admin "Stripe" tab. Powers:
#   GET  /admin/api/stripe/settings        — current config snapshot
#   POST /admin/api/stripe/mode            — flip test/live, fires probe
#   POST /admin/api/stripe/autosync        — toggle product autosync
#   POST /admin/api/stripe/probe           — Stripe Account.retrieve()
#   POST /admin/api/stripe/backfill        — sync every product
#   POST /admin/api/stripe/sync-product    — manual single re-sync
#   GET  /admin/api/stripe/sync-status     — products × mappings table
#   GET  /admin/api/stripe/recent-checkouts — last N Checkout Sessions
#
# All write routes return {ok:bool, ...} and NEVER 5xx on a Stripe SDK
# error — they capture the error message into the response so the UI
# can surface it inline. Auth is admin-only via the existing decorator.
# =============================================================

def _stripe_probe_now():
    """Run Account.retrieve() against the current-mode key. Returns
    {ok, latency_ms, account_id, error, key_kind}. Stamps the result
    into stripe_settings via record_health() as a side-effect."""
    import stripe_settings as _ss
    import stripe_client as _sc
    import time as _time
    started = _time.time()
    try:
        s = _sc.get_stripe()
        acct = s.Account.retrieve()
        latency = int((_time.time() - started) * 1000)
        _ss.record_health(True, "")
        return {
            "ok": True,
            "latency_ms": latency,
            "account_id": acct.get("id") if isinstance(acct, dict) else getattr(acct, "id", ""),
            "key_kind": _sc.detect_active_key_kind(),
        }
    except Exception as e:
        latency = int((_time.time() - started) * 1000)
        msg = f"{type(e).__name__}: {e}"
        _ss.record_health(False, msg)
        return {
            "ok": False,
            "latency_ms": latency,
            "error": msg,
            "key_kind": _sc.detect_active_key_kind(),
        }


@app.route("/admin/api/stripe/settings", methods=["GET"])
@admin_required
def admin_stripe_settings():
    """Returns the full snapshot the Stripe tab needs on first load:
    mode, autosync flag, which env vars are present (booleans only —
    never values), last health check result, last backfill summary,
    and which key the resolver would currently use (test/live/unknown)
    — used to flag mode mismatches in the UI."""
    import stripe_settings as _ss
    import stripe_client as _sc
    settings = _ss.get_settings()
    keys_present = _sc.detect_keys_present()
    active_kind = _sc.detect_active_key_kind()
    return jsonify({
        "mode": settings["mode"],
        "autosync_products": settings["autosync_products"],
        "keys_present": keys_present,
        "active_key_kind": active_kind,
        # Symmetric mismatch: flag BOTH directions. The test→live case is
        # the dangerous one (real cards charged) but live→test is also
        # wrong (admin thinks they're charging real customers but the
        # charges hit Stripe's sandbox), so surface both equally.
        "mode_mismatch": (
            active_kind in ("test", "live")
            and active_kind != settings["mode"]
        ),
        "health": {
            "last_check_at": settings["last_health_check_at"],
            "ok": settings["last_health_ok"],
            "error": settings["last_health_error"],
        },
        "last_backfill": {
            "at": settings["last_backfill_at"],
            "summary": settings["last_backfill_summary"],
        },
    })


@app.route("/admin/api/stripe/mode", methods=["POST"])
@admin_required
def admin_stripe_set_mode():
    """Flip between test/live. Invalidates the key cache so the very
    next get_stripe() call uses the new mode's key, then runs an
    immediate probe so the UI gets a fresh health badge."""
    import stripe_settings as _ss
    import stripe_client as _sc
    data = request.get_json(silent=True) or {}
    mode = (data.get("mode") or "").lower().strip()
    if mode not in ("test", "live"):
        return jsonify({"ok": False, "error": "mode must be 'test' or 'live'"}), 400
    try:
        _ss.set_mode(mode)
        _sc.invalidate_cache()
    except Exception as e:
        capture_exc(e, "admin_stripe_set_mode")
        return jsonify({"ok": False, "error": str(e)}), 500
    return jsonify({
        "ok": True,
        "mode": mode,
        "probe": _stripe_probe_now(),
    })


@app.route("/admin/api/stripe/autosync", methods=["POST"])
@admin_required
def admin_stripe_set_autosync():
    """Persist the product-autosync flag. When enabled, future
    POST/PUT /admin/api/products will mirror to Stripe automatically.
    Existing products are NOT backfilled — admin must hit the
    'Backfill all products' button to sweep the whole catalog."""
    import stripe_settings as _ss
    data = request.get_json(silent=True) or {}
    enabled = bool(data.get("enabled"))
    try:
        _ss.set_autosync(enabled)
    except Exception as e:
        capture_exc(e, "admin_stripe_set_autosync")
        return jsonify({"ok": False, "error": str(e)}), 500
    return jsonify({"ok": True, "autosync_products": enabled})


@app.route("/admin/api/stripe/probe", methods=["POST"])
@admin_required
def admin_stripe_probe():
    """One-shot Stripe Account.retrieve() against the current mode.
    Used by the 'Test connection' button in the UI."""
    return jsonify(_stripe_probe_now())


@app.route("/admin/api/stripe/backfill", methods=["POST"])
@admin_required
def admin_stripe_backfill():
    """Sync every active product to Stripe in one shot. Returns counts +
    a (capped at 20) sample of failures. Records the summary into
    stripe_settings.last_backfill_summary so the UI can show it on
    next load without re-running."""
    try:
        import stripe_sync as _ssync
        result = _ssync.backfill_all()
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "synced": 0,
                        "failed": 0, "errors": []})
    return jsonify({"ok": True, **result})


@app.route("/admin/api/stripe/sync-product", methods=["POST"])
@admin_required
def admin_stripe_sync_product():
    """Manual single-product re-sync. Used by the 'Re-sync' button on
    each row of the sync-status table. Works regardless of the
    autosync toggle (the toggle only governs the AUTOMATIC hook from
    product CRUD; manual re-sync should always be available)."""
    data = request.get_json(silent=True) or {}
    try:
        pid = int(data.get("product_id") or 0)
    except (TypeError, ValueError):
        pid = 0
    if pid <= 0:
        return jsonify({"ok": False, "error": "product_id required"}), 400
    try:
        import stripe_sync as _ssync
        result = _ssync.sync_product(pid)
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})
    return jsonify(result)


@app.route("/admin/api/stripe/sync-status", methods=["GET"])
@admin_required
def admin_stripe_sync_status():
    """Returns products × current-mode mapping, as the table the admin
    sees. Includes a `price_drift` flag per row so unmatched prices
    are immediately visible."""
    try:
        import stripe_sync as _ssync
        return jsonify(_ssync.get_sync_status_rows())
    except Exception as e:
        return jsonify({"ok": False, "error": str(e), "rows": [],
                        "count": 0, "mode": "unknown"})


@app.route("/admin/api/stripe/recent-checkouts", methods=["GET"])
@admin_required
def admin_stripe_recent_checkouts():
    """Read-only window into the last N Checkout Sessions (current
    mode). Pure passthrough to stripe.checkout.Session.list — never
    persisted locally because it changes constantly and would just be
    a stale cache."""
    import stripe_client as _sc
    import stripe_settings as _ss
    try:
        limit = max(1, min(int(request.args.get("limit") or 50), 100))
    except (TypeError, ValueError):
        limit = 50
    try:
        s = _sc.get_stripe()
        listing = s.checkout.Session.list(limit=limit)
        out = []
        for sess in (listing.get("data") if isinstance(listing, dict)
                     else getattr(listing, "data", []) or []):
            d = dict(sess) if not isinstance(sess, dict) else sess
            out.append({
                "id": d.get("id") or "",
                "created": d.get("created"),
                "amount_total": d.get("amount_total"),
                "currency": (d.get("currency") or "").upper(),
                "payment_status": d.get("payment_status") or "",
                "status": d.get("status") or "",
                "customer_email": (
                    d.get("customer_email")
                    or (d.get("customer_details") or {}).get("email")
                    or ""
                ),
                "url": d.get("url") or "",
            })
        return jsonify({
            "ok": True,
            "mode": _ss.get_mode(),
            "sessions": out,
            "count": len(out),
        })
    except Exception as e:
        return jsonify({
            "ok": False,
            "mode": _ss.get_mode(),
            "error": f"{type(e).__name__}: {e}",
            "sessions": [],
            "count": 0,
        })


# =============================================================
# ADMIN: SECRETS / .env MANAGER
# =============================================================
# Routes that back the admin "Secrets" tab. Lets the operator see
# which env vars the app cares about, which are populated, and set
# any that aren't — without ever exposing the value (sensitive vars
# are masked to •••• + last 4 chars).
#
# Source-of-truth precedence: Replit Secrets > local .env file.
# Writes always go to the .env file. If a Replit Secret is currently
# providing a key, the route REJECTS the write with an explanatory
# error — overwriting silently would no-op since the loader doesn't
# override already-set vars.
# =============================================================

@app.route("/admin/api/secrets/status", methods=["GET"])
@admin_required
def admin_secrets_status():
    """Return the full list of known env vars + their current state.
    Sensitive values are NEVER returned in clear — only as
    ``••••XXXX`` (last 4 chars). Non-sensitive config (URLs, emails,
    flags) is returned in full so the admin can verify the value."""
    try:
        return jsonify({
            "ok": True,
            "rows": _env_manager.get_status(),
            # UX hint so the UI labels platform-managed vars accurately
            # ("Replit Secret" on Replit, "Environment" on Heroku /
            # Railway / Fly / Docker / etc). Source classification
            # itself is host-agnostic — see env_manager._classify_source.
            "platform": "replit" if _env_manager.is_replit_platform() else "other",
        })
    except Exception as e:
        capture_exc(e, "admin_secrets_status")
        return jsonify({"ok": False, "error": f"{type(e).__name__}: {e}"}), 500


@app.route("/admin/api/secrets/set", methods=["POST"])
@admin_required
def admin_secrets_set():
    """Set a single whitelisted env var. Body: ``{key, value,
    force_override?: bool}``. Writes to the local .env file and
    updates os.environ so the running process sees the new value
    immediately. Some vars (FLASK_SECRET_KEY, SENTRY_DSN, anything
    with restart=True in the KNOWN_VARS table) won't take full
    effect until the workflow restarts — the response includes a
    ``restart_required`` flag so the UI can warn the admin.

    ``force_override`` (default False) lets the admin explicitly
    overwrite a key currently provided by the host environment
    (Replit Secrets / Heroku Config Vars / etc). Without it, the
    request is rejected with a 400 explaining the host shadow — see
    ``env_manager.set_var`` for the safety reasoning."""
    body = request.get_json(silent=True) or {}
    key = (body.get("key") or "").strip()
    value = body.get("value", "")
    force_override = bool(body.get("force_override", False))
    if not key:
        return jsonify({"ok": False, "error": "Missing 'key'."}), 400
    try:
        row = _env_manager.set_var(key, value, force_override=force_override)
        return jsonify({
            "ok": True,
            "row": row,
            "restart_required": bool(row.get("restart")),
        })
    except _env_manager.EnvManagerError as e:
        return jsonify({"ok": False, "error": str(e)}), 400
    except Exception as e:
        capture_exc(e, "admin_secrets_set")
        return jsonify({"ok": False, "error": f"{type(e).__name__}: {e}"}), 500


@app.route("/admin/api/secrets/unset", methods=["POST"])
@admin_required
def admin_secrets_unset():
    """Remove a single whitelisted env var from the local .env file
    and from os.environ. Body: {key}. Cannot unset Replit Secrets
    (returns 400 with an explanation)."""
    body = request.get_json(silent=True) or {}
    key = (body.get("key") or "").strip()
    if not key:
        return jsonify({"ok": False, "error": "Missing 'key'."}), 400
    try:
        row = _env_manager.unset_var(key)
        return jsonify({
            "ok": True,
            "row": row,
            "restart_required": bool(row.get("restart")),
        })
    except _env_manager.EnvManagerError as e:
        return jsonify({"ok": False, "error": str(e)}), 400
    except Exception as e:
        capture_exc(e, "admin_secrets_unset")
        return jsonify({"ok": False, "error": f"{type(e).__name__}: {e}"}), 500


