def _design_row_to_dict(row, include_html=False):
    """Normalize a site_designs row for JSON. Skip html in list responses."""
    if not row:
        return None
    out = dict(row)
    out["is_active"] = bool(out.pop("_is_active", False))
    out["html_length"] = len(out.get("html") or "")
    if not include_html:
        out.pop("html", None)
    return out


