def _rce_report_row(r):
    d = dict(r)
    d["key_points"] = _vp_as_list(d.get("key_points"))
    d["citations"] = _vp_as_list(d.get("citations"))
    for k in ("created_at", "updated_at"):
        if d.get(k):
            d[k] = d[k].isoformat()
    return d


